window.SPEAK_OR_BOOM_AUDIO = {"version": 1, "engine": "Kokoro-82M v1.0 + Meta AI TTS (movies Ep.1; see VOICE-NOTICE.txt)", "nativeSpeed": 0.95, "scenarios": {"coffee": {"1": {"agent": {"seconds": 1.664, "voice": "af_heart", "text": "Hi! What can I get for you?", "bytes": 20736, "sha256": "57d428b92db8d752310dfb387c64f1efaec59d2ce5f22fa151fb4cb7871fdb62", "src": "audio/coffee/1-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_bella", "text": "Can I get a medium latte, please?", "bytes": 25920, "sha256": "b9d199f06f7a79f7ed379425b93d350e966433c53dc701fb7a70b4454de63172", "src": "audio/coffee/1-user.mp3"}}, "2": {"agent": {"seconds": 1.301, "voice": "af_heart", "text": "For here or to go?", "bytes": 16416, "sha256": "a802f9680e0ac04386f36494db75aa64abfaff081b0be097697071fe0c3a66f3", "src": "audio/coffee/2-agent.mp3"}, "user": {"seconds": 1.088, "voice": "af_bella", "text": "For here, please.", "bytes": 13824, "sha256": "7bc9525cd3c5a99f426e2d00b099dac1d0eded9179f52523b0afe570b25f679e", "src": "audio/coffee/2-user.mp3"}}, "3": {"agent": {"seconds": 1.152, "voice": "af_heart", "text": "Hot or iced?", "bytes": 14400, "sha256": "36c14794e086b2d8e3e2bcbd291d2198658b19c58cac3872f0590d353aed14df", "src": "audio/coffee/3-agent.mp3"}, "user": {"seconds": 1.003, "voice": "af_bella", "text": "Hot, please.", "bytes": 12672, "sha256": "95f1719018d95bd38a187172e9ca30eb597ec79cf197abfc980e7985a7cc9f09", "src": "audio/coffee/3-user.mp3"}}, "4": {"agent": {"seconds": 3.349, "voice": "af_heart", "text": "What size would you like? We have small, medium, and large.", "bytes": 40896, "sha256": "c96e42dd9d97822928f76e029c24eea5f20c9507fc093747d788a44f607643b7", "src": "audio/coffee/4-agent.mp3"}, "user": {"seconds": 1.131, "voice": "af_bella", "text": "Medium, please.", "bytes": 14400, "sha256": "ad430a30abef672a9bc25ea62591e55a34a13cfd469eebac3a4a27c5bdc3bb73", "src": "audio/coffee/4-user.mp3"}}, "5": {"agent": {"seconds": 1.515, "voice": "af_heart", "text": "What kind of milk would you like?", "bytes": 19008, "sha256": "38f7b754383b630cd2bb7d3841d2bab43deae1e42024a0a1ab655656fbd38d01", "src": "audio/coffee/5-agent.mp3"}, "user": {"seconds": 1.173, "voice": "af_bella", "text": "Oat milk, please.", "bytes": 14688, "sha256": "54a5e32f3d9e8aad6ec30093809584c6c638e02da3000851cf62731d082331dd", "src": "audio/coffee/5-user.mp3"}}, "6": {"agent": {"seconds": 2.283, "voice": "af_heart", "text": "Would you like an extra shot of espresso?", "bytes": 28224, "sha256": "9297127ab9d4a6e1770289f8d624b985a325f402beb238c0ba4fe58ff7372b36", "src": "audio/coffee/6-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_bella", "text": "Yes, please. One extra shot.", "bytes": 25920, "sha256": "c55fcbe3968a38bda483d918683bddbce4b7475f57d0b25be1ae9159f54d1381", "src": "audio/coffee/6-user.mp3"}}, "7": {"agent": {"seconds": 1.664, "voice": "af_heart", "text": "Any sugar or syrup today?", "bytes": 20736, "sha256": "71dac01bcc60191cf709dcd616a67e72e2bd57063597373c267413e2811e4f6b", "src": "audio/coffee/7-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "Just one pump of vanilla, please.", "bytes": 26784, "sha256": "bbada3b2a2d203f6539b6261269dda7ec582eacf4e1ced95eb544297b01a8e68", "src": "audio/coffee/7-user.mp3"}}, "8": {"agent": {"seconds": 1.579, "voice": "af_heart", "text": "Can I get a name for the order?", "bytes": 19584, "sha256": "6fb55d017ccfaa87800c1b82c8891a91d083cea5a05c0e9b48550585389d49fb", "src": "audio/coffee/8-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Alex. A-L-E-X.", "bytes": 20160, "sha256": "cae6ab2acd76513a602c0e90e0789276025444535ad8799ad340c73aa22b2654", "src": "audio/coffee/8-user.mp3"}}, "9": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "Would you like whipped cream on top?", "bytes": 21312, "sha256": "a1f94c11f1f24caddce3f6b8342616201dce102b3059ab4c0e0428fff83c3066", "src": "audio/coffee/9-agent.mp3"}, "user": {"seconds": 1.365, "voice": "af_bella", "text": "No whipped cream, thanks.", "bytes": 16992, "sha256": "35bef7783186c91e57eea4f9353122809e82bb8dfbdeac4b04e7059d5af14765", "src": "audio/coffee/9-user.mp3"}}, "10": {"agent": {"seconds": 1.664, "voice": "af_heart", "text": "Do you want it extra hot?", "bytes": 20736, "sha256": "f03ab97aeeb053b67f93de5d36d7654ca1070358e061617d924e3b0c29ad9fdd", "src": "audio/coffee/10-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Regular temperature is fine.", "bytes": 20448, "sha256": "f528c6e1490009385e45e643459d6ee75fa0d733de7fbb4cc417ccb0883ae740", "src": "audio/coffee/10-user.mp3"}}, "11": {"agent": {"seconds": 2.347, "voice": "af_heart", "text": "Would you like to try our new caramel drizzle?", "bytes": 28800, "sha256": "d7a84e7698d816813495b44bf69f891dcd09f6b4b0e7329b0ce9026300f24d5a", "src": "audio/coffee/11-agent.mp3"}, "user": {"seconds": 1.216, "voice": "af_bella", "text": "Sure, let's try it.", "bytes": 15264, "sha256": "b4156d6acf98017fd2c326394310a94d8e9a60680a4ba7be6f2edc6bf64f167d", "src": "audio/coffee/11-user.mp3"}}, "12": {"agent": {"seconds": 1.515, "voice": "af_heart", "text": "Anything else for you today?", "bytes": 19008, "sha256": "c75c7612dc1051d0bd3129dfe5993e22d0f12af4173f49cd3825868f168db00c", "src": "audio/coffee/12-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "That's all for now, thanks.", "bytes": 19008, "sha256": "33dadd4f8cb0a5aebd5198fdca8c4248766885f02bbea1beeccfe55ac5d18ac4", "src": "audio/coffee/12-user.mp3"}}, "13": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "Would you like a pastry with your drink?", "bytes": 23040, "sha256": "7aeb20d98ac6b9bf322ebf5e0e31644e949672fdcedaf329df419cd07285ac49", "src": "audio/coffee/13-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "Yes, a butter croissant, please.", "bytes": 23616, "sha256": "381bef0586a717b4804bc8c7f71c1812dadc00a928e013187a1cf7f289f90d74", "src": "audio/coffee/13-user.mp3"}}, "14": {"agent": {"seconds": 1.579, "voice": "af_heart", "text": "Should I warm that up for you?", "bytes": 19584, "sha256": "3c04cf2f76a427674ffe4d9c0ebf0c5426f5f22f25619eb25795d444caef0e5b", "src": "audio/coffee/14-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "Yes, please warm it up.", "bytes": 19584, "sha256": "bfd89ba0d5e9a8fbc318ad8318e3363c6a3233bcc8fa049cf2e5810d42466fde", "src": "audio/coffee/14-user.mp3"}}, "15": {"agent": {"seconds": 2.667, "voice": "af_heart", "text": "Do you have any food allergies I should know about?", "bytes": 32832, "sha256": "696ee61421b939268b18c3cb898d31f370b17932978935df183f6fe473151e7d", "src": "audio/coffee/15-agent.mp3"}, "user": {"seconds": 1.387, "voice": "af_bella", "text": "No allergies, thanks.", "bytes": 17280, "sha256": "2a5b9a6e366c9030df938de427c466f259f70c92ff7fdf96acfa2592001a4025", "src": "audio/coffee/15-user.mp3"}}, "16": {"agent": {"seconds": 2.645, "voice": "af_heart", "text": "Great. Anything to drink besides the latte?", "bytes": 32544, "sha256": "bb3340b8b9b9e7bbf8d30a09da7bde0fc8fc1ac251276085231d0911d5b4353d", "src": "audio/coffee/16-agent.mp3"}, "user": {"seconds": 1.301, "voice": "af_bella", "text": "No, that's everything.", "bytes": 16416, "sha256": "108a1277689c03251f2eddb4ec8cdce18279bf9d280a2d0aa32ccb1534ecd5ca", "src": "audio/coffee/16-user.mp3"}}, "17": {"agent": {"seconds": 5.12, "voice": "af_heart", "text": "So that's one medium oat milk latte with an extra shot and vanilla, plus a croissant?", "bytes": 62208, "sha256": "e5616e54d3c308b28f1bf5965498fce3fa3efa68f98a2fc8dbae368ac4c9b059", "src": "audio/coffee/17-agent.mp3"}, "user": {"seconds": 2.603, "voice": "af_bella", "text": "Actually, make the latte large instead.", "bytes": 31968, "sha256": "6834c53941c23ef7e46dc4f77a2342f51cbf96a5bc58c35c746f4c17aa44e0fc", "src": "audio/coffee/17-user.mp3"}}, "18": {"agent": {"seconds": 2.987, "voice": "af_heart", "text": "No problem. Large it is. Still oat milk?", "bytes": 36576, "sha256": "3b957279e663e037a2a06d7c186d0afadb168303c7029f600b17eb4b6b7fd656", "src": "audio/coffee/18-agent.mp3"}, "user": {"seconds": 1.557, "voice": "af_bella", "text": "Yes, still oat milk.", "bytes": 19296, "sha256": "07c59bd8d05baf81d72bcc2559a43bad296879771f999da430c59b30e5c2be87", "src": "audio/coffee/18-user.mp3"}}, "19": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "Do you still want the extra shot?", "bytes": 22752, "sha256": "28260e531f40361e311702e79c9cdba253bdb2640c3077e5eec3485068ead31d", "src": "audio/coffee/19-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_bella", "text": "Actually, cancel the extra shot.", "bytes": 27072, "sha256": "52d4758aa2e39be88b35e8618d9058d6fe0442af28ef5314cebf3767072773c1", "src": "audio/coffee/19-user.mp3"}}, "20": {"agent": {"seconds": 3.051, "voice": "af_heart", "text": "Got it. No extra shot. Anything else to change?", "bytes": 37440, "sha256": "1550ce7d14f8d3b28e6884847b5c43a42b16be083a23e5bdbdb8c8dad3f104f6", "src": "audio/coffee/20-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "Can I change vanilla to caramel?", "bytes": 22752, "sha256": "a04ec1d61a7c0b3836b4c6b486e3597c5447f41a3eb1413457d04b7b395281a5", "src": "audio/coffee/20-user.mp3"}}, "21": {"agent": {"seconds": 1.941, "voice": "af_heart", "text": "Sure, caramel instead of vanilla.", "bytes": 23904, "sha256": "37dee4e7b1777aa66f724ee2280e7f2f9b95e9c44421ecaf9382fd60c823ea8d", "src": "audio/coffee/21-agent.mp3"}, "user": {"seconds": 2.667, "voice": "af_bella", "text": "And can I make the croissant an almond croissant?", "bytes": 32832, "sha256": "0842ca1b1ebac73c97f874e59ddf3fc327f6c6b308e748d974ac64437f90c97c", "src": "audio/coffee/21-user.mp3"}}, "22": {"agent": {"seconds": 1.899, "voice": "af_heart", "text": "Of course. Almond croissant.", "bytes": 23616, "sha256": "575ae159c15dccbe6e8f2fbe846869ca4ce313f93c5e39cf441a21d30845ccd2", "src": "audio/coffee/22-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "Sorry for all the changes.", "bytes": 19584, "sha256": "5100bb654120154511426ee11780bd01c5be809f0e9d9647b5f5f6db46982d13", "src": "audio/coffee/22-user.mp3"}}, "23": {"agent": {"seconds": 2.56, "voice": "af_heart", "text": "No worries at all! Let me repeat your order.", "bytes": 31392, "sha256": "ff34e9c012dad5ba0babffb7008d51c88dd1e83df3a792ad54cec19a323c33e2", "src": "audio/coffee/23-agent.mp3"}, "user": {"seconds": 1.067, "voice": "af_bella", "text": "Please go ahead.", "bytes": 13536, "sha256": "488156cbdb337e8e8cf0627d429cf428c6efc8c103345b403bd358d68f0eadfb", "src": "audio/coffee/23-user.mp3"}}, "24": {"agent": {"seconds": 4.821, "voice": "af_heart", "text": "One large oat milk latte with caramel, and one almond croissant. Correct?", "bytes": 58464, "sha256": "674653e80b3a9451af205e6596a1ab49d6d7e099d9e69ba1c5468564ef3efbb3", "src": "audio/coffee/24-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "That's correct. Thank you.", "bytes": 20448, "sha256": "55fa5558d90e6d8a92c05902d75cf338d92b35a6485b115992f4a1e2e6d1c628", "src": "audio/coffee/24-user.mp3"}}, "25": {"agent": {"seconds": 2.411, "voice": "af_heart", "text": "Your total is six dollars and fifty cents.", "bytes": 29664, "sha256": "2332d821103c4c89062ca783da82dd8681c98f9e9089486059dc2a94114bfa7e", "src": "audio/coffee/25-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "Can I pay with Apple Pay?", "bytes": 18144, "sha256": "194e4fe036788079e093c6a26678921df2a4b3e0375d86c5da09db99e99fc0d8", "src": "audio/coffee/25-user.mp3"}}, "26": {"agent": {"seconds": 2.176, "voice": "af_heart", "text": "Of course. Just tap your phone right here.", "bytes": 26784, "sha256": "c13d06aee8ccd7b97282a3e96c5dabc2ab55fc44436371ba329192360348ad1c", "src": "audio/coffee/26-agent.mp3"}, "user": {"seconds": 0.917, "voice": "af_bella", "text": "Here you go.", "bytes": 11808, "sha256": "5a9535f5c32bd6c2ce75cd927d50b194e9fe8d48d5242fcc4624b4c24382fc96", "src": "audio/coffee/26-user.mp3"}}, "27": {"agent": {"seconds": 2.517, "voice": "af_heart", "text": "Hmm, it didn't go through. Could you try again?", "bytes": 30816, "sha256": "8cc2fdf4beb16407416c749bf44fda93d617c1e6513325d8d4d957136c99a21a", "src": "audio/coffee/27-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_bella", "text": "Sure, let me try again.", "bytes": 20736, "sha256": "ad1e5b4c71347fed7781cd781eaa27b51b884bb4814b740cf35bd4e0c680d80b", "src": "audio/coffee/27-user.mp3"}}, "28": {"agent": {"seconds": 1.749, "voice": "af_heart", "text": "Perfect, payment successful!", "bytes": 21600, "sha256": "607067f16c23827e049191120ad268d8c4d58c1340671ad042d870391853ee88", "src": "audio/coffee/28-agent.mp3"}, "user": {"seconds": 1.131, "voice": "af_bella", "text": "Great, thank you.", "bytes": 14400, "sha256": "981d6635caf1c4e2cae8a3b146751e4649e60bcdbbd059fd3655312036a17714", "src": "audio/coffee/28-user.mp3"}}, "29": {"agent": {"seconds": 1.301, "voice": "af_heart", "text": "Would you like a receipt?", "bytes": 16416, "sha256": "3ffa15b9710a0885d48f829d21672f7dae9f55c14a0aac4fb9798ae4888bb000", "src": "audio/coffee/29-agent.mp3"}, "user": {"seconds": 2.475, "voice": "af_bella", "text": "Yes, please. Email receipt is fine.", "bytes": 30528, "sha256": "9d6d057e34d126f74254d92241d698f7e18a38c510902aa7dcc5ac4db1a72bd7", "src": "audio/coffee/29-user.mp3"}}, "30": {"agent": {"seconds": 1.451, "voice": "af_heart", "text": "What's your email address?", "bytes": 18144, "sha256": "6c0485f62cfd7df0a3dc4880d512a45cac3e427c9a6c9f89df513bf9c1d772d4", "src": "audio/coffee/30-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "It's alex at mail dot com.", "bytes": 22752, "sha256": "1ec1c226ff45646b7b9acdf9c17966e75b4e7dbfbc4c76ea9ae734e65fb87169", "src": "audio/coffee/30-user.mp3"}}, "31": {"agent": {"seconds": 1.408, "voice": "af_heart", "text": "Do you want to add a tip?", "bytes": 17568, "sha256": "8c65644cb9e1b43c82cee6c1c31b9da0762bf95b8effe879e0c1c779df220abf", "src": "audio/coffee/31-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Yes, add a tip of two dollars.", "bytes": 25632, "sha256": "cfafade01e1a129375a81848febab7dc9b2c00eb8fb8825713aa70367b1745d6", "src": "audio/coffee/31-user.mp3"}}, "32": {"agent": {"seconds": 2.837, "voice": "af_heart", "text": "Thank you so much! Your order number is forty-two.", "bytes": 34848, "sha256": "1e6a75fb192e803f2a608c6b5785acd3d9208e42d4f692954a97a474996c8b7c", "src": "audio/coffee/32-agent.mp3"}, "user": {"seconds": 1.557, "voice": "af_bella", "text": "Forty-two. Got it.", "bytes": 19296, "sha256": "9d21d8c647e0d073a57f740a9eb331a54080e742f2c77b6c22f702d67d19fc29", "src": "audio/coffee/32-user.mp3"}}, "33": {"agent": {"seconds": 2.475, "voice": "af_heart", "text": "Your drink will be ready in about five minutes.", "bytes": 30528, "sha256": "b7843247d2cd06eb40a539f17de716b83f8aed7a188c6e964bf6e99c8fa80199", "src": "audio/coffee/33-agent.mp3"}, "user": {"seconds": 1.685, "voice": "af_bella", "text": "How long is the wait right now?", "bytes": 21024, "sha256": "77e52ba87ee395764ec7a2b70b9ff0493ca666d2b8ba5a163782c109b9af816c", "src": "audio/coffee/33-user.mp3"}}, "34": {"agent": {"seconds": 2.219, "voice": "af_heart", "text": "Just a few minutes. We're a little backed up.", "bytes": 27360, "sha256": "f47d4788f384420466deabe683de484e1d3ff3b8798da094f86c646e1fc0f8bc", "src": "audio/coffee/34-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "No rush. Take your time.", "bytes": 21312, "sha256": "4f38ecb6a7d7f0e41766e377754c3e60a333cfb94596a4998eeef69c399e1e10", "src": "audio/coffee/34-user.mp3"}}, "35": {"agent": {"seconds": 2.219, "voice": "af_heart", "text": "You can wait right over there by the counter.", "bytes": 27360, "sha256": "b83aa52e2a72d2421d3c5232f3db074180cbdfa89d5076b9be788f79929cdc88", "src": "audio/coffee/35-agent.mp3"}, "user": {"seconds": 1.429, "voice": "af_bella", "text": "Is there free Wi-Fi here?", "bytes": 17856, "sha256": "a67fff6eace53e0cceca0365812d87cb8a72a6a2f3dee4e76cbe06fab34fd1a6", "src": "audio/coffee/35-user.mp3"}}, "36": {"agent": {"seconds": 2.133, "voice": "af_heart", "text": "Yes! The password is on your receipt.", "bytes": 26208, "sha256": "7d696e84f42af8692b79609c4a8b733d2cdc4b943051ea7b9c8a9b19f8189087", "src": "audio/coffee/36-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "What's the Wi-Fi password again?", "bytes": 21312, "sha256": "30be4889e0ab4d662fd7512bb1aba3dca748e0d5f9a64f469f0927f4de49f55f", "src": "audio/coffee/36-user.mp3"}}, "37": {"agent": {"seconds": 2.88, "voice": "af_heart", "text": "It's 'coffee time', all lowercase, no spaces.", "bytes": 35136, "sha256": "a3469a3a02c0082ba27399f4345cb570d158fe98d8b892b14a94edbd107dfb18", "src": "audio/coffee/37-agent.mp3"}, "user": {"seconds": 2.453, "voice": "af_bella", "text": "Coffee time, all lowercase. Thanks.", "bytes": 30240, "sha256": "3bf4f85769c4b475412827520b06e6821760160a6839ba50c70d06dc4e1f2b21", "src": "audio/coffee/37-user.mp3"}}, "38": {"agent": {"seconds": 3.179, "voice": "af_heart", "text": "Are you waiting for someone, or just grabbing a quick coffee?", "bytes": 38880, "sha256": "60e44ac910571cacf72242a42e794b8ca290bda64575aba9e12d3cac36f4571f", "src": "audio/coffee/38-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "Just grabbing a quick coffee.", "bytes": 19008, "sha256": "32049269d4f06caf9f1c0000854bb0a3fa5eadbfec1c8021ad7d0a76ece2e2c6", "src": "audio/coffee/38-user.mp3"}}, "39": {"agent": {"seconds": 1.813, "voice": "af_heart", "text": "Nice. Do you come here often?", "bytes": 22464, "sha256": "95564f8399d1890ff94bbd2ed25775977c81a1df2c5c08e59b0c519e62da3dbc", "src": "audio/coffee/39-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_bella", "text": "Yeah, I come here every morning.", "bytes": 25056, "sha256": "bd3233d9cb4e287c6e007f9e20e819395d187fa88137fb8b2f7fbb40948461ef", "src": "audio/coffee/39-user.mp3"}}, "40": {"agent": {"seconds": 2.283, "voice": "af_heart", "text": "That's great to hear! We love our regulars.", "bytes": 28224, "sha256": "b11fdc9ece736416119f0954397437c553576073ab9dfc560ed30c7823717a8e", "src": "audio/coffee/40-agent.mp3"}, "user": {"seconds": 1.365, "voice": "af_bella", "text": "The coffee here is the best.", "bytes": 16992, "sha256": "e9a83b8ebf6634fa0f3d8105fc88be943a0cbe0f55b77f7c1ca9fc54b6ea603a", "src": "audio/coffee/40-user.mp3"}}, "41": {"agent": {"seconds": 2.261, "voice": "af_heart", "text": "Feel free to grab any open table.", "bytes": 27936, "sha256": "b863399d8e6a526a2f82afd69eee0bd6c6b58f532fe4a2383af8cc0b1d20767a", "src": "audio/coffee/41-agent.mp3"}, "user": {"seconds": 1.152, "voice": "af_bella", "text": "Is this seat taken?", "bytes": 14400, "sha256": "73ce30a437d311f3682166b31859531bafe067de50fdbfb02064082c227137c2", "src": "audio/coffee/41-user.mp3"}}, "42": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "That one's free. Go ahead.", "bytes": 21312, "sha256": "a29b5922aed01106a77a091e045eecd39b90d1fe04d6038bdbeac39eae57f5f2", "src": "audio/coffee/42-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "Is there an outlet near here?", "bytes": 19008, "sha256": "b17e6049aac4fb7cb4c82fefca46bdec4bee2f5c0dff12c0f940eeb302b6c1b6", "src": "audio/coffee/42-user.mp3"}}, "43": {"agent": {"seconds": 2.133, "voice": "af_heart", "text": "Yes, there's one right under the window.", "bytes": 26208, "sha256": "6beb91ca441900574d047dd59521eef65b1e538ac403ad6ca39add1b60b1f0db", "src": "audio/coffee/43-agent.mp3"}, "user": {"seconds": 2.56, "voice": "af_bella", "text": "Perfect. I need to charge my laptop.", "bytes": 31392, "sha256": "4d623eddd2bea5af87718cbb6a84edc32fc81d7fe7d2ae6d60cbdce5509eddb9", "src": "audio/coffee/43-user.mp3"}}, "44": {"agent": {"seconds": 2.368, "voice": "af_heart", "text": "The Wi-Fi can be slow during rush hour.", "bytes": 29088, "sha256": "4c55e17b27b2547d8b0b9a89e1f4501121816ee5ec5ef79aa7e6bbd4a9cf73b8", "src": "audio/coffee/44-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_bella", "text": "That's okay. I'm just checking email.", "bytes": 28224, "sha256": "72b8f5cde4f41814156c9236118b3bcdae2c64b2a2b77d0ed3a3707fedcddbcc", "src": "audio/coffee/44-user.mp3"}}, "45": {"agent": {"seconds": 1.749, "voice": "af_heart", "text": "Let me know if you need anything else.", "bytes": 21600, "sha256": "a8e77c725f3799ec7924e522c6be9a9524545e3559ec6e17b13b59d2820f294f", "src": "audio/coffee/45-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_bella", "text": "Can I get some water, please?", "bytes": 20736, "sha256": "3a62556b71edb552efb068a23025bd30c2ae46a5f2bca97704b97dc47bc3cb09", "src": "audio/coffee/45-user.mp3"}}, "46": {"agent": {"seconds": 1.301, "voice": "af_heart", "text": "Still or sparkling?", "bytes": 16416, "sha256": "eef29f98b226b3ddc5da43d1a72183dc7d7475311e28bc1120c62a732d559901", "src": "audio/coffee/46-agent.mp3"}, "user": {"seconds": 1.323, "voice": "af_bella", "text": "Still water is fine.", "bytes": 16704, "sha256": "5e50773bccdef2f429f2b3fe41e30996ebe1387b12b479e3749d8920b8649f8d", "src": "audio/coffee/46-user.mp3"}}, "47": {"agent": {"seconds": 1.728, "voice": "af_heart", "text": "Here you go. Anything else?", "bytes": 21312, "sha256": "4f7f79c8e07cee7c6e1ee4fd98facce9d6c73d8016553102c165c611fab51d75", "src": "audio/coffee/47-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_bella", "text": "Could I have some napkins too?", "bytes": 20736, "sha256": "89e0ae5c88d4a91e6fd40cc4b58bc4be7708f97808eed0a5324fbd81b0f4eb14", "src": "audio/coffee/47-user.mp3"}}, "48": {"agent": {"seconds": 2.091, "voice": "af_heart", "text": "Sure thing. I'll bring them right over.", "bytes": 25920, "sha256": "a8455ab45ab945e6b990941b7fc4f67f6379f9aa8e7bc3625c62ba76e571cd88", "src": "audio/coffee/48-agent.mp3"}, "user": {"seconds": 1.045, "voice": "af_bella", "text": "Thank you so much.", "bytes": 13248, "sha256": "9d30342fc135c669c1b58b519accd6f312b8106871c79368ac755e62b1afea72", "src": "audio/coffee/48-user.mp3"}}, "49": {"agent": {"seconds": 1.621, "voice": "af_heart", "text": "So, what do you do for work?", "bytes": 20160, "sha256": "d3223db670088c239803c9646eaa693c1ef11adf04232363278a322fca2c029f", "src": "audio/coffee/49-agent.mp3"}, "user": {"seconds": 1.408, "voice": "af_bella", "text": "I'm a software engineer.", "bytes": 17568, "sha256": "719ce448cde84f0dac17bede5afa737d890e64bd6404f1319323a4f5fa9c8e87", "src": "audio/coffee/49-user.mp3"}}, "50": {"agent": {"seconds": 1.771, "voice": "af_heart", "text": "Oh nice! Do you work from home?", "bytes": 21888, "sha256": "d949bfc447a72f874330b919bffc605f8e07d54c1eb36eeb7d4fa5058e7a1369", "src": "audio/coffee/50-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_bella", "text": "Mostly, yes. I work remotely.", "bytes": 27360, "sha256": "c8a28f6c5c568dc1b8dc6877949ed5535709d05d008961b12c79c6530df97707", "src": "audio/coffee/50-user.mp3"}}, "51": {"agent": {"seconds": 2.432, "voice": "af_heart", "text": "That's the dream. What are you working on today?", "bytes": 29952, "sha256": "e9cd8f1a3c7fae8551c0e39134f54bbed94ed74ee72ca3423288f8b4c5b8300a", "src": "audio/coffee/51-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Just catching up on emails.", "bytes": 20160, "sha256": "3bae58343a4f93164d2d9f9bce743bcc4923ca9c76d9e3842498e38b8f12eb05", "src": "audio/coffee/51-user.mp3"}}, "52": {"agent": {"seconds": 1.088, "voice": "af_heart", "text": "Busy day, huh?", "bytes": 13824, "sha256": "4cbdf24e3159235c5ff956906a66a964537147b628973ac6deda6c00f5b05d1b", "src": "audio/coffee/52-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "Yeah, meetings all afternoon.", "bytes": 23328, "sha256": "d81afdc750f4f418860f2daee5cb7e1acb61c3020830dba626e9d7157b3636e8", "src": "audio/coffee/52-user.mp3"}}, "53": {"agent": {"seconds": 1.92, "voice": "af_heart", "text": "Well, at least you have good coffee.", "bytes": 23616, "sha256": "da676a8c4fc53e28fdef2fee95e301500f21face2fec74973e363825cebbb7cd", "src": "audio/coffee/53-agent.mp3"}, "user": {"seconds": 2.581, "voice": "af_bella", "text": "Exactly. Coffee makes everything better.", "bytes": 31680, "sha256": "f40d341c1bd74f8f1f61d8c340b2d251565854c4e8bfe5fef914acd1509316f8", "src": "audio/coffee/53-user.mp3"}}, "54": {"agent": {"seconds": 1.557, "voice": "af_heart", "text": "Where are you from originally?", "bytes": 19296, "sha256": "0b4940ea2958a3ccb3ae612fd0f8ef378ef9ae5b370ff8b447f5253f99aa307f", "src": "audio/coffee/54-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "I'm from Shanghai, originally.", "bytes": 24192, "sha256": "39682f063ea552cf4ed9ca4b25ec857625ff4a9984c4d250ae1dee952a8582bd", "src": "audio/coffee/54-user.mp3"}}, "55": {"agent": {"seconds": 2.411, "voice": "af_heart", "text": "Wow, that's far! How long have you been here?", "bytes": 29664, "sha256": "e7f70f5f3e1c4787b97574c81026015516a09a38fd40764b1d080e5437582f9c", "src": "audio/coffee/55-agent.mp3"}, "user": {"seconds": 1.301, "voice": "af_bella", "text": "About three years now.", "bytes": 16416, "sha256": "7ad69e2004a33c8fc550985b977bab392df81aa23b3450595bc54ec629b75f3f", "src": "audio/coffee/55-user.mp3"}}, "56": {"agent": {"seconds": 1.088, "voice": "af_heart", "text": "Do you miss home?", "bytes": 13824, "sha256": "051fb5d81e233d88b34fd6f082b55251240bc7f3218e2a30d8a161772939142e", "src": "audio/coffee/56-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "Sometimes, but I like it here.", "bytes": 24480, "sha256": "4b2cf8fd182d04203ed4950221fad2d6f2db9e97f52231ee700314bddac3ca47", "src": "audio/coffee/56-user.mp3"}}, "57": {"agent": {"seconds": 2.432, "voice": "af_heart", "text": "Order forty-two! One large latte!", "bytes": 29952, "sha256": "256a4b879af7762002457cc9a945330a4136d1dbcbacd504de844daa3a1c4db3", "src": "audio/coffee/57-agent.mp3"}, "user": {"seconds": 2.389, "voice": "af_bella", "text": "Excuse me, I think this is too sweet.", "bytes": 29376, "sha256": "58f9942d8823f0b2d93b93fe734c13b9d191fd88f838237ddf9f8c6f0669cec3", "src": "audio/coffee/57-user.mp3"}}, "58": {"agent": {"seconds": 3.115, "voice": "af_heart", "text": "Oh no! Let me check the ticket. Did you want caramel?", "bytes": 38016, "sha256": "c87fdd94bc6e4fcbd1ee79bc6f2757ab6c841056402e33c53672c53a81d7fe4f", "src": "audio/coffee/58-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "Yes, but just half the syrup, please.", "bytes": 26784, "sha256": "7e3c2409c09c6e98580ea82e978a1d85e56256ecb922c1978828e3ede25c0bf8", "src": "audio/coffee/58-user.mp3"}}, "59": {"agent": {"seconds": 2.389, "voice": "af_heart", "text": "I'm so sorry. Let me remake it for you.", "bytes": 29376, "sha256": "87959bf001a93f4ceb1d7374c934c28c77e9ee9b09f60e8dd5f658a58bbd839d", "src": "audio/coffee/59-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_bella", "text": "That's okay. These things happen.", "bytes": 24768, "sha256": "ecc219a6bb024493d8fbdfdce43073546f0ba8138f89df5c89dcf7d94544e1d7", "src": "audio/coffee/59-user.mp3"}}, "60": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "While we remake it, is the milk okay?", "bytes": 25920, "sha256": "eb76acb6f522fb563e56ce2a3ecca4b01537a9362b5b857172d9c47972e565fd", "src": "audio/coffee/60-agent.mp3"}, "user": {"seconds": 2.517, "voice": "af_bella", "text": "Actually, this tastes like regular milk.", "bytes": 30816, "sha256": "3a1b431071f7507fc6824ab5ae7943442904eeffff2ff541e56e49fb38557b79", "src": "audio/coffee/60-user.mp3"}}, "61": {"agent": {"seconds": 2.88, "voice": "af_heart", "text": "You're right, that's my mistake. Oat milk, correct?", "bytes": 35136, "sha256": "809a05705729b169708807fc2a3ddcd5db6023a632ddc16ca52d9578b17eeae4", "src": "audio/coffee/61-agent.mp3"}, "user": {"seconds": 1.685, "voice": "af_bella", "text": "Yes, oat milk please.", "bytes": 21024, "sha256": "7daa196a725ef80d6ea9e307af08111745f1063b809ff2b76d284e229901f5eb", "src": "audio/coffee/61-user.mp3"}}, "62": {"agent": {"seconds": 2.581, "voice": "af_heart", "text": "And the size is wrong too. This is a medium.", "bytes": 31680, "sha256": "73256f322315e4c6a19acf04d47fbd6302daa96d6c0cf91830b4a31d3de21553", "src": "audio/coffee/62-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Right, I ordered a large.", "bytes": 20448, "sha256": "ceb0780b4c3661b4b17b6145c57de002bd5f78fc8ced82fc20771905ac5e13f1", "src": "audio/coffee/62-user.mp3"}}, "63": {"agent": {"seconds": 2.56, "voice": "af_heart", "text": "I apologize. We'll get it right this time.", "bytes": 31392, "sha256": "791628d0752eb7aa5a11b6261f9dba1238faf44875b5b07020e5ae4492b28c1a", "src": "audio/coffee/63-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "No worries. I appreciate it.", "bytes": 23616, "sha256": "fb56d03c68e67cdcc705bf39747dfed79023e4a19b17a23c541a5664eac92dd7", "src": "audio/coffee/63-user.mp3"}}, "64": {"agent": {"seconds": 2.389, "voice": "af_heart", "text": "Here's your new drink. Can you taste it first?", "bytes": 29376, "sha256": "b50980b8546d2836cf56244d6886de0938eccb7763dad1e87f372f7650ae9412", "src": "audio/coffee/64-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "This is perfect. Thank you.", "bytes": 22464, "sha256": "18f257b3dffc1e977fd8a5eb3aa841303e9ae5267ac62d14bcf3b49480526178", "src": "audio/coffee/64-user.mp3"}}, "65": {"agent": {"seconds": 1.515, "voice": "af_heart", "text": "Can I get you anything else?", "bytes": 19008, "sha256": "118e3e55180fefd1be2422e753baf6073562d5e80f31694752d342613b0a127b", "src": "audio/coffee/65-agent.mp3"}, "user": {"seconds": 2.581, "voice": "af_bella", "text": "Actually, can I order another drink to go?", "bytes": 31680, "sha256": "6f39a1a77820fe5ed0381627f67cc544be07aad5adcee4256a52a05c06541962", "src": "audio/coffee/65-user.mp3"}}, "66": {"agent": {"seconds": 1.6, "voice": "af_heart", "text": "Of course! What would you like?", "bytes": 19872, "sha256": "902127ef42b4287b630d080d1c387ba61d3ea9d0eb4d9ef58480166528322052", "src": "audio/coffee/66-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "An iced americano, please.", "bytes": 21888, "sha256": "b3ee7941bcc6e8e8ad161985354ced52d04dda8d0cf6b2e10dd1c56c6b72fc82", "src": "audio/coffee/66-user.mp3"}}, "67": {"agent": {"seconds": 0.96, "voice": "af_heart", "text": "What size?", "bytes": 12096, "sha256": "5098f9fd64f60b8b121993ede73e0663ece222b715469f7e9fe423ad216b1aa7", "src": "audio/coffee/67-agent.mp3"}, "user": {"seconds": 0.96, "voice": "af_bella", "text": "Small is fine.", "bytes": 12096, "sha256": "aa4f712c4a3b343e61a3da0acc118b4c6263e83f88b1f67c38cc25541ad36ae9", "src": "audio/coffee/67-user.mp3"}}, "68": {"agent": {"seconds": 1.643, "voice": "af_heart", "text": "Any milk or sugar in that?", "bytes": 20448, "sha256": "3f1c26ba149be1c19d4341fc146935d2d9351e820cbf3fcc9a3841f9cab05b27", "src": "audio/coffee/68-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "Black, no sugar. Thanks.", "bytes": 21888, "sha256": "b6b8ecb489851ec2ff1b4ed5d3c5e86bf6acf52d88e10f274a5eaa8ac977a9a8", "src": "audio/coffee/68-user.mp3"}}, "69": {"agent": {"seconds": 1.045, "voice": "af_heart", "text": "To go, right?", "bytes": 13248, "sha256": "50f6d90c8acecc522d9fe442b4492b663f77dc1a6a34df3a59342d511b97f30d", "src": "audio/coffee/69-agent.mp3"}, "user": {"seconds": 1.365, "voice": "af_bella", "text": "Yes, to go please.", "bytes": 16992, "sha256": "debc5210c8aeb4e10cab800c8e66ed82aaaf9d4344a0c1aaa9091370eb4d2613", "src": "audio/coffee/69-user.mp3"}}, "70": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "That'll be four dollars even.", "bytes": 21312, "sha256": "ef7fd37cf3dfe6efa2bffcaef6d081ea71823cef8148064791121bfc05682ad7", "src": "audio/coffee/70-agent.mp3"}, "user": {"seconds": 1.493, "voice": "af_bella", "text": "How much is it altogether?", "bytes": 18720, "sha256": "6696c043eda809e1741de9aee0f04b70c1493433d444355fcf58ef2bebaea701", "src": "audio/coffee/70-user.mp3"}}, "71": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "Four dollars. You can tap to pay.", "bytes": 25920, "sha256": "01288ee6fe533163284b0e393bc4d91d6557c5bf036125279da01b44af0b90cb", "src": "audio/coffee/71-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "Can I use Apple Pay again?", "bytes": 19584, "sha256": "f925e627dcbd11adc664bb3a76263239ab0e67d27a94b67f29be69a85ad35c6c", "src": "audio/coffee/71-user.mp3"}}, "72": {"agent": {"seconds": 1.984, "voice": "af_heart", "text": "Absolutely. Go ahead and tap.", "bytes": 24480, "sha256": "b38baf37c68422ed4898d5df8d95e2da2e805f9d271f91eada95f867a6ea925e", "src": "audio/coffee/72-agent.mp3"}, "user": {"seconds": 1.493, "voice": "af_bella", "text": "All done. Thank you.", "bytes": 18720, "sha256": "edb43010d5b5d8ccc45b2605319b61f9b90426bddae35e1de0e160a18341087c", "src": "audio/coffee/72-user.mp3"}}, "73": {"agent": {"seconds": 1.664, "voice": "af_heart", "text": "Hi! Is this seat taken?", "bytes": 20736, "sha256": "65496ca655a84108d07ee898c6b19fe7a48b3355bb3d02cac92b44e7840831a9", "src": "audio/coffee/73-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "No, go ahead. It's free.", "bytes": 18144, "sha256": "48b2ca5dc292fc69c59c29c3e179cd58b3dd09e57749eb0904a2f7cc235ea13c", "src": "audio/coffee/73-user.mp3"}}, "74": {"agent": {"seconds": 1.899, "voice": "af_heart", "text": "Thanks! I love this coffee shop.", "bytes": 23616, "sha256": "f080e679b907b826e4d3882ecb5089c8b135146c177f961d54b24b18cc0dac8b", "src": "audio/coffee/74-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "Me too. The vibe is great.", "bytes": 22464, "sha256": "44a1b01ce7c98195877d56a2841abefd6886b28b5815713a89fffb2a79eae71c", "src": "audio/coffee/74-user.mp3"}}, "75": {"agent": {"seconds": 1.152, "voice": "af_heart", "text": "What are you drinking?", "bytes": 14400, "sha256": "147979e54c2a24d98262a0d876e3d12ea60fa78cd02fe627fce201085a9bb724", "src": "audio/coffee/75-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_bella", "text": "An oat milk latte. You should try it.", "bytes": 28512, "sha256": "17543c12bf7e15fdb08f39e9748abaae0086bb764daffd1dc69f1d559a4b8c8a", "src": "audio/coffee/75-user.mp3"}}, "76": {"agent": {"seconds": 1.941, "voice": "af_heart", "text": "That sounds good. Is it sweet?", "bytes": 23904, "sha256": "e4fc0e1dd5f631b60fb6b5d5f8bfa08acdd344195c902a50c1fe7412693b56ad", "src": "audio/coffee/76-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "A little. I get half syrup.", "bytes": 21888, "sha256": "9f719edadc6b638c25a130daf7f627170c9d7a5c3fea3e59480e5ad09cfc7978", "src": "audio/coffee/76-user.mp3"}}, "77": {"agent": {"seconds": 2.069, "voice": "af_heart", "text": "Good tip! I'll try that next time.", "bytes": 25632, "sha256": "48c2b6e0a39dd94963b8b3c394b67abcb71e02ce91100f48a42f66e7fe7e5936", "src": "audio/coffee/77-agent.mp3"}, "user": {"seconds": 1.323, "voice": "af_bella", "text": "Do you come here a lot?", "bytes": 16704, "sha256": "2d46dbf1d96903ddece12c24cac1bf5b6501e348c29704907066538f27d23618", "src": "audio/coffee/77-user.mp3"}}, "78": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "Every weekend. It's my ritual.", "bytes": 25920, "sha256": "58f0a055200f1dfe15e88abe617192ebe9dd580cc5f1db05d865ee1c4f00e693", "src": "audio/coffee/78-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_bella", "text": "Nice ritual. I might join you.", "bytes": 25056, "sha256": "69f88b274c4328658c88a131b837de23e1ffcb71fa1416b5c4c9167e4e83fde0", "src": "audio/coffee/78-user.mp3"}}, "79": {"agent": {"seconds": 1.536, "voice": "af_heart", "text": "Haha, the more the merrier!", "bytes": 19008, "sha256": "bbc2f68689b8dfa9c77867c16fbb1c9bc225f24761ce24f52a0203ad15394d3a", "src": "audio/coffee/79-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "Where are you headed after this?", "bytes": 18144, "sha256": "319f2aaa95a20e255c12d97094a1a813573c0198a96855c86ced7936dde648e0", "src": "audio/coffee/79-user.mp3"}}, "80": {"agent": {"seconds": 1.984, "voice": "af_heart", "text": "Just to the bookstore across the street.", "bytes": 24480, "sha256": "ea7de440a38c93238e1d924ae7e01bd97a9db454d2bc4ab2b7f99d662a664acc", "src": "audio/coffee/80-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "Oh nice. Enjoy your book.", "bytes": 22464, "sha256": "5fc0df8601c924c5b9d2970371635ee6a03f1c20b3d51dd5a66f645bd97ce75d", "src": "audio/coffee/80-user.mp3"}}, "81": {"agent": {"seconds": 1.899, "voice": "af_heart", "text": "Are you all done working for today?", "bytes": 23616, "sha256": "8e6916c69f2cdb92cd20b161f04023e2f7e1c38eb4f4979e56a061e8b7ed99fa", "src": "audio/coffee/81-agent.mp3"}, "user": {"seconds": 2.453, "voice": "af_bella", "text": "Yes, I'm all done. Just relaxing now.", "bytes": 30240, "sha256": "2fc0c244e44d9b7fe98b94e379fa56f4c6e875a4cf20a54f913393c227baf0e8", "src": "audio/coffee/81-user.mp3"}}, "82": {"agent": {"seconds": 1.259, "voice": "af_heart", "text": "Can I clear your cup?", "bytes": 15840, "sha256": "0b13216cf727572d137a2cb1f4110cc77728d235ae84abdf74c14d9e9bceae4b", "src": "audio/coffee/82-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "Yes, please take it. Thanks.", "bytes": 23328, "sha256": "723f1718b1d068c0634ecd09d6301c999029b0898e74b90ce4abbd5bb03a5f92", "src": "audio/coffee/82-user.mp3"}}, "83": {"agent": {"seconds": 2.005, "voice": "af_heart", "text": "Would you like a refill before you go?", "bytes": 24768, "sha256": "48f622ad05acd3cd9701fc5c9138c02ce32ef51c4ab87205999a9e643d7e8349", "src": "audio/coffee/83-agent.mp3"}, "user": {"seconds": 1.387, "voice": "af_bella", "text": "No thanks. I'm good.", "bytes": 17280, "sha256": "31754f7c85951796fd231e84a695af9e28177174cfa326054fe538f03561a36f", "src": "audio/coffee/83-user.mp3"}}, "84": {"agent": {"seconds": 2.027, "voice": "af_heart", "text": "Do you need the restroom before you head out?", "bytes": 25056, "sha256": "1c52075b654beb193990a1ac84c039f672f372b3cfa2df1618caa5cc56e87470", "src": "audio/coffee/84-agent.mp3"}, "user": {"seconds": 1.216, "voice": "af_bella", "text": "Where is the restroom?", "bytes": 15264, "sha256": "e0f6d435f02e955d4e07f370c9bcc9a2adeb97e38f02d53cf54e9482a15c2ca0", "src": "audio/coffee/84-user.mp3"}}, "85": {"agent": {"seconds": 1.771, "voice": "af_heart", "text": "It's down the hall, on the left.", "bytes": 21888, "sha256": "93539448d6ea75ca5c063b7c3df520c2e5d8d5f6edcd0ef140fba9c983885e37", "src": "audio/coffee/85-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_bella", "text": "Down the hall, on the left. Got it.", "bytes": 26496, "sha256": "b10b78133035626bcda445d8593be728b8515543c3a86390bcc7066213a6fe4e", "src": "audio/coffee/85-user.mp3"}}, "86": {"agent": {"seconds": 1.877, "voice": "af_heart", "text": "Anything else I can do for you?", "bytes": 23328, "sha256": "f4c7c359fd6e194a210a4ca672494c664c61e3a85c30c32391094397d5627ff5", "src": "audio/coffee/86-agent.mp3"}, "user": {"seconds": 1.557, "voice": "af_bella", "text": "No, I think I'm all set.", "bytes": 19296, "sha256": "e4009f7b55ee578053aa76619833fec74a7ec6701a4f8b07d1b2c0a18228efa5", "src": "audio/coffee/86-user.mp3"}}, "87": {"agent": {"seconds": 1.92, "voice": "af_heart", "text": "It was great chatting with you today!", "bytes": 23616, "sha256": "f1f5e1bfa1d1ded5ed45dbadd37283833d29ceea538f553ab427c49661e0125d", "src": "audio/coffee/87-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "You too. See you tomorrow.", "bytes": 23328, "sha256": "2f1f86eb3aaa02c2876393193093152105cd2539a8f4cf9319ccf5ab21aa29e0", "src": "audio/coffee/87-user.mp3"}}, "88": {"agent": {"seconds": 1.344, "voice": "af_heart", "text": "Have a wonderful day!", "bytes": 16704, "sha256": "48ec8204e647e4ba2f2dd96db27d666597b006d0c3ca2e03cac5556ae2766af7", "src": "audio/coffee/88-agent.mp3"}, "user": {"seconds": 1.024, "voice": "af_bella", "text": "You too. Bye!", "bytes": 12960, "sha256": "fed33c2ee771793a0fee94222209cd8faf46cf79a015b2747246a3350487d593", "src": "audio/coffee/88-user.mp3"}}}, "airport": {"airport-001": {"agent": {"seconds": 3.669, "voice": "af_bella", "text": "Welcome to the international terminal. How can I help you today?", "bytes": 44640, "sha256": "cd6c3e3ee8830528e3738d9a6d27f91df062dae88a3bc760ae1db634f460ca27", "src": "audio/airport/airport-001-agent.mp3"}, "user": {"seconds": 2.475, "voice": "af_heart", "text": "Hi, I'm flying to Tokyo this morning.", "bytes": 30528, "sha256": "97b00f4ff772f525b2f63c2be800a0d30463f8d449d6d3da53389a961d31d4e5", "src": "audio/airport/airport-001-user.mp3"}}, "airport-002": {"agent": {"seconds": 3.52, "voice": "af_bella", "text": "The departure hall is on level three. Do you need directions?", "bytes": 42912, "sha256": "eea8d7abd34c9961a2a40fb9f67562818fe2bbff8142c32104f03e1f2cdc0213", "src": "audio/airport/airport-002-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_heart", "text": "Yes, please. Where is the check-in area?", "bytes": 28800, "sha256": "4c656e0994266315944f7f1839978dcc9ef45cf21efbeccee49fa86001c9792d", "src": "audio/airport/airport-002-user.mp3"}}, "airport-003": {"agent": {"seconds": 2.325, "voice": "af_bella", "text": "Which airline are you flying with today, sir?", "bytes": 28512, "sha256": "5c5059e4199c340d249ea312b093108ca5b50b213d4dd4b3a15b36cf75ccb6f3", "src": "audio/airport/airport-003-agent.mp3"}, "user": {"seconds": 4.629, "voice": "af_heart", "text": "I'm flying with Air China, flight CA 1837.", "bytes": 56160, "sha256": "67bfb7a040b8b81b538205eb70f854e9fea5084a263ad6a32a87c877e9560a0e", "src": "audio/airport/airport-003-user.mp3"}}, "airport-004": {"agent": {"seconds": 3.115, "voice": "af_bella", "text": "That flight departs at nine forty from gate B twelve.", "bytes": 38016, "sha256": "2d92c7ce98300bb379754e4dc3bf33e2ea479ae94c4c7dff9d0e78e96ecc7321", "src": "audio/airport/airport-004-agent.mp3"}, "user": {"seconds": 4.352, "voice": "af_heart", "text": "My flight is CA 1837 at nine forty.", "bytes": 52992, "sha256": "0079f547937c644af280b46b8092bebf4a754f24e01eda65ab1eac420d95a0fe", "src": "audio/airport/airport-004-user.mp3"}}, "airport-005": {"agent": {"seconds": 3.499, "voice": "af_bella", "text": "Your airline uses Terminal Two. This is Terminal One.", "bytes": 42624, "sha256": "9f5a8b9eaf0245d84f0d0cfb476b85d91ae377e0f87ffdf86e2f7dbf0f6f7469", "src": "audio/airport/airport-005-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_heart", "text": "Oh no. How do I get to Terminal Two?", "bytes": 27072, "sha256": "4e6fb5d660f2dea6648ada9a69fc7db081ada9116a3704a47cb27ee888110338", "src": "audio/airport/airport-005-user.mp3"}}, "airport-006": {"agent": {"seconds": 3.413, "voice": "af_bella", "text": "Take the free shuttle bus outside exit number four.", "bytes": 41760, "sha256": "b8403ae479cda36f2ad9423d8883b0547ac2b3178015ca4e324fa86b8687abd1", "src": "audio/airport/airport-006-agent.mp3"}, "user": {"seconds": 2.645, "voice": "af_heart", "text": "The shuttle bus is outside exit four, right?", "bytes": 32544, "sha256": "67f1552875fd3d31106590a269c21b35c61c611782d90508294bff2c977a4d45", "src": "audio/airport/airport-006-user.mp3"}}, "airport-007": {"agent": {"seconds": 3.072, "voice": "af_bella", "text": "Yes. It runs every ten minutes, around the clock.", "bytes": 37440, "sha256": "5a31283ddf5734b762889708c7668d6369ecb0d5d168600457f24103ca34e57c", "src": "audio/airport/airport-007-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_heart", "text": "Great. I'll catch the next shuttle bus.", "bytes": 27072, "sha256": "f538f39136d936450f2c941e32d9e696aab44805660cdde2d65e0a01046daa3a", "src": "audio/airport/airport-007-user.mp3"}}, "airport-008": {"agent": {"seconds": 2.539, "voice": "af_bella", "text": "Do you need a luggage trolley? They're over there.", "bytes": 31104, "sha256": "336c2518e9ccd567935ae3d9d895df354ee5ba58cc43866b437beffe86f31b26", "src": "audio/airport/airport-008-agent.mp3"}, "user": {"seconds": 2.368, "voice": "af_heart", "text": "Yes, I need a trolley for my suitcase.", "bytes": 29088, "sha256": "c0302b31138b100f5330c62bf4707308097e11a24494c43825d09803ce00f67a", "src": "audio/airport/airport-008-user.mp3"}}, "airport-009": {"agent": {"seconds": 3.179, "voice": "af_bella", "text": "Trolleys cost two dollars. Coins or card only.", "bytes": 38880, "sha256": "949de7002a85ddaf78bd4598903960a2cc8f2e62150838faa3864452f140ef16", "src": "audio/airport/airport-009-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "Can I pay for the trolley by card?", "bytes": 23904, "sha256": "631b6f5086740481e6dbe0ac0893956b1a940fa43e7d10e9606bf8ecfa018fc7", "src": "audio/airport/airport-009-user.mp3"}}, "airport-010": {"agent": {"seconds": 2.603, "voice": "af_bella", "text": "Of course. Just tap your card on the reader.", "bytes": 31968, "sha256": "72699ef3fd4fb1c8b322358f4dd21694111ea39ebf4a47039921b77d6686392e", "src": "audio/airport/airport-010-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_heart", "text": "Thanks. Now where is the departure board?", "bytes": 28512, "sha256": "51f31c5603021fdc27a026b689a45f4ba0619414d216e2932396608144a95391", "src": "audio/airport/airport-010-user.mp3"}}, "airport-011": {"agent": {"seconds": 2.752, "voice": "af_bella", "text": "The big screens are above the information desk.", "bytes": 33696, "sha256": "c2a5ded07ecbda7f8a9769a806cd1c34c43db06b31d7d80c60355c10355fb4f5", "src": "audio/airport/airport-011-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_heart", "text": "I can see my flight on the screen.", "bytes": 23328, "sha256": "ee318eca91a9dec22967c73ebe3a8a74687de4db1eddd2adec9847dfdabdec85", "src": "audio/airport/airport-011-user.mp3"}}, "airport-012": {"agent": {"seconds": 2.56, "voice": "af_bella", "text": "Check-in opens three hours before your flight.", "bytes": 31392, "sha256": "9aafb09e4447d695055da906da31281fba063d425bdd240f62f8cc602aa51ae1", "src": "audio/airport/airport-012-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_heart", "text": "I'll head to the check-in counters now.", "bytes": 24192, "sha256": "0ea2104c573e8686660be45fe1af49b0aab55f218652dee530e8eec5327b901a", "src": "audio/airport/airport-012-user.mp3"}}, "airport-013": {"agent": {"seconds": 3.285, "voice": "af_bella", "text": "Good morning. May I see your passport and booking reference?", "bytes": 40032, "sha256": "bf9efefff9e45e05197a39ff9a2e1afa3a4c662f88631557216ef352219048cd", "src": "audio/airport/airport-013-agent.mp3"}, "user": {"seconds": 3.179, "voice": "af_heart", "text": "Here you are. My booking reference is X T seven K.", "bytes": 38880, "sha256": "1a1de9adeb795bef7c84c0903b3cd334d32559d1067ac3598c9fc17bd184d3b3", "src": "audio/airport/airport-013-user.mp3"}}, "airport-014": {"agent": {"seconds": 2.539, "voice": "af_bella", "text": "Thank you. Are you checking in any bags today?", "bytes": 31104, "sha256": "ed1fb1991924fd5cec04472d6bd0e257bdf68752651b58ed5eee315de3fd907b", "src": "audio/airport/airport-014-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_heart", "text": "Yes, I'd like to check in one suitcase.", "bytes": 28224, "sha256": "5ff99cdade1b69372234b68a6acc7a44f085842d5d3404e3051a3f622be2b208", "src": "audio/airport/airport-014-user.mp3"}}, "airport-015": {"agent": {"seconds": 2.816, "voice": "af_bella", "text": "Please place your bag on the scale, screen side up.", "bytes": 34560, "sha256": "96776776456a7dd3bf28fb249269c7c976eca5bc3f3d89e57fe0e0145ce20766", "src": "audio/airport/airport-015-agent.mp3"}, "user": {"seconds": 2.795, "voice": "af_heart", "text": "It's quite heavy. I hope it's under twenty kilos.", "bytes": 34272, "sha256": "62dd94054398ba33e563485c81bf837b36d3438a1efa37d478c37bfae40e5639", "src": "audio/airport/airport-015-user.mp3"}}, "airport-016": {"agent": {"seconds": 2.795, "voice": "af_bella", "text": "Twenty-three kilos. That's just over the limit.", "bytes": 34272, "sha256": "37208aad21371cb4cfa4e2ce84c688a324765b882046df49a7e0834ea7efd829", "src": "audio/airport/airport-016-agent.mp3"}, "user": {"seconds": 2.368, "voice": "af_heart", "text": "Oh no. How much is the extra charge?", "bytes": 29088, "sha256": "d51216f7977ab935987f2c4f07d96c6ca54b131d090982b7bf8b758b24c2acc2", "src": "audio/airport/airport-016-user.mp3"}}, "airport-017": {"agent": {"seconds": 2.944, "voice": "af_bella", "text": "It's thirty dollars per extra kilo, I'm afraid.", "bytes": 36000, "sha256": "f5383ee384d0d534ad7e37f65faefdc130f945ecabff5cc3195a13541eb9f64d", "src": "audio/airport/airport-017-agent.mp3"}, "user": {"seconds": 2.24, "voice": "af_heart", "text": "That's fine. I'll pay the extra fee.", "bytes": 27648, "sha256": "112b1d261ea3313b1fe7bbdd0b710320e42cd4c8c50cee5133cd57aaa36ebfec", "src": "audio/airport/airport-017-user.mp3"}}, "airport-018": {"agent": {"seconds": 2.261, "voice": "af_bella", "text": "Would you like a window or an aisle seat?", "bytes": 27936, "sha256": "f001bb24e65e0977f86cbfcfd5e1d2d120d46a8ca43abcb7732f598d4ce8e5e4", "src": "audio/airport/airport-018-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "A window seat, please, near the front.", "bytes": 26784, "sha256": "726e433290d66f0a5e82a0016c818d1760da167818a3855c488b6f8787c55dbb", "src": "audio/airport/airport-018-user.mp3"}}, "airport-019": {"agent": {"seconds": 2.901, "voice": "af_bella", "text": "I've put you in seat fourteen A. Is that okay?", "bytes": 35424, "sha256": "fdf5e2864b15f6c3f4a42cfc10bf0155eba96162b26989f32afe92362c7c83bb", "src": "audio/airport/airport-019-agent.mp3"}, "user": {"seconds": 2.517, "voice": "af_heart", "text": "Fourteen A sounds perfect. Thank you.", "bytes": 30816, "sha256": "f28c5953ebed7707ef9f862e6b274253e4c27d2cef59ca983f7351efb2de483e", "src": "audio/airport/airport-019-user.mp3"}}, "airport-020": {"agent": {"seconds": 2.773, "voice": "af_bella", "text": "Here's your boarding pass. Boarding starts at nine.", "bytes": 33984, "sha256": "355e55f264fc14c56565043e828dca98f60746890937274c615936d24548048b", "src": "audio/airport/airport-020-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_heart", "text": "What time does boarding start, sorry?", "bytes": 24768, "sha256": "69dd8d8f8857652bdd2d0f83e90605a7718dadf601631e08915795547a2de78e", "src": "audio/airport/airport-020-user.mp3"}}, "airport-021": {"agent": {"seconds": 2.923, "voice": "af_bella", "text": "Boarding starts at nine o'clock, gate B twelve.", "bytes": 35712, "sha256": "66e33666ba3a5b1f8e9c6b8eb968eb3eb39f1070ceba78c44c97ae44867857a2", "src": "audio/airport/airport-021-agent.mp3"}, "user": {"seconds": 2.859, "voice": "af_heart", "text": "Gate B twelve. Got it. Thank you very much.", "bytes": 35136, "sha256": "5d8dd144bfefb5d1f907ad9dafa6d4bbefc8f7ca0990c912fb1a84311e8c7f62", "src": "audio/airport/airport-021-user.mp3"}}, "airport-022": {"agent": {"seconds": 3.2, "voice": "af_bella", "text": "You're in boarding group three. Listen for the announcement.", "bytes": 39168, "sha256": "968b243ea4618e6a939cee90b7105a128be93c33aecf1ac8edf17bd13831dfe3", "src": "audio/airport/airport-022-agent.mp3"}, "user": {"seconds": 2.453, "voice": "af_heart", "text": "I'm in group three. I'll wait for the call.", "bytes": 30240, "sha256": "8c80c51d430cc76d9b9c5049ce05dde068ff6eb1841baab68f19caacb5a15e62", "src": "audio/airport/airport-022-user.mp3"}}, "airport-023": {"agent": {"seconds": 3.115, "voice": "af_bella", "text": "One last thing — any power banks in your hand luggage?", "bytes": 38016, "sha256": "4b5c1b080ea5709586b2a75c94f0e45d1f49073d2308f3727cf566e139088393", "src": "audio/airport/airport-023-agent.mp3"}, "user": {"seconds": 2.24, "voice": "af_heart", "text": "Yes, my power bank is in my backpack.", "bytes": 27648, "sha256": "64ae1ec8f619a11b63d9f03159cf93cbb82a598d59cf558fe02ea8ab87309d80", "src": "audio/airport/airport-023-user.mp3"}}, "airport-024": {"agent": {"seconds": 2.923, "voice": "af_bella", "text": "That's fine. Keep it with you, not in checked bags.", "bytes": 35712, "sha256": "3793e4d5f27a9b0ca4890bee9f1c1d3ba78fe7d57fb9915d6232324425f79dc1", "src": "audio/airport/airport-024-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_heart", "text": "Understood. I'll keep it in my backpack.", "bytes": 28512, "sha256": "769fdcec2437d4068c2be0227ab9d69d512545b947da1a55d4fa71225e867c33", "src": "audio/airport/airport-024-user.mp3"}}, "airport-025": {"agent": {"seconds": 3.648, "voice": "af_bella", "text": "Baggage drop for Air China is at counters thirty to forty.", "bytes": 44352, "sha256": "4c992409e73103131d1e5fb9463678b8186f377ec9e3a375874834e15937321a", "src": "audio/airport/airport-025-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_heart", "text": "Where is the baggage drop for Air China?", "bytes": 27072, "sha256": "ec25a9ac0ccb54d73655cc381691d2af36c24f182735f8e7c8c2f8671823b8a0", "src": "audio/airport/airport-025-user.mp3"}}, "airport-026": {"agent": {"seconds": 2.987, "voice": "af_bella", "text": "Follow the signs. It's just past the check-in hall.", "bytes": 36576, "sha256": "9c726c61315c8fd16c6eccf03490f1af82398f309c22141bda8e5bf62d558af9", "src": "audio/airport/airport-026-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_heart", "text": "I can see the signs. I'll follow them.", "bytes": 28512, "sha256": "ca8de2faf98215dc8f08132f54573a99cb36b934fa6dfed62194ebac282be745", "src": "audio/airport/airport-026-user.mp3"}}, "airport-027": {"agent": {"seconds": 2.731, "voice": "af_bella", "text": "Please have your boarding pass ready for scanning.", "bytes": 33408, "sha256": "6701ee476a923c4ae75be3e4612a2a4f85a1b0d8ec59efe3fdf8fa1387da79fd", "src": "audio/airport/airport-027-agent.mp3"}, "user": {"seconds": 2.389, "voice": "af_heart", "text": "My boarding pass is ready on my phone.", "bytes": 29376, "sha256": "7159d498e1ece1dac85f6a3fe13547fe9edc2a5512ad4f48be51ff4d491e0d9b", "src": "audio/airport/airport-027-user.mp3"}}, "airport-028": {"agent": {"seconds": 2.389, "voice": "af_bella", "text": "Scan it here, then put your bag on the belt.", "bytes": 29376, "sha256": "4eb6ca8f71cc8d5bf511237577ea64089952e220dd26e5377d63bf4c7d6a5eef", "src": "audio/airport/airport-028-agent.mp3"}, "user": {"seconds": 2.56, "voice": "af_heart", "text": "The scan worked. Now I'll lift my bag up.", "bytes": 31392, "sha256": "4a385e5bdaa16b40bcae67b6bdb9d64f7fb00a15a3e8f390b48fc51e9a7bd2cc", "src": "audio/airport/airport-028-user.mp3"}}, "airport-029": {"agent": {"seconds": 2.88, "voice": "af_bella", "text": "The tag is printing. Please attach it to the handle.", "bytes": 35136, "sha256": "ec65168b75aa0dbefa4eb2ca66da10bc13a401a70ddc5370277182b7731d796e", "src": "audio/airport/airport-029-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_heart", "text": "Where should I attach this luggage tag?", "bytes": 25920, "sha256": "ef36c77fed7c4c664f94aefc77d3cdd77ac54ea31335172648106525b75aeda4", "src": "audio/airport/airport-029-user.mp3"}}, "airport-030": {"agent": {"seconds": 2.688, "voice": "af_bella", "text": "Loop it through the top handle, nice and tight.", "bytes": 32832, "sha256": "b8d092b8d153f244e580a6ceb5abdaebf1f4723f574c6cfd03e86d8934cf54cf", "src": "audio/airport/airport-030-agent.mp3"}, "user": {"seconds": 2.453, "voice": "af_heart", "text": "It's attached. The tag feels secure now.", "bytes": 30240, "sha256": "0e5456a2200133b5f9886070881ae75e934d87de1957e65425c3ffc9c440cae6", "src": "audio/airport/airport-030-user.mp3"}}, "airport-031": {"agent": {"seconds": 2.987, "voice": "af_bella", "text": "Is anything fragile inside? We can add a sticker.", "bytes": 36576, "sha256": "685f6e4fd0953ce1e65a405f94c571b3081aa3c421255ace9c53f36b6b9a699b", "src": "audio/airport/airport-031-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_heart", "text": "Yes, there's a bottle of wine inside.", "bytes": 27360, "sha256": "a22a0c6487df339bb4b4e0bf0e954461415a23a0443a9ca422d4a672fdfda38b", "src": "audio/airport/airport-031-user.mp3"}}, "airport-032": {"agent": {"seconds": 2.709, "voice": "af_bella", "text": "I'll mark it fragile. It'll be handled with care.", "bytes": 33120, "sha256": "dd139ba6290a0f5634f731aba3cfc2bb2e7b2df60ccc3bd753f887d2f7863936", "src": "audio/airport/airport-032-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_heart", "text": "Thank you. Please handle it with care.", "bytes": 25920, "sha256": "087e7d3000bb7af32df069268ccbcdb07e1bd39bd039b14b07fa9921bbecc38f", "src": "audio/airport/airport-032-user.mp3"}}, "airport-033": {"agent": {"seconds": 3.179, "voice": "af_bella", "text": "Keep this claim receipt until you land in Tokyo.", "bytes": 38880, "sha256": "2f7e60fb206d689918926463563119ddb6575cc232670035482a3a51d71d79a3", "src": "audio/airport/airport-033-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "I'll keep the receipt until I land.", "bytes": 23904, "sha256": "4d0a971698b44a5c3091dd2d9b6a15ed581eddd7e8ae17176ec227a85bfae228", "src": "audio/airport/airport-033-user.mp3"}}, "airport-034": {"agent": {"seconds": 2.005, "voice": "af_bella", "text": "You can track your bag in the airline app.", "bytes": 24768, "sha256": "30374de2250625d62d047d045d2b54753fb03d2abc49e88384db82a56d5ed4ea", "src": "audio/airport/airport-034-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_heart", "text": "Can I track my bag in the app?", "bytes": 20736, "sha256": "1e53bc786b4d5e04447ababeaef49f8714d4d1367706339e1984322691e3e2ef", "src": "audio/airport/airport-034-user.mp3"}}, "airport-035": {"agent": {"seconds": 2.88, "voice": "af_bella", "text": "Yes. Just enter the tag number on your receipt.", "bytes": 35136, "sha256": "feadf4799c52c48039ba3407fe34330e293c5856bde78d555aef7b09c77f9b8d", "src": "audio/airport/airport-035-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "I'll enter the tag number right now.", "bytes": 23904, "sha256": "cbddc72c07353d04730730e8f7491d1178d04a329dc595b480b6701453bb90f9", "src": "audio/airport/airport-035-user.mp3"}}, "airport-036": {"agent": {"seconds": 2.923, "voice": "af_bella", "text": "All done. Your bag is on its way to Tokyo.", "bytes": 35712, "sha256": "ce33fe8a38b94721c30d1599a94508ff6ae4229925c66bafa130872f1c9969b0", "src": "audio/airport/airport-036-agent.mp3"}, "user": {"seconds": 2.368, "voice": "af_heart", "text": "Great. Now I'm heading to security check.", "bytes": 29088, "sha256": "46fedc7c122657b78df76f14e177b4e2ec0d1c701eaacf9f695df9303ef1eb37", "src": "audio/airport/airport-036-user.mp3"}}, "airport-037": {"agent": {"seconds": 2.645, "voice": "af_bella", "text": "Have your boarding pass and ID ready, please.", "bytes": 32544, "sha256": "2b2ee8eecbfa28b1d649b6bb5b8536f71e7598700085d8e1717faab870550fbd", "src": "audio/airport/airport-037-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_heart", "text": "My boarding pass and passport are ready.", "bytes": 28512, "sha256": "184788dfc0f79e65fe429668158752e1e4955995ae8cac39587a45de65a2b15f", "src": "audio/airport/airport-037-user.mp3"}}, "airport-038": {"agent": {"seconds": 2.133, "voice": "af_bella", "text": "Place all bags and trays on the belt.", "bytes": 26208, "sha256": "ed6e81ebe54ff0bf31ce89ec792efc336ac8c1c48315c41fa4c295dc8fc98a5e", "src": "audio/airport/airport-038-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_heart", "text": "I'll put my backpack in a tray.", "bytes": 21888, "sha256": "a60a678f17136d4adf5f9788e28a76cb2316236544e1e6d1078a6db63909f99e", "src": "audio/airport/airport-038-user.mp3"}}, "airport-039": {"agent": {"seconds": 3.051, "voice": "af_bella", "text": "Laptops must go in a separate tray, lid open.", "bytes": 37440, "sha256": "54dbb670bdf0719ef3fc76a0933f974c823369de70ade352699ce75dc9bb7174", "src": "audio/airport/airport-039-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_heart", "text": "My laptop is in a separate tray now.", "bytes": 26496, "sha256": "3def363675908b0dd8e6885814fe3ab1dab1b63cbccb9bc14a06668be259ae21", "src": "audio/airport/airport-039-user.mp3"}}, "airport-040": {"agent": {"seconds": 3.136, "voice": "af_bella", "text": "Any liquids? They must be under one hundred milliliters.", "bytes": 38304, "sha256": "51db4cb3b17fb699248862db001bb459baa6735d5a80e56f89bfcc3c1697a008", "src": "audio/airport/airport-040-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_heart", "text": "I have a small bottle of hand cream.", "bytes": 25344, "sha256": "044987484db726ed043d968221d98e3e6087ec4f2b6e60983a5371a3a6bf267c", "src": "audio/airport/airport-040-user.mp3"}}, "airport-041": {"agent": {"seconds": 2.411, "voice": "af_bella", "text": "That needs to go in the clear plastic bag.", "bytes": 29664, "sha256": "6693f0be53b07f78f00c0c3dcae4e75a027226ba9682f472553401d4656f4701", "src": "audio/airport/airport-041-agent.mp3"}, "user": {"seconds": 1.685, "voice": "af_heart", "text": "I'll put it in the plastic bag.", "bytes": 21024, "sha256": "c0be6e5746a88230ba8146149d6f0535394ad068e4f4e0c31a63846657b936f1", "src": "audio/airport/airport-041-user.mp3"}}, "airport-042": {"agent": {"seconds": 2.496, "voice": "af_bella", "text": "Please remove your shoes and belt as well.", "bytes": 30528, "sha256": "4470cfc5d7317fa67dbf4e820e47fe66829c51561b055b3753d12f17b73118a5", "src": "audio/airport/airport-042-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_heart", "text": "My shoes and belt are off already.", "bytes": 24192, "sha256": "f6bcff18f7c7a9a6c17c315f77deadea29ee45afdb9b676c41830fb6edc0c083", "src": "audio/airport/airport-042-user.mp3"}}, "airport-043": {"agent": {"seconds": 2.432, "voice": "af_bella", "text": "Empty your pockets into the tray, please.", "bytes": 29952, "sha256": "90b5aff71ac0804d7deaedf45f7ec3e18653ad4632c8ad518255fa0a81c6db2d", "src": "audio/airport/airport-043-agent.mp3"}, "user": {"seconds": 2.667, "voice": "af_heart", "text": "My pockets are empty. Phone's in the tray.", "bytes": 32832, "sha256": "8aa95bc65f588deffc10c4c304f8693fa0f60b919cdb1129de149922a5cf24b1", "src": "audio/airport/airport-043-user.mp3"}}, "airport-044": {"agent": {"seconds": 2.453, "voice": "af_bella", "text": "Step into the scanner and raise your arms.", "bytes": 30240, "sha256": "f64bbb1eeed53db482cc49ae2b4a98d681da99751266086c701b3a525e7a1c0b", "src": "audio/airport/airport-044-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_heart", "text": "I'm stepping in with my arms raised.", "bytes": 24480, "sha256": "e13a12cb71d179ac12cd763456c060f4e639876ac026ed3a2b37aab0295fd6c5", "src": "audio/airport/airport-044-user.mp3"}}, "airport-045": {"agent": {"seconds": 2.411, "voice": "af_bella", "text": "All clear. You can collect your things now.", "bytes": 29664, "sha256": "fb1d0a943382f32d19e7a1e34a0c39c5b7c359e0561d87f6c3722ddc2c11142e", "src": "audio/airport/airport-045-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "Thank you. I'll collect my things now.", "bytes": 26784, "sha256": "5b0489e1f6ffef7c06a153ce285b7febd845f9362d8f8cf027ef909044ffdb4b", "src": "audio/airport/airport-045-user.mp3"}}, "airport-046": {"agent": {"seconds": 2.496, "voice": "af_bella", "text": "Don't forget anything in the trays behind you.", "bytes": 30528, "sha256": "4bba21a3d8c956bb9f70d4a55a74c7e3b499db96d7157636b3534fc788f95057", "src": "audio/airport/airport-046-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_heart", "text": "Let me double-check the trays behind me.", "bytes": 27072, "sha256": "634cc21678e6c60193f6ab84a6f5df825de0065b148c964a6c412e04e3fd235d", "src": "audio/airport/airport-046-user.mp3"}}, "airport-047": {"agent": {"seconds": 2.923, "voice": "af_bella", "text": "Your watch set off the alarm. Please try again.", "bytes": 35712, "sha256": "56abcb66d5a3240260cb5d531d4fa40c934b8f00747a091111c0b6793e0ad1c1", "src": "audio/airport/airport-047-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_heart", "text": "Sorry, I forgot to take off my watch.", "bytes": 28224, "sha256": "1ef658c9fe0acd9158bb128b8f42c489c049f8b70aaf928878222601315c8346", "src": "audio/airport/airport-047-user.mp3"}}, "airport-048": {"agent": {"seconds": 2.048, "voice": "af_bella", "text": "No problem. You're good to go now.", "bytes": 25344, "sha256": "ef9d01b5cbc05dc52c2d746dff2ab235b55192a5c8f7d5d17104cbb08814ec84", "src": "audio/airport/airport-048-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_heart", "text": "Thanks for your help. Have a nice day.", "bytes": 25920, "sha256": "092269835805590b2f8a1aebbd26697066c4be0a684a572538475cf6cd896195", "src": "audio/airport/airport-048-user.mp3"}}, "airport-049": {"agent": {"seconds": 2.645, "voice": "af_bella", "text": "Next, please. Passport and boarding pass.", "bytes": 32544, "sha256": "fced9dcfdf5e5835ff858d379368fb40759b0d00c438bb2dd109d6715cf20d85", "src": "audio/airport/airport-049-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_heart", "text": "Here's my passport and my boarding pass.", "bytes": 28224, "sha256": "b092fe299d336d1d9300acc44be4f1d3c98121332ddce8ab37a56b4e13edd8a2", "src": "audio/airport/airport-049-user.mp3"}}, "airport-050": {"agent": {"seconds": 1.515, "voice": "af_bella", "text": "What is the purpose of your visit?", "bytes": 19008, "sha256": "2eb11143bf80e7c40331011d5dac0539136676596ed05fe4d17af2ef352a6762", "src": "audio/airport/airport-050-agent.mp3"}, "user": {"seconds": 2.432, "voice": "af_heart", "text": "I'm visiting Tokyo for a short holiday.", "bytes": 29952, "sha256": "0e83f57533894af1e7bd5c5fbd940f4edf5171c8db5e0997e51999a721ce6dd5", "src": "audio/airport/airport-050-user.mp3"}}, "airport-051": {"agent": {"seconds": 1.408, "voice": "af_bella", "text": "How long will you be staying?", "bytes": 17568, "sha256": "dc5c477c91eb5ea83145b3973eb57b344a44539add9645560571012fa87c58a4", "src": "audio/airport/airport-051-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_heart", "text": "I'll be staying for five days.", "bytes": 21600, "sha256": "9aa230e9eb030c93f683c46604b74807db52fd73eb4477689e63aa454f97a8c1", "src": "audio/airport/airport-051-user.mp3"}}, "airport-052": {"agent": {"seconds": 1.813, "voice": "af_bella", "text": "Where will you be staying in Tokyo?", "bytes": 22464, "sha256": "22b9208e4dcd9143ba2d6ed932a5e0047a8073d46a3ecdab040322ce0e15c317", "src": "audio/airport/airport-052-agent.mp3"}, "user": {"seconds": 2.517, "voice": "af_heart", "text": "At the Park Hotel near Tokyo Station.", "bytes": 30816, "sha256": "4709985c619cb55a116436153d21a057de411361dfb52633f9cb717bcabadf61", "src": "audio/airport/airport-052-user.mp3"}}, "airport-053": {"agent": {"seconds": 1.6, "voice": "af_bella", "text": "Do you have a return ticket?", "bytes": 19872, "sha256": "3ac19f2b8c426954a5c6bd2a090facb219762c18f356f5649a074d9e376fbcd3", "src": "audio/airport/airport-053-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "Yes, I fly back on Sunday morning.", "bytes": 26784, "sha256": "98f1ec8740b7f37ed428be6ce14b9d6947368ceec5bc0bb89c167d292909e3b8", "src": "audio/airport/airport-053-user.mp3"}}, "airport-054": {"agent": {"seconds": 1.408, "voice": "af_bella", "text": "What do you do for a living?", "bytes": 17568, "sha256": "b9af23f6022d9bc1972f31fad2162bd60aeb525054d254e2adc9ae4851658dd3", "src": "audio/airport/airport-054-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_heart", "text": "I'm an engineer at a car company.", "bytes": 25056, "sha256": "fa041965f06e478b4be1a6b84f7633ad5ee74beada54119a42e8f9d54f875149", "src": "audio/airport/airport-054-user.mp3"}}, "airport-055": {"agent": {"seconds": 1.941, "voice": "af_bella", "text": "Is this your first visit to Japan?", "bytes": 23904, "sha256": "393d8225cdd54a3745709f8879c93613756a166ec775d053957b927567b984ac", "src": "audio/airport/airport-055-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "Yes, it's my first time in Japan.", "bytes": 26784, "sha256": "a7f491f864a8eb112d37d0ec5310bc42b2b83294f1e8311b6c7cbd01eecd84f2", "src": "audio/airport/airport-055-user.mp3"}}, "airport-056": {"agent": {"seconds": 2.027, "voice": "af_bella", "text": "Please look at the camera for a photo.", "bytes": 25056, "sha256": "8640e78d298f05b566c1506fe7f9fb08eb68ea5594851f060580c32027fad247", "src": "audio/airport/airport-056-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_heart", "text": "Sure. I'm looking at the camera now.", "bytes": 25344, "sha256": "e0d0e9bc161e2a90e55fff21e93205d312afbd6e0d2cd601adc032130ff823bc", "src": "audio/airport/airport-056-user.mp3"}}, "airport-057": {"agent": {"seconds": 2.347, "voice": "af_bella", "text": "Place your right index finger on the scanner.", "bytes": 28800, "sha256": "1e62a55aeaab81ff4369f3e11e8188f932d6d228a46895a1ee80a405a7ef0b62", "src": "audio/airport/airport-057-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_heart", "text": "My finger is on the scanner now.", "bytes": 22752, "sha256": "ba96238bbade675a1927565bffb764bbf06a7eb02f87763ad5835e22634e05df", "src": "audio/airport/airport-057-user.mp3"}}, "airport-058": {"agent": {"seconds": 2.624, "voice": "af_bella", "text": "Everything looks good. Here's your passport back.", "bytes": 32256, "sha256": "e74705d9a678a1c8d52c8f7ad7c064645cc27c1a123043f1940340b431543220", "src": "audio/airport/airport-058-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_heart", "text": "Thank you very much, officer.", "bytes": 21312, "sha256": "fec1b3b9cca1bc973283440ac8fb494c43c1a2326e1bd3f0a3713326b5edc4be", "src": "audio/airport/airport-058-user.mp3"}}, "airport-059": {"agent": {"seconds": 1.792, "voice": "af_bella", "text": "How much cash are you carrying today?", "bytes": 22176, "sha256": "2e4433bf6a8680b3e391a6f019c939e381b5ec1d356e68bfe3578163eaf32af1", "src": "audio/airport/airport-059-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "I'm carrying about three hundred dollars.", "bytes": 26784, "sha256": "398997b1cd6ca25d844c681f25964abfdb1892cbe87a0494ae9db32595fdaab6", "src": "audio/airport/airport-059-user.mp3"}}, "airport-060": {"agent": {"seconds": 2.539, "voice": "af_bella", "text": "That's fine. Enjoy your stay in Japan.", "bytes": 31104, "sha256": "7c802dc455f7c561ebb4c78850bdf94d10c69cfd43fe1d246cedceebb19074c5", "src": "audio/airport/airport-060-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_heart", "text": "Thank you. I'm really looking forward to it.", "bytes": 28224, "sha256": "2d4c2b92379fc0764a3ac623fdef2b504766f0b1eb305ff63733d1aff6a53f70", "src": "audio/airport/airport-060-user.mp3"}}, "airport-061": {"agent": {"seconds": 2.688, "voice": "af_bella", "text": "The information desk is right behind you, miss.", "bytes": 32832, "sha256": "b72b4280bb52fd7f9fe6a70d350f9dabee5d967177ef46b5aa2eb5ade0c63305", "src": "audio/airport/airport-061-agent.mp3"}, "user": {"seconds": 2.496, "voice": "af_heart", "text": "Excuse me, which way is gate B twelve?", "bytes": 30528, "sha256": "8245257c46607df402a3f1f79ee1c4a0d6c12fedb7141fcc5afeb1832e599374", "src": "audio/airport/airport-061-user.mp3"}}, "airport-062": {"agent": {"seconds": 2.517, "voice": "af_bella", "text": "Gates B one to twenty are in the north pier.", "bytes": 30816, "sha256": "83960ccefbc95ca0c149b0fac4d3f992485cdf55a009295390aa0acd28141bea", "src": "audio/airport/airport-062-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "The north pier. How do I get there?", "bytes": 23904, "sha256": "24d33a04161476d9f4143339c466d15c67defd888ba98cb70d125cbac11b55e1", "src": "audio/airport/airport-062-user.mp3"}}, "airport-063": {"agent": {"seconds": 1.792, "voice": "af_bella", "text": "Follow the blue line on the floor.", "bytes": 22176, "sha256": "8fdac76ba842f5dfc989bdaa301b270098b040c6e83ebf675ce821963a18ff19", "src": "audio/airport/airport-063-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_heart", "text": "I'll follow the blue line on the floor.", "bytes": 25344, "sha256": "06b90d843d5b7a68c3000939b92738ba79252883cae9bb6e1130426995a081ee", "src": "audio/airport/airport-063-user.mp3"}}, "airport-064": {"agent": {"seconds": 2.176, "voice": "af_bella", "text": "It's about a fifteen-minute walk from here.", "bytes": 26784, "sha256": "8fc0edacaf95553efd9559603c9fffb44b45f73e2855912280bd7fd47fddb70d", "src": "audio/airport/airport-064-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "Fifteen minutes? I'd better hurry up.", "bytes": 26784, "sha256": "8879e6c2921089060208217771105768c6a99a9ee72f5656cf9217db967a72a5", "src": "audio/airport/airport-064-user.mp3"}}, "airport-065": {"agent": {"seconds": 2.752, "voice": "af_bella", "text": "Or take the shuttle train. It's much faster.", "bytes": 33696, "sha256": "dafc1e44b0cef994bd3de61eabd8b0bec12ab45c0895381042c782ffbf0668e1", "src": "audio/airport/airport-065-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_heart", "text": "Where can I catch the shuttle train?", "bytes": 23616, "sha256": "3a81e6554496cd32e42cc99b35883b81d2ce3c99e16254ae097fdc9c44f25078", "src": "audio/airport/airport-065-user.mp3"}}, "airport-066": {"agent": {"seconds": 2.176, "voice": "af_bella", "text": "Down the escalator, then turn left.", "bytes": 26784, "sha256": "dc077f9d48687f53897929e1a17e700e456929bacc843feae6b88dd13cceff6a", "src": "audio/airport/airport-066-agent.mp3"}, "user": {"seconds": 2.624, "voice": "af_heart", "text": "Down the escalator and turn left. Thanks.", "bytes": 32256, "sha256": "0622776ea5d4f19fe836c3e7c55e754b0bca326d9b87466577f5fded61d062c7", "src": "audio/airport/airport-066-user.mp3"}}, "airport-067": {"agent": {"seconds": 1.856, "voice": "af_bella", "text": "The train leaves every three minutes.", "bytes": 23040, "sha256": "001aaedfca151b5f77483f66de72d08f687e1843dee2ea71608daac5adc536ba", "src": "audio/airport/airport-067-agent.mp3"}, "user": {"seconds": 2.539, "voice": "af_heart", "text": "Every three minutes. That's very convenient.", "bytes": 31104, "sha256": "1842f72686a97df677c88252e072c06250e9f04a3b5ad69e6e17ed1f64430fd6", "src": "audio/airport/airport-067-user.mp3"}}, "airport-068": {"agent": {"seconds": 2.517, "voice": "af_bella", "text": "There are shops and cafés near gate B ten.", "bytes": 30816, "sha256": "2f7399837072001f733147cf8efbabd8b4d2049847907629cc3559a56ffb4aa5", "src": "audio/airport/airport-068-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_heart", "text": "I'd like to grab a coffee first.", "bytes": 21600, "sha256": "daf55ab9033eec9db41af0355fcb6a0251b444c3336100c74fba013872e57c83", "src": "audio/airport/airport-068-user.mp3"}}, "airport-069": {"agent": {"seconds": 2.155, "voice": "af_bella", "text": "The coffee shop is next to the bookstore.", "bytes": 26496, "sha256": "4495f26fb667baf4c071079d2fe65f25e6f6bbc9e281ebb7e7ea6598ab2db38a", "src": "audio/airport/airport-069-agent.mp3"}, "user": {"seconds": 2.496, "voice": "af_heart", "text": "A latte to go, please. I'm in a hurry.", "bytes": 30528, "sha256": "081367e2c154461cfde656bde6ae6eeaa24cb49b68a29815a6c1966bae14f209", "src": "audio/airport/airport-069-user.mp3"}}, "airport-070": {"agent": {"seconds": 2.517, "voice": "af_bella", "text": "Restrooms are on your right, past the café.", "bytes": 30816, "sha256": "68432b57b21fa5c9ffb30ded48c4f42c5883d091a60d3bea7c025c109f0412ab", "src": "audio/airport/airport-070-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_heart", "text": "I'll use the restroom before boarding.", "bytes": 24480, "sha256": "8ba56825406ffc54c17a84b740dc010e6540f1fc0983ffa06c3a8704f835134e", "src": "audio/airport/airport-070-user.mp3"}}, "airport-071": {"agent": {"seconds": 2.667, "voice": "af_bella", "text": "Free charging stations are by the windows.", "bytes": 32832, "sha256": "3f2e9b620cd45feb3b83cecb615375f1ebbcd538bb69c5b3c255c685ac7964d8", "src": "audio/airport/airport-071-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "I need to charge my phone quickly.", "bytes": 23904, "sha256": "ea0c3726b9c8f38a06324dfefd56ae2b50e420b3eb72ceb9b79b6d6b05e9485e", "src": "audio/airport/airport-071-user.mp3"}}, "airport-072": {"agent": {"seconds": 2.539, "voice": "af_bella", "text": "Gate B twelve is just around the corner.", "bytes": 31104, "sha256": "5aaf08893eddd70d27dfe00a1db3251214983f2502580d1b5edc3b4e925ec0d1", "src": "audio/airport/airport-072-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_heart", "text": "I can see gate B twelve now.", "bytes": 23616, "sha256": "ea16fe96c6e18744e48b6fc00cddb22402076b1f41e02eeea45e54eadb0628d8", "src": "audio/airport/airport-072-user.mp3"}}, "airport-073": {"agent": {"seconds": 3.755, "voice": "af_bella", "text": "Now boarding flight CA eighteen thirty-seven to Tokyo.", "bytes": 45792, "sha256": "5300ff850037af4aab814cae497d572164ce6a77addead670ee604950817f2dc", "src": "audio/airport/airport-073-agent.mp3"}, "user": {"seconds": 2.133, "voice": "af_heart", "text": "That's my flight. I'll join the queue.", "bytes": 26208, "sha256": "befb6ef8c2f4f3e0bc3123e488b3bffd081f243ecb7a00216cdcc3c91780dce2", "src": "audio/airport/airport-073-user.mp3"}}, "airport-074": {"agent": {"seconds": 1.963, "voice": "af_bella", "text": "Please have your boarding pass ready.", "bytes": 24192, "sha256": "f9b0a684374bb63e32e7ac8ed9237f84f40f561189d77dc5cd2b7ee5fe0dd6c4", "src": "audio/airport/airport-074-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_heart", "text": "My boarding pass is ready in my hand.", "bytes": 28224, "sha256": "f25f7c6d199f84c18bae11eb31f34d2cc26e8f6d5572dd578a98c76fb1eef42c", "src": "audio/airport/airport-074-user.mp3"}}, "airport-075": {"agent": {"seconds": 2.88, "voice": "af_bella", "text": "We're now boarding group three. Group three only.", "bytes": 35136, "sha256": "5fdb7ec17ba633098f3f824e9b4a888a212320585af0df2c95f3ba6816bf6c72", "src": "audio/airport/airport-075-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_heart", "text": "I'm group three. This is my turn.", "bytes": 28224, "sha256": "419bd369fd89cc10a993aee6ef80737356077c3d79366ddd94ea56f9e67d695e", "src": "audio/airport/airport-075-user.mp3"}}, "airport-076": {"agent": {"seconds": 2.795, "voice": "af_bella", "text": "The scanner didn't read it. Try holding it flat.", "bytes": 34272, "sha256": "ac9c65db4c00783fd6be90db911d7621190e6e7167e535c757001e099a3cc705", "src": "audio/airport/airport-076-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_heart", "text": "Let me hold my phone a bit flatter.", "bytes": 24192, "sha256": "3a16e2bba11063d6a0fbef940795058fbe6cd16662398a742c2fc389d85192bf", "src": "audio/airport/airport-076-user.mp3"}}, "airport-077": {"agent": {"seconds": 3.051, "voice": "af_bella", "text": "There we go. Seat fourteen A, enjoy your flight.", "bytes": 37440, "sha256": "3054276242fd41519a278cd9a6e1d7c06347cb3222ac92f2447f4354550e90d6", "src": "audio/airport/airport-077-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_heart", "text": "Fourteen A. Thank you very much.", "bytes": 25920, "sha256": "c6c212eca662e1ec2b8994a70d98409fa34fd28be1d5a2d74b6c72c72d2790d6", "src": "audio/airport/airport-077-user.mp3"}}, "airport-078": {"agent": {"seconds": 2.027, "voice": "af_bella", "text": "Your bag is too big for the cabin, sir.", "bytes": 25056, "sha256": "bf121dabbfc927e97aa5f8c9eceb5d56e653d443ddeabc97b57efda0118a7be8", "src": "audio/airport/airport-078-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_heart", "text": "Oh really? Can I check it at the gate?", "bytes": 27360, "sha256": "8a8bd8c93aa9dc21ce2052ce00760ee4749858fd90d38b12c518e37781c473c4", "src": "audio/airport/airport-078-user.mp3"}}, "airport-079": {"agent": {"seconds": 2.389, "voice": "af_bella", "text": "Yes, we'll tag it and check it for free.", "bytes": 29376, "sha256": "e5f13e28f4a285fa3a333d7cb9b5940f5c371acbb7cf703951c1a7a3852236d0", "src": "audio/airport/airport-079-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "That's kind. Please tag it for me.", "bytes": 26784, "sha256": "3f68033deac088e12cd0bb5fbc787dd8301ce3ceed8de789569efa522980883b", "src": "audio/airport/airport-079-user.mp3"}}, "airport-080": {"agent": {"seconds": 2.347, "voice": "af_bella", "text": "Families with small children board first.", "bytes": 28800, "sha256": "123c1dca86073dad4863a4ab083993d4b7c6c7975fb472ffd699be9c9f035fac", "src": "audio/airport/airport-080-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_heart", "text": "I'll wait until they call my group.", "bytes": 25920, "sha256": "8aea57e0477d426f92817f233390ea8a86bf27e177e774e497a0353040789efa", "src": "audio/airport/airport-080-user.mp3"}}, "airport-081": {"agent": {"seconds": 2.453, "voice": "af_bella", "text": "Priority boarding is through the left lane.", "bytes": 30240, "sha256": "e194ee1dba9e54ff1d24b69d7d54443f937a0ed4289fc299f36ed3f405521bb2", "src": "audio/airport/airport-081-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_heart", "text": "I'll use the regular lane, thank you.", "bytes": 24768, "sha256": "5813144658bcf9bc0cecb1bf6b645e7643e5357c5c5109aa672bde35ff05ad5f", "src": "audio/airport/airport-081-user.mp3"}}, "airport-082": {"agent": {"seconds": 2.581, "voice": "af_bella", "text": "Please keep your passport out until you're seated.", "bytes": 31680, "sha256": "68267ba1ef115e21c7b649cf80d0337b83d1baa2fa39b4220a7922adaa72675a", "src": "audio/airport/airport-082-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_heart", "text": "I'll keep my passport out until I'm seated.", "bytes": 28800, "sha256": "9153089dac32fe0bca5f886829db85798e40cd0a97bd3b05607ad5a9a5a1fec4", "src": "audio/airport/airport-082-user.mp3"}}, "airport-083": {"agent": {"seconds": 2.603, "voice": "af_bella", "text": "Welcome aboard. Your seat is on the left.", "bytes": 31968, "sha256": "85cfb80bb980454f7fa142feb5f1a6e14727229025ca29f795906ab1cf15e073", "src": "audio/airport/airport-083-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_heart", "text": "Thank you. I'm happy to be aboard.", "bytes": 25056, "sha256": "b1b2eb81cd2cfec75cbc47d97659d81663fea6f50606089f5d595e8084600bb7", "src": "audio/airport/airport-083-user.mp3"}}, "airport-084": {"agent": {"seconds": 2.517, "voice": "af_bella", "text": "Please stow your bag and take your seat quickly.", "bytes": 30816, "sha256": "a16b4d1a476c141b7921f9b842cdf280143e54cad6bbed72b9372a9207a24de4", "src": "audio/airport/airport-084-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_heart", "text": "I'll stow my bag and sit down now.", "bytes": 25056, "sha256": "722eaba284a8d3123d4ecef6a751af76846bc939ec268d366dd3215b768a82f5", "src": "audio/airport/airport-084-user.mp3"}}, "airport-085": {"agent": {"seconds": 3.093, "voice": "af_bella", "text": "Please fasten your seatbelt. We're about to push back.", "bytes": 37728, "sha256": "ae386e738638e18727be6c966eebf49ec837c1a39690068dfbb4ee0a5d0daa2a", "src": "audio/airport/airport-085-agent.mp3"}, "user": {"seconds": 2.581, "voice": "af_heart", "text": "My seatbelt is fastened. I'm ready to go.", "bytes": 31680, "sha256": "25e123e8a2596458ec02dc5cd39607a5f8cb62d4bee271542acbf62be549e634", "src": "audio/airport/airport-085-user.mp3"}}, "airport-086": {"agent": {"seconds": 2.709, "voice": "af_bella", "text": "Tray tables up and seats upright for takeoff.", "bytes": 33120, "sha256": "1633fd67fe51bad637a855eab5e9542b59887ffd7c60a661452738d37dcf9d0c", "src": "audio/airport/airport-086-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_heart", "text": "My tray table is up and locked.", "bytes": 24192, "sha256": "40e60b055d1a043187a0780e2ca9e9b4af20c1cb918ddb974cce090242736aca", "src": "audio/airport/airport-086-user.mp3"}}, "airport-087": {"agent": {"seconds": 1.6, "voice": "af_bella", "text": "Would you like something to drink?", "bytes": 19872, "sha256": "145cada86459a31b12320309f08a1b043ecbe96533414920fc32ec102f0c725f", "src": "audio/airport/airport-087-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_heart", "text": "Just a glass of water, please.", "bytes": 22176, "sha256": "f2f55f56b773371f473f1f03f67be51db53129f53f730abbac017e1c2066e7a2", "src": "audio/airport/airport-087-user.mp3"}}, "airport-088": {"agent": {"seconds": 2.197, "voice": "af_bella", "text": "Chicken or beef for your main course?", "bytes": 27072, "sha256": "245eb4812d915554c067db85e9d3c46a22555c50e227e819b33f5da143b9e36c", "src": "audio/airport/airport-088-agent.mp3"}, "user": {"seconds": 1.557, "voice": "af_heart", "text": "I'll have the chicken, please.", "bytes": 19296, "sha256": "4bb97afbb891c13d8c9dacdd3d5679789d37b6451e00d981def023fc2014c80d", "src": "audio/airport/airport-088-user.mp3"}}, "airport-089": {"agent": {"seconds": 2.347, "voice": "af_bella", "text": "Do you have any food allergies we should know?", "bytes": 28800, "sha256": "c507902e27574d7621b3b08a9ce6b9bade2a7abb7d18bd98840399706d0c03fa", "src": "audio/airport/airport-089-agent.mp3"}, "user": {"seconds": 2.901, "voice": "af_heart", "text": "No allergies, but I'm vegetarian, actually.", "bytes": 35424, "sha256": "5f510f651637fe7abe33d4a7da5f64cf9230b2270d332b4b523f0a1d8c8feda2", "src": "audio/airport/airport-089-user.mp3"}}, "airport-090": {"agent": {"seconds": 2.837, "voice": "af_bella", "text": "We have a vegetarian meal available for you.", "bytes": 34848, "sha256": "5bf164d69bc54226e80c4c922ebf87be9802a653232595ff1e10c02b214aee2a", "src": "audio/airport/airport-090-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_heart", "text": "The vegetarian meal would be perfect.", "bytes": 28512, "sha256": "48d4c610e1d6a8aaf5859fcd9ac15cf9369f8d9ee84565e856970ea2ee22edab", "src": "audio/airport/airport-090-user.mp3"}}, "airport-091": {"agent": {"seconds": 2.816, "voice": "af_bella", "text": "More coffee or tea? We're doing a second round.", "bytes": 34560, "sha256": "4f488a0cbaf87a69b08874243f98cfa13eb31cf2f557226a70ac9928e8416cc5", "src": "audio/airport/airport-091-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_heart", "text": "A cup of green tea, please.", "bytes": 21888, "sha256": "ddeadae436ed9823190d1a29fea8128cd7fd1dd84c8ad2c4cb873fd5a5ab2744", "src": "audio/airport/airport-091-user.mp3"}}, "airport-092": {"agent": {"seconds": 2.347, "voice": "af_bella", "text": "Would you like a blanket? It's getting chilly.", "bytes": 28800, "sha256": "199bd0387d5652d0a41f294e741128c9e875e2b62f7d69f784afb727eb8c2610", "src": "audio/airport/airport-092-agent.mp3"}, "user": {"seconds": 2.389, "voice": "af_heart", "text": "Yes, please. A blanket would be lovely.", "bytes": 29376, "sha256": "57ed4b7446e8d14a0392f94c39236d3dbe279de4ea6f05f19e739f17fe91c550", "src": "audio/airport/airport-092-user.mp3"}}, "airport-093": {"agent": {"seconds": 2.901, "voice": "af_bella", "text": "The entertainment system is in the seatback screen.", "bytes": 35424, "sha256": "481c03af4ac88c196864e206ec6abde3e312fc123b108b68276ff0e2a0334638", "src": "audio/airport/airport-093-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_heart", "text": "How do I turn on the movie screen?", "bytes": 23040, "sha256": "0c9cb7abf345c8310d2c590fb5ebba9340116ce6360457055f6115bc64ff22fd", "src": "audio/airport/airport-093-user.mp3"}}, "airport-094": {"agent": {"seconds": 2.539, "voice": "af_bella", "text": "Please raise your window shade for landing.", "bytes": 31104, "sha256": "176294e7990511d43339745442cbc29a9c6a94f6274119b0be24fb4aabd9e32d", "src": "audio/airport/airport-094-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_heart", "text": "My window shade is up already.", "bytes": 23328, "sha256": "edfd5045ebc14418abbed2e8ed2c7ad1e6b777129528f9850db887e09a6df2ed", "src": "audio/airport/airport-094-user.mp3"}}, "airport-095": {"agent": {"seconds": 2.987, "voice": "af_bella", "text": "We're expecting some turbulence. Please stay seated.", "bytes": 36576, "sha256": "288c00088de9bb75ffbe76a8f8fa97fba8820cabf3afcb89f9720bc3c7c2d393", "src": "audio/airport/airport-095-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_heart", "text": "I'll stay seated with my belt fastened.", "bytes": 27072, "sha256": "ce60d9288837b3ed94b15965ad6dfc713b97d603537f2acefa12bf5df919e050", "src": "audio/airport/airport-095-user.mp3"}}, "airport-096": {"agent": {"seconds": 1.856, "voice": "af_bella", "text": "Thank you for flying with us today.", "bytes": 23040, "sha256": "e6179eaa0e7a95ae80ceaf8bac695ff277fc610da7a26f64df69b8959ecef3b8", "src": "audio/airport/airport-096-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_heart", "text": "Thank you. It was a smooth flight.", "bytes": 22752, "sha256": "2d17977b08a8ad3918c92fa583a419846063fad776f4c2b53829acbe3ec75a2f", "src": "audio/airport/airport-096-user.mp3"}}, "airport-097": {"agent": {"seconds": 3.819, "voice": "af_bella", "text": "Welcome to Tokyo. Please join the foreign passports line.", "bytes": 46656, "sha256": "eaf5b706b1590358d4964a60d76bfc79a87fb1e6865759d8a1e9f88c3a63b170", "src": "audio/airport/airport-097-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_heart", "text": "I'm joining the foreign passports line now.", "bytes": 28224, "sha256": "449e0d7e4e3a7f4fb9d34cfeb8d09c6b4a3c286b1165de777b098bb565ff0003", "src": "audio/airport/airport-097-user.mp3"}}, "airport-098": {"agent": {"seconds": 2.005, "voice": "af_bella", "text": "Have you filled in your arrival card?", "bytes": 24768, "sha256": "98df3b2e384287fa68d1e9c7cbbc7ae84842a2462530ecef8ced228a74f477bf", "src": "audio/airport/airport-098-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "Yes, I filled it in on the plane.", "bytes": 23904, "sha256": "568694ccb7fe6ae585fed81f1876d768323420d28e6e3008f6871bc79870d34c", "src": "audio/airport/airport-098-user.mp3"}}, "airport-099": {"agent": {"seconds": 1.515, "voice": "af_bella", "text": "What is the purpose of your visit?", "bytes": 19008, "sha256": "2eb11143bf80e7c40331011d5dac0539136676596ed05fe4d17af2ef352a6762", "src": "audio/airport/airport-099-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_heart", "text": "Tourism. I'm here for five days.", "bytes": 27360, "sha256": "ea54c9d08129e089c30fe9254b834b081e5b97754e5ebd9def21e6de9a4b4aa9", "src": "audio/airport/airport-099-user.mp3"}}, "airport-100": {"agent": {"seconds": 1.643, "voice": "af_bella", "text": "Where are you staying in Tokyo?", "bytes": 20448, "sha256": "57bf568eb0b71b5e023f794b0008fe57cd062911d4ec5d4b67ab0ffe45d78ce5", "src": "audio/airport/airport-100-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_heart", "text": "At the Park Hotel in Shinjuku.", "bytes": 25344, "sha256": "3b10a1e7a86af68d3b5d9c030806486615d4e287df49936f9e606d7c827db260", "src": "audio/airport/airport-100-user.mp3"}}, "airport-101": {"agent": {"seconds": 1.664, "voice": "af_bella", "text": "Do you have anything to declare?", "bytes": 20736, "sha256": "eb56f3d9aa3a7b1ea9c6e120e6248e1f4f62949baaa53602de7acea97135d29e", "src": "audio/airport/airport-101-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_heart", "text": "I have one bottle of wine to declare.", "bytes": 27072, "sha256": "a5678451050bb4457a58b74c2d58fdde219d7b9a6fba46c9d7a02b843f0e2b96", "src": "audio/airport/airport-101-user.mp3"}}, "airport-102": {"agent": {"seconds": 2.517, "voice": "af_bella", "text": "One bottle is within the duty-free limit.", "bytes": 30816, "sha256": "80293d75fe1c8739a07b60f9b6f62412e2c7001c30ddd46a81d05b4fe53d4f3b", "src": "audio/airport/airport-102-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_heart", "text": "Good. It's a gift for my friend.", "bytes": 23328, "sha256": "6921eb1ed4cf197f5bc3f7ea6a5bba792b8bb106d1b22ba07c85a6c9290bd5c9", "src": "audio/airport/airport-102-user.mp3"}}, "airport-103": {"agent": {"seconds": 2.197, "voice": "af_bella", "text": "Are you carrying any fresh food or fruit?", "bytes": 27072, "sha256": "d6e8ef45724b448bade9fd5229187fa878ab021b3b7bbb30008ac80ac6ee1812", "src": "audio/airport/airport-103-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_heart", "text": "No fresh food, just some chocolate.", "bytes": 26496, "sha256": "70601662a2597877654c7f9aebc13790ee28a2116c87dc250df949ed2c74c2e5", "src": "audio/airport/airport-103-user.mp3"}}, "airport-104": {"agent": {"seconds": 2.389, "voice": "af_bella", "text": "Any medicine? Some types need a permit.", "bytes": 29376, "sha256": "b35460546c08882b123ca6bb0d6d3c1109ccd9c2afcc90c2a238384324ec132f", "src": "audio/airport/airport-104-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_heart", "text": "Just some vitamins, nothing special.", "bytes": 26784, "sha256": "03640d0a1ed74045ac58b41da2225283d540dfea449e11d66fce019390fd19b3", "src": "audio/airport/airport-104-user.mp3"}}, "airport-105": {"agent": {"seconds": 1.707, "voice": "af_bella", "text": "How much cash are you bringing in?", "bytes": 21312, "sha256": "0a70ff71dd7e2b58dfab267236c5752041d19472da14adc6141071fef7dee758", "src": "audio/airport/airport-105-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_heart", "text": "About three hundred dollars in cash.", "bytes": 25632, "sha256": "83080130db2ab658e2cbff9f139be314cdef9f281423dddce36f2b58a6e7f921", "src": "audio/airport/airport-105-user.mp3"}}, "airport-106": {"agent": {"seconds": 2.453, "voice": "af_bella", "text": "Are you bringing in any expensive electronics?", "bytes": 30240, "sha256": "8aedae6b5bf86ebf9e725dec04dddacf68022c92de6bebf8e057313a9a04dc7a", "src": "audio/airport/airport-106-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_heart", "text": "Just my laptop and my camera.", "bytes": 23616, "sha256": "9f8f71d5e680d55f20261e5ee92cca218994d2caa591e6b5ac9189f24fea72d0", "src": "audio/airport/airport-106-user.mp3"}}, "airport-107": {"agent": {"seconds": 2.048, "voice": "af_bella", "text": "Please walk through the green channel.", "bytes": 25344, "sha256": "e114ad3272771fd3a1ec88877efbbae33a8e6abd8f88560d5074d81e8d8b7788", "src": "audio/airport/airport-107-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "I'll go through the green channel now.", "bytes": 23904, "sha256": "05ee85a9d701a14c0e5c0e1b34300e63cd7400596b001df1242c1dda6b6f6836", "src": "audio/airport/airport-107-user.mp3"}}, "airport-108": {"agent": {"seconds": 3.093, "voice": "af_bella", "text": "Enjoy your stay in Japan. Have a wonderful trip.", "bytes": 37728, "sha256": "3a3a81a9e53008097e66f2b67e8c1607cb94b56b6a8f1a5a1c02e3489f6c046c", "src": "audio/airport/airport-108-agent.mp3"}, "user": {"seconds": 2.709, "voice": "af_heart", "text": "Thank you. I'm excited to explore Tokyo.", "bytes": 33120, "sha256": "22988f17e7f6f5028c0c3a60040795abe3890d9ebcf42a74ed5dc81787b373dd", "src": "audio/airport/airport-108-user.mp3"}}, "airport-109": {"agent": {"seconds": 2.901, "voice": "af_bella", "text": "Baggage claim is downstairs, past customs.", "bytes": 35424, "sha256": "71c874371f0e9e24b0f1955624db57069844d3418fb75188b21ff9527fe2ae1e", "src": "audio/airport/airport-109-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_heart", "text": "Where do I find the baggage carousels?", "bytes": 24768, "sha256": "f7444f1a39a8a2792bfc381a0713bec5b81d81894281baf5423112e79cc744db", "src": "audio/airport/airport-109-user.mp3"}}, "airport-110": {"agent": {"seconds": 2.325, "voice": "af_bella", "text": "Your flight's bags are on carousel seven.", "bytes": 28512, "sha256": "91d4e68d7b2ce1cf5df83a0c55e03c6cc0fd9c3ff7f21fb52d52eb7f2345cfb1", "src": "audio/airport/airport-110-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_heart", "text": "Carousel seven. I'll wait over there.", "bytes": 28224, "sha256": "0cc81c57785dc95c39e7409dd2bf75f8139a99daff4e75c12aaa8fb5fc84a5cc", "src": "audio/airport/airport-110-user.mp3"}}, "airport-111": {"agent": {"seconds": 3.392, "voice": "af_bella", "text": "Bags from Tokyo flights usually take twenty minutes.", "bytes": 41472, "sha256": "03e45d154f8c7bd61b07365cde19f96f32ecc85588a15f875e8b922ad56dd217", "src": "audio/airport/airport-111-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_heart", "text": "Twenty minutes? I'll wait patiently then.", "bytes": 28224, "sha256": "3761beade718ff194f0ee14e104a1474ba277e41bfa9b90163d62b8136c2c29e", "src": "audio/airport/airport-111-user.mp3"}}, "airport-112": {"agent": {"seconds": 2.197, "voice": "af_bella", "text": "Is that your black suitcase going around?", "bytes": 27072, "sha256": "2d1e927c11c71f61b3ce73e42d39957c4be841fd5b013b14cec70556839daf52", "src": "audio/airport/airport-112-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_heart", "text": "No, mine has a red strap on it.", "bytes": 25056, "sha256": "1cf3c2508f5faa3caf64c4140513fa096f8cd99117e18719bfeaa64a42364b12", "src": "audio/airport/airport-112-user.mp3"}}, "airport-113": {"agent": {"seconds": 2.624, "voice": "af_bella", "text": "The carousel has stopped. Is your bag missing?", "bytes": 32256, "sha256": "5a7837fd24c8725b09264d26f27bd269e978fdc8aeeb3dd28ad02e97f81f1aa3", "src": "audio/airport/airport-113-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_heart", "text": "Yes, my suitcase hasn't come out yet.", "bytes": 27360, "sha256": "6c9b9a704e2589f6ba476239a4fc8b16c80a80118232d0219b98bf39349c0e0b", "src": "audio/airport/airport-113-user.mp3"}}, "airport-114": {"agent": {"seconds": 2.773, "voice": "af_bella", "text": "Let's file a report. Can you describe your bag?", "bytes": 33984, "sha256": "5b3a53c919b30ea8bef180d2690b5348714d808b8388bc850a2b45b2224991c9", "src": "audio/airport/airport-114-agent.mp3"}, "user": {"seconds": 2.24, "voice": "af_heart", "text": "It's a large black suitcase with wheels.", "bytes": 27648, "sha256": "e37a01e435753e3a80a82282905deaff6fb808df6adf4a4f5384434bcab96541", "src": "audio/airport/airport-114-user.mp3"}}, "airport-115": {"agent": {"seconds": 2.347, "voice": "af_bella", "text": "Any stickers or tags to identify it?", "bytes": 28800, "sha256": "dcc27fc86f475ab91166d7199937eb7c55b5e663dda464f0434bd1c1c928cea7", "src": "audio/airport/airport-115-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_heart", "text": "There's a red strap and a wine sticker.", "bytes": 26496, "sha256": "8dc1653c664844d8f24e0b2667ec84e1cb7d4fe46275dd7eeb7257fb25e9f7f6", "src": "audio/airport/airport-115-user.mp3"}}, "airport-116": {"agent": {"seconds": 1.877, "voice": "af_bella", "text": "What's the tag number on your receipt?", "bytes": 23328, "sha256": "9e491ecaec4377fbe84201a404b7ce0e7ae0358a784cc4ed0984d3741c356c2e", "src": "audio/airport/airport-116-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_heart", "text": "The tag number is eight four two nine.", "bytes": 25920, "sha256": "4883d6592e02d24c49150d4c283a73e0d4de2c77ef30f971e772eb02234ac79a", "src": "audio/airport/airport-116-user.mp3"}}, "airport-117": {"agent": {"seconds": 2.283, "voice": "af_bella", "text": "We'll deliver it to your hotel tomorrow.", "bytes": 28224, "sha256": "7adf3ffcea705bd53d49b54117091d389708aa4b0396377eb044f749fabdcce7", "src": "audio/airport/airport-117-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_heart", "text": "Please deliver it to the Park Hotel.", "bytes": 25920, "sha256": "e869e3cb09570d68c621a4ccd5ceafdad45086f111eaf28d4180c2fe9a5d83fe", "src": "audio/airport/airport-117-user.mp3"}}, "airport-118": {"agent": {"seconds": 2.112, "voice": "af_bella", "text": "Here's some money for essentials tonight.", "bytes": 25920, "sha256": "27f4062c1d783ae6e2c8ff009c627652a501417ac8caafe96333e22ed42d1a5e", "src": "audio/airport/airport-118-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_heart", "text": "Thank you. That's very kind of you.", "bytes": 23904, "sha256": "d3938a08988da94831517868fae2a49c4f08ed9d6204b555db98298e40f37ddb", "src": "audio/airport/airport-118-user.mp3"}}, "airport-119": {"agent": {"seconds": 1.856, "voice": "af_bella", "text": "We'll call you the moment we find it.", "bytes": 23040, "sha256": "8f39b5b94e2ac6816a8176ed7926e65e9871b3c139becd5d4215abad5be84cee", "src": "audio/airport/airport-119-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_heart", "text": "My phone number is on the report.", "bytes": 25056, "sha256": "ec2355b98b829fa4ee2a11e648be9f456d14a9b841ac4631a4fbdc1dfd417b63", "src": "audio/airport/airport-119-user.mp3"}}, "airport-120": {"agent": {"seconds": 2.133, "voice": "af_bella", "text": "Good news — your bag just arrived.", "bytes": 26208, "sha256": "60e8b71886ee7879e9c9de215ae9e5e3abefcca0da9adac3f546f0e03937186f", "src": "audio/airport/airport-120-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_heart", "text": "That's wonderful news. Thank you so much.", "bytes": 28800, "sha256": "de84f7176b01ff3b7cfe24b34c433fcfb42333ac0b6ad865f84b8d81df57edab", "src": "audio/airport/airport-120-user.mp3"}}, "airport-121": {"agent": {"seconds": 3.52, "voice": "af_bella", "text": "Attention: flight CA eighteen thirty-eight is delayed.", "bytes": 42912, "sha256": "41418af99385cf30ac576bd135dee6094550bfcc8c01ebc110d7058545b61e08", "src": "audio/airport/airport-121-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_heart", "text": "My flight is delayed? How long for?", "bytes": 28224, "sha256": "510ccb545394dbab32d84b05784492d745b69749b6c28c3e58bf88540bce7a43", "src": "audio/airport/airport-121-user.mp3"}}, "airport-122": {"agent": {"seconds": 2.347, "voice": "af_bella", "text": "About two hours, due to heavy fog.", "bytes": 28800, "sha256": "cd8809e9488fb822d3ab2959069d240f68c1b035f0f99b04bc87faa925c2ff17", "src": "audio/airport/airport-122-agent.mp3"}, "user": {"seconds": 2.261, "voice": "af_heart", "text": "Two hours because of fog. I see.", "bytes": 27936, "sha256": "f46137412ade8c68660dc864ba2cad86e5ec2485a27878dd68f7de32f7918cab", "src": "audio/airport/airport-122-user.mp3"}}, "airport-123": {"agent": {"seconds": 2.027, "voice": "af_bella", "text": "Please check the screens for updates.", "bytes": 25056, "sha256": "0bb164c8702c1b09508deabdee0a8b8106852fb09bb2b3c5a006c91287646418", "src": "audio/airport/airport-123-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_heart", "text": "I'll keep an eye on the screens.", "bytes": 21600, "sha256": "f48a441502eafc0eacb553e4888736cbb9d26d363d437ed4759de6f47d3a1d05", "src": "audio/airport/airport-123-user.mp3"}}, "airport-124": {"agent": {"seconds": 1.856, "voice": "af_bella", "text": "We can rebook you on the next flight.", "bytes": 23040, "sha256": "364c2b7b588c38316c15d642b8ca4c3264bd453c542da20cc732a94675adee7f", "src": "audio/airport/airport-124-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_heart", "text": "Can you rebook me on the next flight?", "bytes": 22176, "sha256": "171100d5d097fa649cc83f8d9b1c37d02e8b655d9d57c6976c995f3f8cc33f85", "src": "audio/airport/airport-124-user.mp3"}}, "airport-125": {"agent": {"seconds": 2.027, "voice": "af_bella", "text": "The next flight leaves at four fifteen.", "bytes": 25056, "sha256": "5980f7f20d4571f696dec1057c98a84a31df511a166466a121942274ca48b1c3", "src": "audio/airport/airport-125-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_heart", "text": "Four fifteen works fine for me.", "bytes": 23040, "sha256": "b23d8ca3ee6851c3788d7125cededa65ca25471072b7dca3922d53c4717d5304", "src": "audio/airport/airport-125-user.mp3"}}, "airport-126": {"agent": {"seconds": 1.771, "voice": "af_bella", "text": "Here's a meal voucher for the delay.", "bytes": 21888, "sha256": "234411930901ddc157d3501a2b0330a32c3d70adc41f11f8ff4b50bbee54380f", "src": "audio/airport/airport-126-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_heart", "text": "Thank you for the meal voucher.", "bytes": 20736, "sha256": "205157eef3234d504b8c0061a0ae0c937d948ed12b9395d521f30ce4fc7c0fa4", "src": "audio/airport/airport-126-user.mp3"}}, "airport-127": {"agent": {"seconds": 2.304, "voice": "af_bella", "text": "You can use it at any restaurant upstairs.", "bytes": 28224, "sha256": "0a0c63beb34f3d66d56e048910fc2119dc7de39319e1cb123f58961a6434f291", "src": "audio/airport/airport-127-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_heart", "text": "I'll grab lunch upstairs, then.", "bytes": 22752, "sha256": "3e61b1af5c1a6e4e7b580b1e2155bc893ecb95ab934748d86b70e46f28dff13a", "src": "audio/airport/airport-127-user.mp3"}}, "airport-128": {"agent": {"seconds": 3.371, "voice": "af_bella", "text": "The airline lounge is open to delayed passengers.", "bytes": 41184, "sha256": "fafc3d2de163febbf34a26de61881c7611ee3c8934549d0d89d732ccbde51d52", "src": "audio/airport/airport-128-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_heart", "text": "Can I wait in the lounge instead?", "bytes": 22752, "sha256": "fbf000c9a057d08e89fb78312eb82ecaeeace1fb470cb592bf44222024eaa506", "src": "audio/airport/airport-128-user.mp3"}}, "airport-129": {"agent": {"seconds": 2.475, "voice": "af_bella", "text": "Of course. Show your boarding pass at the door.", "bytes": 30528, "sha256": "506179cbdfee534a67c0f9295e7deaa115258722943df233a5def8775345a596", "src": "audio/airport/airport-129-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_heart", "text": "I'll show my boarding pass at the door.", "bytes": 25056, "sha256": "7daaf5044f29b938720e9be51f7af712781726cababe7c6a6e64dcea1b98b664", "src": "audio/airport/airport-129-user.mp3"}}, "airport-130": {"agent": {"seconds": 2.283, "voice": "af_bella", "text": "Boarding will now start at gate C five.", "bytes": 28224, "sha256": "87194110c0dceee7ee8b70af123670200559c27bcd96445918bfe94e44143cee", "src": "audio/airport/airport-130-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_heart", "text": "Gate C five. I'll head there now.", "bytes": 27360, "sha256": "f939fed62ef983ac95a900984c580f6116005fb26b7e631fe41288464c7530b3", "src": "audio/airport/airport-130-user.mp3"}}, "airport-131": {"agent": {"seconds": 2.816, "voice": "af_bella", "text": "We apologize again for the inconvenience.", "bytes": 34560, "sha256": "15122c87cd3256dba3ec9bcdc9936a397c02019914ff480201bdade5b781b0f7", "src": "audio/airport/airport-131-agent.mp3"}, "user": {"seconds": 2.261, "voice": "af_heart", "text": "These things happen. Thanks for your help.", "bytes": 27936, "sha256": "323621c3f803e45e052243d10a03bee6e81df1720c6030e4f6f511ae52247209", "src": "audio/airport/airport-131-user.mp3"}}, "airport-132": {"agent": {"seconds": 2.667, "voice": "af_bella", "text": "Your new seat is twenty-two K, window side.", "bytes": 32832, "sha256": "a3a40b568af84ef4e9620cf49a340fe65522a0e6823f238a611a8f4f8839e8ce", "src": "audio/airport/airport-132-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_heart", "text": "Twenty-two K. I like window seats.", "bytes": 28224, "sha256": "ffc6b0c8c48084adbbddc399f356db161cf6fa4a53973f586bf08e0745e94c7d", "src": "audio/airport/airport-132-user.mp3"}}, "airport-133": {"agent": {"seconds": 2.645, "voice": "af_bella", "text": "We've landed late. You may miss your connection.", "bytes": 32544, "sha256": "dad83000558ace78421e06d03143d7dbda5ca9a312811ee3a4890c72211bff80", "src": "audio/airport/airport-133-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_heart", "text": "I think I've missed my connecting flight.", "bytes": 25920, "sha256": "75bedd585ae2f631b4c6b8e43365b5ba41ffcc57b3d207632060ae74cdb710c1", "src": "audio/airport/airport-133-user.mp3"}}, "airport-134": {"agent": {"seconds": 2.347, "voice": "af_bella", "text": "The transfer desk is near gate D two.", "bytes": 28800, "sha256": "5fbfd9562fab99134fd6e81922d44cfa10750cb4ae632e9411526bd78c171a70", "src": "audio/airport/airport-134-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_heart", "text": "Where is the transfer desk, please?", "bytes": 23040, "sha256": "13826c59bbb789b0f0ef707344b6d8401d51d3f95d787541a703e09715c58746", "src": "audio/airport/airport-134-user.mp3"}}, "airport-135": {"agent": {"seconds": 2.475, "voice": "af_bella", "text": "Let me check the next available flight for you.", "bytes": 30528, "sha256": "0c11e57a191900225fc5fca69cceac1cb4a53e371718836cc3c7121e4f518318", "src": "audio/airport/airport-135-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_heart", "text": "Please check the next available flight.", "bytes": 25920, "sha256": "a527433e91a318da972fac1c98553c6f5c1fdd66d7ef9faba77966721f20e7c6", "src": "audio/airport/airport-135-user.mp3"}}, "airport-136": {"agent": {"seconds": 1.749, "voice": "af_bella", "text": "The next flight is tomorrow at eight.", "bytes": 21600, "sha256": "4c1d1bb6653c4b340b06e341899bb7290d368dabcba43c8bf917b0ebf3ac800d", "src": "audio/airport/airport-136-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_heart", "text": "Tomorrow at eight? That's quite early.", "bytes": 26496, "sha256": "9480615582eb535007a79a6fb967a105682db90f3e8d9e6791051fab2f4cd908", "src": "audio/airport/airport-136-user.mp3"}}, "airport-137": {"agent": {"seconds": 1.963, "voice": "af_bella", "text": "We'll put you in a hotel for the night.", "bytes": 24192, "sha256": "cacdc6a30074d75ed07d93da7bdb833a5a9044ca7dba28b5a41d3fd6d262d2a5", "src": "audio/airport/airport-137-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_heart", "text": "A hotel for the night sounds good.", "bytes": 23040, "sha256": "203b46337994545e1fab5ad802bb520cbc15f55ae271beae840c2c3bef89f2bc", "src": "audio/airport/airport-137-user.mp3"}}, "airport-138": {"agent": {"seconds": 2.176, "voice": "af_bella", "text": "Here's a voucher for dinner and breakfast.", "bytes": 26784, "sha256": "898d9ea5d085edf4432a261f13b5ff8d1f47db363c560b2f96195430390157cb", "src": "audio/airport/airport-138-agent.mp3"}, "user": {"seconds": 2.603, "voice": "af_heart", "text": "Dinner and breakfast are included. Great.", "bytes": 31968, "sha256": "b63b0a6283c4248efaa2e96cb3d6f9f6461bacc6129d1df221c873376f7194e5", "src": "audio/airport/airport-138-user.mp3"}}, "airport-139": {"agent": {"seconds": 2.731, "voice": "af_bella", "text": "The shuttle to the hotel leaves in ten minutes.", "bytes": 33408, "sha256": "53db1d03582a3b963054b74b87341f70d55471ba28902ac1474c3ed97a225db9", "src": "audio/airport/airport-139-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_heart", "text": "I'll catch the hotel shuttle in ten minutes.", "bytes": 28224, "sha256": "8b3215cb25ae534634e9ade78045daecb2f8107eea3324957db49198878e4101", "src": "audio/airport/airport-139-user.mp3"}}, "airport-140": {"agent": {"seconds": 2.88, "voice": "af_bella", "text": "Your bag will go straight to the final destination.", "bytes": 35136, "sha256": "afae4ba5d855f90cb06cb878b91c2003366af20dc706afb7b34a01ae24b0b26c", "src": "audio/airport/airport-140-agent.mp3"}, "user": {"seconds": 2.368, "voice": "af_heart", "text": "My bag goes straight through? Perfect.", "bytes": 29088, "sha256": "c77ad1831cd2094d6379b84568cfa58be1435dfb9e61d32f64e1acc963d26b1f", "src": "audio/airport/airport-140-user.mp3"}}, "airport-141": {"agent": {"seconds": 2.091, "voice": "af_bella", "text": "Here's your new boarding pass for tomorrow.", "bytes": 25920, "sha256": "8d4af97a211e5e4ae8db505ed261fb03c643151f0de82ff3b14105c6ad5c9148", "src": "audio/airport/airport-141-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_heart", "text": "Thank you for the new boarding pass.", "bytes": 21600, "sha256": "186d733dfbc51b309939e4d4ede282301344dcb264d5d4316b4d6ec1b52c041e", "src": "audio/airport/airport-141-user.mp3"}}, "airport-142": {"agent": {"seconds": 2.411, "voice": "af_bella", "text": "Please be at the gate by seven fifteen.", "bytes": 29664, "sha256": "c3c5a6f45dcd0dbaca0fdb232e46c2998b8fea31a0f89d75335ebbefdd5e51da", "src": "audio/airport/airport-142-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_heart", "text": "I'll be at the gate by seven fifteen.", "bytes": 25920, "sha256": "84b0e9a5be556e748918f76f603ae6b120c02ac123b8518cad4fe117b35012ed", "src": "audio/airport/airport-142-user.mp3"}}, "airport-143": {"agent": {"seconds": 2.325, "voice": "af_bella", "text": "Is there anything else I can do for you?", "bytes": 28512, "sha256": "398a735ea6c9d4d5c111a95a718a1d73f8f2109e5c85455062d85b74c8bb3124", "src": "audio/airport/airport-143-agent.mp3"}, "user": {"seconds": 2.24, "voice": "af_heart", "text": "No, you've been very helpful. Thanks.", "bytes": 27648, "sha256": "8d8b1f353a9d507f10dc048542da1494c5a64ff07328dd7ee6c22b730d73535f", "src": "audio/airport/airport-143-user.mp3"}}, "airport-144": {"agent": {"seconds": 2.389, "voice": "af_bella", "text": "Safe travels, and sorry for the trouble.", "bytes": 29376, "sha256": "433f650c25a5817a39b632adfeadc5b683ded66314a027870179fca51365565b", "src": "audio/airport/airport-144-agent.mp3"}, "user": {"seconds": 2.667, "voice": "af_heart", "text": "Thanks. I'll plan longer layovers next time.", "bytes": 32832, "sha256": "63ae832af383277275e6fcd3170da1cc36cd8acefb4d699c2740aa15f9ec1aa6", "src": "audio/airport/airport-144-user.mp3"}}}, "hotel": {"hotel-001": {"agent": {"seconds": 3.243, "voice": "af_heart", "text": "Good morning, Grand Plaza Hotel. How may I help you?", "bytes": 39744, "sha256": "b99b3fb0e50543a98c5534f68148cb97a249dcae56175b80f337efe441b11c6c", "src": "audio/hotel/hotel-001-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_bella", "text": "Good morning. I would like to book a room.", "bytes": 27360, "sha256": "047b90e910c80dbfca0f21f7597a55fea70c8961fc9a0311e091772256b196b3", "src": "audio/hotel/hotel-001-user.mp3"}}, "hotel-002": {"agent": {"seconds": 2.432, "voice": "af_heart", "text": "Of course. What dates are you planning to stay?", "bytes": 29952, "sha256": "04efc6e00484e0d7363eac9557fe4e20d2a00d8a93c9342dd0570200c119ecd6", "src": "audio/hotel/hotel-002-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "From Friday to Sunday, two nights.", "bytes": 26784, "sha256": "cb87c4bf0a84e0922f2bb78a95013a9178680a90f34605e725f4f47e931b86d6", "src": "audio/hotel/hotel-002-user.mp3"}}, "hotel-003": {"agent": {"seconds": 1.899, "voice": "af_heart", "text": "And what type of room would you prefer?", "bytes": 23616, "sha256": "e9cdbe6442de72c30f0fbfa1ceabec4d5c6fb75b99802735dbc85509d196e21b", "src": "audio/hotel/hotel-003-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "A double room, please.", "bytes": 18144, "sha256": "0fe3852961fdf41de0f3adb701851d2fc203609947cb9bc4827ff69473558efd", "src": "audio/hotel/hotel-003-user.mp3"}}, "hotel-004": {"agent": {"seconds": 2.859, "voice": "af_heart", "text": "Would you prefer a smoking or non-smoking room?", "bytes": 35136, "sha256": "8b6cbd8657af8bdd42710e8d2a41820ddc417f68ba87b88b366f79b84c2fe0a3", "src": "audio/hotel/hotel-004-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "A non-smoking room, please.", "bytes": 21312, "sha256": "01fb35cca3b8c99703bf21f0877c868f1464b272071d9881c70d8f955c7c5e11", "src": "audio/hotel/hotel-004-user.mp3"}}, "hotel-005": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "May I have your full name, please?", "bytes": 21312, "sha256": "2e0c2c47d89ce322333de9d13443d50ad9b584d5a53d858c88ee0715478f830e", "src": "audio/hotel/hotel-005-agent.mp3"}, "user": {"seconds": 1.408, "voice": "af_bella", "text": "My name is Li Zhengfang.", "bytes": 17568, "sha256": "f6a238374937f19cf7dda5ab8f06c557efb27d8c05ae7ccb099e0d985305a6c6", "src": "audio/hotel/hotel-005-user.mp3"}}, "hotel-006": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "And a phone number where we can reach you?", "bytes": 25920, "sha256": "d729f5389ef75bfccd953b1382e0ae8326a79da2eb1472a52538b48ba6352359", "src": "audio/hotel/hotel-006-agent.mp3"}, "user": {"seconds": 4.629, "voice": "af_bella", "text": "My mobile number is 555-0134.", "bytes": 56160, "sha256": "1c5e2ef647df367e966e88095bd9085e242c8ed4abe0766edbcd5076a3fdbd3d", "src": "audio/hotel/hotel-006-user.mp3"}}, "hotel-007": {"agent": {"seconds": 2.325, "voice": "af_heart", "text": "Do you need breakfast included in your rate?", "bytes": 28512, "sha256": "1b325dbea5d2489eb4d7ddbeb186df668f5922332259ee4d69ea9df4ba37abcd", "src": "audio/hotel/hotel-007-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "Yes, please include breakfast.", "bytes": 22464, "sha256": "6cd521ed5e96d84eca259592011367da4ea6a2673fef309c46e7c14e0a93c576", "src": "audio/hotel/hotel-007-user.mp3"}}, "hotel-008": {"agent": {"seconds": 2.24, "voice": "af_heart", "text": "We have a sea view room for a little extra.", "bytes": 27648, "sha256": "80929a10c92146198a8868958c8e6f3fbc32c780f037331e958a451bcb6fdee7", "src": "audio/hotel/hotel-008-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_bella", "text": "That sounds nice. I will take it.", "bytes": 25920, "sha256": "9f503068fcb407e794f5497b2170f221b6e4801d93705a163fa336bde0d85e09", "src": "audio/hotel/hotel-008-user.mp3"}}, "hotel-009": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "What time do you expect to arrive?", "bytes": 23040, "sha256": "0c9ec9abd374a6dd51f2e02d30ec6240ccb8083e82cd7a82e590d87aee96826d", "src": "audio/hotel/hotel-009-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_bella", "text": "I will arrive around six in the evening.", "bytes": 25056, "sha256": "96fea893da67b95db8911cabc47fdfa902f8c7a9c265c8e541920c34e500afe1", "src": "audio/hotel/hotel-009-user.mp3"}}, "hotel-010": {"agent": {"seconds": 2.24, "voice": "af_heart", "text": "Would you like a quiet room on a high floor?", "bytes": 27648, "sha256": "83f40f608bd8e0b2f016614011f124f5cef69699444166a9fd54e602bb143a00", "src": "audio/hotel/hotel-010-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Yes, a high floor would be great.", "bytes": 25632, "sha256": "3076a4182137b735ae4ac6bfb502f009dfd851639530b88820052cbfc462eeeb", "src": "audio/hotel/hotel-010-user.mp3"}}, "hotel-011": {"agent": {"seconds": 2.24, "voice": "af_heart", "text": "Is there anything else I can do for you?", "bytes": 27648, "sha256": "9fcea3fcba11e7666d89c732a47be55916bd6c075e445331313fd6c8e9a61d02", "src": "audio/hotel/hotel-011-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_bella", "text": "No, thank you. That is everything.", "bytes": 25344, "sha256": "eb8fb67fc0e7d34cb58bdbabd13e8ac877556a9bcb39187cc192e46f4f89269f", "src": "audio/hotel/hotel-011-user.mp3"}}, "hotel-012": {"agent": {"seconds": 2.795, "voice": "af_heart", "text": "Your reservation is confirmed. See you soon!", "bytes": 34272, "sha256": "63964828309d2979236a39642e4a25b41389f6f1de2933fbceab9a7f3aa4eccb", "src": "audio/hotel/hotel-012-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "Thank you very much. Goodbye!", "bytes": 23616, "sha256": "afb1944ab228140fb1a87c4fc4d4ddb0a36c80ab9e2a5aaf1a97a6b65e9914f4", "src": "audio/hotel/hotel-012-user.mp3"}}, "hotel-013": {"agent": {"seconds": 2.048, "voice": "af_heart", "text": "Welcome to the Grand Plaza Hotel!", "bytes": 25344, "sha256": "3946d161f5702b7ea3275dc473fb7d543bc351fdcff2c726e096acb37495a147", "src": "audio/hotel/hotel-013-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "Hello! I have a reservation.", "bytes": 24192, "sha256": "ece5194b07906943d0cd8448d370531396529180d34d43bd83153b73d984f5bc", "src": "audio/hotel/hotel-013-user.mp3"}}, "hotel-014": {"agent": {"seconds": 1.515, "voice": "af_heart", "text": "May I have your name, please?", "bytes": 19008, "sha256": "f35bf949f1a1647795b9673c042beece54b418ea228e0129f05fe53f53556368", "src": "audio/hotel/hotel-014-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_bella", "text": "It is Li Zhengfang. I booked online.", "bytes": 28800, "sha256": "5b724072e849d530f6eb2fd2ea1e3426fe77b22c4f783e5e4be24a0069a79b06", "src": "audio/hotel/hotel-014-user.mp3"}}, "hotel-015": {"agent": {"seconds": 2.155, "voice": "af_heart", "text": "Could I see your passport or ID, please?", "bytes": 26496, "sha256": "58d446fc4768c8d44d31bd5751d13b8fd1c9a8868cfd09a035d9a6bf7bfca0e4", "src": "audio/hotel/hotel-015-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Sure, here is my passport.", "bytes": 20448, "sha256": "2ccb328926020623a249acd5b1e534ce90b6fee4d81ee47fd2897dd699a2d260", "src": "audio/hotel/hotel-015-user.mp3"}}, "hotel-016": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "How long will you be staying with us?", "bytes": 22752, "sha256": "175a668a14fb7e9531fba841fc1de9dd5b658e7344b7117431b437de429bc628", "src": "audio/hotel/hotel-016-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "Just two nights, until Sunday.", "bytes": 23616, "sha256": "b7cfc495eba3b959c793deeb95b35f2597b60b33fe2a1d10cc237c04ad3f3945", "src": "audio/hotel/hotel-016-user.mp3"}}, "hotel-017": {"agent": {"seconds": 3.541, "voice": "af_heart", "text": "Your room is 1208, on the twelfth floor.", "bytes": 43200, "sha256": "1446d660ee7e76a26bfa530dfb293869f6a2bd42039e9d88436a58c9efe10d15", "src": "audio/hotel/hotel-017-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Great. Where is the elevator?", "bytes": 23904, "sha256": "507215e3382af1619e7ffc84849266679061dc35e14d5b2fdae399171fd0ba52", "src": "audio/hotel/hotel-017-user.mp3"}}, "hotel-018": {"agent": {"seconds": 2.197, "voice": "af_heart", "text": "The elevators are just past the lobby.", "bytes": 27072, "sha256": "802c3a5ee7cd207c4f27ab5146759167977b3e6f9310c938ef6f2a02362cb988", "src": "audio/hotel/hotel-018-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_bella", "text": "Thank you. What time is checkout?", "bytes": 25920, "sha256": "9410b5d155a78748a3323c51a3858b85fbecb8c2a4e39c3cdd43085aed09cef3", "src": "audio/hotel/hotel-018-user.mp3"}}, "hotel-019": {"agent": {"seconds": 1.813, "voice": "af_heart", "text": "Checkout time is at twelve noon.", "bytes": 22464, "sha256": "4a7c6f340185e3954a8f4a5e1ad92926412bee153f95d9a7fc3b5468d82fc8eb", "src": "audio/hotel/hotel-019-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "Is late checkout possible?", "bytes": 19008, "sha256": "5fd5fd4f8b81c21e1fa52e600ef19f08014ec91bb3079359b167477dadeb895b", "src": "audio/hotel/hotel-019-user.mp3"}}, "hotel-020": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "Yes, until two o'clock for free.", "bytes": 25920, "sha256": "971827236891ff5b0ea8a7c2e65c196e8ac6de58cddc323eb4820acd1e187d72", "src": "audio/hotel/hotel-020-agent.mp3"}, "user": {"seconds": 1.707, "voice": "af_bella", "text": "Perfect, thank you very much.", "bytes": 21312, "sha256": "f97e2937b5bde83389296d1bb3044e7a0b22141084dca5056bc8b66a71b9bdef", "src": "audio/hotel/hotel-020-user.mp3"}}, "hotel-021": {"agent": {"seconds": 2.325, "voice": "af_heart", "text": "Here is your key card. Enjoy your stay!", "bytes": 28512, "sha256": "c93106e3b596ea2267b2d9081e9f99036ed8983f6db107b94e9051fa493e48ee", "src": "audio/hotel/hotel-021-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "Thanks! Is Wi-Fi free here?", "bytes": 23616, "sha256": "ac22e4b59c4c793f9fb226975e772b578482f3df57f20e865d23534c6766b436", "src": "audio/hotel/hotel-021-user.mp3"}}, "hotel-022": {"agent": {"seconds": 1.941, "voice": "af_heart", "text": "The password is on the card sleeve.", "bytes": 23904, "sha256": "a78f12b8e6893342a349b5e53f2e7dc5082f2d7d343d15b8e7adaed58d183931", "src": "audio/hotel/hotel-022-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Could you help me with my bags?", "bytes": 20160, "sha256": "55193e3a0e49c74583efdb25b3b00d25b851706d751a31463c54a1c5cde82f8a", "src": "audio/hotel/hotel-022-user.mp3"}}, "hotel-023": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "Of course, the bellboy will assist you.", "bytes": 25920, "sha256": "b4f86d816311b237ad3baccca407fa56aad8a4389e309bb63b49ebe39ea76135", "src": "audio/hotel/hotel-023-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "That would be wonderful, thanks.", "bytes": 19584, "sha256": "53653b4c68f933fb06d3262a3cdcb82b5c8b7941eca510682b18d39d4fd26ae4", "src": "audio/hotel/hotel-023-user.mp3"}}, "hotel-024": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "Is there anything else you need right now?", "bytes": 25920, "sha256": "b1917b0319c2d1f34073fd635a0110cf1de2b3a674258e38aae1a53e764217e9", "src": "audio/hotel/hotel-024-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "No, I am all set. Thanks!", "bytes": 22752, "sha256": "b44292323a3c89dee9a76a25a9423f7f0f96c6926d6839f36dbcab90ab2d7309", "src": "audio/hotel/hotel-024-user.mp3"}}, "hotel-025": {"agent": {"seconds": 2.283, "voice": "af_heart", "text": "Hello, front desk. How can I help you?", "bytes": 28224, "sha256": "83cb0ace8890b338c37f844a594cd92b55508fe568d9f8364ed533d8fb0f5699", "src": "audio/hotel/hotel-025-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_bella", "text": "Hi, could I get some extra towels?", "bytes": 27072, "sha256": "063add7b8d0f417a37c7b59c8df012edb231f3aecd84745b4fb7115df380e9e0", "src": "audio/hotel/hotel-025-user.mp3"}}, "hotel-026": {"agent": {"seconds": 1.792, "voice": "af_heart", "text": "Of course. How many would you like?", "bytes": 22176, "sha256": "d6443c4dccf69f5f725d7c23e7d6bb4f6f0e1ee618bffddac72a1d60db7e9a5f", "src": "audio/hotel/hotel-026-agent.mp3"}, "user": {"seconds": 1.387, "voice": "af_bella", "text": "Two more towels, please.", "bytes": 17280, "sha256": "e659a6abd0a4ecd91e9ab0923ee642d060c3ef84d7ebe1c2ae9b5e55e9f1d2c3", "src": "audio/hotel/hotel-026-user.mp3"}}, "hotel-027": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "Is there anything else for your room?", "bytes": 22752, "sha256": "9e4502f08de1febd40270934ea71fb99e6af0e7a30e711ff44e2e37bdb30cbab", "src": "audio/hotel/hotel-027-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Could I also have an extra pillow?", "bytes": 23904, "sha256": "66759689d2fa6baad37d90a1fb9d521a0f3828ebdde82bdde7918707b1eb7b55", "src": "audio/hotel/hotel-027-user.mp3"}}, "hotel-028": {"agent": {"seconds": 1.92, "voice": "af_heart", "text": "Certainly. We will bring them right up.", "bytes": 23616, "sha256": "6f54250854e22928dd3ccd05a768dd2488b5eafcf5df7b64a09da0ceeb8ccacd", "src": "audio/hotel/hotel-028-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Thank you so much for your help.", "bytes": 20448, "sha256": "2b94b2ce6e8e6632b42f55c0eeca9ce693e6ba622df162b185cf2622a2e42dee", "src": "audio/hotel/hotel-028-user.mp3"}}, "hotel-029": {"agent": {"seconds": 1.813, "voice": "af_heart", "text": "Would you like a room with a bathtub?", "bytes": 22464, "sha256": "e168dcb7ca3cbd7ac8649fedaf0261719e06544e38cb7c9858da9a544309c0e6", "src": "audio/hotel/hotel-029-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_bella", "text": "Yes, a bathtub would be lovely.", "bytes": 25920, "sha256": "39e0ee452ae6e2cd6d97d569ed71ab11e3149b495879e7a2576610223578b988", "src": "audio/hotel/hotel-029-user.mp3"}}, "hotel-030": {"agent": {"seconds": 1.664, "voice": "af_heart", "text": "Do you need a crib for the baby?", "bytes": 20736, "sha256": "66e31b1b4e8b2b174f7c114ab76cc877a53abcae80f4b05d003d1b69fe4c6e12", "src": "audio/hotel/hotel-030-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_bella", "text": "No baby, but thanks for asking.", "bytes": 26496, "sha256": "afc9de30292b2c3c79951ac47148261a1b42ae01190f980c7680c394fcdf1b1a", "src": "audio/hotel/hotel-030-user.mp3"}}, "hotel-031": {"agent": {"seconds": 1.941, "voice": "af_heart", "text": "We can send up an iron and board.", "bytes": 23904, "sha256": "cef03e03409908129342680a495e9a236ba1e2272b9aa455598f61dbfe714b9f", "src": "audio/hotel/hotel-031-agent.mp3"}, "user": {"seconds": 1.365, "voice": "af_bella", "text": "That would be very helpful.", "bytes": 16992, "sha256": "1dd1bb3d49ed0c6d03f006e49283d32635c6a9461dfd59de60427ee41e9d764f", "src": "audio/hotel/hotel-031-user.mp3"}}, "hotel-032": {"agent": {"seconds": 1.771, "voice": "af_heart", "text": "Would you prefer a quieter room?", "bytes": 21888, "sha256": "cc146c7f76233175dc071d12d0e44aa996f513c01cd0929bda9a3761715c50af", "src": "audio/hotel/hotel-032-agent.mp3"}, "user": {"seconds": 2.432, "voice": "af_bella", "text": "Yes, away from the elevator, please.", "bytes": 29952, "sha256": "79dafd61cc957dd6a6a8b81c713901ad70ed4b4d90d0f1af7b845ac615c08aa2", "src": "audio/hotel/hotel-032-user.mp3"}}, "hotel-033": {"agent": {"seconds": 1.899, "voice": "af_heart", "text": "I can move you to the garden side.", "bytes": 23616, "sha256": "99d50d49bc7dff8cf240548f3b7728eea57859a1fc15e9f58db789582ca393d0", "src": "audio/hotel/hotel-033-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "That sounds perfect. Thank you.", "bytes": 24480, "sha256": "3b04655ae77ebad88dae0388c70b5f5ee2e31b8a4acca05dc102c0a9ffd115f7", "src": "audio/hotel/hotel-033-user.mp3"}}, "hotel-034": {"agent": {"seconds": 1.941, "voice": "af_heart", "text": "Do you need a wake-up call tomorrow?", "bytes": 23904, "sha256": "7a174b42972d0da2fbbc596a262100ea3435a19a6afe0a1eaf72be8f238df39c", "src": "audio/hotel/hotel-034-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_bella", "text": "Yes, please call me at seven.", "bytes": 23040, "sha256": "490921cc5664fafe1f0634fc6b7736a370f968c1aa45d42d739acd55f7f49486", "src": "audio/hotel/hotel-034-user.mp3"}}, "hotel-035": {"agent": {"seconds": 2.581, "voice": "af_heart", "text": "Seven AM sharp. Is there anything else?", "bytes": 31680, "sha256": "0b60d822abbf802b07336bd0526f5e3df0e9d09f67f86b5716d312f5ba5250d3", "src": "audio/hotel/hotel-035-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "Could I get a city map, too?", "bytes": 19584, "sha256": "7667e97599cfd8fb5c0ca9621668b50f2ee12fc3ea22c611507b0ad8906df314", "src": "audio/hotel/hotel-035-user.mp3"}}, "hotel-036": {"agent": {"seconds": 1.557, "voice": "af_heart", "text": "We will leave one at your door.", "bytes": 19296, "sha256": "8bdf92281fa1720f3ea0f951a80bb16720b3626203ffd5cb15f2757e43437ef8", "src": "audio/hotel/hotel-036-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "Great, I really appreciate it.", "bytes": 24480, "sha256": "0c2e4859b286fa74875da42a9910b89305d72e5a30b93cda41e98dbf6b1519a5", "src": "audio/hotel/hotel-036-user.mp3"}}, "hotel-037": {"agent": {"seconds": 2.261, "voice": "af_heart", "text": "Front desk, what seems to be the problem?", "bytes": 27936, "sha256": "6a75d82cb96015e19d31b901fef1df13512ae08d22b322ad8bad801f3d6eec62", "src": "audio/hotel/hotel-037-agent.mp3"}, "user": {"seconds": 2.133, "voice": "af_bella", "text": "The air conditioner is not working.", "bytes": 26208, "sha256": "0876fd3e9065225fc141a90f76b36f035b33b2813d5ce3a6fd67cc6032be483a", "src": "audio/hotel/hotel-037-user.mp3"}}, "hotel-038": {"agent": {"seconds": 2.176, "voice": "af_heart", "text": "I am sorry to hear that. Which room?", "bytes": 26784, "sha256": "66b43ea698b5bfda2870714c00d1cd78503118e38217b135f818ac9e47c2615e", "src": "audio/hotel/hotel-038-agent.mp3"}, "user": {"seconds": 3.243, "voice": "af_bella", "text": "Room 1208, on the twelfth floor.", "bytes": 39744, "sha256": "e05d471ee9073d5307a4b8809b96c32b9b907d12f8bbf83a564ff6e488c50ce2", "src": "audio/hotel/hotel-038-user.mp3"}}, "hotel-039": {"agent": {"seconds": 2.091, "voice": "af_heart", "text": "I will send maintenance up right away.", "bytes": 25920, "sha256": "879a3d6751c8de0204f5849ab4e45a579effd2d65d720cdf5710a70bb4e6c12c", "src": "audio/hotel/hotel-039-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "Thank you. How long will it take?", "bytes": 23328, "sha256": "a5a807c0db7ea5c2cb28c89a63eec27363953a79fec810eebe9d4bd0aa98925c", "src": "audio/hotel/hotel-039-user.mp3"}}, "hotel-040": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "About fifteen minutes, I would say.", "bytes": 23040, "sha256": "dd5f1f519ac1d1415d7004783417a69136b2eba8399a0af12b6879d7dec179a7", "src": "audio/hotel/hotel-040-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_bella", "text": "That is fine. I will wait in the room.", "bytes": 28224, "sha256": "153e23d7f2031b2f08dac421baf61913fdeae1a93b3f4195f10f247023df8704", "src": "audio/hotel/hotel-040-user.mp3"}}, "hotel-041": {"agent": {"seconds": 2.24, "voice": "af_heart", "text": "Is the TV in your room working properly?", "bytes": 27648, "sha256": "3644e8bd281eb82b3f3a0a19bc73f6fd4bb7fd1aee078a7e33f3fd040378a848", "src": "audio/hotel/hotel-041-agent.mp3"}, "user": {"seconds": 2.368, "voice": "af_bella", "text": "Actually, the TV has no signal.", "bytes": 29088, "sha256": "c060af21046adf2898315c9f3a63eea0c071320c9ca34287d5806b6de18fe0ae", "src": "audio/hotel/hotel-041-user.mp3"}}, "hotel-042": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "Have you tried the remote control?", "bytes": 23040, "sha256": "5209517b3cedddbe900c5d289d6778ad28343b782a6e13584340d53c4f9f2b61", "src": "audio/hotel/hotel-042-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_bella", "text": "Yes, but nothing happens at all.", "bytes": 24768, "sha256": "f0eafc4e4586e0fa819c940a9e3cbd26c46ca92def6ed8caf9cfcc97a5e96c60", "src": "audio/hotel/hotel-042-user.mp3"}}, "hotel-043": {"agent": {"seconds": 1.984, "voice": "af_heart", "text": "The shower water is too hot, you said?", "bytes": 24480, "sha256": "e8b51b7553a90329f16e1d7dbad603cb42ff663d2c32c3676218057da952f322", "src": "audio/hotel/hotel-043-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_bella", "text": "Yes, I can not adjust the temperature.", "bytes": 28800, "sha256": "300f8504204274cf47a8a962311ba77e0e015a816213454ee6ba74edf3db4557", "src": "audio/hotel/hotel-043-user.mp3"}}, "hotel-044": {"agent": {"seconds": 1.6, "voice": "af_heart", "text": "We will fix it within the hour.", "bytes": 19872, "sha256": "144369bf7f6d98346577fb40538d7dd5f1621384629219b0477c988cbfbb41f8", "src": "audio/hotel/hotel-044-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Could I change rooms instead?", "bytes": 20160, "sha256": "fe6ce265483fc7cb7ea0f71acfc5a1a2a1615ca82daa9e71bda908af9525a75d", "src": "audio/hotel/hotel-044-user.mp3"}}, "hotel-045": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "Let me check what is available.", "bytes": 21312, "sha256": "db3b6b159c9bdbd2dfbe5a8f885f22f4f85eafae5a92f1eda7b2065ff5421264", "src": "audio/hotel/hotel-045-agent.mp3"}, "user": {"seconds": 2.389, "voice": "af_bella", "text": "I would prefer a room upstairs, please.", "bytes": 29376, "sha256": "aa97fa8ffc4788ff67e1c2c31e3234b0ccc542f454c48d718bb2be2d363d3ede", "src": "audio/hotel/hotel-045-user.mp3"}}, "hotel-046": {"agent": {"seconds": 2.069, "voice": "af_heart", "text": "You mentioned a strange noise, correct?", "bytes": 25632, "sha256": "25500d84c9351e562e50c1ef1366698572f1ccc2101da40b5ea0382085261c62", "src": "audio/hotel/hotel-046-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_bella", "text": "Yes, the room next door is noisy.", "bytes": 26496, "sha256": "ce8867853ead2a25beb072b8b5b83ac978df4ccb0ea39f0422d7ea88cd86fd1a", "src": "audio/hotel/hotel-046-user.mp3"}}, "hotel-047": {"agent": {"seconds": 2.517, "voice": "af_heart", "text": "I sincerely apologize for the disturbance.", "bytes": 30816, "sha256": "9df3eeed650e459947ae1ac4c0cdfc31a2091a3b5b18dbcb0a71ad537918c4a5", "src": "audio/hotel/hotel-047-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_bella", "text": "It is okay, just please fix it.", "bytes": 26496, "sha256": "40173f2b755451136947db6e685afb62f810ea54c75e30a6cb4089954085e0fe", "src": "audio/hotel/hotel-047-user.mp3"}}, "hotel-048": {"agent": {"seconds": 2.965, "voice": "af_heart", "text": "We have moved you to room 1502.", "bytes": 36288, "sha256": "74304a45fc4a1464513714cf8e9f4ddf675f0c99767db629e470fb3c1c5addcd", "src": "audio/hotel/hotel-048-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "Thank you for handling this quickly.", "bytes": 22464, "sha256": "5e4de69c5af2f9e99bbf4453b19e3871165770fe34c0c77b8fb5c5d5476e6d27", "src": "audio/hotel/hotel-048-user.mp3"}}, "hotel-049": {"agent": {"seconds": 1.941, "voice": "af_heart", "text": "Housekeeping! May I come in, please?", "bytes": 23904, "sha256": "76bee9d3cbb2dc826d17eee35f4a4c06ea4fa7b9b40886cb607a7c0d34b78f80", "src": "audio/hotel/hotel-049-agent.mp3"}, "user": {"seconds": 1.408, "voice": "af_bella", "text": "Yes, come in, please.", "bytes": 17568, "sha256": "ed8b9470168a730c8fe5e76323db221d274735825865434bfe186bbadc37d0c3", "src": "audio/hotel/hotel-049-user.mp3"}}, "hotel-050": {"agent": {"seconds": 1.728, "voice": "af_heart", "text": "Would you like your room cleaned now?", "bytes": 21312, "sha256": "fa122d7a9486dd65d2c29ef5c45dc0e4cbd28d20a3a23d2ca431684f9589c3be", "src": "audio/hotel/hotel-050-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "Yes, please clean the room now.", "bytes": 23616, "sha256": "cf34e66eea14581d7dc60ec007000c675314172eba7d92a23284114adfb6957c", "src": "audio/hotel/hotel-050-user.mp3"}}, "hotel-051": {"agent": {"seconds": 1.813, "voice": "af_heart", "text": "Should I change the bedsheets too?", "bytes": 22464, "sha256": "e1decb853e92b86cd1754ef763a023b0f028b66fa6fa963f5dc9706798bcdd68", "src": "audio/hotel/hotel-051-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_bella", "text": "Yes, fresh sheets would be nice.", "bytes": 24768, "sha256": "a3dfaadce220df3ae468dde7ff3486986655b60a183569333410c3f85df4c291", "src": "audio/hotel/hotel-051-user.mp3"}}, "hotel-052": {"agent": {"seconds": 1.792, "voice": "af_heart", "text": "Do you need the minibar restocked?", "bytes": 22176, "sha256": "e443fab0d1b6570a79e494fe69de48c614a76c876df07da6074c4cf5941cb2e8", "src": "audio/hotel/hotel-052-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Just two bottles of water, please.", "bytes": 25632, "sha256": "5ce71d09a8bb9882207dfe831f36e866c8c899d48e0ac68867fe7e3639392af0", "src": "audio/hotel/hotel-052-user.mp3"}}, "hotel-053": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "I will replace the towels as well.", "bytes": 23040, "sha256": "4ad0c4ae32f818c26da978d761f3c84323613601a780dd919b6964c0ec6bf447", "src": "audio/hotel/hotel-053-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "Thank you, that would be great.", "bytes": 21888, "sha256": "55a6770e27f5ea4d3679cd9d6792027890fd66ec7fad4e3d846129ab559de737", "src": "audio/hotel/hotel-053-user.mp3"}}, "hotel-054": {"agent": {"seconds": 1.493, "voice": "af_heart", "text": "What time should I come back?", "bytes": 18720, "sha256": "3033f5fb682e06f3727ebcc1f2b64d516c97f678be975660daf3eeafd1f6eb44", "src": "audio/hotel/hotel-054-agent.mp3"}, "user": {"seconds": 1.6, "voice": "af_bella", "text": "Please come back after lunch.", "bytes": 19872, "sha256": "8a8f9fe9769d015ccd6f65c1e10fd1fd630a6e4386766fd32f62cd44672272d2", "src": "audio/hotel/hotel-054-user.mp3"}}, "hotel-055": {"agent": {"seconds": 2.005, "voice": "af_heart", "text": "I will leave fresh soap in the bathroom.", "bytes": 24768, "sha256": "bb779b27fd27f4cb5c0f39c99fc36e3d3feceff85bc1653561d0f8cdca4c75f6", "src": "audio/hotel/hotel-055-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Could you bring more shampoo, too?", "bytes": 20448, "sha256": "7299b8a088908b69ebda190fed0837f8fb17fb0f3c647f542555206045c13b2d", "src": "audio/hotel/hotel-055-user.mp3"}}, "hotel-056": {"agent": {"seconds": 2.24, "voice": "af_heart", "text": "Is the room temperature comfortable for you?", "bytes": 27648, "sha256": "4347a7c695c4782fb94b33bfac46ba89ed16233fc22710feb85269c789baefb7", "src": "audio/hotel/hotel-056-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_bella", "text": "It is a little cold, actually.", "bytes": 23040, "sha256": "a53fb9e5ac9f46dbece2f2104f4d605eb87e5baa917058e7bb8892329311dcdd", "src": "audio/hotel/hotel-056-user.mp3"}}, "hotel-057": {"agent": {"seconds": 1.728, "voice": "af_heart", "text": "I will turn the heating up for you.", "bytes": 21312, "sha256": "e424f541c8af8ef57df955c71677992012cda439915906a9ff8c2ef4e16af411", "src": "audio/hotel/hotel-057-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_bella", "text": "Thanks, I appreciate your help.", "bytes": 22176, "sha256": "a5278038a5e3add56099bda32df0d93acd5fc0beb6d1ae7e588a671189a95af4", "src": "audio/hotel/hotel-057-user.mp3"}}, "hotel-058": {"agent": {"seconds": 1.941, "voice": "af_heart", "text": "Would you like turndown service tonight?", "bytes": 23904, "sha256": "8a3397fc9059c5d3141a0a37c04c31bfb349890bde5ca6bbff9408a4cbfc4c53", "src": "audio/hotel/hotel-058-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "What time is turndown service?", "bytes": 20448, "sha256": "2c904ccd3d4793ca9d48b3184f01495175d74dfeb197cbf4cf1d02843fd7503b", "src": "audio/hotel/hotel-058-user.mp3"}}, "hotel-059": {"agent": {"seconds": 1.771, "voice": "af_heart", "text": "We come around eight in the evening.", "bytes": 21888, "sha256": "f4ea4074beb16e88682a3dde6fef3d83f7cb015139470fef9e904c5b78d5d6f3", "src": "audio/hotel/hotel-059-agent.mp3"}, "user": {"seconds": 1.515, "voice": "af_bella", "text": "Eight o'clock works for me.", "bytes": 19008, "sha256": "cbf5e3a1450430f72780f691985bd6612d7acc8565a10e94ca9e86c833d654e4", "src": "audio/hotel/hotel-059-user.mp3"}}, "hotel-060": {"agent": {"seconds": 2.005, "voice": "af_heart", "text": "Your room is all done. Enjoy!", "bytes": 24768, "sha256": "4742eb34dd5769ba3736e785c97a4bf4c85d0e456f0bc90a699a8d0abb64595d", "src": "audio/hotel/hotel-060-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "Thank you! It looks wonderful.", "bytes": 22752, "sha256": "cc90dc406008cf3f1bc4d2a4d529269cd6d872dc359ebad75e8bf263f12ff151", "src": "audio/hotel/hotel-060-user.mp3"}}, "hotel-061": {"agent": {"seconds": 2.091, "voice": "af_heart", "text": "Good morning! Table for how many?", "bytes": 25920, "sha256": "5e2174c29e7f5708d91d4fcd00bf3fdf118835467c74eebcd0ef0a75c9fc7a84", "src": "audio/hotel/hotel-061-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_bella", "text": "Just one person, please.", "bytes": 20736, "sha256": "aca8b4f62daee856a33ec26ef3ff5a5de65fcc90cae8bfef862a52d9569ce9da", "src": "audio/hotel/hotel-061-user.mp3"}}, "hotel-062": {"agent": {"seconds": 2.261, "voice": "af_heart", "text": "Breakfast is served until ten thirty.", "bytes": 27936, "sha256": "68583c2e9624650bb28a4cc5b05f04555e5a71384dc414dd833ebe2ee6f2a05b", "src": "audio/hotel/hotel-062-agent.mp3"}, "user": {"seconds": 1.365, "voice": "af_bella", "text": "What time does it start?", "bytes": 16992, "sha256": "7c1f5058532eb8da44899c3a7cc204aedabb771f5f9ac72d2038d50f2c0a8710", "src": "audio/hotel/hotel-062-user.mp3"}}, "hotel-063": {"agent": {"seconds": 1.685, "voice": "af_heart", "text": "We start at six thirty AM.", "bytes": 21024, "sha256": "5c7643b05461981cc7bebab2d307d569557541d1f04fc29b16735c8329e63af9", "src": "audio/hotel/hotel-063-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "Is breakfast included in my room?", "bytes": 23616, "sha256": "03784d1884781f6a26f9f76ee9e42c4d9d1928393d45cf070b8e2f7b2baaf85d", "src": "audio/hotel/hotel-063-user.mp3"}}, "hotel-064": {"agent": {"seconds": 2.005, "voice": "af_heart", "text": "Yes, it is included in your rate.", "bytes": 24768, "sha256": "837f1da28265ff96809cb0299338ded65da676074275dd4d7fd1a04bacaa3f9a", "src": "audio/hotel/hotel-064-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "Wonderful. Where should I sit?", "bytes": 22464, "sha256": "9062d9f64a716f35881e0e880e6b23a905813e25b27ed697cd381e94a11d2eb7", "src": "audio/hotel/hotel-064-user.mp3"}}, "hotel-065": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "Anywhere you like by the window.", "bytes": 21312, "sha256": "132da110f0ab93a2d70277ee4c529aee2e5356476b3590e28e3d86e70f593256", "src": "audio/hotel/hotel-065-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "Could I have some coffee, please?", "bytes": 21312, "sha256": "1dc12504e10a2ef0b1280298c2dbd8d60b0d13c22d9632ec3253b77f4ee41c58", "src": "audio/hotel/hotel-065-user.mp3"}}, "hotel-066": {"agent": {"seconds": 1.813, "voice": "af_heart", "text": "Would you like eggs or pancakes?", "bytes": 22464, "sha256": "ee5dee45f133cbd26d1517fba97f492a0d4aff2318b6f642f349336a9a57d14f", "src": "audio/hotel/hotel-066-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Scrambled eggs would be lovely.", "bytes": 20448, "sha256": "363e02e5a77cd0f3f140ec231eb931149d21ff622a39d8c0e4380059a1e61ac1", "src": "audio/hotel/hotel-066-user.mp3"}}, "hotel-067": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "Would you like white toast or whole wheat?", "bytes": 25920, "sha256": "8d4beb0aeb2cc7f76d057936b002bf940e5341a08f3a1204baaf08b23d3190a5", "src": "audio/hotel/hotel-067-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "Whole wheat toast, please.", "bytes": 19584, "sha256": "ea885a188da59b58c1cd1eb1cdd2ea1c7c0d87adfdd2db48f9c9c90339eb689f", "src": "audio/hotel/hotel-067-user.mp3"}}, "hotel-068": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "Would you like some fresh orange juice?", "bytes": 24192, "sha256": "ac233da252068934b53461f8952d76b99400627c956423b25ebcd3d251f71e99", "src": "audio/hotel/hotel-068-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "Yes, orange juice sounds great.", "bytes": 26784, "sha256": "2ff9f2449e29c01a2cc63e5894828a912648f3f193046a90ff561b99945bb4e2", "src": "audio/hotel/hotel-068-user.mp3"}}, "hotel-069": {"agent": {"seconds": 1.515, "voice": "af_heart", "text": "Can I get you anything else?", "bytes": 19008, "sha256": "118e3e55180fefd1be2422e753baf6073562d5e80f31694752d342613b0a127b", "src": "audio/hotel/hotel-069-agent.mp3"}, "user": {"seconds": 1.344, "voice": "af_bella", "text": "Some more coffee, please.", "bytes": 16704, "sha256": "df5397138e6db524af21210952ce96dc2d1268f8f0c3d6bb97619167e95b6e32", "src": "audio/hotel/hotel-069-user.mp3"}}, "hotel-070": {"agent": {"seconds": 1.771, "voice": "af_heart", "text": "How was your breakfast this morning?", "bytes": 21888, "sha256": "3ade298203ea5320b7342b8e018562d89d12716be058adf4d7c0d980045a9eda", "src": "audio/hotel/hotel-070-agent.mp3"}, "user": {"seconds": 1.707, "voice": "af_bella", "text": "It was delicious, thank you.", "bytes": 21312, "sha256": "ec75c9f1386b8af8bb4196ef301f5f96703837657f507ec0dd8ef842cc2e03bb", "src": "audio/hotel/hotel-070-user.mp3"}}, "hotel-071": {"agent": {"seconds": 1.408, "voice": "af_heart", "text": "Would you like the bill now?", "bytes": 17568, "sha256": "53d8c9d6944f4474f038956f8c208bf3a1109bbc1de9f6c80aa6be6e9477944b", "src": "audio/hotel/hotel-071-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "It is included, is it not?", "bytes": 22464, "sha256": "071c4472da2ea3fb42f0ad8bc79bc407f39985f1928b7b4776b0f04b583978f5", "src": "audio/hotel/hotel-071-user.mp3"}}, "hotel-072": {"agent": {"seconds": 2.091, "voice": "af_heart", "text": "Yes, all set. Have a great day!", "bytes": 25920, "sha256": "55970f2fa65360ea23255dfbb42aaec8da211e9631ef431ce7d126d1455b6b4d", "src": "audio/hotel/hotel-072-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "You too! See you tomorrow.", "bytes": 23328, "sha256": "1d795bd709fcb99fd2caae000a64b4e5c59e62d9f45bed70d225effa1b666c28", "src": "audio/hotel/hotel-072-user.mp3"}}, "hotel-073": {"agent": {"seconds": 1.792, "voice": "af_heart", "text": "The pool is on the third floor.", "bytes": 22176, "sha256": "e8eead1782d17915421cd80ead5d947005bcf00b8083e986189f1b6c8ae7b897", "src": "audio/hotel/hotel-073-agent.mp3"}, "user": {"seconds": 1.365, "voice": "af_bella", "text": "What are the pool hours?", "bytes": 16992, "sha256": "c4b8e0ae981df05756c59c0c8e13b92c16f2b1cc9c1e13f137adffbe774af720", "src": "audio/hotel/hotel-073-user.mp3"}}, "hotel-074": {"agent": {"seconds": 2.005, "voice": "af_heart", "text": "From seven AM to ten PM.", "bytes": 24768, "sha256": "30139d9ef38e9ab5a3147ca645cae2dd356a3e771205ca4553785e05bacec97c", "src": "audio/hotel/hotel-074-agent.mp3"}, "user": {"seconds": 1.429, "voice": "af_bella", "text": "Do I need to bring a towel?", "bytes": 17856, "sha256": "fc9f122c6dbad713a6455565486015acc7768bdc62acc4503f34f777e11d89dd", "src": "audio/hotel/hotel-074-user.mp3"}}, "hotel-075": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "Towels are provided at the pool.", "bytes": 22752, "sha256": "e1d1848ab8ee45b987bfa9dc6e72bb62801f0dfb5996af1d802fff8674cd80ff", "src": "audio/hotel/hotel-075-agent.mp3"}, "user": {"seconds": 1.28, "voice": "af_bella", "text": "Is there a gym as well?", "bytes": 16128, "sha256": "785929071c5a5ae83fb88dbd7cbd92434f9af0e8472a3559159fae4623385796", "src": "audio/hotel/hotel-075-user.mp3"}}, "hotel-076": {"agent": {"seconds": 2.048, "voice": "af_heart", "text": "Yes, the gym is open all day.", "bytes": 25344, "sha256": "239e879a20a9529160354189e212909275ae2ad83f6c46809d1bbf934ea2775a", "src": "audio/hotel/hotel-076-agent.mp3"}, "user": {"seconds": 1.344, "voice": "af_bella", "text": "What time does it close?", "bytes": 16704, "sha256": "116097df5c64a0bd9f80494be18d16f2c19469b1cb66bb79813bba0b96e5e270", "src": "audio/hotel/hotel-076-user.mp3"}}, "hotel-077": {"agent": {"seconds": 1.792, "voice": "af_heart", "text": "It closes at eleven at night.", "bytes": 22176, "sha256": "183e8d8fc4165441fbd042b34beb98d3923b456b15876604f56102f66e19b7b5", "src": "audio/hotel/hotel-077-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Great, I will go this evening.", "bytes": 23904, "sha256": "6d4f247b04c4070f12c740f8fd509428831d94460c239220de2c890039697690", "src": "audio/hotel/hotel-077-user.mp3"}}, "hotel-078": {"agent": {"seconds": 2.155, "voice": "af_heart", "text": "The spa offers massages from noon.", "bytes": 26496, "sha256": "ca4c41a3fcb130dfff58b2d32f109851f7ec3df48bd38fd44051bc6ec1ecee35", "src": "audio/hotel/hotel-078-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "How do I book a massage?", "bytes": 18144, "sha256": "be918449c2ab57004de295421080d1a56af3a571c7994f1105ae21901cb8db2d", "src": "audio/hotel/hotel-078-user.mp3"}}, "hotel-079": {"agent": {"seconds": 1.6, "voice": "af_heart", "text": "I can book one for you now.", "bytes": 19872, "sha256": "b889f904c55f99406f57a6ba837aad8b41b9a46cfc17b65accb1269388e7c639", "src": "audio/hotel/hotel-079-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_bella", "text": "That would be lovely, thank you.", "bytes": 22176, "sha256": "8d472c1fd100d7d01a1ce6630ab0284ca16a3ad353dcc7d440b3fabdbc7a3a4d", "src": "audio/hotel/hotel-079-user.mp3"}}, "hotel-080": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "There is free parking in the basement.", "bytes": 22752, "sha256": "2a9c142b23e62b24b4cc3cd7ee79d2623c8c6cafedd99489a01d234e6058c87e", "src": "audio/hotel/hotel-080-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "Where is the parking entrance?", "bytes": 18144, "sha256": "ee2b6be8efd044508cca6c0a300ce2804840c17f8ece45008785c91d6e0c2512", "src": "audio/hotel/hotel-080-user.mp3"}}, "hotel-081": {"agent": {"seconds": 2.325, "voice": "af_heart", "text": "Just around the corner, past reception.", "bytes": 28512, "sha256": "8b59954ffb860772a175a725dbd2a0e606f1978afa817aad585de548313b63af", "src": "audio/hotel/hotel-081-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "Is the parking free for guests?", "bytes": 19584, "sha256": "643456fad0809dc359aa4d82167f217da9a7e8fa76a8da6aa44b5c731f910ba4", "src": "audio/hotel/hotel-081-user.mp3"}}, "hotel-082": {"agent": {"seconds": 1.643, "voice": "af_heart", "text": "Yes, just show your room key.", "bytes": 20448, "sha256": "04129ed51956546eeab3c1516310d1f104336fa8e6bddb1fa1939141f2a1886c", "src": "audio/hotel/hotel-082-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "Perfect. Is there a business center?", "bytes": 26784, "sha256": "d9926df26d0c92051412e6e6d5f449d17061a665d3da53f7028a36742bf65fa9", "src": "audio/hotel/hotel-082-user.mp3"}}, "hotel-083": {"agent": {"seconds": 2.667, "voice": "af_heart", "text": "On the second floor, open 24 hours.", "bytes": 32832, "sha256": "a67a86149322d93d5ae770e8ebcb1402b0f0adc19531fd0e20dcea277a672eb6", "src": "audio/hotel/hotel-083-agent.mp3"}, "user": {"seconds": 1.387, "voice": "af_bella", "text": "Can I print something there?", "bytes": 17280, "sha256": "23385689f117bba09d8106a50046fb41ea4c00f144a162bc2dbbba6e4b66f0c1", "src": "audio/hotel/hotel-083-user.mp3"}}, "hotel-084": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "Of course, it is free for guests.", "bytes": 24192, "sha256": "a4aae1ab2aba94c26043da677f3bae65271d36302691b56c3d130f07bacb0ea8", "src": "audio/hotel/hotel-084-agent.mp3"}, "user": {"seconds": 1.344, "voice": "af_bella", "text": "Thank you for all your help.", "bytes": 16704, "sha256": "aec4cb76ebb191109491a8f7562cd8fe095e345ed35fa9987e4618085ffab833", "src": "audio/hotel/hotel-084-user.mp3"}}, "hotel-085": {"agent": {"seconds": 1.813, "voice": "af_heart", "text": "How can the business center help you?", "bytes": 22464, "sha256": "65da9abea6e7542b32f7a59381992d8433ad0fc9698ca6db40f9b8c915887435", "src": "audio/hotel/hotel-085-agent.mp3"}, "user": {"seconds": 1.707, "voice": "af_bella", "text": "I need to print some documents.", "bytes": 21312, "sha256": "9fd72ffa0aeb871ca693cef71904563fac1b44af57d232f132c502ea634df213", "src": "audio/hotel/hotel-085-user.mp3"}}, "hotel-086": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "You can email them to our printer.", "bytes": 22752, "sha256": "43f9bee85806a1a54caaa766a955fb76c83f50f557fb71cd4376790f16a10415", "src": "audio/hotel/hotel-086-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "What is the email address?", "bytes": 18144, "sha256": "606198f0bb8b6073e00fe132ff38a6b02fa6ffc89c343bf6a33e7b3cf9d0f6e3", "src": "audio/hotel/hotel-086-user.mp3"}}, "hotel-087": {"agent": {"seconds": 2.176, "voice": "af_heart", "text": "It is print at grandplaza dot com.", "bytes": 26784, "sha256": "8636df4ae99446b9a471149817e10931ff7171ab2f6c24b309b7b14f8741abf3", "src": "audio/hotel/hotel-087-agent.mp3"}, "user": {"seconds": 1.387, "voice": "af_bella", "text": "Could you spell that for me?", "bytes": 17280, "sha256": "e253af05c03c523a32c330508954c182c3877dfd4468a6609e401cbfa0343623", "src": "audio/hotel/hotel-087-user.mp3"}}, "hotel-088": {"agent": {"seconds": 3.499, "voice": "af_heart", "text": "P-R-I-N-T at grandplaza dot com, all lowercase.", "bytes": 42624, "sha256": "51c9716a1bc1ac1043dec64f207af3656867f36e952cca34875ab49b42e98350", "src": "audio/hotel/hotel-088-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "Got it, thank you very much.", "bytes": 21600, "sha256": "8a630bc081c7e13a8690189a7bd5ce021b527733a39049c30fc7bad04af5cefb", "src": "audio/hotel/hotel-088-user.mp3"}}, "hotel-089": {"agent": {"seconds": 1.472, "voice": "af_heart", "text": "Do you need to send a fax?", "bytes": 18432, "sha256": "69b1b896775528250484b3063f864f9aeae87a0dea8eec1563618a83656ba19c", "src": "audio/hotel/hotel-089-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "No, but I need to scan something.", "bytes": 24192, "sha256": "98a663f2a8e56a954f49a90053e5406e4d02bd56e97c8d2a596e4e4a6d1ab983", "src": "audio/hotel/hotel-089-user.mp3"}}, "hotel-090": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "The scanner is next to the printer.", "bytes": 22752, "sha256": "a87e3c496643821c20491d7741b0fcd959944b3da45520a448ace68687f972e4", "src": "audio/hotel/hotel-090-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Could you show me how it works?", "bytes": 20160, "sha256": "f38293ab7e6e32079c191baafb241ad861a7803fa67c54d67d6cfc8c71a8f74a", "src": "audio/hotel/hotel-090-user.mp3"}}, "hotel-091": {"agent": {"seconds": 2.091, "voice": "af_heart", "text": "We also have meeting rooms available.", "bytes": 25920, "sha256": "a224ebd87dbef2c70f8a659f816635d2f26a9e795cdd83010b706d906161e69f", "src": "audio/hotel/hotel-091-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "How much is a small meeting room?", "bytes": 22464, "sha256": "0355ca39d613c83d3e19c8ade0b5267122e32abbfbf601e74597e847082c4aa9", "src": "audio/hotel/hotel-091-user.mp3"}}, "hotel-092": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "Two hundred dollars per half day.", "bytes": 23040, "sha256": "b1faacbb47a2cd9867a022e762aa8406a5d8839c0dd3813a134d68d9ef252f7e", "src": "audio/hotel/hotel-092-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "That is a bit expensive for me.", "bytes": 21600, "sha256": "02c27efb8139b5f864a40af3baf64ca6db5568738190fc8436673b54807c62e9", "src": "audio/hotel/hotel-092-user.mp3"}}, "hotel-093": {"agent": {"seconds": 2.197, "voice": "af_heart", "text": "We offer ten percent off for our guests.", "bytes": 27072, "sha256": "560974dba783881593ecdf166d5309e64a9280127d2e04d2d470505adf262d08", "src": "audio/hotel/hotel-093-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "Wonderful! I would like to book it.", "bytes": 23616, "sha256": "222a919833c0a1899a1dd473f322ce986070450541126ca474ab8ed5d25b9236", "src": "audio/hotel/hotel-093-user.mp3"}}, "hotel-094": {"agent": {"seconds": 1.451, "voice": "af_heart", "text": "Would you like to book it now?", "bytes": 18144, "sha256": "3903d643d3acfc70d6a4a65fd41fab7fc201dfa698e6485aab1414ba8ee19a04", "src": "audio/hotel/hotel-094-agent.mp3"}, "user": {"seconds": 1.472, "voice": "af_bella", "text": "Let me think about it first.", "bytes": 18432, "sha256": "29eabd2b5ee29b3fd3bd109eed7269378c9fea7159b7c6d65ca78871678e4292", "src": "audio/hotel/hotel-094-user.mp3"}}, "hotel-095": {"agent": {"seconds": 2.091, "voice": "af_heart", "text": "Here is my card if you need anything.", "bytes": 25920, "sha256": "63e11efcb461eb024e5f79eb6c90a3b1a229cadcf9adeff36c1226c266a8c691", "src": "audio/hotel/hotel-095-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "Thank you, I will be in touch.", "bytes": 22464, "sha256": "2ef7260847b7945c94e55f0e4e073804bdafaa7175d59024a36b35d3ccb63369", "src": "audio/hotel/hotel-095-user.mp3"}}, "hotel-096": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "Good luck with your meeting today!", "bytes": 21312, "sha256": "c980367461c5374c4fa65900eff36a33eace715433d9173bed652e97738e343f", "src": "audio/hotel/hotel-096-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "Thanks! I hope it goes well.", "bytes": 21888, "sha256": "d668f27b05ad6736cc01919152322c2f2f267c8f2c16050e1f2a69e5a750f6cf", "src": "audio/hotel/hotel-096-user.mp3"}}, "hotel-097": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "Front desk, how may I help you?", "bytes": 23040, "sha256": "710aa56d869c135b110786e4b293c8fa73fcf2a85aa80c4fd837b213a94b54f2", "src": "audio/hotel/hotel-097-agent.mp3"}, "user": {"seconds": 1.685, "voice": "af_bella", "text": "I would like to extend my stay.", "bytes": 21024, "sha256": "c915665cf225f8cdadbece5c6d17b994f797fc53ae46a778e230f15754856b74", "src": "audio/hotel/hotel-097-user.mp3"}}, "hotel-098": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "For how many extra nights, please?", "bytes": 23040, "sha256": "82e40476252b2714d5c8e0d99d60f3a21c68dd96f5826a598a7e697bf8702c67", "src": "audio/hotel/hotel-098-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "Just one more night, please.", "bytes": 19584, "sha256": "4f0fae73c097e41390904141cc6d1db41cb69812fb5be8a8581cf7b8a3825834", "src": "audio/hotel/hotel-098-user.mp3"}}, "hotel-099": {"agent": {"seconds": 2.112, "voice": "af_heart", "text": "Let me check the room availability now.", "bytes": 25920, "sha256": "a76b6515687324a7a76bbfef49bcf25158b55943d297c7f1b40452a1d489e307", "src": "audio/hotel/hotel-099-agent.mp3"}, "user": {"seconds": 1.408, "voice": "af_bella", "text": "I hope my room is free.", "bytes": 17568, "sha256": "6c47c27afd683af113ade843e1b1f9c3ee1900f603d71b9808df8777f4c2a7f1", "src": "audio/hotel/hotel-099-user.mp3"}}, "hotel-100": {"agent": {"seconds": 3.221, "voice": "af_heart", "text": "Good news, you can stay in 1208.", "bytes": 39456, "sha256": "3a6b4b05c0ead980a3854508b8d436abc97c8ef7c34352ab229be98cbb63ef01", "src": "audio/hotel/hotel-100-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "That is great, thank you.", "bytes": 19008, "sha256": "6fbdaf4fb4c234420e5ca201e8513d6d6d21f8f926b7f3d3e978fc2a5ea3178e", "src": "audio/hotel/hotel-100-user.mp3"}}, "hotel-101": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "The rate is the same as before.", "bytes": 24192, "sha256": "8981ba451e64317cdbf2b7c2a60366cb3d697a7fbf43d5a22e8c207b605e00e6", "src": "audio/hotel/hotel-101-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "Perfect. Please extend it.", "bytes": 22752, "sha256": "28a81c246c2a68236342a82941142748e458e66aaf64b96df3b14d831647f1d5", "src": "audio/hotel/hotel-101-user.mp3"}}, "hotel-102": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "Would you like late checkout instead?", "bytes": 24192, "sha256": "780b791650d8c4a734bdde2be8f71b98feb129d1a3946e77e1e7b5a7b27b92c6", "src": "audio/hotel/hotel-102-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "Both would be ideal, actually.", "bytes": 23328, "sha256": "801887cd7f9505208fe644d4112e065befd86e698f694f283bf53e1d375290cc", "src": "audio/hotel/hotel-102-user.mp3"}}, "hotel-103": {"agent": {"seconds": 2.027, "voice": "af_heart", "text": "I can offer checkout at two PM.", "bytes": 25056, "sha256": "eec5e32a227ec6f6cbd9a3530ab64335514d8cd0b834628adc6be5338f428e52", "src": "audio/hotel/hotel-103-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_bella", "text": "Two o'clock is perfect for me.", "bytes": 22176, "sha256": "b8f10a7b1232d236c912e9a3d0f896f3ab1ff76db8774c08fa819b128bb78e7c", "src": "audio/hotel/hotel-103-user.mp3"}}, "hotel-104": {"agent": {"seconds": 1.984, "voice": "af_heart", "text": "Shall I update your reservation now?", "bytes": 24480, "sha256": "010870069d906458bd193b8a55f5dbde72c8f9ce1b9710134d3e6596f84289fd", "src": "audio/hotel/hotel-104-agent.mp3"}, "user": {"seconds": 1.429, "voice": "af_bella", "text": "Yes, please go ahead.", "bytes": 17856, "sha256": "6bc62c8bce1f96af80628755c4cb7d8f1fb4264491cb2d66a7e9efd5d61289c2", "src": "audio/hotel/hotel-104-user.mp3"}}, "hotel-105": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "All done. Is there anything else?", "bytes": 24192, "sha256": "7e4e381ae1b6d49b04eceb2b54c37b1286f477eba65c90c1a9c467d4210a9f69", "src": "audio/hotel/hotel-105-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "Could I get a new key card?", "bytes": 19008, "sha256": "03744f85bf6ebd2021c787b99e4767df1b357828888884800b1a8205245bc858", "src": "audio/hotel/hotel-105-user.mp3"}}, "hotel-106": {"agent": {"seconds": 1.749, "voice": "af_heart", "text": "Your old card will still work.", "bytes": 21600, "sha256": "a1c5686683dbcff6fe755e13caba2fd11172c3b0dd54d1d13b04153c5f1fc2c9", "src": "audio/hotel/hotel-106-agent.mp3"}, "user": {"seconds": 1.344, "voice": "af_bella", "text": "Good to know, thanks.", "bytes": 16704, "sha256": "defad0fe78a143c6caec44c83ab72f3b3fad3baf4820be93bef971b0fad602dc", "src": "audio/hotel/hotel-106-user.mp3"}}, "hotel-107": {"agent": {"seconds": 1.621, "voice": "af_heart", "text": "Enjoy the rest of your stay!", "bytes": 20160, "sha256": "9a32ac894e253dfb1f212ba5f13aca7cbf4d8b82b92f32a39029eeb3fc8b6ced", "src": "audio/hotel/hotel-107-agent.mp3"}, "user": {"seconds": 1.131, "voice": "af_bella", "text": "Thank you, I will.", "bytes": 14400, "sha256": "215f02de1fbc5cec707a5a77c45da69ad378b4f24c986c2723e2b6ebc3e6db93", "src": "audio/hotel/hotel-107-user.mp3"}}, "hotel-108": {"agent": {"seconds": 2.453, "voice": "af_heart", "text": "We really appreciate you choosing our hotel.", "bytes": 30240, "sha256": "c4fc76bc8af45ba0768d802ed9e2178767266bce9b51688c44460b2f5ef31c5b", "src": "audio/hotel/hotel-108-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "It is a lovely hotel, honestly.", "bytes": 24192, "sha256": "54b5cacbc3b5a0dd33bbb67624806414907bb9322d13aa6aa2f5c5d58219d2b2", "src": "audio/hotel/hotel-108-user.mp3"}}, "hotel-109": {"agent": {"seconds": 2.219, "voice": "af_heart", "text": "Good morning! Are you checking out today?", "bytes": 27360, "sha256": "94fd4d7229af6c6e9c4a8e976aefdf6a0e652ef82d36f873f1ab1e3a9cc65ed6", "src": "audio/hotel/hotel-109-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_bella", "text": "Yes, I am checking out now.", "bytes": 23040, "sha256": "2628ff938153d7156f34539f9d58f9394408ffc036de4668100576cb520b730d", "src": "audio/hotel/hotel-109-user.mp3"}}, "hotel-110": {"agent": {"seconds": 1.451, "voice": "af_heart", "text": "May I have your room number?", "bytes": 18144, "sha256": "5288941c0064b39a0a7426f9f06efbb8f81413ca88f12dc74fc85efa59dd6632", "src": "audio/hotel/hotel-110-agent.mp3"}, "user": {"seconds": 2.667, "voice": "af_bella", "text": "I am in room 1208.", "bytes": 32832, "sha256": "824082c07e6a093eadb780abbb9648ce71408d92166ef0c0467a945b0707cbd5", "src": "audio/hotel/hotel-110-user.mp3"}}, "hotel-111": {"agent": {"seconds": 2.069, "voice": "af_heart", "text": "Did you use anything from the minibar?", "bytes": 25632, "sha256": "5d56d770aaa72bb3631a15bf42f2993a8ce9fc7acb7e4992c49bdd92a5064b12", "src": "audio/hotel/hotel-111-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "Just a bottle of water.", "bytes": 18144, "sha256": "c87b95fef6ead1adde666bb12e5c984e4205243eefb4736d0d224863c011b6f1", "src": "audio/hotel/hotel-111-user.mp3"}}, "hotel-112": {"agent": {"seconds": 1.493, "voice": "af_heart", "text": "I will add that to your bill.", "bytes": 18720, "sha256": "ca0d0d63227bc49d26d0e8d7d4d39ff24348dcdb93a057b05433423cfeb96a96", "src": "audio/hotel/hotel-112-agent.mp3"}, "user": {"seconds": 1.515, "voice": "af_bella", "text": "Could I see the bill, please?", "bytes": 19008, "sha256": "edcb2df18ddaafa6046dbb5bedc2795fe0c292895a985cb7d76f3ee5fe1ea579", "src": "audio/hotel/hotel-112-user.mp3"}}, "hotel-113": {"agent": {"seconds": 1.835, "voice": "af_heart", "text": "Here is your itemized bill, sir.", "bytes": 22752, "sha256": "782032373171fc252640b210da2250addc104279db1ea0a93a0ec063716bf82c", "src": "audio/hotel/hotel-113-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Everything looks correct, thank you.", "bytes": 23904, "sha256": "ca59e1ddd28dc88be61844a802d0518519210704dca5f4a728a67cbcc70e61a1", "src": "audio/hotel/hotel-113-user.mp3"}}, "hotel-114": {"agent": {"seconds": 1.408, "voice": "af_heart", "text": "How would you like to pay?", "bytes": 17568, "sha256": "d78539644f6760dad83ed28bdb7539aa223c62b174d58c74a325cc782a9e7109", "src": "audio/hotel/hotel-114-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "By credit card, please.", "bytes": 19584, "sha256": "383f77b09fa50e71ac23fbb38fddcd6691f2bdd717cacd7034ba2d2faacde8dc", "src": "audio/hotel/hotel-114-user.mp3"}}, "hotel-115": {"agent": {"seconds": 1.557, "voice": "af_heart", "text": "Could I see the card, please?", "bytes": 19296, "sha256": "999f3c809cddc84e6ee0eb92dc3578a8bdfb5490e388f9bf87cd874aebe06784", "src": "audio/hotel/hotel-115-agent.mp3"}, "user": {"seconds": 1.28, "voice": "af_bella", "text": "Here you are, thank you.", "bytes": 16128, "sha256": "a8297bcf7a2ebb9a6d5f3d887c42da40255d70f1946c1ffa607fc18183517dab", "src": "audio/hotel/hotel-115-user.mp3"}}, "hotel-116": {"agent": {"seconds": 1.6, "voice": "af_heart", "text": "Please sign your name right here.", "bytes": 19872, "sha256": "3dff25e1d54c49501e3486e4aea6f9c96916f444c70b646e3f5bd5d7315ef8e9", "src": "audio/hotel/hotel-116-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "Sure, where do I sign?", "bytes": 18144, "sha256": "5dac6f4b0ccfd7265b5a6b892d41a7e7eca681911534892809628cddc6fe6b5a", "src": "audio/hotel/hotel-116-user.mp3"}}, "hotel-117": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "Would you like a receipt for your stay?", "bytes": 23040, "sha256": "935d6c0c4c353bf1ebde10c884159b84e33da3a2fa58dd01699e0719dd16734f", "src": "audio/hotel/hotel-117-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "Yes, please email it to me.", "bytes": 21888, "sha256": "f68b4a7c0f7738c49edce802af7d63acb07cbf46680050b4fb07b34d74c246f6", "src": "audio/hotel/hotel-117-user.mp3"}}, "hotel-118": {"agent": {"seconds": 1.451, "voice": "af_heart", "text": "Can I call you a taxi?", "bytes": 18144, "sha256": "021b529201f73a6dd9ffa19d8c4ee0ebbaf986e51638a2713f9cb79fa7cfca83", "src": "audio/hotel/hotel-118-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "Yes, to the airport, please.", "bytes": 23616, "sha256": "cd71fc45a734ffe708bb55cfa00604aab1ae67574e37a4a1a10580d385a321d1", "src": "audio/hotel/hotel-118-user.mp3"}}, "hotel-119": {"agent": {"seconds": 1.557, "voice": "af_heart", "text": "The taxi will be here soon.", "bytes": 19296, "sha256": "b54b9489f8e2d379077b3da73df5a8282fb3aa68f1d13dc75b05bd883db4a16f", "src": "audio/hotel/hotel-119-agent.mp3"}, "user": {"seconds": 1.301, "voice": "af_bella", "text": "Thank you for everything.", "bytes": 16416, "sha256": "116cb34062c1c8e4ca336a6ab37a3dc17d31df7ddc35bfe8a18c08bbea2668cb", "src": "audio/hotel/hotel-119-user.mp3"}}, "hotel-120": {"agent": {"seconds": 1.429, "voice": "af_heart", "text": "We hope to see you again!", "bytes": 17856, "sha256": "5f13201fedc08e53150aad68a5c84061adb95190eb89a81249019b5233552057", "src": "audio/hotel/hotel-120-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "I had a wonderful stay, goodbye!", "bytes": 25632, "sha256": "62980b3edcdcef362a6f26e1da8cadd820087634b97b32c41f755cfadd0f63d0", "src": "audio/hotel/hotel-120-user.mp3"}}, "hotel-121": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "Lost and found, how can I help?", "bytes": 24192, "sha256": "129d0ebd0541011bbd71ebd4c6691b14367ba56b67598362ba3368ae9fc352a7", "src": "audio/hotel/hotel-121-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "I think I left something behind.", "bytes": 22752, "sha256": "78ed623110f85bae115f98229f13878ab4604a018675fdfb9a83335afba7ce2b", "src": "audio/hotel/hotel-121-user.mp3"}}, "hotel-122": {"agent": {"seconds": 1.728, "voice": "af_heart", "text": "What exactly did you lose, sir?", "bytes": 21312, "sha256": "38c30aa079e02d755135cb6100db77940b1b3a81076afc6baa9313fffa276d4c", "src": "audio/hotel/hotel-122-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "My black umbrella, I believe.", "bytes": 23616, "sha256": "871243f2cb4fcc85cd523ddcad53b3b5722dab6c1c6a99d225017cda420e2983", "src": "audio/hotel/hotel-122-user.mp3"}}, "hotel-123": {"agent": {"seconds": 1.323, "voice": "af_heart", "text": "Where did you last see it?", "bytes": 16704, "sha256": "a0743c399e6f7a5ccef30e83d61214802706f5fa08dcc040155def59967bf3ab", "src": "audio/hotel/hotel-123-agent.mp3"}, "user": {"seconds": 1.515, "voice": "af_bella", "text": "Probably in the restaurant.", "bytes": 19008, "sha256": "d9d49865fb0f0370b67f9254589e635fa2a6fbda3c597e7bbe3632641f0c22d4", "src": "audio/hotel/hotel-123-user.mp3"}}, "hotel-124": {"agent": {"seconds": 1.515, "voice": "af_heart", "text": "What does the item look like?", "bytes": 19008, "sha256": "f10a9d7b9fa7ee5c8a8909428a7db5bd8dcfea0936d7a8f6c78a3bb91c1c212e", "src": "audio/hotel/hotel-124-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "It is black with a wooden handle.", "bytes": 21312, "sha256": "1eab3358730c77525243a1012167b1f8e8977af0d3326eeb782ebcaa674f36e2", "src": "audio/hotel/hotel-124-user.mp3"}}, "hotel-125": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "Let me check our storage room.", "bytes": 21312, "sha256": "c988f554afc743cbefe32b65b5ef03161e6b17c7d3f1035eaab24bb3e48e08f3", "src": "audio/hotel/hotel-125-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "Thank you, I will hold on.", "bytes": 21600, "sha256": "6c091dc211259c2ceeba28040e5eb6b81341a896f007cff208000ebd82cbd4f5", "src": "audio/hotel/hotel-125-user.mp3"}}, "hotel-126": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "Yes, we found a black umbrella!", "bytes": 24192, "sha256": "6aac4314d42e92a4a528061877af0384b96303e8647cfb5a04240b7a4bf1df0c", "src": "audio/hotel/hotel-126-agent.mp3"}, "user": {"seconds": 2.091, "voice": "af_bella", "text": "That is wonderful news, thank you.", "bytes": 25920, "sha256": "a70867788c15fecbf37582170dc235bae2b2a01ec882d3d62e65e790b5b92442", "src": "audio/hotel/hotel-126-user.mp3"}}, "hotel-127": {"agent": {"seconds": 1.557, "voice": "af_heart", "text": "Can you describe it once more?", "bytes": 19296, "sha256": "dc76aaedff085f177138564819ab83930fdf6b551cbaff8ea25e74c5acffb08b", "src": "audio/hotel/hotel-127-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Black, with a curved wooden handle.", "bytes": 25632, "sha256": "a52c6ce9ef464fec28a93deb1d4f30f23867845cd86b5f662814218b0018577d", "src": "audio/hotel/hotel-127-user.mp3"}}, "hotel-128": {"agent": {"seconds": 2.176, "voice": "af_heart", "text": "That matches. When can you collect it?", "bytes": 26784, "sha256": "7071f6e6f52970cf3b9bc88451d5610b8ea086e6aa2fbf247ebafde07d842308", "src": "audio/hotel/hotel-128-agent.mp3"}, "user": {"seconds": 1.515, "voice": "af_bella", "text": "I will pick it up this evening.", "bytes": 19008, "sha256": "2a9e59a8e495e1a981664c4c4a0e3dcbfd08542a665930bddaa4c93312d86c4b", "src": "audio/hotel/hotel-128-user.mp3"}}, "hotel-129": {"agent": {"seconds": 1.579, "voice": "af_heart", "text": "It is at the front desk now.", "bytes": 19584, "sha256": "fa6d01ab90d7f73b4b2ef4f347765e19b24baff211f9b20fe5ef9ac65c19c746", "src": "audio/hotel/hotel-129-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_bella", "text": "Perfect, I will stop by soon.", "bytes": 25344, "sha256": "99f588db20bf53fd6df1d276637ffafdf056857c447d7bcf1d8a225208a80c11", "src": "audio/hotel/hotel-129-user.mp3"}}, "hotel-130": {"agent": {"seconds": 1.707, "voice": "af_heart", "text": "Please bring some ID with you.", "bytes": 21312, "sha256": "6fa0912a103a70b6f4c775661e88edf91fd6d56da9f7dfcf142b4213791f8761", "src": "audio/hotel/hotel-130-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Of course, no problem at all.", "bytes": 23904, "sha256": "1b6f57dde67f3cde5f957bb19d7069ddc55da5d7d5130d5b0d0d6f4163d42a11", "src": "audio/hotel/hotel-130-user.mp3"}}, "hotel-131": {"agent": {"seconds": 1.664, "voice": "af_heart", "text": "We are glad we could help you.", "bytes": 20736, "sha256": "5aa2975f45c08417bf5c43bbd05a79d3b01f2bed430d4f97c12bde47ef6984e1", "src": "audio/hotel/hotel-131-agent.mp3"}, "user": {"seconds": 1.323, "voice": "af_bella", "text": "Thank you for finding it.", "bytes": 16704, "sha256": "6d296aa88bc24b1385298ae2969a3a29fea50ae3db86508ebcbdf6f159e8c96a", "src": "audio/hotel/hotel-131-user.mp3"}}, "hotel-132": {"agent": {"seconds": 1.621, "voice": "af_heart", "text": "Have a very safe trip home!", "bytes": 20160, "sha256": "3016be414f362511a665752d22d9ce52a043fef8a33988586d6e618495975c18", "src": "audio/hotel/hotel-132-agent.mp3"}, "user": {"seconds": 1.707, "voice": "af_bella", "text": "Thanks, goodbye and take care!", "bytes": 21312, "sha256": "147a4f87aaa8163fbdaddd781d5460292a9c10b30854b818b54b3ffa8d96d2d4", "src": "audio/hotel/hotel-132-user.mp3"}}, "hotel-133": {"agent": {"seconds": 1.877, "voice": "af_heart", "text": "Front desk. How can I help you?", "bytes": 23328, "sha256": "27e89a119e5116c6c51ae990169797ea2c92333b27f364807072288824160ee4", "src": "audio/hotel/hotel-133-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "I am afraid my room is too noisy.", "bytes": 24480, "sha256": "6bf12544d7d0a412a725081b05cb61c9be6ac5cce15836a1d93a8b58d5a0e29b", "src": "audio/hotel/hotel-133-user.mp3"}}, "hotel-134": {"agent": {"seconds": 1.771, "voice": "af_heart", "text": "I am very sorry to hear that.", "bytes": 21888, "sha256": "ddbecb21859d18957352db19ef15a33c2a3481c95e9e839195de172b9279c038", "src": "audio/hotel/hotel-134-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "There is loud music next door.", "bytes": 21888, "sha256": "a9f677cce756011cd0ebf555d9a34b7799f9722d263df71733b9b89ac2c17b1b", "src": "audio/hotel/hotel-134-user.mp3"}}, "hotel-135": {"agent": {"seconds": 1.749, "voice": "af_heart", "text": "I will speak to those guests now.", "bytes": 21600, "sha256": "bf2300ec9cef849ce49ac47047fda9d4ae30fc80c5146959fd5bb0789304bc36", "src": "audio/hotel/hotel-135-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_bella", "text": "Thank you, I would appreciate that.", "bytes": 25344, "sha256": "4650d716e415c71f633dcb163aba07be30372873f1875ff4145d3216467d1bc9", "src": "audio/hotel/hotel-135-user.mp3"}}, "hotel-136": {"agent": {"seconds": 1.899, "voice": "af_heart", "text": "You mentioned the hallway lights, correct?", "bytes": 23616, "sha256": "f12d382b3c77f90b451f6f3c2a587e10f9b88987c9d1d0b8185bfc56c6b2b59d", "src": "audio/hotel/hotel-136-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "Yes, they are too bright at night.", "bytes": 23616, "sha256": "61e7b8822f903982fa33975daa89ecd21a6bfd47e40b90fb36a7e7a2a8a93a52", "src": "audio/hotel/hotel-136-user.mp3"}}, "hotel-137": {"agent": {"seconds": 2.773, "voice": "af_heart", "text": "I sincerely apologize for this inconvenience.", "bytes": 33984, "sha256": "444a2da2293a2b0b72876557cdd5224d93e0a7cc2e16e331266ff7afc0ba9699", "src": "audio/hotel/hotel-137-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "Could I move to another room?", "bytes": 19008, "sha256": "a5feb16ffbee9f4f2f5ac1cb2164bc1abe8f244a175136199de1681fdbbf25e8", "src": "audio/hotel/hotel-137-user.mp3"}}, "hotel-138": {"agent": {"seconds": 1.643, "voice": "af_heart", "text": "Let me see what is available.", "bytes": 20448, "sha256": "85911ad345a57a0d9eb22934bb8469d4f8dba5ef052bcf9e1b83bb6ff6795255", "src": "audio/hotel/hotel-138-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "A quieter room would be ideal.", "bytes": 21600, "sha256": "b784ec756fa46c4ac5983d38ac300508a51ff1f407f9f9c49ffe5ed78b320169", "src": "audio/hotel/hotel-138-user.mp3"}}, "hotel-139": {"agent": {"seconds": 1.856, "voice": "af_heart", "text": "The Wi-Fi seems slow, you said?", "bytes": 23040, "sha256": "a0de23312b086364f7af876ef680afe220eeb13c716f444c335b854eb92a7c5c", "src": "audio/hotel/hotel-139-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "Yes, it keeps disconnecting.", "bytes": 23616, "sha256": "61d02caa06357830dc72af0ae615ff0cab2a1b1d8e4d75d70d31277463cb57d7", "src": "audio/hotel/hotel-139-user.mp3"}}, "hotel-140": {"agent": {"seconds": 1.92, "voice": "af_heart", "text": "We will reset the router right away.", "bytes": 23616, "sha256": "fb2cfa32b79628308d20e602aec4c27fddbd9a58ace45c977ecc7773084fa7c5", "src": "audio/hotel/hotel-140-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "Thank you for your quick response.", "bytes": 21312, "sha256": "ec72bd7ba5b0b2520521c389c345fe3036ca34f16350d7a1b3c5202a72b9b91d", "src": "audio/hotel/hotel-140-user.mp3"}}, "hotel-141": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "Is the breakfast area too crowded?", "bytes": 24192, "sha256": "4617dc5d66bf0620c3c895b346bbdbdca7baf3c5b408637ea682fa8049d815cb", "src": "audio/hotel/hotel-141-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_bella", "text": "A little, but the food is great.", "bytes": 23040, "sha256": "43ac042175fd1d7259dc4f3a61cccb68ec7e9c8b21b0f426b9fdb4a3e375290b", "src": "audio/hotel/hotel-141-user.mp3"}}, "hotel-142": {"agent": {"seconds": 2.368, "voice": "af_heart", "text": "Your feedback is very valuable to us.", "bytes": 29088, "sha256": "0fdb1cd23e05161cd4dece0099f72c1acf39bfeebe7cf7ccb24fc5ead4702aa3", "src": "audio/hotel/hotel-142-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_bella", "text": "I am glad you take it seriously.", "bytes": 23040, "sha256": "c89766706b6b9e30bdc70d849c3374f508ee298415dc9a6ae72dea67cb41401a", "src": "audio/hotel/hotel-142-user.mp3"}}, "hotel-143": {"agent": {"seconds": 1.621, "voice": "af_heart", "text": "We would like to offer you dessert.", "bytes": 20160, "sha256": "7c32b0aecf0436cba6d80df2dbd303173e0ad41df1a53921706bb084ae0df861", "src": "audio/hotel/hotel-143-agent.mp3"}, "user": {"seconds": 1.429, "voice": "af_bella", "text": "That is very kind of you.", "bytes": 17856, "sha256": "f88920c9868d04db00074967ae7f71e91d8a40ae20d2a956746a065a2e63c506", "src": "audio/hotel/hotel-143-user.mp3"}}, "hotel-144": {"agent": {"seconds": 1.963, "voice": "af_heart", "text": "Thank you very much for your patience.", "bytes": 24192, "sha256": "a1ef4f9bc84d4dea26e1640a8a1123a8deb9fd7c2574ab07438c1c823be286f5", "src": "audio/hotel/hotel-144-agent.mp3"}, "user": {"seconds": 1.6, "voice": "af_bella", "text": "Thank you for listening to me.", "bytes": 19872, "sha256": "e448fe5a6959ea06ef1db19656fab3c596f40f27e4c803df61a95db83713fe2f", "src": "audio/hotel/hotel-144-user.mp3"}}}, "interview": {"interview-001": {"agent": {"seconds": 3.584, "voice": "am_michael", "text": "Hi, welcome in! I'm Sarah, the hiring manager.", "bytes": 43776, "sha256": "a81c847b753a7c4cf43e8e94c4184efff10318bf957b06363f280b09829c4b59", "src": "audio/interview/interview-001-agent.mp3"}, "user": {"seconds": 2.923, "voice": "af_heart", "text": "Hi Sarah, great to meet you. Thanks for having me.", "bytes": 35712, "sha256": "eac171325d192a9b7c0dbf7a020f5023a01b70a01e6a85421ae5abbaf65b9aa8", "src": "audio/interview/interview-001-user.mp3"}}, "interview-002": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "Did you find the office alright?", "bytes": 27072, "sha256": "03067ee1cf6841b2fb35d409a80a0782a48867aa435a75a5407d25525b12e316", "src": "audio/interview/interview-002-agent.mp3"}, "user": {"seconds": 3.264, "voice": "af_heart", "text": "Yes, your directions were very clear. No trouble at all.", "bytes": 39744, "sha256": "ac0fa742a68bd3f3104cb3206a1daea53343fb00e51ecefa6fb5cf3eab590053", "src": "audio/interview/interview-002-user.mp3"}}, "interview-003": {"agent": {"seconds": 2.368, "voice": "am_michael", "text": "Can I get you some water or coffee?", "bytes": 29088, "sha256": "1381f7d9df32902d0d7b164ff551840f66613c16f5d43a185f7c4314288820c1", "src": "audio/interview/interview-003-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_heart", "text": "A glass of water would be great, thank you.", "bytes": 27360, "sha256": "102757fa2857a99571159854dd810c8d42fbd96844b27290dffa6d5e4e00b983", "src": "audio/interview/interview-003-user.mp3"}}, "interview-004": {"agent": {"seconds": 2.155, "voice": "am_michael", "text": "How was your trip over here today?", "bytes": 26496, "sha256": "8abe14542640d34935a898fc3f19c6acd905ac137d633a5a3c66f1e6cbcefcaa", "src": "audio/interview/interview-004-agent.mp3"}, "user": {"seconds": 3.136, "voice": "af_heart", "text": "Pretty smooth. The subway was faster than I expected.", "bytes": 38304, "sha256": "18d3ea257cd313fbf00dc23680f1204cfbe6956ff029659ec062e72240a1f4b7", "src": "audio/interview/interview-004-user.mp3"}}, "interview-005": {"agent": {"seconds": 2.432, "voice": "am_michael", "text": "Traffic can be terrible around this area.", "bytes": 29952, "sha256": "29da77329074bac8dd0f19a7894d7cd113a204a0ea5491f26981d011524e0863", "src": "audio/interview/interview-005-agent.mp3"}, "user": {"seconds": 3.179, "voice": "af_heart", "text": "I left early just in case, so I arrived relaxed.", "bytes": 38880, "sha256": "ef1deb5b98f4e47c320132304e5f7a6a7bcee662eed9dae924244d39d8310b19", "src": "audio/interview/interview-005-user.mp3"}}, "interview-006": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "I see you brought a copy of your resume.", "bytes": 31968, "sha256": "cd763e357ca3840e744f556ef1330d19db9876453889e023f85e983f03c6ff58", "src": "audio/interview/interview-006-agent.mp3"}, "user": {"seconds": 2.411, "voice": "af_heart", "text": "Yes, I printed a few copies for the team.", "bytes": 29664, "sha256": "df40d8c5a9e81c86bb8261a124ca7319491c4b2d78e4a858e465ecb185463a99", "src": "audio/interview/interview-006-user.mp3"}}, "interview-007": {"agent": {"seconds": 1.92, "voice": "am_michael", "text": "So, how are you feeling today?", "bytes": 23616, "sha256": "694e10fffbb555855a6384d325f57be00532ee2c8555cbff53012929868cb40e", "src": "audio/interview/interview-007-agent.mp3"}, "user": {"seconds": 3.861, "voice": "af_heart", "text": "Excited, honestly. I've been looking forward to this conversation.", "bytes": 46944, "sha256": "e6cfad45c20789f0fc1b65cc23f924f47e2e504e2cd9437d063804eeac268fe0", "src": "audio/interview/interview-007-user.mp3"}}, "interview-008": {"agent": {"seconds": 3.157, "voice": "am_michael", "text": "Great office, isn't it? We moved in last spring.", "bytes": 38592, "sha256": "ff9b85596d1f13a02212514058a5b5c1aa8649b7c224eda502ceba56b44e5d27", "src": "audio/interview/interview-008-agent.mp3"}, "user": {"seconds": 3.093, "voice": "af_heart", "text": "It's lovely. The open space feels really welcoming.", "bytes": 37728, "sha256": "f1ca8c4d00bad6a5aba4b2ed349b10b778552caeec31caba1fef2ccd8f653cb3", "src": "audio/interview/interview-008-user.mp3"}}, "interview-009": {"agent": {"seconds": 2.283, "voice": "am_michael", "text": "Before we start, anything you need?", "bytes": 28224, "sha256": "fd0e54613cbfdc343a5c8a6103d7fb1018b5bd0fc74007735742006bb6c97a6b", "src": "audio/interview/interview-009-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_heart", "text": "I'm all set. Shall we dive right in?", "bytes": 25632, "sha256": "8474c1cb23fbf702bc3c593732b23d8eaa9e27b4b189b13624758b377784c29e", "src": "audio/interview/interview-009-user.mp3"}}, "interview-010": {"agent": {"seconds": 2.411, "voice": "am_michael", "text": "I enjoyed our phone chat last week.", "bytes": 29664, "sha256": "112a937472ef7038c6e5f4a5921e218b0da132a24fe6f98cf3f240bc2c01a912", "src": "audio/interview/interview-010-agent.mp3"}, "user": {"seconds": 2.837, "voice": "af_heart", "text": "Me too. It got me even more interested in the role.", "bytes": 34848, "sha256": "613ef8ed9a52bae1f4e2df119d1cb434c1a4ae13bde2326cdcd5419d61b4fc8f", "src": "audio/interview/interview-010-user.mp3"}}, "interview-011": {"agent": {"seconds": 2.56, "voice": "am_michael", "text": "Let me grab my notes, one second.", "bytes": 31392, "sha256": "57aadf606c380ddf67c91ada26e19955769cc4264bd5d1ba7e07b61477893896", "src": "audio/interview/interview-011-agent.mp3"}, "user": {"seconds": 2.475, "voice": "af_heart", "text": "Of course, take your time. I'm in no rush.", "bytes": 30528, "sha256": "728fd8fdd4eca06a3c3184efb5691dad568ee432828dc8fe0983de190705c9fa", "src": "audio/interview/interview-011-user.mp3"}}, "interview-012": {"agent": {"seconds": 2.368, "voice": "am_michael", "text": "Alright, let's get started, shall we?", "bytes": 29088, "sha256": "3500d4d9e87dd373a7e89fb8e069a5895780f1e002e19d2036b277dfe78f237d", "src": "audio/interview/interview-012-agent.mp3"}, "user": {"seconds": 2.475, "voice": "af_heart", "text": "Absolutely. I'm ready whenever you are.", "bytes": 30528, "sha256": "92494f9400f3e5f795ea835b7f6d4b0b4cafe7c1af38de250e29fb34f3705503", "src": "audio/interview/interview-012-user.mp3"}}, "interview-013": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "So, tell me a little about yourself.", "bytes": 27072, "sha256": "5038485e64ec148cd432472461e00919b2ff17bdf62cb46550f68568f6acfffd", "src": "audio/interview/interview-013-agent.mp3"}, "user": {"seconds": 3.285, "voice": "af_heart", "text": "Sure. I'm a quality engineer with eight years of experience.", "bytes": 40032, "sha256": "f9571c52f274c9caaff70a242596653680967e8ade9f4ce6173a21beef2af000", "src": "audio/interview/interview-013-user.mp3"}}, "interview-014": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "Walk me through your background, please.", "bytes": 27648, "sha256": "a008773e0ebc8b9d70f4922cc006e97c7116910980addc52a7bb45f7539ee80d", "src": "audio/interview/interview-014-agent.mp3"}, "user": {"seconds": 4.117, "voice": "af_heart", "text": "I started as a process engineer, then moved into quality management.", "bytes": 50112, "sha256": "efe020cdf2421292dbda8824418a63c611e0c2fb38ccfdcfe505a9189995b0ca", "src": "audio/interview/interview-014-user.mp3"}}, "interview-015": {"agent": {"seconds": 2.176, "voice": "am_michael", "text": "What does your current role involve?", "bytes": 26784, "sha256": "d7151708f77350d34318386aaffdfdb55eda9fcfd5780d5ea287b77f2576adce", "src": "audio/interview/interview-015-agent.mp3"}, "user": {"seconds": 3.989, "voice": "af_heart", "text": "I lead supplier quality for three major automotive programs.", "bytes": 48672, "sha256": "622682019eb4e6c201fb05f356ff00df183844306a231e287f7f3b91da20d42e", "src": "audio/interview/interview-015-user.mp3"}}, "interview-016": {"agent": {"seconds": 1.749, "voice": "am_michael", "text": "What got you into this field?", "bytes": 21600, "sha256": "d247c6a58c1396028e865c3f4156cfa5b8f52ebfdeca2a2518a533bf4f1d1a7b", "src": "audio/interview/interview-016-agent.mp3"}, "user": {"seconds": 3.648, "voice": "af_heart", "text": "I've always loved solving problems that affect real products.", "bytes": 44352, "sha256": "ac14dd85e8b4df5773ebeec0ff66b0586851bfeffe94e35f7e6cf8d2a35cab90", "src": "audio/interview/interview-016-user.mp3"}}, "interview-017": {"agent": {"seconds": 2.624, "voice": "am_michael", "text": "Summarize your biggest achievement for me.", "bytes": 32256, "sha256": "5158fcd56d28eb1830e153b3c9c1e5c2fc5480494b58b34c00b1ec5f8aa7b94a", "src": "audio/interview/interview-017-agent.mp3"}, "user": {"seconds": 3.115, "voice": "af_heart", "text": "I cut our defect rate by forty percent in one year.", "bytes": 38016, "sha256": "aa7ff18513dfc5e06635cb43dc0eec5f5270c9a7aea02f2c36ebf8d46c9ef75d", "src": "audio/interview/interview-017-user.mp3"}}, "interview-018": {"agent": {"seconds": 1.621, "voice": "am_michael", "text": "Where did you do your studies?", "bytes": 20160, "sha256": "133a8b93005a07cc7c08d7fb733e8171e5b7f414720223f4c14fbd32ed7ae981", "src": "audio/interview/interview-018-agent.mp3"}, "user": {"seconds": 4.437, "voice": "af_heart", "text": "I earned my engineering degree at a technical university in Shenzhen.", "bytes": 53856, "sha256": "feeddf5b9ad0cbb143670f1f5ef2cc4b929e44f5b9eb9e402fb0c408f8578026", "src": "audio/interview/interview-018-user.mp3"}}, "interview-019": {"agent": {"seconds": 2.688, "voice": "am_michael", "text": "Do you hold any certifications worth mentioning?", "bytes": 32832, "sha256": "9d5a26d41621531a220d3c5e6490d9deb91bd382e943c559ed53f7327eef0313", "src": "audio/interview/interview-019-agent.mp3"}, "user": {"seconds": 4.011, "voice": "af_heart", "text": "I'm a certified Six Sigma Black Belt, and I speak three languages.", "bytes": 48960, "sha256": "7e97288a05bea3ef6b3f8b272d1479028723a58ea22288e7ead1ad21c15eb76d", "src": "audio/interview/interview-019-user.mp3"}}, "interview-020": {"agent": {"seconds": 1.771, "voice": "am_michael", "text": "What are you doing right now?", "bytes": 21888, "sha256": "53ead548b7b81e1eb29183ebe51e78a6f0c3528fd091962b53d45a3c6da2f194", "src": "audio/interview/interview-020-agent.mp3"}, "user": {"seconds": 3.307, "voice": "af_heart", "text": "Currently I manage a team of five quality engineers.", "bytes": 40320, "sha256": "30ecff35ff5d8749ae10fcd9d1de79637a8f9c13e6909b43c059fc8ad190d163", "src": "audio/interview/interview-020-user.mp3"}}, "interview-021": {"agent": {"seconds": 2.005, "voice": "am_michael", "text": "Why are you looking to move on?", "bytes": 24768, "sha256": "a44edacdadfee506b8575e58cbc8acb44c9d6ed4911e1f52c33fd85a25c4ed4b", "src": "audio/interview/interview-021-agent.mp3"}, "user": {"seconds": 3.477, "voice": "af_heart", "text": "I'm ready for a bigger challenge and broader responsibility.", "bytes": 42336, "sha256": "d513b57bc3d642a5532ff8cd92ee5408f98e5c900ac34523678526445313f134", "src": "audio/interview/interview-021-user.mp3"}}, "interview-022": {"agent": {"seconds": 2.411, "voice": "am_michael", "text": "Give me the short version of your career.", "bytes": 29664, "sha256": "7cda10e01b5dcaa3296e1d33d59c9636a104967439ee41273600083769ecf008", "src": "audio/interview/interview-022-agent.mp3"}, "user": {"seconds": 4.587, "voice": "af_heart", "text": "Eight years, three companies, one clear focus: building reliable products.", "bytes": 55872, "sha256": "0d96b94385fe4218554f168997aeec721aff2d2fc8b11a8121c578c7ba0a2d23", "src": "audio/interview/interview-022-user.mp3"}}, "interview-023": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "What should I remember about you?", "bytes": 25344, "sha256": "d2903c604760458c45e0ab98416afe705b9c8eab5249e32e836be7c3d8b869e9", "src": "audio/interview/interview-023-agent.mp3"}, "user": {"seconds": 3.648, "voice": "af_heart", "text": "That I turn quality problems into measurable business results.", "bytes": 44352, "sha256": "eb70fc8f230e1cf4faa7a7bebc67cf3ea51555ddeac59e7987681f15e1f789b7", "src": "audio/interview/interview-023-user.mp3"}}, "interview-024": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "Anything else before we move on?", "bytes": 27072, "sha256": "22fdb3150b0f1901ab9139921dea8f121c95d20f377fbd53509717c32fd20801", "src": "audio/interview/interview-024-agent.mp3"}, "user": {"seconds": 3.093, "voice": "af_heart", "text": "Just that I'm genuinely excited about this opportunity.", "bytes": 37728, "sha256": "dff887fb0c4f1d68d5eb276ad03149a4597a7bb44048f872db3ecdae66088a79", "src": "audio/interview/interview-024-user.mp3"}}, "interview-025": {"agent": {"seconds": 2.795, "voice": "am_michael", "text": "Describe your most recent project for me.", "bytes": 34272, "sha256": "d207a2cf1cbc37ebefb0dcc2b93b19411ba3a60f216b7425831a401364055063", "src": "audio/interview/interview-025-agent.mp3"}, "user": {"seconds": 3.989, "voice": "af_heart", "text": "I led the launch quality plan for a new electric vehicle platform.", "bytes": 48672, "sha256": "34101d4443f47f48f7742126f9cbd0b030d43c17efe622de0e6eb13b0c96587d", "src": "audio/interview/interview-025-user.mp3"}}, "interview-026": {"agent": {"seconds": 2.773, "voice": "am_michael", "text": "What was your exact responsibility there?", "bytes": 33984, "sha256": "e1c93ba04e8654e2f9f9da24c9d0e2d62db5772387d7f2ce407e6de6eb9644ad", "src": "audio/interview/interview-026-agent.mp3"}, "user": {"seconds": 3.712, "voice": "af_heart", "text": "I owned the supplier audit schedule and the containment process.", "bytes": 45216, "sha256": "1cce27cef0bfd0aa7657b1da68eb183f09e490cd21a8ea6a43cd285ef2e16559", "src": "audio/interview/interview-026-user.mp3"}}, "interview-027": {"agent": {"seconds": 2.304, "voice": "am_michael", "text": "Tell me about a problem you solved.", "bytes": 28224, "sha256": "35813e9c1529fdd726ba097b59d81959987ea0f0fc1402d185980c86921f763b", "src": "audio/interview/interview-027-agent.mp3"}, "user": {"seconds": 3.157, "voice": "af_heart", "text": "A key supplier kept shipping parts with surface defects.", "bytes": 38592, "sha256": "412f48098b46e20176907c9fdd53e64fe3542036196bb4a6399ba8bd7b27fbe9", "src": "audio/interview/interview-027-user.mp3"}}, "interview-028": {"agent": {"seconds": 2.176, "voice": "am_michael", "text": "What action did you take exactly?", "bytes": 26784, "sha256": "6365709f0ee8f4c64b7541f050edab845f6d17e7a6c88aa5b9335ac8e7b8a90f", "src": "audio/interview/interview-028-agent.mp3"}, "user": {"seconds": 4.075, "voice": "af_heart", "text": "I visited their plant and redesigned the inspection checklist with them.", "bytes": 49536, "sha256": "ac585ae107d0b8cf9d54660dc762568bf0832c6ec1c9801d3c1823f1889ab606", "src": "audio/interview/interview-028-user.mp3"}}, "interview-029": {"agent": {"seconds": 1.92, "voice": "am_michael", "text": "And what was the final result?", "bytes": 23616, "sha256": "f2d90242a4e90c467ad4048fda3eb46c0bb6e056e90107fcf562566fefa765d2", "src": "audio/interview/interview-029-agent.mp3"}, "user": {"seconds": 2.667, "voice": "af_heart", "text": "Defects dropped to nearly zero within two months.", "bytes": 32832, "sha256": "4ba60e776a4de1a810688c683b201fbe4d2f252d4d9f6788387fc50ebd42ebb3", "src": "audio/interview/interview-029-user.mp3"}}, "interview-030": {"agent": {"seconds": 2.432, "voice": "am_michael", "text": "Give me another example with numbers.", "bytes": 29952, "sha256": "42d1ca757544cd2bb3329ca6aa22e31af531fb589e97700a13839bd89d0df136", "src": "audio/interview/interview-030-agent.mp3"}, "user": {"seconds": 4.544, "voice": "af_heart", "text": "I reduced warranty claims by twenty-five percent across two product lines.", "bytes": 55296, "sha256": "b003fcf6dfa27f3c2af67db97bdd6c9856a48d16be638ab1808f4f42be29b85d", "src": "audio/interview/interview-030-user.mp3"}}, "interview-031": {"agent": {"seconds": 1.877, "voice": "am_michael", "text": "How big were the teams you led?", "bytes": 23328, "sha256": "873461e78774661eb6726e950b1056e629e9153088e3c546725c69e73b6e4196", "src": "audio/interview/interview-031-agent.mp3"}, "user": {"seconds": 3.712, "voice": "af_heart", "text": "Usually five to eight people, plus external supplier teams.", "bytes": 45216, "sha256": "07ada64837f9bfe0d82b784ac61ee3a3331ef34d80cc69617dc7fe9b654704ac", "src": "audio/interview/interview-031-user.mp3"}}, "interview-032": {"agent": {"seconds": 1.984, "voice": "am_michael", "text": "What tools do you use daily?", "bytes": 24480, "sha256": "ac089655b4411e5afc8b9663d146688bc8276b14f50e334cdf8aca47dc70fc94", "src": "audio/interview/interview-032-agent.mp3"}, "user": {"seconds": 5.227, "voice": "af_heart", "text": "Mostly data dashboards, 8D reports, and statistical process control charts.", "bytes": 63360, "sha256": "d59c8c5b57ab96acb35dc5b1c2bdccd47baf5348762a1ecb3ec2b6b2aef15327", "src": "audio/interview/interview-032-user.mp3"}}, "interview-033": {"agent": {"seconds": 2.283, "voice": "am_michael", "text": "Have you ever been promoted at work?", "bytes": 28224, "sha256": "2969e9fdff22add0cde93666759e6c082df9297d5c4d188ee9ddcacb71da0a6a", "src": "audio/interview/interview-033-agent.mp3"}, "user": {"seconds": 4.16, "voice": "af_heart", "text": "Twice. Both times after delivering major cost-saving projects.", "bytes": 50688, "sha256": "d95013320f232274f6bcfe31b9e362b8e74aaaa5269a353a757858e1d88131f2", "src": "audio/interview/interview-033-user.mp3"}}, "interview-034": {"agent": {"seconds": 2.453, "voice": "am_michael", "text": "What's the hardest project you've handled?", "bytes": 30240, "sha256": "9fab7d20916c46288aee05774a5742efc3db8525354cb23e8d3b36b804f8a5c8", "src": "audio/interview/interview-034-agent.mp3"}, "user": {"seconds": 4.395, "voice": "af_heart", "text": "A recall investigation with a forty-eight-hour deadline from management.", "bytes": 53568, "sha256": "6a14b42b6ddd49f2bef885280225ed3602abb2fac0c44fc61429cea3e3770101", "src": "audio/interview/interview-034-user.mp3"}}, "interview-035": {"agent": {"seconds": 2.069, "voice": "am_michael", "text": "How did you manage that pressure?", "bytes": 25632, "sha256": "0aaab16287698ce7c1d75381b2e88729ba38f03d29593ec6059ae66e6c676ca3", "src": "audio/interview/interview-035-agent.mp3"}, "user": {"seconds": 3.755, "voice": "af_heart", "text": "I broke the work into shifts and kept everyone updated hourly.", "bytes": 45792, "sha256": "89e1358d8edac37e5ac1e4022f38c2fd94ce771fa4c66f563263f59fc9f2df64", "src": "audio/interview/interview-035-user.mp3"}}, "interview-036": {"agent": {"seconds": 1.536, "voice": "am_michael", "text": "What did you learn from it?", "bytes": 19008, "sha256": "beeb4b4f03109e4f0d6752802671c793ceee32618331f6e842fd2a10dabc546a", "src": "audio/interview/interview-036-agent.mp3"}, "user": {"seconds": 3.755, "voice": "af_heart", "text": "That clear communication matters more than perfect analysis.", "bytes": 45792, "sha256": "3a6ad19e131ce1384be0a8c4c3e22e3aa56e535443860f88600ebadba7ef0c36", "src": "audio/interview/interview-036-user.mp3"}}, "interview-037": {"agent": {"seconds": 1.899, "voice": "am_michael", "text": "What would you say are your strengths?", "bytes": 23616, "sha256": "08dbd646167a9c19a5a6a1accac84512f35e26efb3c429ca67f6430021cec228", "src": "audio/interview/interview-037-agent.mp3"}, "user": {"seconds": 3.221, "voice": "af_heart", "text": "I'm analytical, persistent, and calm under pressure.", "bytes": 39456, "sha256": "32a2ad0bbe37db4c6756273e5ed1ea94cba81a61f44267c6dd7f7581bdb424f8", "src": "audio/interview/interview-037-user.mp3"}}, "interview-038": {"agent": {"seconds": 3.136, "voice": "am_michael", "text": "Give me an example of your analytical thinking.", "bytes": 38304, "sha256": "a8116988ff73151a8f901e5944adaa0bfb23d6a0f7a6a729dfbdb733858964d4", "src": "audio/interview/interview-038-agent.mp3"}, "user": {"seconds": 3.52, "voice": "af_heart", "text": "I traced a recurring failure to one faulty sensor batch.", "bytes": 42912, "sha256": "4a37c667c0f5c0e0bc1994ad58dcfdf6e8756259373b7b5b4a118ea7e0b2cd4e", "src": "audio/interview/interview-038-user.mp3"}}, "interview-039": {"agent": {"seconds": 2.005, "voice": "am_michael", "text": "What do colleagues praise you for?", "bytes": 24768, "sha256": "3a44de956085a1b0629e6e552d3a90f42f8cb8c36376d5bc93a62b2e44b8ecc6", "src": "audio/interview/interview-039-agent.mp3"}, "user": {"seconds": 3.179, "voice": "af_heart", "text": "They say I explain complex issues in simple terms.", "bytes": 38880, "sha256": "d38251a8bd9c1334783fe445b86effd5b96df2b0bb210ff66226e750a2a861c4", "src": "audio/interview/interview-039-user.mp3"}}, "interview-040": {"agent": {"seconds": 2.688, "voice": "am_michael", "text": "What makes you different from other candidates?", "bytes": 32832, "sha256": "56ad47952e8499c8369327f7fe36057c3bdfafc3fe16f596a6e539989cca7a77", "src": "audio/interview/interview-040-agent.mp3"}, "user": {"seconds": 3.179, "voice": "af_heart", "text": "I combine shop-floor experience with strong data skills.", "bytes": 38880, "sha256": "a2229a7323a603d20c05c4e9f9256c306176c016e18bc3b7c4d7466382775145", "src": "audio/interview/interview-040-user.mp3"}}, "interview-041": {"agent": {"seconds": 2.347, "voice": "am_michael", "text": "Are you more of a leader or a doer?", "bytes": 28800, "sha256": "332ae86c5be8be2937dacc46596442195332df76b249e396cf4551d40903eb7c", "src": "audio/interview/interview-041-agent.mp3"}, "user": {"seconds": 3.349, "voice": "af_heart", "text": "Both. I lead the strategy, then roll up my sleeves.", "bytes": 40896, "sha256": "42f7a9af8f2595df0250fb48408fcd5f82b6e919b78a489399f5ad55fa7fd96f", "src": "audio/interview/interview-041-user.mp3"}}, "interview-042": {"agent": {"seconds": 2.645, "voice": "am_michael", "text": "How would you rate your communication skills?", "bytes": 32544, "sha256": "e2570b73b41a851f1444d99aa2b61b51897c93101de0c8d30687b2f2fa9fea6b", "src": "audio/interview/interview-042-agent.mp3"}, "user": {"seconds": 3.925, "voice": "af_heart", "text": "Strong. I present to executives and operators with equal ease.", "bytes": 47808, "sha256": "d9a27bb9279c8d8a08208328944050572fdb7e7ce8be2b9d2d486283c7ab8038", "src": "audio/interview/interview-042-user.mp3"}}, "interview-043": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "Can you give a leadership example?", "bytes": 25344, "sha256": "0349bfb255c39a1ed1276fc49cbf99a917cdd395c798da068b27c8878c997f6f", "src": "audio/interview/interview-043-agent.mp3"}, "user": {"seconds": 3.52, "voice": "af_heart", "text": "I mentored two junior engineers who both earned promotions.", "bytes": 42912, "sha256": "d10c102aa227c1c9dac3d5075e35f171e10222dcfcc5019766c090b5b4dcfb1b", "src": "audio/interview/interview-043-user.mp3"}}, "interview-044": {"agent": {"seconds": 2.155, "voice": "am_michael", "text": "How do you handle data in your work?", "bytes": 26496, "sha256": "f65fc4181c1a8f921cc214cf03f45cef6c9d58deeecd65a891a1d46e4cec9add", "src": "audio/interview/interview-044-agent.mp3"}, "user": {"seconds": 3.328, "voice": "af_heart", "text": "I turn raw numbers into decisions people can act on.", "bytes": 40608, "sha256": "d864bd8c3710a74937c274b88ce4092db038971f770a5d4072ee3351dbac8d0f", "src": "audio/interview/interview-044-user.mp3"}}, "interview-045": {"agent": {"seconds": 2.795, "voice": "am_michael", "text": "What about creativity in problem solving?", "bytes": 34272, "sha256": "46f0e066d691d2995c92c38da1f464ec20cba87f4a47df30e52c7381a6e5dbe9", "src": "audio/interview/interview-045-agent.mp3"}, "user": {"seconds": 3.456, "voice": "af_heart", "text": "I find practical fixes, not just textbook solutions.", "bytes": 42048, "sha256": "4624979232f6e4a882f5825e78ea858a3578059baa097b7f4694e613014d35b0", "src": "audio/interview/interview-045-user.mp3"}}, "interview-046": {"agent": {"seconds": 3.221, "voice": "am_michael", "text": "Would you describe yourself as detail-oriented?", "bytes": 39456, "sha256": "54ce36aa8ab2018acd8a5d63da984a7bed6ed4e13cc428af2d9c2c9fdc2e8f67", "src": "audio/interview/interview-046-agent.mp3"}, "user": {"seconds": 3.051, "voice": "af_heart", "text": "Very. I catch issues in drawings that others miss.", "bytes": 37440, "sha256": "7ce38177dd42d15a340e85472d6a73331ec60441b05c532783c3ba0a74fa0da9", "src": "audio/interview/interview-046-user.mp3"}}, "interview-047": {"agent": {"seconds": 2.731, "voice": "am_michael", "text": "How quickly do you usually learn new things?", "bytes": 33408, "sha256": "88025cf4617e0263addcd958806712607d452348efadbfd84ea8e51e9ddde8f2", "src": "audio/interview/interview-047-agent.mp3"}, "user": {"seconds": 3.349, "voice": "af_heart", "text": "Fast. I mastered our new QMS software in two weeks.", "bytes": 40896, "sha256": "90b6dc1d0bf7690163083c1c92cf408c10b277aa39081f399e346b825614b9a5", "src": "audio/interview/interview-047-user.mp3"}}, "interview-048": {"agent": {"seconds": 2.389, "voice": "am_michael", "text": "Sum up your strengths in one sentence.", "bytes": 29376, "sha256": "9e0d82824b4d1316a098d21d4b89a9988293fb0f1f86a004ec62c07c965e0bf4", "src": "audio/interview/interview-048-agent.mp3"}, "user": {"seconds": 3.157, "voice": "af_heart", "text": "I solve real problems fast and bring people with me.", "bytes": 38592, "sha256": "c16c40db9844b080ef8e660e68eacddb7cf1362a7e57c8832435dbb442904c65", "src": "audio/interview/interview-048-user.mp3"}}, "interview-049": {"agent": {"seconds": 2.688, "voice": "am_michael", "text": "Now the classic one: your weaknesses?", "bytes": 32832, "sha256": "649fbfa222c892a22cb5ffe83ad4e9396e30de85fcf28d29a179ae1257fa960d", "src": "audio/interview/interview-049-agent.mp3"}, "user": {"seconds": 2.624, "voice": "af_heart", "text": "I used to over-prepare for every single meeting.", "bytes": 32256, "sha256": "3f684786fb955ac5742d86c5daf033161dd17d4c043f23fbf434d4af246646c4", "src": "audio/interview/interview-049-user.mp3"}}, "interview-050": {"agent": {"seconds": 2.027, "voice": "am_michael", "text": "How did you address that weakness?", "bytes": 25056, "sha256": "560f62f00a6568ea685c11a7168f8bbea2eaf00d6d46c1600e2f062dd71b2645", "src": "audio/interview/interview-050-agent.mp3"}, "user": {"seconds": 2.965, "voice": "af_heart", "text": "I learned to trust my preparation and stay flexible.", "bytes": 36288, "sha256": "e95c437d01f8ea280eb76a19ec02f5b35bdb497674b679bf8332a0368d6b087f", "src": "audio/interview/interview-050-user.mp3"}}, "interview-051": {"agent": {"seconds": 2.837, "voice": "am_michael", "text": "Is there an area you're actively improving now?", "bytes": 34848, "sha256": "d88ebce93e8440a867c7867aa77b349064ac42474e6f06874cbc22835d8f17a0", "src": "audio/interview/interview-051-agent.mp3"}, "user": {"seconds": 3.541, "voice": "af_heart", "text": "Public speaking. I joined a Toastmasters club last year.", "bytes": 43200, "sha256": "b701ded016c32d6da2bd57dbc286a44559d543eb749522c165f36794b4f7f160", "src": "audio/interview/interview-051-user.mp3"}}, "interview-052": {"agent": {"seconds": 2.624, "voice": "am_michael", "text": "Has any feedback ever surprised you?", "bytes": 32256, "sha256": "4273c7ad88ba0fb894ddcc7c7e8a15dcb60034fc7f2c72a0acd1532836bffb66", "src": "audio/interview/interview-052-agent.mp3"}, "user": {"seconds": 3.008, "voice": "af_heart", "text": "Once. My manager said I should delegate more often.", "bytes": 36864, "sha256": "6da9c9b153f4a18c76c002255935631c9586e85f62d310f7440cd820eb8a54dd", "src": "audio/interview/interview-052-user.mp3"}}, "interview-053": {"agent": {"seconds": 1.515, "voice": "am_michael", "text": "What did you do about it?", "bytes": 19008, "sha256": "71cab7260f3919b791a3518c5facb5d91ecb91333938b662ecb0dbab319a55ae", "src": "audio/interview/interview-053-agent.mp3"}, "user": {"seconds": 3.712, "voice": "af_heart", "text": "I started coaching my team instead of doing everything myself.", "bytes": 45216, "sha256": "adf6fbfbafcdd9aa9fbc9b1a518823f66349874063de4d47ee7f45f6d2376c4b", "src": "audio/interview/interview-053-user.mp3"}}, "interview-054": {"agent": {"seconds": 2.091, "voice": "am_michael", "text": "Tell me about a mistake you made.", "bytes": 25920, "sha256": "688c82fe7757ac317552cd534fea9627e9521d7a6b2f3099172656289c0cfad0", "src": "audio/interview/interview-054-agent.mp3"}, "user": {"seconds": 2.944, "voice": "af_heart", "text": "I approved a supplier change without full testing.", "bytes": 36000, "sha256": "ed34ffd58847f0b229a69d86822adc85199575d23790eba33356b86cee2c0a83", "src": "audio/interview/interview-054-user.mp3"}}, "interview-055": {"agent": {"seconds": 2.389, "voice": "am_michael", "text": "What happened after that big mistake?", "bytes": 29376, "sha256": "5cd72787d411ca2aa253b43f64b17615cbf07b15972c86f900864c43dc9f2e1f", "src": "audio/interview/interview-055-agent.mp3"}, "user": {"seconds": 2.603, "voice": "af_heart", "text": "We caught it early, but it taught me to slow down.", "bytes": 31968, "sha256": "a8b3ab0a79ed1e1be20d1c2876669aa5aaaf70ae6d5525bbf4e26b15acbc585d", "src": "audio/interview/interview-055-user.mp3"}}, "interview-056": {"agent": {"seconds": 2.069, "voice": "am_michael", "text": "What skill do you still want to build?", "bytes": 25632, "sha256": "e1668a2595cfa81cc42bffea195393831ca3fc861132b0a87adddcd2f09f1755", "src": "audio/interview/interview-056-agent.mp3"}, "user": {"seconds": 2.795, "voice": "af_heart", "text": "I'd like to strengthen my financial modeling skills.", "bytes": 34272, "sha256": "620281d20ef7f85500e65524350a4b81ed9d8428d99e1e10b16890faa7485662", "src": "audio/interview/interview-056-user.mp3"}}, "interview-057": {"agent": {"seconds": 2.539, "voice": "am_michael", "text": "How do you usually handle criticism?", "bytes": 31104, "sha256": "bcfd931d48971f525f5cd2a43f2dd9fc7c823d3bcb2398ee4e7c0f14bdb295f6", "src": "audio/interview/interview-057-agent.mp3"}, "user": {"seconds": 2.688, "voice": "af_heart", "text": "I listen first, then decide what to change.", "bytes": 32832, "sha256": "ea1ddcdbf24258de7e0f9b190d9f9f11a6af19f373821bc215cac51982a727ee", "src": "audio/interview/interview-057-user.mp3"}}, "interview-058": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "Do you ever struggle with work-life balance?", "bytes": 31968, "sha256": "1aa95ebf38e2c0c766c776e1822ca2ea551b138d85bb645392a8debe4305c8d8", "src": "audio/interview/interview-058-agent.mp3"}, "user": {"seconds": 3.221, "voice": "af_heart", "text": "Sometimes, so I now block evenings for family time.", "bytes": 39456, "sha256": "1ca9fb1f3f0831c8559ce73bb72c59b6afee70b44935b02d1f81e6ee7afd740b", "src": "audio/interview/interview-058-user.mp3"}}, "interview-059": {"agent": {"seconds": 2.709, "voice": "am_michael", "text": "What's your biggest development goal this year?", "bytes": 33120, "sha256": "320aea04ef4585582f6067eeba8d32f48c2de514ed666c73549b52d04230faae", "src": "audio/interview/interview-059-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_heart", "text": "To become a better coach for my team members.", "bytes": 28512, "sha256": "b6783b079d915959828c0962110a1ce5d8f87aa01f94f6cdccb2477b35cc9c3a", "src": "audio/interview/interview-059-user.mp3"}}, "interview-060": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "Anything you wish you'd learned earlier?", "bytes": 28512, "sha256": "a21be0ba28abaddee3843883255f0764ff4029fba23737445b37c064d0af5557", "src": "audio/interview/interview-060-agent.mp3"}, "user": {"seconds": 2.752, "voice": "af_heart", "text": "To ask for help sooner instead of struggling alone.", "bytes": 33696, "sha256": "62d3e492e99b9ba7f83ebd8e2db91bdbdaa00659d8065eb9ec0045b4a931e319", "src": "audio/interview/interview-060-user.mp3"}}, "interview-061": {"agent": {"seconds": 2.389, "voice": "am_michael", "text": "Tell me about a great team you worked in.", "bytes": 29376, "sha256": "7962771b4fbf116c343fa9f9c3924cb25b288d4c7ef6776d30d4968e5da8ac4a", "src": "audio/interview/interview-061-agent.mp3"}, "user": {"seconds": 3.2, "voice": "af_heart", "text": "Our launch team hit every milestone for eighteen months straight.", "bytes": 39168, "sha256": "a22022a2bfb2db4ce2acb8025106e2596f034fc61846bb1aca79dd655f1c6b25", "src": "audio/interview/interview-061-user.mp3"}}, "interview-062": {"agent": {"seconds": 1.451, "voice": "am_michael", "text": "What was your role in it?", "bytes": 18144, "sha256": "eda88c1a8046ee4372af95d69303917c00d7707ae6375e7445f14e36e190a6fb", "src": "audio/interview/interview-062-agent.mp3"}, "user": {"seconds": 4.245, "voice": "af_heart", "text": "I coordinated quality gates between engineering and manufacturing.", "bytes": 51552, "sha256": "d72336c5d791bbdeb1282aee6cb561b110c57d1a14f2ff703e6cd10bef25238f", "src": "audio/interview/interview-062-user.mp3"}}, "interview-063": {"agent": {"seconds": 2.283, "voice": "am_michael", "text": "Ever had a conflict with a colleague?", "bytes": 28224, "sha256": "10e3db765213b0e6dd7fc1a03b16efea62514e741cc4d349e58034854a3a54c5", "src": "audio/interview/interview-063-agent.mp3"}, "user": {"seconds": 3.349, "voice": "af_heart", "text": "Yes. A designer and I disagreed on a tolerance spec.", "bytes": 40896, "sha256": "2a374c5489f77d4d99753f8ab8396dfe2567498f578016004b5d75ceb5031fc3", "src": "audio/interview/interview-063-user.mp3"}}, "interview-064": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "How did you resolve that conflict?", "bytes": 28512, "sha256": "2c982da88f6a16ad497beaccb409dd5e334d6baa2907fe28d449c949e5a49cc8", "src": "audio/interview/interview-064-agent.mp3"}, "user": {"seconds": 2.987, "voice": "af_heart", "text": "We tested both options and let the data decide.", "bytes": 36576, "sha256": "a332e4707f9c895fe581343eed302176602270fa730a9ec0d35f8395668371b1", "src": "audio/interview/interview-064-user.mp3"}}, "interview-065": {"agent": {"seconds": 2.432, "voice": "am_michael", "text": "Tell me about helping a struggling teammate.", "bytes": 29952, "sha256": "a90168e24fb9831a98fe5534851676a9d697f964331c1a659a4174474eecdd7f", "src": "audio/interview/interview-065-agent.mp3"}, "user": {"seconds": 3.179, "voice": "af_heart", "text": "I spent two weeks coaching a new hire through his first audit.", "bytes": 38880, "sha256": "799e99e9b4b700229956ca6a168056d2b98dd1be1f538de8e90c8671c9f15d94", "src": "audio/interview/interview-065-user.mp3"}}, "interview-066": {"agent": {"seconds": 2.176, "voice": "am_michael", "text": "How do you work with difficult people?", "bytes": 26784, "sha256": "a444aa384c1ecc913f650ca6b1c11d18bec3ef9091d3acf296ff5ec4f0aea1b2", "src": "audio/interview/interview-066-agent.mp3"}, "user": {"seconds": 3.2, "voice": "af_heart", "text": "I focus on shared goals, not personal differences.", "bytes": 39168, "sha256": "d6759f66a88cad82e24dd0c0045423c32332188868ab5698fd669b42de6ec1ce", "src": "audio/interview/interview-066-user.mp3"}}, "interview-067": {"agent": {"seconds": 3.136, "voice": "am_michael", "text": "Describe a cross-functional project you joined.", "bytes": 38304, "sha256": "e96401e8e19548e783242f214fd4cfcabea88999f08f22e6bea6266b62b37334", "src": "audio/interview/interview-067-agent.mp3"}, "user": {"seconds": 3.627, "voice": "af_heart", "text": "I partnered with purchasing and R&D on a supplier switch.", "bytes": 44352, "sha256": "1deaa2c894956a576e19bd35ded4d3b807148a736b065d4c7e09a7a2b2c6ea39", "src": "audio/interview/interview-067-user.mp3"}}, "interview-068": {"agent": {"seconds": 2.261, "voice": "am_michael", "text": "How do you build trust in a new team?", "bytes": 27936, "sha256": "1aae5a2f05a8c2da11e40bc24e9c97322a98644e813a0fc7bac150c590156e6a", "src": "audio/interview/interview-068-agent.mp3"}, "user": {"seconds": 3.968, "voice": "af_heart", "text": "By delivering on small promises, consistently, from day one.", "bytes": 48384, "sha256": "4d9735692db12fba37daee37e5bd90353d3e507288af8378f6bdd80ecd28480e", "src": "audio/interview/interview-068-user.mp3"}}, "interview-069": {"agent": {"seconds": 1.963, "voice": "am_michael", "text": "Have you led a team through change?", "bytes": 24192, "sha256": "7895230f081fc589364bcff4d22a660fe94d25957748b257ba6e024ad5a9f60b", "src": "audio/interview/interview-069-agent.mp3"}, "user": {"seconds": 3.307, "voice": "af_heart", "text": "Yes. I guided my team through a full system migration.", "bytes": 40320, "sha256": "ebe117871c81c20702bc0b009e6101b0b25a2e69dce0ca0e77b6180e1105f4b0", "src": "audio/interview/interview-069-user.mp3"}}, "interview-070": {"agent": {"seconds": 2.219, "voice": "am_michael", "text": "What does good teamwork look like to you?", "bytes": 27360, "sha256": "459c9646adec9a218adb68c0de79862c6fb9ff498c87a34f279c70ae34e199fc", "src": "audio/interview/interview-070-agent.mp3"}, "user": {"seconds": 3.051, "voice": "af_heart", "text": "Honest debate in the room, full commitment outside it.", "bytes": 37440, "sha256": "30d80cec05ae8d2ff24770fd614abe1a7418d683af1d2a3fcb471fdf2a8be95e", "src": "audio/interview/interview-070-user.mp3"}}, "interview-071": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "How do you celebrate team wins?", "bytes": 25344, "sha256": "95fff33782a8d648dd5c4b3c35c2a448c2b346a5408167443c992432b8e62ec3", "src": "audio/interview/interview-071-agent.mp3"}, "user": {"seconds": 3.413, "voice": "af_heart", "text": "I always credit the team publicly before mentioning myself.", "bytes": 41760, "sha256": "f9fe532e60b4fd639f5bb2062b356df0a8529115ff0d6d0dd0e9f908e19d131f", "src": "audio/interview/interview-071-user.mp3"}}, "interview-072": {"agent": {"seconds": 1.899, "voice": "am_michael", "text": "What would your team say about you?", "bytes": 23616, "sha256": "a81be2b16b1d66bc29df2a355283446ef20f32e1347c900096f6131b74e7e4c7", "src": "audio/interview/interview-072-agent.mp3"}, "user": {"seconds": 2.795, "voice": "af_heart", "text": "That I'm demanding but fair, and I have their backs.", "bytes": 34272, "sha256": "7f45f72682980e5291c5f59859b11a661d6c1ddd9910beffe3d9f31aa2ac5b68", "src": "audio/interview/interview-072-user.mp3"}}, "interview-073": {"agent": {"seconds": 2.133, "voice": "am_michael", "text": "How do you handle tight deadlines?", "bytes": 26208, "sha256": "4a025d5bee1d38038ab5f7a38194c0c8236bcfc5bd8351e4077a3380e2f3405f", "src": "audio/interview/interview-073-agent.mp3"}, "user": {"seconds": 3.925, "voice": "af_heart", "text": "I prioritize ruthlessly and communicate progress every day.", "bytes": 47808, "sha256": "62c00665b8fda0ff212e904d1116a9764f238c2f007a0888176d877b28946b14", "src": "audio/interview/interview-073-user.mp3"}}, "interview-074": {"agent": {"seconds": 2.923, "voice": "am_michael", "text": "Describe a high-pressure situation you faced.", "bytes": 35712, "sha256": "6c4bf046cfbdf8b008a25f2032b3b7dafd2953bf34ad865fe4909921acd31568", "src": "audio/interview/interview-074-agent.mp3"}, "user": {"seconds": 3.925, "voice": "af_heart", "text": "A customer escalation arrived the night before a major audit.", "bytes": 47808, "sha256": "14c9b44adaa935513c81a736f3495dc123a9da5200773a78ac26bdda8dd73970", "src": "audio/interview/interview-074-user.mp3"}}, "interview-075": {"agent": {"seconds": 2.475, "voice": "am_michael", "text": "What did you do first in that situation?", "bytes": 30528, "sha256": "1a6d845f2e19a13667ddb9c1e22d5b06506fdd513d2ea1aecb561d20edda8c51", "src": "audio/interview/interview-075-agent.mp3"}, "user": {"seconds": 3.243, "voice": "af_heart", "text": "I gathered the facts before reacting or assigning blame.", "bytes": 39744, "sha256": "01556a4479d4ce6c51281155c7adb1cc96257e337f78e906438ddd3570470647", "src": "audio/interview/interview-075-user.mp3"}}, "interview-076": {"agent": {"seconds": 2.347, "voice": "am_michael", "text": "How do you stay calm under pressure?", "bytes": 28800, "sha256": "d0e9df81e9a08cfbef0b37df671c946d90d6e1a8c62fc4568599b73d22b984e0", "src": "audio/interview/interview-076-agent.mp3"}, "user": {"seconds": 3.413, "voice": "af_heart", "text": "I focus on the next concrete step, not the whole mountain.", "bytes": 41760, "sha256": "6b62ea930365c58846ec4a70f8821d78d958a459260877fcbd12ddb037bba946", "src": "audio/interview/interview-076-user.mp3"}}, "interview-077": {"agent": {"seconds": 1.941, "voice": "am_michael", "text": "Tell me about a time you failed.", "bytes": 23904, "sha256": "e1ecce87f04e8cad27e03a296a7e868d268f911e16b106267c71589707298e02", "src": "audio/interview/interview-077-agent.mp3"}, "user": {"seconds": 2.88, "voice": "af_heart", "text": "I missed a cost target on my first big project.", "bytes": 35136, "sha256": "e33b8242067c1b10abc52c4e7a4ff374b57936d8d43629e0f93664ceb476ad25", "src": "audio/interview/interview-077-user.mp3"}}, "interview-078": {"agent": {"seconds": 2.219, "voice": "am_michael", "text": "How did you recover from that failure?", "bytes": 27360, "sha256": "862ac660d1a8fdb9fe6d3f25609722e283cba069d1ead8dba5d4be33b5d62250", "src": "audio/interview/interview-078-agent.mp3"}, "user": {"seconds": 3.541, "voice": "af_heart", "text": "I presented a recovery plan and delivered it ahead of schedule.", "bytes": 43200, "sha256": "60254d36bb4b92e7ad9444faaefcc100ec9669077087542d8da0da23656fb734", "src": "audio/interview/interview-078-user.mp3"}}, "interview-079": {"agent": {"seconds": 2.261, "voice": "am_michael", "text": "What if everything goes wrong at once?", "bytes": 27936, "sha256": "87e2f546cb542ad0200d9f782cc8219d2638304ab4a3c943e148773508bb15d5", "src": "audio/interview/interview-079-agent.mp3"}, "user": {"seconds": 3.029, "voice": "af_heart", "text": "I triage like a doctor: stop the bleeding first.", "bytes": 37152, "sha256": "2a721d6c63a1167d84458a60d2edee51e05321f644b60e5923352c33ceba0208", "src": "audio/interview/interview-079-user.mp3"}}, "interview-080": {"agent": {"seconds": 2.539, "voice": "am_michael", "text": "How do you prioritize competing tasks?", "bytes": 31104, "sha256": "119180ba08980705e5f18c345678e421c75283b0b799a2ff0df62ad1f264be09", "src": "audio/interview/interview-080-agent.mp3"}, "user": {"seconds": 3.819, "voice": "af_heart", "text": "Impact first, urgency second, everything else gets scheduled.", "bytes": 46656, "sha256": "77ed2c6c97cc581a41decbc2e8bdf365b4dc2c5c99196e704a1af6758637b784", "src": "audio/interview/interview-080-user.mp3"}}, "interview-081": {"agent": {"seconds": 3.029, "voice": "am_michael", "text": "Ever disagreed with your boss under pressure?", "bytes": 37152, "sha256": "0ad20088a97492c4432e57e2e028147817ca1851b87ed88870c719ce1821683d", "src": "audio/interview/interview-081-agent.mp3"}, "user": {"seconds": 3.861, "voice": "af_heart", "text": "Yes. I presented the risks clearly, then followed the decision.", "bytes": 46944, "sha256": "6e9d07a5ff069e47af4db50d9591fb25d197d04258db6bce92c2edf08f37c9ef", "src": "audio/interview/interview-081-user.mp3"}}, "interview-082": {"agent": {"seconds": 2.645, "voice": "am_michael", "text": "How do you avoid burnout in busy periods?", "bytes": 32544, "sha256": "f7463f613a9bf2ec73ca4c10d6241f966c492d3b04d99e602156193ac1ef7898", "src": "audio/interview/interview-082-agent.mp3"}, "user": {"seconds": 2.923, "voice": "af_heart", "text": "I protect my sleep and take real weekends off.", "bytes": 35712, "sha256": "144bf8d3f8154e04bdc221364d0798e521a65fcfbe7b64b9c34ee12b8ad6b63f", "src": "audio/interview/interview-082-user.mp3"}}, "interview-083": {"agent": {"seconds": 2.731, "voice": "am_michael", "text": "What keeps you motivated in tough times?", "bytes": 33408, "sha256": "ec8a3595ed47357b40e7d5f495f817b48aebe2fd11b57ca7ef4aa14d3589bd76", "src": "audio/interview/interview-083-agent.mp3"}, "user": {"seconds": 3.243, "voice": "af_heart", "text": "Seeing a fix I designed working on the production line.", "bytes": 39744, "sha256": "784ecaef4bfe54a1dd6eac070506f2c532eff5a71cc36f74a239543a68c581c1", "src": "audio/interview/interview-083-user.mp3"}}, "interview-084": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "Sum up your approach to pressure.", "bytes": 25344, "sha256": "07c8213062e56f09259e2a2cb7f8f08340a85ff871a4fbed35e6228d0da56ca2", "src": "audio/interview/interview-084-agent.mp3"}, "user": {"seconds": 3.115, "voice": "af_heart", "text": "Stay calm, get the facts, act fast, learn always.", "bytes": 38016, "sha256": "fd4c8b0a45e5807e856f678530f5d95cdc24c616946579387a2ac854b2e7803d", "src": "audio/interview/interview-084-user.mp3"}}, "interview-085": {"agent": {"seconds": 3.029, "voice": "am_michael", "text": "What are your salary expectations for this role?", "bytes": 37152, "sha256": "acb54f24dcf45ac127329408cac47d58cccde9d937d4a1f1c77b6e448a77705d", "src": "audio/interview/interview-085-agent.mp3"}, "user": {"seconds": 3.797, "voice": "af_heart", "text": "I'm looking for a base in the ninety to one-hundred-ten range.", "bytes": 46368, "sha256": "0c60e2ea62f41d32e972bfb28950b86eff7a906613cb41898f353b903fb83100", "src": "audio/interview/interview-085-user.mp3"}}, "interview-086": {"agent": {"seconds": 2.624, "voice": "am_michael", "text": "That's above our initial budget. Thoughts?", "bytes": 32256, "sha256": "d8df15ec5119892bde0d373b11eecbb639f9dd6269c6ad9db91fcd812ba3eef2", "src": "audio/interview/interview-086-agent.mp3"}, "user": {"seconds": 3.627, "voice": "af_heart", "text": "I understand budgets matter. Let's discuss the full package.", "bytes": 44352, "sha256": "baf2a8ba44ad31c75916ca7643228de8c40fa49952b5afe627b63658b0761d37", "src": "audio/interview/interview-086-user.mp3"}}, "interview-087": {"agent": {"seconds": 2.56, "voice": "am_michael", "text": "What matters most to you in compensation?", "bytes": 31392, "sha256": "ba9f76523d906d67eb326583a35d5696e9c1eb513a64c2fcd3d4b452000bbd44", "src": "audio/interview/interview-087-agent.mp3"}, "user": {"seconds": 3.072, "voice": "af_heart", "text": "Fair base pay, plus growth tied to clear results.", "bytes": 37440, "sha256": "1ba2509606a115599c2ab71df840791e1d5bf675fde6a74fd5e24a101fb42336", "src": "audio/interview/interview-087-user.mp3"}}, "interview-088": {"agent": {"seconds": 2.624, "voice": "am_michael", "text": "Would you consider a lower base with bonus?", "bytes": 32256, "sha256": "9f24b38b0e9a431f2881ef4451b137ae854d3695cb3d5892058183d1f55e2d2e", "src": "audio/interview/interview-088-agent.mp3"}, "user": {"seconds": 3.541, "voice": "af_heart", "text": "Yes, if the targets are realistic and clearly defined.", "bytes": 43200, "sha256": "5c6ae90e9a824a1fee5aa603cd3e86e68d8e36fec48e7a8ebdc6ef8c02b1445c", "src": "audio/interview/interview-088-user.mp3"}}, "interview-089": {"agent": {"seconds": 2.027, "voice": "am_michael", "text": "What benefits matter most to you?", "bytes": 25056, "sha256": "afd3baba2b7658d8825fd030330f86eae6da78ae3bce27795d8a3db616341972", "src": "audio/interview/interview-089-agent.mp3"}, "user": {"seconds": 3.115, "voice": "af_heart", "text": "Health coverage and learning budget matter a lot to me.", "bytes": 38016, "sha256": "2418a0a74b9cf94cf599e6048e6a7a446021f4f3863c03264cc06f72a2d3d5d2", "src": "audio/interview/interview-089-user.mp3"}}, "interview-090": {"agent": {"seconds": 2.475, "voice": "am_michael", "text": "Is there flexibility on your number?", "bytes": 30528, "sha256": "894cf45dfa24ecc00e15b2983bdd9c14cd1664135a0b2700ff636b64f15ccdbf", "src": "audio/interview/interview-090-agent.mp3"}, "user": {"seconds": 2.261, "voice": "af_heart", "text": "Some, for the right role and the right team.", "bytes": 27936, "sha256": "cca1549bbc0fc753b1e472ad73243d540e98ca641ef978e5bd7520201b028f4a", "src": "audio/interview/interview-090-user.mp3"}}, "interview-091": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "What does your current package look like?", "bytes": 27648, "sha256": "30e27f98dc6184ad233078d0a7b04713de8e20ab00068fe52e17e20134792994", "src": "audio/interview/interview-091-agent.mp3"}, "user": {"seconds": 2.581, "voice": "af_heart", "text": "I'd rather focus on the value I'll bring here.", "bytes": 31680, "sha256": "7ea4b6029680025c2e1bb31fd6a8a81d0198625c6b1621e41bb63984057370c5", "src": "audio/interview/interview-091-user.mp3"}}, "interview-092": {"agent": {"seconds": 2.261, "voice": "am_michael", "text": "We need a number to move forward.", "bytes": 27936, "sha256": "a12f70946ba501c6a7e713619f49a18243c69bdc55d964335e6abf607da0a97b", "src": "audio/interview/interview-092-agent.mp3"}, "user": {"seconds": 3.648, "voice": "af_heart", "text": "Then let's use my range as a starting point for discussion.", "bytes": 44352, "sha256": "e23b55e2d6988325866b4f7deab85e9ba06dbc877cb10946eb5d868e101a0aa0", "src": "audio/interview/interview-092-user.mp3"}}, "interview-093": {"agent": {"seconds": 2.667, "voice": "am_michael", "text": "How do you feel about equity or stock?", "bytes": 32832, "sha256": "a4503457488517a36c1a12ceebad8532ae9552452547f2ab19fef2a2f94d171b", "src": "audio/interview/interview-093-agent.mp3"}, "user": {"seconds": 2.859, "voice": "af_heart", "text": "I like it. It shows we're building something together.", "bytes": 35136, "sha256": "4fe25d0e5a83988a40339fc566b5d515e4e69ed994671ba8c6fa1b33e00feb7e", "src": "audio/interview/interview-093-user.mp3"}}, "interview-094": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "What if we can't meet your expectation?", "bytes": 28512, "sha256": "da9aed5a1f671d2be8b4f7daa47a4d35daa005ccbd4bacc7b8d28473e9540630", "src": "audio/interview/interview-094-agent.mp3"}, "user": {"seconds": 2.709, "voice": "af_heart", "text": "Then I'll need to weigh it against my other options.", "bytes": 33120, "sha256": "c16dabe18bfec7df604401475a04e37289d34748b56c5b4fb933b566352fa983", "src": "audio/interview/interview-094-user.mp3"}}, "interview-095": {"agent": {"seconds": 2.709, "voice": "am_michael", "text": "Are you interviewing with other companies too?", "bytes": 33120, "sha256": "1de098110234757169761a31759167e79b94b203d5ec898bdd30a2b3045fb837", "src": "audio/interview/interview-095-agent.mp3"}, "user": {"seconds": 2.709, "voice": "af_heart", "text": "Yes, but this role is my top choice so far.", "bytes": 33120, "sha256": "c6178fd82e8aefdae4287903cc2663058d568656a97fbdd7872f2fa8b2e7b8f0", "src": "audio/interview/interview-095-user.mp3"}}, "interview-096": {"agent": {"seconds": 3.093, "voice": "am_michael", "text": "Anything else you'd like to add on compensation?", "bytes": 37728, "sha256": "9fbc81a524b7ea2484eddf379fa721cdedb354b62638bc1c4951297c27aabc71", "src": "audio/interview/interview-096-agent.mp3"}, "user": {"seconds": 3.264, "voice": "af_heart", "text": "Just that I'm confident we can find a fair middle ground.", "bytes": 39744, "sha256": "3c5a306933bb6d9ca8debf0eac9ad0b24bbe065cbe0a335b0f11d286ff566522", "src": "audio/interview/interview-096-user.mp3"}}, "interview-097": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "What questions do you have for us?", "bytes": 25344, "sha256": "2ccd585e661da904782a597b273ca46566ce75397d9f29e41c84c75bff529218", "src": "audio/interview/interview-097-agent.mp3"}, "user": {"seconds": 2.539, "voice": "af_heart", "text": "What does success look like in the first six months?", "bytes": 31104, "sha256": "a89e907f8e46b517f7b2d605c11e94838ef90500c98eb2687394b8756b75ee8b", "src": "audio/interview/interview-097-user.mp3"}}, "interview-098": {"agent": {"seconds": 2.773, "voice": "am_michael", "text": "Good question. What else is on your mind?", "bytes": 33984, "sha256": "8ea38e4a60f44f81089c57e8e7bdf0eea55a1c5aa9b4114f934579a41761ce39", "src": "audio/interview/interview-098-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_heart", "text": "How would you describe the team culture here?", "bytes": 26496, "sha256": "c9d5760e389a90c2a97a218d79a9797ecb6badfbfc3a239d16d97c96f0447550", "src": "audio/interview/interview-098-user.mp3"}}, "interview-099": {"agent": {"seconds": 3.029, "voice": "am_michael", "text": "Anything you'd like to ask about the role itself?", "bytes": 37152, "sha256": "7a1d26b4ea4a662fac893a0d8e348d6ef822203e7cfce766925cbe62e18c321c", "src": "audio/interview/interview-099-agent.mp3"}, "user": {"seconds": 3.157, "voice": "af_heart", "text": "What are the biggest challenges facing this team right now?", "bytes": 38592, "sha256": "92d46d99981b37c5aaa2ec839d29807fbf79735ef5535a6f710897261194e0f1", "src": "audio/interview/interview-099-user.mp3"}}, "interview-100": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "That's a good one. Please go on.", "bytes": 25344, "sha256": "751bbc8998698867907175312dbea2961876773bf0204d09bf3278b032d59bb4", "src": "audio/interview/interview-100-agent.mp3"}, "user": {"seconds": 2.923, "voice": "af_heart", "text": "How is performance measured and reviewed in this role?", "bytes": 35712, "sha256": "0c7a7477941cfe6ea87354dafa4714040eac3601b6e4bb3788c117f4b7278ea7", "src": "audio/interview/interview-100-user.mp3"}}, "interview-101": {"agent": {"seconds": 1.899, "voice": "am_michael", "text": "What else would you like to know?", "bytes": 23616, "sha256": "3134d380f01758dd2ae6928f3a85c6cf48244a87c7596479b8b164a86882cc68", "src": "audio/interview/interview-101-agent.mp3"}, "user": {"seconds": 3.136, "voice": "af_heart", "text": "What opportunities exist for professional growth and learning?", "bytes": 38304, "sha256": "6bf28019f041ca3de7c45035d0db4b6a897d56006055c93d81ba1aca9ea648e4", "src": "audio/interview/interview-101-user.mp3"}}, "interview-102": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "Sure thing. What's your next question?", "bytes": 27072, "sha256": "f711708a435f7c95222dcccce602b273fbe18a61aa8d2ee1752935e37bd88b7d", "src": "audio/interview/interview-102-agent.mp3"}, "user": {"seconds": 2.389, "voice": "af_heart", "text": "Why did the previous person in this role leave?", "bytes": 29376, "sha256": "e610fcfbb8a0433cfdd4a4b1bae7dbe2239e90fe3ad05f9608d6166fd669579c", "src": "audio/interview/interview-102-user.mp3"}}, "interview-103": {"agent": {"seconds": 3.072, "voice": "am_michael", "text": "Fair question. Anything else you'd like to ask?", "bytes": 37440, "sha256": "997be7bf1eeb1247049676861b66fec8ace27c3ba1019195c77e177c64378818", "src": "audio/interview/interview-103-agent.mp3"}, "user": {"seconds": 3.285, "voice": "af_heart", "text": "How does the company support work-life balance in practice?", "bytes": 40032, "sha256": "123b450823d82f0ae13338d6e907edb09dee3f05b701f31dd1c09b708a7706a8", "src": "audio/interview/interview-103-user.mp3"}}, "interview-104": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "Good ones. Keep the questions coming.", "bytes": 27072, "sha256": "ed346425f001a5617f098f1a7ef84326ce47d016b6b8dd58de1e0fd3ba7b8f36", "src": "audio/interview/interview-104-agent.mp3"}, "user": {"seconds": 3.072, "voice": "af_heart", "text": "What's the most exciting project on the roadmap this year?", "bytes": 37440, "sha256": "13d26fc9a60670a70e29222fb160ca9ca3484d5c9a3a5ba07af278953a1c60fd", "src": "audio/interview/interview-104-user.mp3"}}, "interview-105": {"agent": {"seconds": 1.963, "voice": "am_michael", "text": "What about the team structure here?", "bytes": 24192, "sha256": "672cfe8ca5b47d5a0c60a50d79c9c5f59ff33a5de32d8537f110c8c2d810d654", "src": "audio/interview/interview-105-agent.mp3"}, "user": {"seconds": 2.581, "voice": "af_heart", "text": "Who would I report to, and who reports to me?", "bytes": 31680, "sha256": "6a1baff00666e8af585f289a6c1fd02a8f3c797addf0d7e2f9b26a4910da31b7", "src": "audio/interview/interview-105-user.mp3"}}, "interview-106": {"agent": {"seconds": 3.243, "voice": "am_michael", "text": "Anything you'd like to know about our future plans?", "bytes": 39744, "sha256": "625132b49137d3dd44c4a8da4df6155e1b687210ce34d38e3b95556664118805", "src": "audio/interview/interview-106-agent.mp3"}, "user": {"seconds": 2.453, "voice": "af_heart", "text": "Where do you see the company heading in five years?", "bytes": 30240, "sha256": "180428c85e6b393baed37380cbdc93b697282da70818c6e0337d6e500c08eea2", "src": "audio/interview/interview-106-user.mp3"}}, "interview-107": {"agent": {"seconds": 2.368, "voice": "am_michael", "text": "Do you have one last question for us?", "bytes": 29088, "sha256": "b22d678ae11ed11118e12d86bfc15c5ae88ddddf1b86fdb582ca8c82980a1837", "src": "audio/interview/interview-107-agent.mp3"}, "user": {"seconds": 2.261, "voice": "af_heart", "text": "What are the next steps in your hiring process?", "bytes": 27936, "sha256": "a41dceed6e8b76118baee91b5828fbe44eb76411ff580b11c8fabaa2169c84ae", "src": "audio/interview/interview-107-user.mp3"}}, "interview-108": {"agent": {"seconds": 1.877, "voice": "am_michael", "text": "We'll be in touch within a week.", "bytes": 23328, "sha256": "d9e1efacf13948b8b17af3fafad02805d79823897d1e0a659521141f584f9f0f", "src": "audio/interview/interview-108-agent.mp3"}, "user": {"seconds": 2.688, "voice": "af_heart", "text": "Perfect. I really appreciate your time today.", "bytes": 32832, "sha256": "805b380faee8679a6b62467597b46c918225b961f9fda25043c1c5db58b4b000", "src": "audio/interview/interview-108-user.mp3"}}, "interview-109": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "Hi, is this a good time to talk?", "bytes": 27648, "sha256": "d6c515c34f5a417b1915ec034bf5226d42805a4685146cc40bc8ef33da354687", "src": "audio/interview/interview-109-agent.mp3"}, "user": {"seconds": 3.051, "voice": "af_heart", "text": "Yes, perfect timing. I have about thirty minutes.", "bytes": 37440, "sha256": "f7b0cf2a3a1c51cae727bb17175b2dd8c79909fddfca6ed1936a8d611ff2e6fe", "src": "audio/interview/interview-109-user.mp3"}}, "interview-110": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "Great. Why are you interested in us?", "bytes": 27648, "sha256": "721cabfff13bab0b4eab67e08620e895e479202146533874ee0670beb61e4544", "src": "audio/interview/interview-110-agent.mp3"}, "user": {"seconds": 4.032, "voice": "af_heart", "text": "Your reputation for innovation really stands out in the industry.", "bytes": 48960, "sha256": "621ba7131f016bde3fb08eca9c4af0d44521f4b77368e2c2434e977612cbefeb", "src": "audio/interview/interview-110-user.mp3"}}, "interview-111": {"agent": {"seconds": 2.816, "voice": "am_michael", "text": "What's your notice period at your current job?", "bytes": 34560, "sha256": "6f702e96528e62d7e4beb7151fbddf0ae150d383ab9450449ec8fc96477061ff", "src": "audio/interview/interview-111-agent.mp3"}, "user": {"seconds": 3.307, "voice": "af_heart", "text": "Thirty days, though I can sometimes negotiate it shorter.", "bytes": 40320, "sha256": "1ae16e9265345e4ff9fdf04c12f9b43fb66794b95488357181d8a0d71475a25c", "src": "audio/interview/interview-111-user.mp3"}}, "interview-112": {"agent": {"seconds": 2.88, "voice": "am_michael", "text": "Would you be open to relocating for this role?", "bytes": 35136, "sha256": "2b2f95837a8c2e03018f8460069d33cd2a83e629388dac6bd109e48d48e75cee", "src": "audio/interview/interview-112-agent.mp3"}, "user": {"seconds": 2.581, "voice": "af_heart", "text": "Yes. I've already discussed it with my family.", "bytes": 31680, "sha256": "4b4ee2f8c5be3abdcc5a114a67e5ae7b3b574da41b56971a1e63d34a01456830", "src": "audio/interview/interview-112-user.mp3"}}, "interview-113": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "This role is hybrid. Does that work?", "bytes": 31968, "sha256": "8a16a71353c1e0197d85f4059e8774809738b69ddf159208cba9a5e37747ea6c", "src": "audio/interview/interview-113-agent.mp3"}, "user": {"seconds": 3.371, "voice": "af_heart", "text": "Absolutely. I work well both remotely and on-site.", "bytes": 41184, "sha256": "3cf5eddc489342f469b5e7c9d3bbd4a30d025d19a154fb6ce29ac1174cddfd0c", "src": "audio/interview/interview-113-user.mp3"}}, "interview-114": {"agent": {"seconds": 2.752, "voice": "am_michael", "text": "Would you need visa sponsorship from us?", "bytes": 33696, "sha256": "c1c7d37d874630c8a511eded8e145a5e0411ee1187934636535fb1ad973c923e", "src": "audio/interview/interview-114-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_heart", "text": "No, I'm fully authorized to work here.", "bytes": 27360, "sha256": "e48e7a084303ae9623c9d0beff26bfb4707d4eaddea32194294d1f4a62d5b0af", "src": "audio/interview/interview-114-user.mp3"}}, "interview-115": {"agent": {"seconds": 2.411, "voice": "am_michael", "text": "Can you share your current salary band?", "bytes": 29664, "sha256": "fea7cd48f23aacf71fbf117676dfa5d09f60a803cb67bc337addd00332f235c1", "src": "audio/interview/interview-115-agent.mp3"}, "user": {"seconds": 2.581, "voice": "af_heart", "text": "I'd prefer to discuss that later in the process.", "bytes": 31680, "sha256": "badca0327f1182f0b65add2737e3fcdf62b3c4688032e1abe53a6cfd3591beb7", "src": "audio/interview/interview-115-user.mp3"}}, "interview-116": {"agent": {"seconds": 2.389, "voice": "am_michael", "text": "Why are you leaving your current job?", "bytes": 29376, "sha256": "907446be5046c5d614af420479fc81a7cb3f6d3315e3d90cfc10e23d075d37f3", "src": "audio/interview/interview-116-agent.mp3"}, "user": {"seconds": 2.453, "voice": "af_heart", "text": "I've grown as far as I can in my current role.", "bytes": 30240, "sha256": "8ba53221aeb0181238b3f13c2ca1b2f34585a38fbfa89691c5f439fa8b188221", "src": "audio/interview/interview-116-user.mp3"}}, "interview-117": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "When would you be able to start?", "bytes": 25344, "sha256": "8c3f6d15ece9d444589c4ad94169c6db5d8c8f416725d7554b7f3d4b94704d17", "src": "audio/interview/interview-117-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_heart", "text": "Early next quarter would be ideal for me.", "bytes": 28800, "sha256": "3957b0c790ce1286a84c9679b70c089e310230e0f70ac90ddf462ad0c53358a1", "src": "audio/interview/interview-117-user.mp3"}}, "interview-118": {"agent": {"seconds": 2.133, "voice": "am_michael", "text": "Any questions for me at this stage?", "bytes": 26208, "sha256": "fb47c5cc28735246d75c3a2fa0669c0cb28243a04e6a92da1264389a74f9afe9", "src": "audio/interview/interview-118-agent.mp3"}, "user": {"seconds": 2.432, "voice": "af_heart", "text": "What's the timeline for the next interview rounds?", "bytes": 29952, "sha256": "b6ae4c54658a723ddb2feb54281fc5df1f5dea76e98fe6ec8a594deb2fe2b2e4", "src": "audio/interview/interview-118-user.mp3"}}, "interview-119": {"agent": {"seconds": 2.389, "voice": "am_michael", "text": "We'll schedule the panel for next week.", "bytes": 29376, "sha256": "ea3a3a3d13d1189e9369acec305ab09a15dcf94fcb40a76e3b0bf5852048ba9c", "src": "audio/interview/interview-119-agent.mp3"}, "user": {"seconds": 2.901, "voice": "af_heart", "text": "That works for me. I'll keep my calendar open.", "bytes": 35424, "sha256": "d09db8883cb6990dbceb53671ba9201a1a2e5603181316c8cb3e3cc1f0c77f4d", "src": "audio/interview/interview-119-user.mp3"}}, "interview-120": {"agent": {"seconds": 2.219, "voice": "am_michael", "text": "Thanks so much for your time today.", "bytes": 27360, "sha256": "91c8ad3f1da3d8da18114a7318053f4ee48d3f72927e2681d824a1baa1506a31", "src": "audio/interview/interview-120-agent.mp3"}, "user": {"seconds": 2.539, "voice": "af_heart", "text": "Thank you. I'm looking forward to the next steps.", "bytes": 31104, "sha256": "7c02ef11ddf315ec2dfe1967ebd27e6970c9aace56b1ac99d2e6278a43c7e0b7", "src": "audio/interview/interview-120-user.mp3"}}, "interview-121": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "Welcome back. Ready for round two?", "bytes": 28512, "sha256": "ea530b552a45e30c737041aae351a2e7adbcd7a81e1d34c60eaa01bce65ad066", "src": "audio/interview/interview-121-agent.mp3"}, "user": {"seconds": 3.179, "voice": "af_heart", "text": "Definitely. I've been thinking about our last conversation.", "bytes": 38880, "sha256": "40073720cb23172a6a9317ecfc3019dceaea83f87c9970bdbb990dd3a100a7b9", "src": "audio/interview/interview-121-user.mp3"}}, "interview-122": {"agent": {"seconds": 2.432, "voice": "am_michael", "text": "Why do you want to work here specifically?", "bytes": 29952, "sha256": "e9707c3976520b38eb90a6ecfcfda0e282c876ec41f331d3062db96b9b9b4c5e", "src": "audio/interview/interview-122-agent.mp3"}, "user": {"seconds": 3.328, "voice": "af_heart", "text": "Your quality-first culture matches how I already work.", "bytes": 40608, "sha256": "239bbb20e35fa04c3ccf0527a8ca5417e5d04146afbab3fd15b176141ca071b0", "src": "audio/interview/interview-122-user.mp3"}}, "interview-123": {"agent": {"seconds": 2.347, "voice": "am_michael", "text": "Where do you see yourself in five years?", "bytes": 28800, "sha256": "64a4cd61603c74c91f42e7a97f3b8973ea7be1d14a509f3b94f06292ffb7205d", "src": "audio/interview/interview-123-agent.mp3"}, "user": {"seconds": 3.755, "voice": "af_heart", "text": "Leading a quality organization and mentoring future leaders.", "bytes": 45792, "sha256": "47aa7869fbddb832e01cc1e5e1e9a2630aaac19417a049ea2dfcf070d11ab911", "src": "audio/interview/interview-123-user.mp3"}}, "interview-124": {"agent": {"seconds": 2.411, "voice": "am_michael", "text": "How would you handle our biggest challenge?", "bytes": 29664, "sha256": "7a221f4631dd83cf4d0c24545cd00e72c602e28f2a17aa2313a45654450686f8", "src": "audio/interview/interview-124-agent.mp3"}, "user": {"seconds": 3.563, "voice": "af_heart", "text": "First I'd listen to the team, then map the real bottlenecks.", "bytes": 43488, "sha256": "3d58dc65c9d71946dbb092bb524b2fd8b72f046116161663970292ad08562694", "src": "audio/interview/interview-124-user.mp3"}}, "interview-125": {"agent": {"seconds": 2.581, "voice": "am_michael", "text": "Walk me through a tough technical decision.", "bytes": 31680, "sha256": "49432ea986531b46808f8693dfe0117642e0769d5634b4493d2971d3e35ce661", "src": "audio/interview/interview-125-agent.mp3"}, "user": {"seconds": 3.477, "voice": "af_heart", "text": "I chose a slower supplier with far better process controls.", "bytes": 42336, "sha256": "e09038bc8c60c579c0059438879514ec9e1eedbf4640568fd5fee7b3b992ccc3", "src": "audio/interview/interview-125-user.mp3"}}, "interview-126": {"agent": {"seconds": 2.368, "voice": "am_michael", "text": "What would your first ninety days look like?", "bytes": 29088, "sha256": "4e689d07517db7e590e37ada8a8da92191a151ccf50e77b596e6a7c5abda6fc0", "src": "audio/interview/interview-126-agent.mp3"}, "user": {"seconds": 3.157, "voice": "af_heart", "text": "Listen, learn the systems, then deliver one quick win.", "bytes": 38592, "sha256": "aba84120f4313083fd011621d0f0f867a91c87d66a4e813a2a9e5ef4d167e3e1", "src": "audio/interview/interview-126-user.mp3"}}, "interview-127": {"agent": {"seconds": 2.624, "voice": "am_michael", "text": "How do you feel about our company values?", "bytes": 32256, "sha256": "26789ba1d8ff9e4bd0548ab8ca13056a76432f440b5212671c19e4518c07a9d7", "src": "audio/interview/interview-127-agent.mp3"}, "user": {"seconds": 3.541, "voice": "af_heart", "text": "They resonate with me, especially the focus on integrity.", "bytes": 43200, "sha256": "cb9db2dcbf91b7e52bdc3d92d3d54859b7ed83e0f92edc6fc2b11d8cca5a90b2", "src": "audio/interview/interview-127-user.mp3"}}, "interview-128": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "What questions do you have for the panel?", "bytes": 27648, "sha256": "cfc67becc06d5305ed849eee29da18fa9daa200fbf2309b745a8d64fd0924966", "src": "audio/interview/interview-128-agent.mp3"}, "user": {"seconds": 3.755, "voice": "af_heart", "text": "How do teams here typically resolve disagreements on priorities?", "bytes": 45792, "sha256": "14cd8c7c9436d78b5f7e1947036f1e24105e48b8aa5f302dc542eb5872a937c6", "src": "audio/interview/interview-128-user.mp3"}}, "interview-129": {"agent": {"seconds": 2.624, "voice": "am_michael", "text": "Do you have any concerns about this role?", "bytes": 32256, "sha256": "c429be7a3a8889479aba1fe0dde805f349510af58367637edeb97b3150fd879d", "src": "audio/interview/interview-129-agent.mp3"}, "user": {"seconds": 3.435, "voice": "af_heart", "text": "Only that I want to make sure expectations are realistic.", "bytes": 42048, "sha256": "92077b338ef6425d13cbe250496a98d494fab3e25b2bc7edd5dc373970692257", "src": "audio/interview/interview-129-user.mp3"}}, "interview-130": {"agent": {"seconds": 2.155, "voice": "am_michael", "text": "How do you keep your skills current?", "bytes": 26496, "sha256": "d27fceb0a1e11bdb709299a7b04e7627a59357f0d04c4be055b4cef069af77f8", "src": "audio/interview/interview-130-agent.mp3"}, "user": {"seconds": 3.541, "voice": "af_heart", "text": "I take courses, attend conferences, and learn from mentors.", "bytes": 43200, "sha256": "f9fb2d3290075ccead97904bba1c678d642e66a0d757ae7576d4178acd0b1fe8", "src": "audio/interview/interview-130-user.mp3"}}, "interview-131": {"agent": {"seconds": 2.731, "voice": "am_michael", "text": "Why should we choose you over other candidates?", "bytes": 33408, "sha256": "50f4c4e3a8b39021579acdc2147faeb350ad80e3336be71771190f7c4e7a97ff", "src": "audio/interview/interview-131-agent.mp3"}, "user": {"seconds": 3.392, "voice": "af_heart", "text": "Because I deliver results and make the people around me better.", "bytes": 41472, "sha256": "096b558f3e9fb16a149c94384e175fc70e97c719930b25ebc0ce591be8185b9d", "src": "audio/interview/interview-131-user.mp3"}}, "interview-132": {"agent": {"seconds": 2.112, "voice": "am_michael", "text": "We'll discuss and get back to you.", "bytes": 25920, "sha256": "6485a6577fe83fa1c42a78e723ede722d503d2a9c551fe32a06adfbe766d0386", "src": "audio/interview/interview-132-agent.mp3"}, "user": {"seconds": 3.243, "voice": "af_heart", "text": "Sounds good. This has been a great experience overall.", "bytes": 39744, "sha256": "29ed300a4c5486142fa0f7198d85953e5d88bb88813d103ab9b0bbed7402d9b1", "src": "audio/interview/interview-132-user.mp3"}}, "interview-133": {"agent": {"seconds": 2.901, "voice": "am_michael", "text": "We're almost done here. Any final thoughts?", "bytes": 35424, "sha256": "48cdcb15e4748578f0f11256f6b7e0320ece5307aa1a35d69e68fdfea7a9bf6a", "src": "audio/interview/interview-133-agent.mp3"}, "user": {"seconds": 3.563, "voice": "af_heart", "text": "This conversation confirmed my strong interest in the role.", "bytes": 43488, "sha256": "990aa40972b5d4c8b958a06290f9f794029d4982bd725b439e237704cf6f1e0a", "src": "audio/interview/interview-133-user.mp3"}}, "interview-134": {"agent": {"seconds": 2.475, "voice": "am_michael", "text": "Is there anything we didn't cover today?", "bytes": 30528, "sha256": "3b2491c901ab68cf4bc813d93178a33abdbc326978f3bb0c9485cbcb6551833d", "src": "audio/interview/interview-134-agent.mp3"}, "user": {"seconds": 3.136, "voice": "af_heart", "text": "I'd love to share references from two former managers.", "bytes": 38304, "sha256": "efcc6053bd43dfdc22948260dc7553cb4d966bcbb66ca90915f9ad2509a3172f", "src": "audio/interview/interview-134-user.mp3"}}, "interview-135": {"agent": {"seconds": 2.091, "voice": "am_michael", "text": "That would be very helpful, thank you.", "bytes": 25920, "sha256": "bde1f8ba800289b061c69a79ea39570f7a9237ee240ab78abc7d9c81a53095f0", "src": "audio/interview/interview-135-agent.mp3"}, "user": {"seconds": 3.072, "voice": "af_heart", "text": "I'll send their contact details by tomorrow morning.", "bytes": 37440, "sha256": "8d3f44c90bae77ae61f6bc99fd5c334fb74d284447caf1dd8559a6cc8670671e", "src": "audio/interview/interview-135-user.mp3"}}, "interview-136": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "When is the best time to reach you?", "bytes": 27072, "sha256": "cdb5440b359415ec3f1845473cc9830c322f3f1f8e824edbe21efbf03a4b2138", "src": "audio/interview/interview-136-agent.mp3"}, "user": {"seconds": 2.368, "voice": "af_heart", "text": "Any weekday after six works best for me.", "bytes": 29088, "sha256": "f7b5d9c6aa598c05da3ffe7e7f6aba055ad919ff82f80afd26083947e0522de6", "src": "audio/interview/interview-136-user.mp3"}}, "interview-137": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "Thanks for coming in to see us today.", "bytes": 27072, "sha256": "558de8c27d1adea42f9ed60aa61df430a5cd612b0f65d4093ec6045de923e814", "src": "audio/interview/interview-137-agent.mp3"}, "user": {"seconds": 2.688, "voice": "af_heart", "text": "Thank you for the thoughtful questions and your time.", "bytes": 32832, "sha256": "ed34a46677387e90ba2cbbadeb20ecd2990b4e7708ae924c537799825cc796f4", "src": "audio/interview/interview-137-user.mp3"}}, "interview-138": {"agent": {"seconds": 1.835, "voice": "am_michael", "text": "We'll be in touch very soon.", "bytes": 22752, "sha256": "a48b3207fcb379eab6aa92a15808cd71b04745722258d984fffb1902e47f010a", "src": "audio/interview/interview-138-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_heart", "text": "I look forward to hearing from you.", "bytes": 22752, "sha256": "413fff5667a95423845f75cc7a60604cf1856418b09adf51b29c936b3812ab6d", "src": "audio/interview/interview-138-user.mp3"}}, "interview-139": {"agent": {"seconds": 1.856, "voice": "am_michael", "text": "Do you want a tour of the office?", "bytes": 23040, "sha256": "6f7ac70274ee1adbdb08f4a9bd065ad5159bdeb568f9d12cf97b6e0575a9ecbd", "src": "audio/interview/interview-139-agent.mp3"}, "user": {"seconds": 2.816, "voice": "af_heart", "text": "I'd love one. It helps me picture working here.", "bytes": 34560, "sha256": "12287e109e81ad0c9cd480cb8fd8636359c0479038bf7938716493cfda391be4", "src": "audio/interview/interview-139-user.mp3"}}, "interview-140": {"agent": {"seconds": 2.752, "voice": "am_michael", "text": "Here's the production floor where it all happens.", "bytes": 33696, "sha256": "d85619e3792875cf85eb8795396af8d570bf704af90ad2b21b6723c1d93277b8", "src": "audio/interview/interview-140-agent.mp3"}, "user": {"seconds": 3.392, "voice": "af_heart", "text": "Impressive setup. The workflow looks very well organized.", "bytes": 41472, "sha256": "bb04c38aa7ea5fafb1422d4420555510a2bc2a6dbd558e807d8b7e6b9f5414f9", "src": "audio/interview/interview-140-user.mp3"}}, "interview-141": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "And this is where your team would sit.", "bytes": 27648, "sha256": "6062ff59e47bf9f4939b5ba157134f2792275380bcd8bff47978455591ab230a", "src": "audio/interview/interview-141-agent.mp3"}, "user": {"seconds": 3.691, "voice": "af_heart", "text": "Great location. I can already see myself collaborating here.", "bytes": 44928, "sha256": "156eaf577e014a6751be7db9d3aa2ba65a00b52cde4a768ac668a93887c4e6be", "src": "audio/interview/interview-141-user.mp3"}}, "interview-142": {"agent": {"seconds": 2.283, "voice": "am_michael", "text": "Have a safe trip back home today.", "bytes": 28224, "sha256": "65ea09cac0d51d526bfc781f0ad2c4807d553800069782da0dbd37bbd0bb4a1c", "src": "audio/interview/interview-142-agent.mp3"}, "user": {"seconds": 3.371, "voice": "af_heart", "text": "Thanks again. I'll follow up with a thank-you email tonight.", "bytes": 41184, "sha256": "25db5ed70125b6de2e2a569cb4b4ff413c910238cc6fbbf8c08b03ac28f376f6", "src": "audio/interview/interview-142-user.mp3"}}, "interview-143": {"agent": {"seconds": 2.944, "voice": "am_michael", "text": "We really appreciate your enthusiasm today.", "bytes": 36000, "sha256": "6b23182b865ede21af11c4e36533564513cbf5e2ac2eadf072d95f1a17e6939a", "src": "audio/interview/interview-143-agent.mp3"}, "user": {"seconds": 3.2, "voice": "af_heart", "text": "The feeling is mutual. This feels like the right fit.", "bytes": 39168, "sha256": "a561837e49ae846e4063418b889450057ea0095123ea76782313ad9742410d3a", "src": "audio/interview/interview-143-user.mp3"}}, "interview-144": {"agent": {"seconds": 2.091, "voice": "am_michael", "text": "Goodbye for now, and good luck!", "bytes": 25920, "sha256": "b7b5516ff7e8abb227a92b2219e7cf91dce3e3bbd6ef64f18138178251c1279b", "src": "audio/interview/interview-144-agent.mp3"}, "user": {"seconds": 2.475, "voice": "af_heart", "text": "Goodbye! I hope we get to work together soon.", "bytes": 30528, "sha256": "71fb8c81ebd7a98c4e02c1ac5c58b3b2b378a3ebea203cf3bc44e0730edea260", "src": "audio/interview/interview-144-user.mp3"}}}, "movies": {"movies-001": {"agent": {"seconds": 4.632, "voice": "avocado_v2:ronan", "text": "Morning, Mia! You look like you slept a full eight hours.", "bytes": 37093, "sha256": "a075a09fb4296461d9290c27a31529c166f4910152b5f27c0e5c056d1b32c340", "src": "audio/movies/movies-001-agent.mp3"}, "user": {"seconds": 2.808, "voice": "avocado_v2:MAI_01", "text": "I did. You look like you didn't sleep at all.", "bytes": 22501, "sha256": "6a41216b2d81d8d0dd1506488ac6208b3b5227c681eb1a1212eb066dd9f407e0", "src": "audio/movies/movies-001-user.mp3"}}, "movies-002": {"agent": {"seconds": 3.072, "voice": "avocado_v2:ronan", "text": "I was up all night fixing the demo. It works now.", "bytes": 24613, "sha256": "691256f33e25de2709f0c1bd3945062de6a845f483c2ba7f8579a3f2acff2309", "src": "audio/movies/movies-002-agent.mp3"}, "user": {"seconds": 3.048, "voice": "avocado_v2:MAI_01", "text": "It better. Mr. Chen arrives tomorrow at ten.", "bytes": 24421, "sha256": "ab2be1a01882b66a157e3e98763adbdfc3f462ccff7c2aa5cf0f7b59843e02cf", "src": "audio/movies/movies-002-user.mp3"}}, "movies-003": {"agent": {"seconds": 7.8, "voice": "avocado_v2:myrtle", "text": "Good morning! I brought my famous oatmeal cookies.", "bytes": 62437, "sha256": "a55d63b0985c075e12d5d7a224e8e94ae0e068a5e35c3ed4d4061abd5416961a", "src": "audio/movies/movies-003-agent.mp3"}, "user": {"seconds": 3.768, "voice": "avocado_v2:MAI_01", "text": "They smell amazing, Lucy. But I'm too nervous to eat.", "bytes": 30181, "sha256": "026dec735562826cdb61293708874dbe15699af175e34acc43fee085f62dde5d", "src": "audio/movies/movies-003-user.mp3"}}, "movies-004": {"agent": {"seconds": 3.6, "voice": "avocado_v2:ronan", "text": "Nervous? The demo is tomorrow. We have plenty of time.", "bytes": 28837, "sha256": "98cce42948a7f46f40c1dd1a0bbfb98587bad3c1591e98f84225936d226b2dd3", "src": "audio/movies/movies-004-agent.mp3"}, "user": {"seconds": 3.072, "voice": "avocado_v2:MAI_01", "text": "Famous last words. Did you test the new build?", "bytes": 24613, "sha256": "019fc2bf88e7cf2f9446d9b91b00d591bdb3397eb164b05d107b28943019edc3", "src": "audio/movies/movies-004-user.mp3"}}, "movies-005": {"agent": {"seconds": 3.408, "voice": "avocado_v2:ronan", "text": "Test? I wrote it at two in the morning. It is perfect.", "bytes": 27301, "sha256": "e68df1f44aa60503e9afe12a93ae550104580a29886b10884484ce7d77851ffe", "src": "audio/movies/movies-005-agent.mp3"}, "user": {"seconds": 3.12, "voice": "avocado_v2:MAI_01", "text": "Jake, two in the morning is not a good sign.", "bytes": 24997, "sha256": "2b46172d33ef9cbacf79d3abd0909298f4d77fac61bbe9f230db506ffd6db7ee", "src": "audio/movies/movies-005-user.mp3"}}, "movies-006": {"agent": {"seconds": 5.688, "voice": "avocado_v2:myrtle", "text": "Has anyone tried the coffee machine? It sounds weird.", "bytes": 45541, "sha256": "429f6cbbefc83a6d21e36c7c5aa0a03c74df9a1e449665ee4b520383a1ee7112", "src": "audio/movies/movies-006-agent.mp3"}, "user": {"seconds": 3.48, "voice": "avocado_v2:MAI_01", "text": "Not again. Jake, did you touch the coffee machine?", "bytes": 27877, "sha256": "8a3d1a9eb8768bc962a1673e7d7be90160f80c6f7415d6017af05cfb78a55f81", "src": "audio/movies/movies-006-user.mp3"}}, "movies-007": {"agent": {"seconds": 3.528, "voice": "avocado_v2:ronan", "text": "I just tried to make it faster. Now it makes no coffee.", "bytes": 28261, "sha256": "347f4e07ff506616586cc46d75683a42ba4b10cb7b589841cb048d8ac0a2d578", "src": "audio/movies/movies-007-agent.mp3"}, "user": {"seconds": 3.648, "voice": "avocado_v2:MAI_01", "text": "You broke it? On demo week? Are you serious?", "bytes": 29221, "sha256": "b12b868c6c6b1f6df097b55f6d6c33f2617baf93553564429f487be0101a9e5d", "src": "audio/movies/movies-007-user.mp3"}}, "movies-008": {"agent": {"seconds": 41.688, "voice": "avocado_v2:myrtle", "text": "Relax. I will fix it after the demo. Priorities, people.", "bytes": 333541, "sha256": "b84ad9afd2ef6d56a69899fea5a83ed93ed934084e84b0a1b6fa458a6940fb72", "src": "audio/movies/movies-008-agent.mp3"}, "user": {"seconds": 3.648, "voice": "avocado_v2:MAI_01", "text": "You're right. Demo first, coffee later. I can survive.", "bytes": 29221, "sha256": "8a5e1243143de20bd2f9d2ed3ac3d82acc33721bfa341371b4a08413111112ef", "src": "audio/movies/movies-008-user.mp3"}}, "movies-009": {"agent": {"seconds": 5.4, "voice": "avocado_v2:ronan", "text": "So the plan is simple. Mia pitches, I click, Lucy smiles.", "bytes": 43237, "sha256": "1069a6ead9dde733709c3ad4a7b65191a128ed34ce75f28660e4127678c6965c", "src": "audio/movies/movies-009-agent.mp3"}, "user": {"seconds": 2.76, "voice": "avocado_v2:MAI_01", "text": "And what could possibly go wrong with that plan?", "bytes": 22117, "sha256": "0df6e67049ac05c8a21e3c2606c607dfdb29e5f0cff744bb180f5b40b90a5ac4", "src": "audio/movies/movies-009-user.mp3"}}, "movies-010": {"agent": {"seconds": 5.28, "voice": "avocado_v2:myrtle", "text": "Do not jinx it, Mia. Last time the projector died.", "bytes": 42277, "sha256": "98296077cce6d56ac9f5879a38f2f7f9abf816b81da593fb740d33e6ab6515bc", "src": "audio/movies/movies-010-agent.mp3"}, "user": {"seconds": 3.84, "voice": "avocado_v2:MAI_01", "text": "Okay, okay. Positive thinking. The demo will be perfect.", "bytes": 30757, "sha256": "c92544de390a8b0780febff91fc4de146b8e32018d50a83f79c115392e469d30", "src": "audio/movies/movies-010-user.mp3"}}, "movies-011": {"agent": {"seconds": 3.168, "voice": "avocado_v2:ronan", "text": "Now, who wants to see my amazing new animation feature?", "bytes": 25381, "sha256": "7ae0b8091e00ef668b659fed5e26a8095ca3e87828be1fe8f7407d56388d8a88", "src": "audio/movies/movies-011-agent.mp3"}, "user": {"seconds": 3.648, "voice": "avocado_v2:MAI_01", "text": "New feature? Jake, we froze the code last Friday!", "bytes": 29221, "sha256": "4ffbe3191832a306d462491efb7c47894b24b669277d66db66cca476f4ba968e", "src": "audio/movies/movies-011-user.mp3"}}, "movies-012": {"agent": {"seconds": 3.768, "voice": "avocado_v2:ronan", "text": "Relax, it is just a small animation. Watch this.", "bytes": 30181, "sha256": "6fca77be2d2c0b9755fd06c78272088d6deabd62356697b0058b2383f71b34f4", "src": "audio/movies/movies-012-agent.mp3"}, "user": {"seconds": 3.36, "voice": "avocado_v2:MAI_01", "text": "No! Don't touch anything until after the demo!", "bytes": 26917, "sha256": "3541a2ddd22e130ec70618f3c90bfe6b9116f493f4554786c3dd7284a953069b", "src": "audio/movies/movies-012-user.mp3"}}, "movies-013": {"agent": {"seconds": 5.568, "voice": "avocado_v2:myrtle", "text": "That's Mr. Chen's office calling. This cannot be good.", "bytes": 44581, "sha256": "34dd71191a8d306fec2c5409562a057dd0b169b377f6ea1dd2e0f74f678926ce", "src": "audio/movies/movies-013-agent.mp3"}, "user": {"seconds": 1.968, "voice": "avocado_v2:MAI_01", "text": "Answer it, Lucy. Put it on speaker.", "bytes": 15781, "sha256": "8a6044c6cf04525b8397deb9511726e0d105506d4e048924a3ca7f1abd0526a2", "src": "audio/movies/movies-013-user.mp3"}}, "movies-014": {"agent": {"seconds": 6.432, "voice": "avocado_v2:myrtle", "text": "That was his assistant. The demo moved to today at three.", "bytes": 51493, "sha256": "9bb674942bed5aa17ed55776ffbcfd72b6fbcdc4d2ab1ee13e01d3bf73ed6cdc", "src": "audio/movies/movies-014-agent.mp3"}, "user": {"seconds": 3.48, "voice": "avocado_v2:MAI_01", "text": "Today? At three? That's in four hours!", "bytes": 27877, "sha256": "bb154e34313a15add7813081e6137e08b5ff4f7b150be4ee6a89126fe67bd098", "src": "audio/movies/movies-014-user.mp3"}}, "movies-015": {"agent": {"seconds": 3.72, "voice": "avocado_v2:ronan", "text": "Four hours? I need four days! My code needs four days!", "bytes": 29797, "sha256": "b541cb6d0a769b711caa472b3c205a1227b1107ed2fb5550c84f821c69c4b7f5", "src": "audio/movies/movies-015-agent.mp3"}, "user": {"seconds": 3.192, "voice": "avocado_v2:MAI_01", "text": "Breathe, Jake. We'll make a plan and stick to it.", "bytes": 25573, "sha256": "4e7e7da0635bd8e1a2e4be9664e0c06bd1752fd2e84277fcea2471c7d616a5f3", "src": "audio/movies/movies-015-user.mp3"}}, "movies-016": {"agent": {"seconds": 5.76, "voice": "avocado_v2:myrtle", "text": "Mia's right. Panic never fixed a single bug.", "bytes": 46117, "sha256": "6bd3739a777dee6c36678ab942472adcdeb389f6e828726892ba155e32f28190", "src": "audio/movies/movies-016-agent.mp3"}, "user": {"seconds": 2.832, "voice": "avocado_v2:MAI_01", "text": "Okay. First, we test the demo right now.", "bytes": 22693, "sha256": "a4f8372e69fa26f7a66f67500decb8394e0419df2d5b0d6cc61ec58af87b9d99", "src": "audio/movies/movies-016-user.mp3"}}, "movies-017": {"agent": {"seconds": 4.872, "voice": "avocado_v2:ronan", "text": "Fine. Opening the app... and... oh no.", "bytes": 39013, "sha256": "e16e5313a0b252334a653512b70c57a583e9ec0a4d335d8b5c6c89fe7e8df801", "src": "audio/movies/movies-017-agent.mp3"}, "user": {"seconds": 3.048, "voice": "avocado_v2:MAI_01", "text": "Oh no what? Jake, what does oh no mean?", "bytes": 24421, "sha256": "b8b25e89f8c57bbd250f9232b8ade3ba396e320f1e757a83026bc5fd9ae2c84d", "src": "audio/movies/movies-017-user.mp3"}}, "movies-018": {"agent": {"seconds": 3.792, "voice": "avocado_v2:ronan", "text": "The scan button freezes. The whole app just freezes.", "bytes": 30373, "sha256": "0930c5e52cb0d866ba07920b29fbef8ad2a607dd113128241966f26ed62bf3f1", "src": "audio/movies/movies-018-agent.mp3"}, "user": {"seconds": 2.52, "voice": "avocado_v2:MAI_01", "text": "The two in the morning update broke it, didn't it?", "bytes": 20197, "sha256": "6cee344a4a41bfaed70d385bd0aaaa7ef7690edb903b6c30131e802eaa425ad2", "src": "audio/movies/movies-018-user.mp3"}}, "movies-019": {"agent": {"seconds": 4.152, "voice": "avocado_v2:ronan", "text": "Maybe a little. But my animation is beautiful!", "bytes": 33253, "sha256": "6e92b43345146313f0e763901cfdbc943fd1615ce6d0002ae5e0b9db2a829df8", "src": "audio/movies/movies-019-agent.mp3"}, "user": {"seconds": 2.352, "voice": "avocado_v2:MAI_01", "text": "I don't care about beautiful. I need working!", "bytes": 18853, "sha256": "c9429a41e2b97d96e369d7d641cf1444dccd2f3d74db62cb9e8a1735acbf2fb0", "src": "audio/movies/movies-019-user.mp3"}}, "movies-020": {"agent": {"seconds": 5.952, "voice": "avocado_v2:myrtle", "text": "Jake, did you save yesterday's version anywhere safe?", "bytes": 47653, "sha256": "b62ed51caebacb736881652e3648ffb93d96193f246983fc3b01503b1917ad7f", "src": "audio/movies/movies-020-agent.mp3"}, "user": {"seconds": 2.832, "voice": "avocado_v2:MAI_01", "text": "Please say yes. Please, please say yes.", "bytes": 22693, "sha256": "872f539d3569b30db02fd488086867a11c7df61c04cb986e6151c3d0ff0a6b5d", "src": "audio/movies/movies-020-user.mp3"}}, "movies-021": {"agent": {"seconds": 2.568, "voice": "avocado_v2:ronan", "text": "Of course! It's on my lucky thumb drive.", "bytes": 20581, "sha256": "1c395e3eb661f2891b55540215f23f3afafc2c88e5cf2b9489a64c7b2c42c208", "src": "audio/movies/movies-021-agent.mp3"}, "user": {"seconds": 2.472, "voice": "avocado_v2:MAI_01", "text": "Great! Where is your lucky thumb drive?", "bytes": 19813, "sha256": "62324691ae30255eaf70913e03bc9ad203178627917c0cb3302a119b8489984f", "src": "audio/movies/movies-021-user.mp3"}}, "movies-022": {"agent": {"seconds": 5.352, "voice": "avocado_v2:ronan", "text": "It is... hmm. It was in my backpack. Or my desk.", "bytes": 42853, "sha256": "26821bd90ab9837969bd8bd249391bab6cdc80c4d3909815866100051f070620", "src": "audio/movies/movies-022-agent.mp3"}, "user": {"seconds": 3.0, "voice": "avocado_v2:MAI_01", "text": "Jake! The backup is missing hours before demo?", "bytes": 24037, "sha256": "ed2234abc5b2fdcec583715f778c74c07fa601969b66c4856b13e69c98284629", "src": "audio/movies/movies-022-user.mp3"}}, "movies-023": {"agent": {"seconds": 4.992, "voice": "avocado_v2:myrtle", "text": "Everyone stay calm. We'll search the office together.", "bytes": 39973, "sha256": "1b3eb9005774578db31ac41e78d2515968f2b32ada7833aafd6dbaba69f343fb", "src": "audio/movies/movies-023-agent.mp3"}, "user": {"seconds": 2.712, "voice": "avocado_v2:MAI_01", "text": "Good idea. Jake, you check your desk drawers.", "bytes": 21733, "sha256": "5cb76ee123e243919f2809a4ff9ee0d11c3c0757664220256f65e6a28b923e3d", "src": "audio/movies/movies-023-user.mp3"}}, "movies-024": {"agent": {"seconds": 4.032, "voice": "avocado_v2:ronan", "text": "My desk has a system! It is called organized chaos.", "bytes": 32293, "sha256": "17300fbb2444c804fe3b2fd69908e0ab8b471006bd9cff3c7aaef5a4d2759682", "src": "audio/movies/movies-024-agent.mp3"}, "user": {"seconds": 3.12, "voice": "avocado_v2:MAI_01", "text": "Your system lost our backup. Start searching now.", "bytes": 24997, "sha256": "9a8f9d61feea72342f5d99612903088552132ced29c9b361f93ab95be87f06be", "src": "audio/movies/movies-024-user.mp3"}}, "movies-025": {"agent": {"seconds": 5.808, "voice": "avocado_v2:myrtle", "text": "I will check the meeting room. Mia, check the kitchen.", "bytes": 46501, "sha256": "8b3e11227b07f2df0a8499fc9d7826f40a09570ceab2e5d6f560a77ae195311e", "src": "audio/movies/movies-025-agent.mp3"}, "user": {"seconds": 3.312, "voice": "avocado_v2:MAI_01", "text": "On it. And Jake, no more brilliant ideas today.", "bytes": 26533, "sha256": "fb803e2452c3caeca1b9cc26a645100dba142fef4e2bd9139a612e2a9b7b25ee", "src": "audio/movies/movies-025-user.mp3"}}, "movies-026": {"agent": {"seconds": 3.12, "voice": "avocado_v2:ronan", "text": "I found an old sandwich! Does that count as backup?", "bytes": 24997, "sha256": "14143478f2aca112061361442775e8b7568ea427bd752932f4ee0669dec86c67", "src": "audio/movies/movies-026-agent.mp3"}, "user": {"seconds": 2.928, "voice": "avocado_v2:MAI_01", "text": "A sandwich is not a backup drive, Jake.", "bytes": 23461, "sha256": "423d3972a0ec5d4cf35ac23eb0527757509f7631ae1f452d911584157733551c", "src": "audio/movies/movies-026-user.mp3"}}, "movies-027": {"agent": {"seconds": 6.432, "voice": "avocado_v2:myrtle", "text": "Nothing in the meeting room. Jake, think harder.", "bytes": 51493, "sha256": "0bbcf18b482b1a3044ba9709fa62652beb6a595c5a4737ca7315f8be8c56fb40", "src": "audio/movies/movies-027-agent.mp3"}, "user": {"seconds": 2.232, "voice": "avocado_v2:MAI_01", "text": "When did you last see the thumb drive?", "bytes": 17893, "sha256": "339c2dfd767a591146737eb7a3e1cf12dce76b7e0e95d4d658340ab3aeca9fa8", "src": "audio/movies/movies-027-user.mp3"}}, "movies-028": {"agent": {"seconds": 3.192, "voice": "avocado_v2:ronan", "text": "Yesterday... I was showing it to Captain Quackers.", "bytes": 25573, "sha256": "6bb805be324c7b0f58b98191bb6de55668c8d40cbb8e3a3f3af54c0ec2871fdd", "src": "audio/movies/movies-028-agent.mp3"}, "user": {"seconds": 2.52, "voice": "avocado_v2:MAI_01", "text": "Who is Captain Quackers? And why?", "bytes": 20197, "sha256": "a1556decc2cf2a3e23c0f9867af2c083b412a9b8213be8bba4ab7f8c38b1cbd5", "src": "audio/movies/movies-028-user.mp3"}}, "movies-029": {"agent": {"seconds": 4.2, "voice": "avocado_v2:ronan", "text": "Captain Quackers is my rubber duck. I debug with him.", "bytes": 33637, "sha256": "602eed67f03ee824a935b1e19723aa640b1bf715eceecbce41026f7299ab3449", "src": "audio/movies/movies-029-agent.mp3"}, "user": {"seconds": 2.28, "voice": "avocado_v2:MAI_01", "text": "You talk to a rubber duck about code?", "bytes": 18277, "sha256": "964622c0995871ceb6fefcf3b57a5a49bb17d09eba99eef2e07348277aa1085b", "src": "audio/movies/movies-029-user.mp3"}}, "movies-030": {"agent": {"seconds": 3.36, "voice": "avocado_v2:ronan", "text": "Every great developer does! The duck never judges.", "bytes": 26917, "sha256": "e22f975889052329d7c7af8f8e8fa6182346a0bc47f6243ad64761db3ef7546c", "src": "audio/movies/movies-030-agent.mp3"}, "user": {"seconds": 2.928, "voice": "avocado_v2:MAI_01", "text": "Focus, Jake. Where did you last have the drive?", "bytes": 23461, "sha256": "edda1ad3d6ff2eedd0083a617204cac26b2cc18de2051a5af49f3470df0e318d", "src": "audio/movies/movies-030-user.mp3"}}, "movies-031": {"agent": {"seconds": 3.192, "voice": "avocado_v2:ronan", "text": "I was near the coffee machine... trying to fix it...", "bytes": 25573, "sha256": "325cc63b21c1a939ceb49ea12bf56a50e81fbfa70424ebeab0d253c7ef093a17", "src": "audio/movies/movies-031-agent.mp3"}, "user": {"seconds": 2.928, "voice": "avocado_v2:MAI_01", "text": "The coffee machine? Why was the drive near there?", "bytes": 23461, "sha256": "136f23a2b5fca6a078df032a4ddfeb3974baccef62ddcf9b3183a1f03b9755eb", "src": "audio/movies/movies-031-user.mp3"}}, "movies-032": {"agent": {"seconds": 4.992, "voice": "avocado_v2:myrtle", "text": "Jake, please tell me you didn't put it inside the machine.", "bytes": 39973, "sha256": "7e7394ce2fdef9e37cf0f11dad2819c9e22709cade24b0fb3a096eb0f9eaebaa", "src": "audio/movies/movies-032-agent.mp3"}, "user": {"seconds": 3.072, "voice": "avocado_v2:MAI_01", "text": "He did, didn't he? I can see it on his face.", "bytes": 24613, "sha256": "3f7840714ad73aa00875dd66610e6978598a5d485f814f96aa7fd92a8ede670f", "src": "audio/movies/movies-032-user.mp3"}}, "movies-033": {"agent": {"seconds": 3.312, "voice": "avocado_v2:ronan", "text": "It was the safest spot! No one looks in a coffee machine!", "bytes": 26533, "sha256": "e595f96742bd91e4930cffeb10b5914672b59f357671fcfb443a8b1e2b21cab3", "src": "audio/movies/movies-033-agent.mp3"}, "user": {"seconds": 2.808, "voice": "avocado_v2:MAI_01", "text": "Nobody puts a thumb drive in a coffee machine, Jake!", "bytes": 22501, "sha256": "5d820e782534fee5402a83c298bfcdd173fdc03c72cf1db648e2d87ac529346f", "src": "audio/movies/movies-033-user.mp3"}}, "movies-034": {"agent": {"seconds": 6.888, "voice": "avocado_v2:myrtle", "text": "I'll get my tools. Mia, unplug that machine right now.", "bytes": 55141, "sha256": "07c6b4a4f54685ad74940d63d2f08650d9ced7d6bcc9165179befee4e37f57e5", "src": "audio/movies/movies-034-agent.mp3"}, "user": {"seconds": 3.312, "voice": "avocado_v2:MAI_01", "text": "Unplugged. Jake, you're buying the next coffee machine.", "bytes": 26533, "sha256": "1a087485138d3eb072e2a566869e5f82fada958bab514f8738cb8e1a1604c207", "src": "audio/movies/movies-034-user.mp3"}}, "movies-035": {"agent": {"seconds": 2.568, "voice": "avocado_v2:ronan", "text": "Got it! It's a little wet, but it's here!", "bytes": 20581, "sha256": "de037da5296d537304fb384c8f8d83d04a81bdd728eb2edbd140248b2202fc4e", "src": "audio/movies/movies-035-agent.mp3"}, "user": {"seconds": 3.48, "voice": "avocado_v2:MAI_01", "text": "Wet? Jake, water and electronics don't mix!", "bytes": 27877, "sha256": "d8e7fae073467607200e25034a53216c70a12b3a499db9ae9537e716788cca11", "src": "audio/movies/movies-035-user.mp3"}}, "movies-036": {"agent": {"seconds": 8.28, "voice": "avocado_v2:myrtle", "text": "Let me see... Mia, I'm afraid this drive is dead.", "bytes": 66277, "sha256": "3cc36dd9cb8132b81776e643a60c310ace5a9145f75a15598e60d76fa0685060", "src": "audio/movies/movies-036-agent.mp3"}, "user": {"seconds": 3.288, "voice": "avocado_v2:MAI_01", "text": "Dead? As in completely, totally dead?", "bytes": 26341, "sha256": "ac4fa45b781a82687388095cbdf8b593a7015baf377558cca43ed7e70ab7cec8", "src": "audio/movies/movies-036-user.mp3"}}, "movies-037": {"agent": {"seconds": 3.552, "voice": "avocado_v2:ronan", "text": "Maybe if we put it in rice? Rice fixes everything!", "bytes": 28453, "sha256": "a370ccc30fde6ca502350e3390fbde95d048aa9db673549dd4aa46364c1c9cb8", "src": "audio/movies/movies-037-agent.mp3"}, "user": {"seconds": 3.48, "voice": "avocado_v2:MAI_01", "text": "Rice fixes phones, not our demo, not today.", "bytes": 27877, "sha256": "9c44ac1e264c41fbf6827914225b6369ae07b9bad40dd35a6e67349bfc61e47c", "src": "audio/movies/movies-037-user.mp3"}}, "movies-038": {"agent": {"seconds": 5.04, "voice": "avocado_v2:myrtle", "text": "The drive is gone. We need a new plan, fast.", "bytes": 40357, "sha256": "895e9195b005b17f156dd5e9f5140b65ce8276b71e5c9f108a620c22b2b475d0", "src": "audio/movies/movies-038-agent.mp3"}, "user": {"seconds": 4.008, "voice": "avocado_v2:MAI_01", "text": "You are right. Panicking wastes time. Think, Mia, think.", "bytes": 32101, "sha256": "ed3f706cfcc211b7b327cbfca2551bbefd01caad6f61d58311873ef84799c0e2", "src": "audio/movies/movies-038-user.mp3"}}, "movies-039": {"agent": {"seconds": 4.488, "voice": "avocado_v2:ronan", "text": "I could rebuild the demo! I just need... six hours.", "bytes": 35941, "sha256": "d1b13e883dd414294d72fc6ac7ff2b48f3a5706f897d165de672d16b97e8c0e8", "src": "audio/movies/movies-039-agent.mp3"}, "user": {"seconds": 3.6, "voice": "avocado_v2:MAI_01", "text": "We have three. And you need sleep, not more coding.", "bytes": 28837, "sha256": "a69c3c007d69b9fd8a3bec3661db479efb6c76b597a4070156d318fb3b20ed7f", "src": "audio/movies/movies-039-user.mp3"}}, "movies-040": {"agent": {"seconds": 4.032, "voice": "avocado_v2:myrtle", "text": "What about the screenshots from last week's test?", "bytes": 32293, "sha256": "e451734a880ee8f248733ba948ddfc054d91543d60b13ed1d1b3f79a678bc4e6", "src": "audio/movies/movies-040-agent.mp3"}, "user": {"seconds": 3.072, "voice": "avocado_v2:MAI_01", "text": "Screenshots? Lucy, that's actually not crazy.", "bytes": 24613, "sha256": "c664ddb17273b3379f9a05b3457e5ad28c02ff36bfd77095712c156c5895c164", "src": "audio/movies/movies-040-user.mp3"}}, "movies-041": {"agent": {"seconds": 6.552, "voice": "avocado_v2:myrtle", "text": "I printed every screen. Old school, but it works.", "bytes": 52453, "sha256": "be0815df4a79f70943c71b8ad948a23a469ae20e37b22a3fbb4cbe34ff52731f", "src": "audio/movies/movies-041-agent.mp3"}, "user": {"seconds": 3.408, "voice": "avocado_v2:MAI_01", "text": "You printed them? Lucy, you're a genius!", "bytes": 27301, "sha256": "1eff59dc2eacc2781d4636a9e465bafd42b756f1d8a37763f8cfa4575e6de9cd", "src": "audio/movies/movies-041-user.mp3"}}, "movies-042": {"agent": {"seconds": 4.368, "voice": "avocado_v2:ronan", "text": "Paper screenshots? That's like using a paper map today!", "bytes": 34981, "sha256": "086fd2c4d09b4466c95a5e0bab202d835bbf64f4b33d08c967cba43ae7539a9d", "src": "audio/movies/movies-042-agent.mp3"}, "user": {"seconds": 2.76, "voice": "avocado_v2:MAI_01", "text": "Maps still work when the GPS dies, Jake.", "bytes": 22117, "sha256": "aa2ebb3313f3d36994050d5dc80509314012614eeb2ff5fab9c7c0a305ffbf7d", "src": "audio/movies/movies-042-user.mp3"}}, "movies-043": {"agent": {"seconds": 8.88, "voice": "avocado_v2:myrtle", "text": "I have forty screenshots, in order, from login to checkout.", "bytes": 71077, "sha256": "faa66381b29c17edf58df4ad5e193e529e6f638d2aaaa034d9a891512f52fea3", "src": "audio/movies/movies-043-agent.mp3"}, "user": {"seconds": 2.808, "voice": "avocado_v2:MAI_01", "text": "Forty? When did you even print all these?", "bytes": 22501, "sha256": "ea9912990ae1dbb0ba2f92b525c814e3795909a5c8aea1fefc1879573761340c", "src": "audio/movies/movies-043-user.mp3"}}, "movies-044": {"agent": {"seconds": 6.888, "voice": "avocado_v2:myrtle", "text": "Last Friday. I never trust Jake's midnight coding.", "bytes": 55141, "sha256": "1e2f8247c9417cf49b1a9ef8322c1f6482154882c6ccf3de7af95f2828881803", "src": "audio/movies/movies-044-agent.mp3"}, "user": {"seconds": 2.568, "voice": "avocado_v2:MAI_01", "text": "Smartest decision anyone made this week.", "bytes": 20581, "sha256": "0c9731bfe3e59192464613f74024c809b4f857f515e2367e8418a5cbe1dc3aeb", "src": "audio/movies/movies-044-user.mp3"}}, "movies-045": {"agent": {"seconds": 4.44, "voice": "avocado_v2:ronan", "text": "Hey! My midnight coding is inspired! Mostly.", "bytes": 35557, "sha256": "71f9374178369e4859cd3550c820642d689ce55585b8d6cd48d1a072332a3622", "src": "audio/movies/movies-045-agent.mp3"}, "user": {"seconds": 3.24, "voice": "avocado_v2:MAI_01", "text": "Inspired chaos. Now help us sort these pages.", "bytes": 25957, "sha256": "07384731a339c7b6ad06cfdbe140f96964f66ecd68bb052d13d7d07a8113bdad", "src": "audio/movies/movies-045-user.mp3"}}, "movies-046": {"agent": {"seconds": 4.392, "voice": "avocado_v2:ronan", "text": "What if we just tell Mr. Chen the app is... invisible?", "bytes": 35173, "sha256": "08177be3aeb556e67061718a9039854e57f2a25abf6f01364bd8dc9bf3587e3f", "src": "audio/movies/movies-046-agent.mp3"}, "user": {"seconds": 3.0, "voice": "avocado_v2:MAI_01", "text": "No. We are not lying to an investor, Jake.", "bytes": 24037, "sha256": "5b8f213d4d8e548cbb9e7eca40344a391a3687b4e4726bff789a5915bdcc5f40", "src": "audio/movies/movies-046-user.mp3"}}, "movies-047": {"agent": {"seconds": 3.312, "voice": "avocado_v2:ronan", "text": "What if I do a live drawing of the app? I'm artistic!", "bytes": 26533, "sha256": "45931c60a7a2895429c4df6694bf08c8355f5a183a7df3f70a825c124e0a733f", "src": "audio/movies/movies-047-agent.mp3"}, "user": {"seconds": 2.712, "voice": "avocado_v2:MAI_01", "text": "Your stick figures are not investor-ready.", "bytes": 21733, "sha256": "fc1f3b767b4287d8d4699eb152c4f54cf3b8640b678ba2432b9ca73bddfc3a90", "src": "audio/movies/movies-047-user.mp3"}}, "movies-048": {"agent": {"seconds": 7.56, "voice": "avocado_v2:myrtle", "text": "Enough. Mia, you pitch with my screenshots. Jake, you assist.", "bytes": 60517, "sha256": "7575c4ad4d64f3267bad8b7627bd9d211487138b52e11dec2c257c59b52d5c30", "src": "audio/movies/movies-048-agent.mp3"}, "user": {"seconds": 3.192, "voice": "avocado_v2:MAI_01", "text": "Assist how? He breaks everything he touches.", "bytes": 25573, "sha256": "2bfc4ea40180f11c2d39c47109d63859c08c2e307c8111ed5db3a2210a39ff76", "src": "audio/movies/movies-048-user.mp3"}}, "movies-049": {"agent": {"seconds": 4.632, "voice": "avocado_v2:myrtle", "text": "He'll handle questions. Honest answers, Jake. No jokes.", "bytes": 37093, "sha256": "f03001926e142ec1a7aa937df9a1f797a2d0aab5a5eee63bdbd0bf88a76c65c9", "src": "audio/movies/movies-049-agent.mp3"}, "user": {"seconds": 3.84, "voice": "avocado_v2:MAI_01", "text": "No jokes? That's like asking fish not to swim.", "bytes": 30757, "sha256": "9660725325e2b014e80381a35f1b1712bb2864fd881c62a0daec90b6542df1a7", "src": "audio/movies/movies-049-user.mp3"}}, "movies-050": {"agent": {"seconds": 5.232, "voice": "avocado_v2:ronan", "text": "I can be serious! Watch: I am serious now.", "bytes": 41893, "sha256": "84760d706a21455e4608bf603f3fc83127af059afeefe7b2cc0365678ccd5f09", "src": "audio/movies/movies-050-agent.mp3"}, "user": {"seconds": 2.88, "voice": "avocado_v2:MAI_01", "text": "You're smiling. That's not a serious face.", "bytes": 23077, "sha256": "fbbac7a1dea35631b2a8d6271ac62b9d86de4d34091f4866c0d5a49594ef52d4", "src": "audio/movies/movies-050-user.mp3"}}, "movies-051": {"agent": {"seconds": 5.328, "voice": "avocado_v2:myrtle", "text": "Jake, log into the company account. We need the slides.", "bytes": 42661, "sha256": "1776ba6700861b348a8e5c0246cad58d2f5400ffefdb6dc43341b778ebafed72", "src": "audio/movies/movies-051-agent.mp3"}, "user": {"seconds": 4.032, "voice": "avocado_v2:MAI_01", "text": "Please tell me the password is not password one two three four.", "bytes": 32293, "sha256": "d22a6ac47584b421cec4ea084590a57e0ac4ca838fcd1cbe33953924e1c0458b", "src": "audio/movies/movies-051-user.mp3"}}, "movies-052": {"agent": {"seconds": 4.8, "voice": "avocado_v2:ronan", "text": "It's... password one two three four. I added numbers.", "bytes": 38437, "sha256": "e560ff194830dfebd55913d7d4b98f183ff23c3d1837d5da2c23c1216ff45420", "src": "audio/movies/movies-052-agent.mp3"}, "user": {"seconds": 2.832, "voice": "avocado_v2:MAI_01", "text": "That's not security, Jake! Change it tonight!", "bytes": 22693, "sha256": "7c8003b0087944d0419d19fae3e08cd15db55a95cd9e0f959beef477850bd53e", "src": "audio/movies/movies-052-user.mp3"}}, "movies-053": {"agent": {"seconds": 5.112, "voice": "avocado_v2:myrtle", "text": "Slides are up. Mia, let's practice your pitch.", "bytes": 40933, "sha256": "a0c8a2b35551e70bb715e11a41493ef9a7f98dfdb402e061f7514bd4cc4069c8", "src": "audio/movies/movies-053-agent.mp3"}, "user": {"seconds": 4.032, "voice": "avocado_v2:MAI_01", "text": "Practice? With three hours left? Absolutely.", "bytes": 32293, "sha256": "d37bcc8aeb20cb6c2067d713cdafc830b6a457d6fd25b6565f98a61f8250b9cb", "src": "audio/movies/movies-053-user.mp3"}}, "movies-054": {"agent": {"seconds": 3.36, "voice": "avocado_v2:ronan", "text": "Can Captain Quackers watch? He's great moral support.", "bytes": 26917, "sha256": "812586dbd2fa6cce62a7ed417da1e886eed964fa24b545bc13ab1ecd8d7ea39a", "src": "audio/movies/movies-054-agent.mp3"}, "user": {"seconds": 3.432, "voice": "avocado_v2:MAI_01", "text": "Fine. The duck can stay. No talking, duck.", "bytes": 27493, "sha256": "2654cba59337b8b90a2bbcb4d3a1cc9a6f4db82a524e074cafe87d8cda2d9704", "src": "audio/movies/movies-054-user.mp3"}}, "movies-055": {"agent": {"seconds": 7.848, "voice": "avocado_v2:myrtle", "text": "Remember: smile, breathe, and don't rush the ending.", "bytes": 62821, "sha256": "ee53d19d88c5d239aafaf88b093d2aa058a168c6d6b4c8b30562a0e84e9a0ec7", "src": "audio/movies/movies-055-agent.mp3"}, "user": {"seconds": 4.032, "voice": "avocado_v2:MAI_01", "text": "Smile, breathe, don't rush. Got it, Lucy.", "bytes": 32293, "sha256": "81a58d5f92aacda3035d6f59c35e84f9174fa6ae164199a06c65be134282fcb2", "src": "audio/movies/movies-055-user.mp3"}}, "movies-056": {"agent": {"seconds": 3.312, "voice": "avocado_v2:ronan", "text": "And if all else fails, I'll do my robot dance.", "bytes": 26533, "sha256": "efd890f4136d0ab48dbe1ac51783824fbfa2ef37ac174aae83dfeb0c5e549654", "src": "audio/movies/movies-056-agent.mp3"}, "user": {"seconds": 2.592, "voice": "avocado_v2:MAI_01", "text": "If all else fails, we're already doomed.", "bytes": 20773, "sha256": "f775965a5d3147a1b31762476bd3fa12c78f8c27c4f77f4b4a8865d512b7957d", "src": "audio/movies/movies-056-user.mp3"}}, "movies-057": {"agent": {"seconds": 3.912, "voice": "avocado_v2:ronan", "text": "Okay, superstar. Pitch to us like we're Mr. Chen.", "bytes": 31333, "sha256": "9bf8453e56709d9365a0ef2c33e0f212faefc16a36cc20fb65c1acab1417d44c", "src": "audio/movies/movies-057-agent.mp3"}, "user": {"seconds": 2.88, "voice": "avocado_v2:MAI_01", "text": "BrightBox is the smart lunchbox that thinks for you.", "bytes": 23077, "sha256": "a17917de58d1f8ecb577db3431b3a9923337db720ce7860068ee92d8a38fbb83", "src": "audio/movies/movies-057-user.mp3"}}, "movies-058": {"agent": {"seconds": 5.952, "voice": "avocado_v2:myrtle", "text": "Good start! But slow down. You're racing the words.", "bytes": 47653, "sha256": "c54f5b6df393135c48b6a4d724e12c600de4a6d23818bc1d09c7622e0b8cda09", "src": "audio/movies/movies-058-agent.mp3"}, "user": {"seconds": 3.288, "voice": "avocado_v2:MAI_01", "text": "Sorry. BrightBox... is the smart lunchbox...", "bytes": 26341, "sha256": "efb812520edaf38412e97660b5e77937c2dd7e3cbc48a8ab708d51c02f1580ba", "src": "audio/movies/movies-058-user.mp3"}}, "movies-059": {"agent": {"seconds": 3.432, "voice": "avocado_v2:ronan", "text": "You sound like a robot! Where's the passion?", "bytes": 27493, "sha256": "77bd5ba75174f1399cb6a1e7ed08aef79ab6484c67dd2a62f3efa5e69d762ff6", "src": "audio/movies/movies-059-agent.mp3"}, "user": {"seconds": 3.288, "voice": "avocado_v2:MAI_01", "text": "Passion? I'm running on fear and no coffee.", "bytes": 26341, "sha256": "0dbc231eb5f8984b6278934b3d41dc9865f26b77bd5416f2d0c8c578a23a8e2c", "src": "audio/movies/movies-059-user.mp3"}}, "movies-060": {"agent": {"seconds": 5.232, "voice": "avocado_v2:myrtle", "text": "Pretend you're telling a friend. Just talk to us.", "bytes": 41893, "sha256": "b2450fde1d83f37cb6d192e1e9fe91b3b951c01ce75f4aa965566865c83d76aa", "src": "audio/movies/movies-060-agent.mp3"}, "user": {"seconds": 3.768, "voice": "avocado_v2:MAI_01", "text": "Okay... Imagine never guessing what is for lunch.", "bytes": 30181, "sha256": "0d6b37b6b2eea130378fa2a562d2ec7d4ba64c7f28121d6fbd05fa0db6fa115e", "src": "audio/movies/movies-060-user.mp3"}}, "movies-061": {"agent": {"seconds": 2.76, "voice": "avocado_v2:ronan", "text": "Better! Now sell me the dream! Sell it!", "bytes": 22117, "sha256": "40e41940fd0533187996d9af8e6b65f699eaee6a5c2eae406d3f874ae82a6447", "src": "audio/movies/movies-061-agent.mp3"}, "user": {"seconds": 2.808, "voice": "avocado_v2:MAI_01", "text": "Our app scans your food in two seconds flat!", "bytes": 22501, "sha256": "cd4f24b1226537ea1ab2df1abd2a18a77da2666fa7c49804e8efc949bbd44d8a", "src": "audio/movies/movies-061-user.mp3"}}, "movies-062": {"agent": {"seconds": 4.8, "voice": "avocado_v2:myrtle", "text": "Lovely! And what does the app do next?", "bytes": 38437, "sha256": "eb0ab6dc7bbfcff1ce92fc7ece69813a49f45824ecdfa545311651ec33a0af51", "src": "audio/movies/movies-062-agent.mp3"}, "user": {"seconds": 3.0, "voice": "avocado_v2:MAI_01", "text": "It tracks nutrition and suggests healthier swaps.", "bytes": 24037, "sha256": "ac06aab5b98c6b0c8d8fdc9e52869fea17cecb344ae5957ba906e496665fba5b", "src": "audio/movies/movies-062-user.mp3"}}, "movies-063": {"agent": {"seconds": 3.888, "voice": "avocado_v2:ronan", "text": "Now with feeling! Like it is the best thing ever!", "bytes": 31141, "sha256": "973a8615106de772c3252250d077d72929b3ad619160c0c55e3af694e13ac601", "src": "audio/movies/movies-063-agent.mp3"}, "user": {"seconds": 2.688, "voice": "avocado_v2:MAI_01", "text": "It's like a nutritionist living in your lunchbox!", "bytes": 21541, "sha256": "064ea24098f90c0a1db66dfcf452444eba4272a05d66764a23dc5b5977d6711b", "src": "audio/movies/movies-063-user.mp3"}}, "movies-064": {"agent": {"seconds": 5.832, "voice": "avocado_v2:myrtle", "text": "That's the one! Say that exact line to Mr. Chen.", "bytes": 46693, "sha256": "bd2bb424de2cae989a643d388c6469be208f8b1a72759abc9c0429e355b6c82d", "src": "audio/movies/movies-064-agent.mp3"}, "user": {"seconds": 2.52, "voice": "avocado_v2:MAI_01", "text": "I will. I think I'm actually ready.", "bytes": 20197, "sha256": "4f4c03568e29e3f925ce6704d6a6c3a8cf01ee2a3e3e659f8882c3b8e39c8079", "src": "audio/movies/movies-064-user.mp3"}}, "movies-065": {"agent": {"seconds": 3.24, "voice": "avocado_v2:ronan", "text": "One more time, but I'll heckle like an investor.", "bytes": 25957, "sha256": "309cf2729798393f6ec699baaee33846717e3ae901ea0c9f4726427b833a7110", "src": "audio/movies/movies-065-agent.mp3"}, "user": {"seconds": 2.4, "voice": "avocado_v2:MAI_01", "text": "Bring it on. I can handle your heckling.", "bytes": 19237, "sha256": "9bab167f12dac35e5cdfadfa56acc84a9b516d5df35035108da166aa29612cf3", "src": "audio/movies/movies-065-user.mp3"}}, "movies-066": {"agent": {"seconds": 3.648, "voice": "avocado_v2:ronan", "text": "Why should I invest? Convince me in one sentence!", "bytes": 29221, "sha256": "330c68a809dfb86c249f6066fc34a20c14d370878e1b465436e7fd23be6b136f", "src": "audio/movies/movies-066-agent.mp3"}, "user": {"seconds": 3.648, "voice": "avocado_v2:MAI_01", "text": "Because everyone eats, and everyone wants to eat smarter.", "bytes": 29221, "sha256": "3f371b6c15f6dd081ae9f489fdc383a60f15603985fc30baf162cfb0eab64289", "src": "audio/movies/movies-066-user.mp3"}}, "movies-067": {"agent": {"seconds": 5.232, "voice": "avocado_v2:myrtle", "text": "Brilliant answer! Quick, confident, no rambling.", "bytes": 41893, "sha256": "47f357620d24c9959caec137d64e979ebf7627f842e1863b0bde5f8dbe5e6b7a", "src": "audio/movies/movies-067-agent.mp3"}, "user": {"seconds": 2.808, "voice": "avocado_v2:MAI_01", "text": "Thanks, Lucy. My stomach is growling, though.", "bytes": 22501, "sha256": "b05942a4366ea7b314575f11ff5163c05555a8c0bcd4c993d3f24c7eba91f257", "src": "audio/movies/movies-067-user.mp3"}}, "movies-068": {"agent": {"seconds": 5.04, "voice": "avocado_v2:myrtle", "text": "Oatmeal cookie? I saved you one from this morning.", "bytes": 40357, "sha256": "b3c524059a4e45bc173e52974201065ca4ac2306c37fb64cae278c3fbce5c796", "src": "audio/movies/movies-068-agent.mp3"}, "user": {"seconds": 3.192, "voice": "avocado_v2:MAI_01", "text": "Yes, please! Nerves are gone, hunger is back.", "bytes": 25573, "sha256": "1d8b49f9391780b3a6e30e19cc4b4d4e4e4235f9158c7e6beda4b8a9d3875f2e", "src": "audio/movies/movies-068-user.mp3"}}, "movies-069": {"agent": {"seconds": 3.6, "voice": "avocado_v2:ronan", "text": "Hey! Where's my cookie? I was nervous too!", "bytes": 28837, "sha256": "2972756c18ac4d9d1c7ff8422a529f3576e8b4aa886b6c1999079c383a202458", "src": "audio/movies/movies-069-agent.mp3"}, "user": {"seconds": 2.688, "voice": "avocado_v2:MAI_01", "text": "You were never nervous. You were just hungry.", "bytes": 21541, "sha256": "507c377594cdc96e77f739cc82400cc184f21d0c30ba986d93496c2c941f6ef1", "src": "audio/movies/movies-069-user.mp3"}}, "movies-070": {"agent": {"seconds": 3.672, "voice": "avocado_v2:myrtle", "text": "There's plenty for everyone. Eat up, team.", "bytes": 29413, "sha256": "bc6a4935e9c4f74bf317b174534f80f7124eb4a199aa9f123150aff9fac2f075", "src": "audio/movies/movies-070-agent.mp3"}, "user": {"seconds": 3.84, "voice": "avocado_v2:MAI_01", "text": "Best cookie ever. Okay, I'm ready for Mr. Chen.", "bytes": 30757, "sha256": "64e8e577f42f671462aedd5e265b6584d4c34a3641747b6b4a5f095ebef20a07", "src": "audio/movies/movies-070-user.mp3"}}, "movies-071": {"agent": {"seconds": 2.952, "voice": "avocado_v2:ronan", "text": "Was that the door? Please tell me that's not the door.", "bytes": 23653, "sha256": "186e48ee181aa7673f2839f3aadb77506933382c9faec532fef7964d92287e57", "src": "audio/movies/movies-071-agent.mp3"}, "user": {"seconds": 2.592, "voice": "avocado_v2:MAI_01", "text": "It's two o'clock. He's an hour early!", "bytes": 20773, "sha256": "48b5780d2b8aebac055b9354294f06b3fe3500125cd78ede19e819083b23dfc7", "src": "audio/movies/movies-071-user.mp3"}}, "movies-072": {"agent": {"seconds": 6.528, "voice": "avocado_v2:myrtle", "text": "Everyone look busy! Jake, hide the sandwich!", "bytes": 52261, "sha256": "de2868295b707399632ad23bd76916bc7a7310d449bb7cc6fa49559cbb2c7a4e", "src": "audio/movies/movies-072-agent.mp3"}, "user": {"seconds": 2.688, "voice": "avocado_v2:MAI_01", "text": "Hide the sandwich? That's your priority?", "bytes": 21541, "sha256": "e364d41295b62b099a0ed6cae3650e3c7dbe37ba50a7f0abb217c1edac02db83", "src": "audio/movies/movies-072-user.mp3"}}, "movies-073": {"agent": {"seconds": 3.192, "voice": "avocado_v2:ronan", "text": "The sandwich is gone! I ate it during practice!", "bytes": 25573, "sha256": "a22d599d2449fff315d8c953da310b2496eb374760d7e25aa4a4f36a96b60acb", "src": "audio/movies/movies-073-agent.mp3"}, "user": {"seconds": 3.192, "voice": "avocado_v2:MAI_01", "text": "Of course you did. Just smile and look professional.", "bytes": 25573, "sha256": "344a0a532a69268ded54c108a8a3a3f45ba66c197ebaccb05605d5ae774874c7", "src": "audio/movies/movies-073-user.mp3"}}, "movies-074": {"agent": {"seconds": 5.4, "voice": "avocado_v2:myrtle", "text": "Mr. Chen! Welcome! We're so glad you're early.", "bytes": 43237, "sha256": "c9fd0715a0913cd0c536b5e3526772a7b31661644172c6df220fea2a5bec885a", "src": "audio/movies/movies-074-agent.mp3"}, "user": {"seconds": 3.048, "voice": "avocado_v2:MAI_01", "text": "Yes, welcome! Please come in and sit down.", "bytes": 24421, "sha256": "e0613782c2b05b2a2bf584cf0a59b6a926312da5f2619f7ea14736a06ab739a5", "src": "audio/movies/movies-074-user.mp3"}}, "movies-075": {"agent": {"seconds": 3.888, "voice": "avocado_v2:ronan", "text": "Mr. Chen, I'm Jake. I built the app. Mostly.", "bytes": 31141, "sha256": "b59e3e0c2a7d59c732a6ee67ed5f69c1da9de413f2b80c41a91bb3faabbc7f6d", "src": "audio/movies/movies-075-agent.mp3"}, "user": {"seconds": 2.712, "voice": "avocado_v2:MAI_01", "text": "He built all of it. He's being modest.", "bytes": 21733, "sha256": "6dc9148504fb026f60166481dbfdc2e5fda8de180877f3043743b18bcb1d4977", "src": "audio/movies/movies-075-user.mp3"}}, "movies-076": {"agent": {"seconds": 7.368, "voice": "avocado_v2:myrtle", "text": "Can I get you coffee? Oh... our machine is resting today.", "bytes": 58981, "sha256": "3e9d5c8e02ff69e5073dadbbdf5accafbd2681f8d8f4e6e38a72ee570f02d00a", "src": "audio/movies/movies-076-agent.mp3"}, "user": {"seconds": 3.768, "voice": "avocado_v2:MAI_01", "text": "Resting? Lucy, it's broken. Jake broke it.", "bytes": 30181, "sha256": "b1aaae16641876d309f7e8124d52c5bac042c26e6d641909eb095f1c0ecc1435", "src": "audio/movies/movies-076-user.mp3"}}, "movies-077": {"agent": {"seconds": 2.52, "voice": "avocado_v2:ronan", "text": "I prefer to say I gave it an early retirement.", "bytes": 20197, "sha256": "438688b09a4560d03301bf722a4e2989708f19847074a6a28627e7106073b539", "src": "audio/movies/movies-077-agent.mp3"}, "user": {"seconds": 3.192, "voice": "avocado_v2:MAI_01", "text": "Mr. Chen, please excuse our... creative team.", "bytes": 25573, "sha256": "51f7730220af084fbb6cca78b997d367cf2edc987c0c9e956fa5a35294f364a3", "src": "audio/movies/movies-077-user.mp3"}}, "movies-078": {"agent": {"seconds": 6.048, "voice": "avocado_v2:myrtle", "text": "So, Mr. Chen, what brings you to startups like ours?", "bytes": 48421, "sha256": "bd601609c49130fce7eddf4941158871c666fec9ae03688dc389495900aacc09", "src": "audio/movies/movies-078-agent.mp3"}, "user": {"seconds": 2.472, "voice": "avocado_v2:MAI_01", "text": "Yes, we'd love to hear what caught your eye.", "bytes": 19813, "sha256": "7e1af268ddfd9364f245ceb6304a012b42dcb47bf3a7acec3fcaffbbcdd85c94", "src": "audio/movies/movies-078-user.mp3"}}, "movies-079": {"agent": {"seconds": 3.288, "voice": "avocado_v2:ronan", "text": "He probably saw our amazing website. I made it!", "bytes": 26341, "sha256": "eec3fcc002646e52b279b0e21677fa762cd40abd854b92607322122ddd37daf0", "src": "audio/movies/movies-079-agent.mp3"}, "user": {"seconds": 2.712, "voice": "avocado_v2:MAI_01", "text": "The website is great. But our product is better.", "bytes": 21733, "sha256": "6754d0deb1fcb5f527ba30fcff4294a8607caa41bdd8dc8b55a765737cac9a7a", "src": "audio/movies/movies-079-user.mp3"}}, "movies-080": {"agent": {"seconds": 7.992, "voice": "avocado_v2:myrtle", "text": "Mia, why don't you show Mr. Chen what BrightBox does?", "bytes": 63973, "sha256": "1352251adade6adb92708e6eac2eba5b650f3f2386a345d19e1a98c8fe04ea42", "src": "audio/movies/movies-080-agent.mp3"}, "user": {"seconds": 3.768, "voice": "avocado_v2:MAI_01", "text": "I'd love to. Mr. Chen, have you seen a smart lunchbox?", "bytes": 30181, "sha256": "10205aca78706379669d930e17eb672b7399f607dd7f4b3f50f49110721f2836", "src": "audio/movies/movies-080-user.mp3"}}, "movies-081": {"agent": {"seconds": 3.912, "voice": "avocado_v2:ronan", "text": "It's not just a box! It's a revolution in a box!", "bytes": 31333, "sha256": "b2df6fc16f12b593693e04881729676c9c7c6f7c24885aa2d8df0029798ee9b9", "src": "audio/movies/movies-081-agent.mp3"}, "user": {"seconds": 2.88, "voice": "avocado_v2:MAI_01", "text": "Jake, let me pitch. You handle the questions later.", "bytes": 23077, "sha256": "d273aaa296581a161477d5a32449e023fd2c6647b2ce8331aab3c88396271456", "src": "audio/movies/movies-081-user.mp3"}}, "movies-082": {"agent": {"seconds": 6.12, "voice": "avocado_v2:myrtle", "text": "Take your time, Mia. Remember: smile and breathe.", "bytes": 48997, "sha256": "ad63cd6f74acc24981f743a7ad045481e63af78b057f5d5baec22f88a230e1f7", "src": "audio/movies/movies-082-agent.mp3"}, "user": {"seconds": 2.928, "voice": "avocado_v2:MAI_01", "text": "Smile and breathe. Here we go, team.", "bytes": 23461, "sha256": "183596ebbc2818bf807e24e7929b553b329185b02e7667633ad52cf8f0eb12a9", "src": "audio/movies/movies-082-user.mp3"}}, "movies-083": {"agent": {"seconds": 2.472, "voice": "avocado_v2:ronan", "text": "You've got this, Mia! We're right behind you!", "bytes": 19813, "sha256": "84bad347f3597a7d0c324883b0c65ea0d8f5995659d7f668215195aea4a8ee5e", "src": "audio/movies/movies-083-agent.mp3"}, "user": {"seconds": 2.52, "voice": "avocado_v2:MAI_01", "text": "Here goes. Wish me luck, everyone.", "bytes": 20197, "sha256": "7f1371dd79f3a9c2dd82c3789c01e0083d4981de2a60215746cb83115670d820", "src": "audio/movies/movies-083-user.mp3"}}, "movies-084": {"agent": {"seconds": 3.96, "voice": "avocado_v2:myrtle", "text": "No luck needed. You've done the work.", "bytes": 31717, "sha256": "8527deae4381510ce95871433fca235771de209b248f35a492f16214a9afeebf", "src": "audio/movies/movies-084-agent.mp3"}, "user": {"seconds": 3.528, "voice": "avocado_v2:MAI_01", "text": "Okay. Mr. Chen, let me tell you about BrightBox.", "bytes": 28261, "sha256": "d9264e54ef6bd52fa59591bb6dfeed58a347b82e05066f2a124ca70e38e6ec8b", "src": "audio/movies/movies-084-user.mp3"}}, "movies-085": {"agent": {"seconds": 2.688, "voice": "avocado_v2:ronan", "text": "She's starting! Everyone act natural and professional!", "bytes": 21541, "sha256": "802d5f7960a1fadac9e6c581e063aede4d07e5a73ca01857a720ca5d98476805", "src": "audio/movies/movies-085-agent.mp3"}, "user": {"seconds": 3.6, "voice": "avocado_v2:MAI_01", "text": "Mr. Chen, meet BrightBox: lunch, upgraded.", "bytes": 28837, "sha256": "6c2826af059b7730a35df63a84d15490650b40e363df20998a836169434a38fd", "src": "audio/movies/movies-085-user.mp3"}}, "movies-086": {"agent": {"seconds": 4.752, "voice": "avocado_v2:myrtle", "text": "She's showing the screenshots now. Looking good.", "bytes": 38053, "sha256": "7c679d9b2278ae561489c6221821f59690db5cb57fa35f31d9c9491391e14701", "src": "audio/movies/movies-086-agent.mp3"}, "user": {"seconds": 2.76, "voice": "avocado_v2:MAI_01", "text": "Our app scans any meal in two seconds flat.", "bytes": 22117, "sha256": "832aab1a4c9b9b30cef32809792ba90d1a65b1717020cdcd720b8a4632b4e3d7", "src": "audio/movies/movies-086-user.mp3"}}, "movies-087": {"agent": {"seconds": 3.792, "voice": "avocado_v2:ronan", "text": "Two seconds! I timed it! It's really fast!", "bytes": 30373, "sha256": "ece5cd0a80e935a2dc3b96b7053ddc961fa5648d42d09c1be535d6ef89c04625", "src": "audio/movies/movies-087-agent.mp3"}, "user": {"seconds": 2.688, "voice": "avocado_v2:MAI_01", "text": "Then it builds your nutrition profile automatically.", "bytes": 21541, "sha256": "6c2f59afdc6029a3601031bbc109eae67ad4afc588796a732fd093020f814477", "src": "audio/movies/movies-087-user.mp3"}}, "movies-088": {"agent": {"seconds": 5.808, "voice": "avocado_v2:myrtle", "text": "Mr. Chen is nodding. Keep going, Mia.", "bytes": 46501, "sha256": "7a73d15376090c4e6e720a57651dd5b4cf02d93ee845e499c9188c094f028812", "src": "audio/movies/movies-088-agent.mp3"}, "user": {"seconds": 3.072, "voice": "avocado_v2:MAI_01", "text": "No more guessing. No more boring food diaries.", "bytes": 24613, "sha256": "9ae3bb4c779cda07afe904433460086003cca6f0bc0c2c49ef67583e33e6e55c", "src": "audio/movies/movies-088-user.mp3"}}, "movies-089": {"agent": {"seconds": 3.192, "voice": "avocado_v2:ronan", "text": "Come on, one live demo! The investors love live demos!", "bytes": 25573, "sha256": "bc8edb2da7cd7fd71c9174d142758ba0ea1abed523db581cec9c8dc0c4a42c55", "src": "audio/movies/movies-089-agent.mp3"}, "user": {"seconds": 2.76, "voice": "avocado_v2:MAI_01", "text": "Fine. One quick scan. Jake, make it work.", "bytes": 22117, "sha256": "d90242c6d41472bec5c6b2a8870e361fdabb83e96f3f88df3b8c7a95799dd5bf", "src": "audio/movies/movies-089-user.mp3"}}, "movies-090": {"agent": {"seconds": 6.672, "voice": "avocado_v2:ronan", "text": "Scanning... scanning... come on... frozen. Classic.", "bytes": 53413, "sha256": "d3554653e32e9ec8b0eb0e2a119ad3450eca3f1396b2b4a25ce8aa6998032169", "src": "audio/movies/movies-090-agent.mp3"}, "user": {"seconds": 2.64, "voice": "avocado_v2:MAI_01", "text": "And that's why we brought screenshots, Mr. Chen!", "bytes": 21157, "sha256": "77a7e507f9679da46817fcd8fb513391aec83418a28061829215d775e25aef1d", "src": "audio/movies/movies-090-user.mp3"}}, "movies-091": {"agent": {"seconds": 3.96, "voice": "avocado_v2:myrtle", "text": "Smooth recovery, Mia! He's actually smiling!", "bytes": 31717, "sha256": "1614533d9f1000e3d06def95b67ccb30f0089850037592e131c7fa57b8c97482", "src": "audio/movies/movies-091-agent.mp3"}, "user": {"seconds": 3.96, "voice": "avocado_v2:MAI_01", "text": "Honesty works. Our app crashed, our team didn't.", "bytes": 31717, "sha256": "8c637fe63713c78d7665bd042e08399641dcbe83126ba8a871598489d0e2e5c4", "src": "audio/movies/movies-091-user.mp3"}}, "movies-092": {"agent": {"seconds": 3.168, "voice": "avocado_v2:ronan", "text": "Mr. Chen wants to know about our competitors.", "bytes": 25381, "sha256": "7f03d73f932f544175b65c965a7e737bb72418be95964ff24e1c660615082d9d", "src": "audio/movies/movies-092-agent.mp3"}, "user": {"seconds": 3.408, "voice": "avocado_v2:MAI_01", "text": "Good question. We're cheaper and much simpler to use.", "bytes": 27301, "sha256": "ded16416390696485747f569daad692622840600406aa08332b8be08b76cdda2", "src": "audio/movies/movies-092-user.mp3"}}, "movies-093": {"agent": {"seconds": 4.44, "voice": "avocado_v2:myrtle", "text": "He's asking about your background, Mia. Tell him.", "bytes": 35557, "sha256": "1e0be20608e26ed5f5480cb7f9f8f02b215d19d82e6709c93090763b25c55ba4", "src": "audio/movies/movies-093-agent.mp3"}, "user": {"seconds": 3.072, "voice": "avocado_v2:MAI_01", "text": "I managed food apps for five years before BrightBox.", "bytes": 24613, "sha256": "dc8e655122f530d58c14588b6c421ebe38960525e6abfc9d759724e6facf0a4a", "src": "audio/movies/movies-093-user.mp3"}}, "movies-094": {"agent": {"seconds": 3.048, "voice": "avocado_v2:ronan", "text": "He's pointing at Captain Quackers! He wants to know!", "bytes": 24421, "sha256": "f80000d2a7b563016a23b9ca6f5032e5f006cc93ee02178931c83962dbb960af", "src": "audio/movies/movies-094-agent.mp3"}, "user": {"seconds": 2.568, "voice": "avocado_v2:MAI_01", "text": "That's Jake's debugging duck. Don't ask.", "bytes": 20581, "sha256": "6fe1fac20a6d3296b6f879e33d05229bbb59a6ab275f8be840fa4f7cbbc07e38", "src": "audio/movies/movies-094-user.mp3"}}, "movies-095": {"agent": {"seconds": 3.6, "voice": "avocado_v2:ronan", "text": "The duck finds bugs! I explain code to him!", "bytes": 28837, "sha256": "a4b548afd1382017b29605a92c3b69a6e831c3cf141312c29a6c4ab39809acf2", "src": "audio/movies/movies-095-agent.mp3"}, "user": {"seconds": 2.928, "voice": "avocado_v2:MAI_01", "text": "And somehow it works. Don't question the duck.", "bytes": 23461, "sha256": "a7e54dfe45640250b266e1b5a318eccc8ed7253cef676eab72bcc95152a8f135", "src": "audio/movies/movies-095-user.mp3"}}, "movies-096": {"agent": {"seconds": 4.608, "voice": "avocado_v2:myrtle", "text": "Mr. Chen is laughing! He loves the duck story!", "bytes": 36901, "sha256": "c6453a18c13bcecbc4ec156e297bdbbc3956df8fcf3264ff5f92310d1445ac7b", "src": "audio/movies/movies-096-agent.mp3"}, "user": {"seconds": 3.36, "voice": "avocado_v2:MAI_01", "text": "See? Honesty and a duck. That's our strategy.", "bytes": 26917, "sha256": "d8b78c04fa05ec788e1306d89d5bd818f88bc765fd4a593a9318346afaf99f1a", "src": "audio/movies/movies-096-user.mp3"}}, "movies-097": {"agent": {"seconds": 3.672, "voice": "avocado_v2:ronan", "text": "He's asking the big one: why will you win?", "bytes": 29413, "sha256": "798f50ad1919d192517760b057a1c2c552c6b4fdf6e1c2de495aa0b81c2cd574", "src": "audio/movies/movies-097-agent.mp3"}, "user": {"seconds": 2.88, "voice": "avocado_v2:MAI_01", "text": "Because we solve a real problem real people have.", "bytes": 23077, "sha256": "279d9d209a8d874edd221f2a5b902a7b103aaa9611d6dd94afc73aab1a7c793f", "src": "audio/movies/movies-097-user.mp3"}}, "movies-098": {"agent": {"seconds": 4.92, "voice": "avocado_v2:myrtle", "text": "Pitch complete! Mia, you were wonderful!", "bytes": 39397, "sha256": "d2269cf941818c1f462889ae013c0223a5d73bebac9cf2b97be1ecd0324d3a21", "src": "audio/movies/movies-098-agent.mp3"}, "user": {"seconds": 3.12, "voice": "avocado_v2:MAI_01", "text": "Thank you. Now the hard part: his decision.", "bytes": 24997, "sha256": "f0328db564eb90a4e875d8987334af064b0920a21f45925559b931964675a2df", "src": "audio/movies/movies-098-user.mp3"}}, "movies-099": {"agent": {"seconds": 4.368, "voice": "avocado_v2:ronan", "text": "He's quiet. Quiet is bad. Quiet is very bad.", "bytes": 34981, "sha256": "defb49521705062e0837cd3d0c61a2cc0bfff6816686c57f392ccb802af33922", "src": "audio/movies/movies-099-agent.mp3"}, "user": {"seconds": 2.4, "voice": "avocado_v2:MAI_01", "text": "Quiet just means he's thinking, Jake.", "bytes": 19237, "sha256": "208b6d83205a31a7932f85b01ddbc5af1de20213e899524c3e396bbf02359bd6", "src": "audio/movies/movies-099-user.mp3"}}, "movies-100": {"agent": {"seconds": 4.128, "voice": "avocado_v2:myrtle", "text": "He's asking to speak with you alone, Mia.", "bytes": 33061, "sha256": "156d0b705be04e229a87fab7a7e0ae0c3bbc77de0708423fe62b95fef5ceee95", "src": "audio/movies/movies-100-agent.mp3"}, "user": {"seconds": 4.368, "voice": "avocado_v2:MAI_01", "text": "Alone? Okay. Guys, wish me luck.", "bytes": 34981, "sha256": "d25d970a1fd91c6fc7c005484accb5b29d9be11c7e960ce23615a63d4f139b3d", "src": "audio/movies/movies-100-user.mp3"}}, "movies-101": {"agent": {"seconds": 2.832, "voice": "avocado_v2:ronan", "text": "We'll be right outside! With the duck for support!", "bytes": 22693, "sha256": "60a92efcce6223d11df02e0270a7fc85fdbeab1116161ade8fe1b22c46934c47", "src": "audio/movies/movies-101-agent.mp3"}, "user": {"seconds": 2.88, "voice": "avocado_v2:MAI_01", "text": "Mr. Chen, what did you want to discuss?", "bytes": 23077, "sha256": "266a976c5a7a85f4251ed9637f6f65db801a2ed438ba76a214d0bcb5977c5da2", "src": "audio/movies/movies-101-user.mp3"}}, "movies-102": {"agent": {"seconds": 4.512, "voice": "avocado_v2:myrtle", "text": "Take your time in there. We'll keep busy out here.", "bytes": 36133, "sha256": "a2e2d0b93ceafaccdfd49e6e1260ff3bcb5d2f3deb2683be2783994dee6e927a", "src": "audio/movies/movies-102-agent.mp3"}, "user": {"seconds": 3.24, "voice": "avocado_v2:MAI_01", "text": "So, Mr. Chen, what are your thoughts so far?", "bytes": 25957, "sha256": "297a9e07e8753635de4317397cf11a92e1d4094a0477e399b06859c20edf1183", "src": "audio/movies/movies-102-user.mp3"}}, "movies-103": {"agent": {"seconds": 3.408, "voice": "avocado_v2:ronan", "text": "He stepped out to take a call. What happened in there?", "bytes": 27301, "sha256": "a9236c153b8844cf5cb550be3012711969b43cab0f5c5554fdee63c388c80381", "src": "audio/movies/movies-103-agent.mp3"}, "user": {"seconds": 3.12, "voice": "avocado_v2:MAI_01", "text": "He told me about his daughter. She has diabetes.", "bytes": 24997, "sha256": "e6a5704edfc91d8bb1a8fb67748f93dbf408ec13db15e3de9f156d4203628431", "src": "audio/movies/movies-103-user.mp3"}}, "movies-104": {"agent": {"seconds": 6.552, "voice": "avocado_v2:myrtle", "text": "Oh, the poor man. That explains his interest.", "bytes": 52453, "sha256": "7fc7e133c184eeac511ce2b657ff588645b2167bee7015eafb8688ae74103407", "src": "audio/movies/movies-104-agent.mp3"}, "user": {"seconds": 2.76, "voice": "avocado_v2:MAI_01", "text": "He tracks her meals by hand every single day.", "bytes": 22117, "sha256": "d5d278cce98353c0f6ebb8aca1aa644a6f84169473db3e7abe217001a01b0b9a", "src": "audio/movies/movies-104-user.mp3"}}, "movies-105": {"agent": {"seconds": 2.448, "voice": "avocado_v2:ronan", "text": "So this isn't just business for him. It's personal.", "bytes": 19621, "sha256": "c9711c8ef5793bd92079d86bc84e1167f5fe8a326ec4b01327d6c779a34acea8", "src": "audio/movies/movies-105-agent.mp3"}, "user": {"seconds": 3.672, "voice": "avocado_v2:MAI_01", "text": "Exactly. He wants BrightBox to help families like his.", "bytes": 29413, "sha256": "94b85f98518475de677b92ace35b84d119f16968b0c5306baaf9d1962326b950", "src": "audio/movies/movies-105-user.mp3"}}, "movies-106": {"agent": {"seconds": 4.152, "voice": "avocado_v2:myrtle", "text": "But what did he decide? Don't keep us waiting.", "bytes": 33253, "sha256": "f1257a8273aab16ace6f13da152e25423e2d6b702eec26c50fc7128046cfa569", "src": "audio/movies/movies-106-agent.mp3"}, "user": {"seconds": 3.168, "voice": "avocado_v2:MAI_01", "text": "He has not decided. He moved the meeting to test us.", "bytes": 25381, "sha256": "04c9e9b1c52896e05559dfdec89d0c999a76fe3730489de7c0655658f62ebbac", "src": "audio/movies/movies-106-user.mp3"}}, "movies-107": {"agent": {"seconds": 2.928, "voice": "avocado_v2:ronan", "text": "Test us? That early meeting was a test?", "bytes": 23461, "sha256": "282293b7849127cf4f77ce3aabceb2a29c15a492acc36d02377355fb313dabbf", "src": "audio/movies/movies-107-agent.mp3"}, "user": {"seconds": 3.0, "voice": "avocado_v2:MAI_01", "text": "He wanted to see us under pressure. Sneaky, right?", "bytes": 24037, "sha256": "fe2122449be45c4dd3d96090b96a9c24113874ca61cf533bbd46ab91ae46a414", "src": "audio/movies/movies-107-user.mp3"}}, "movies-108": {"agent": {"seconds": 4.44, "voice": "avocado_v2:myrtle", "text": "And did we pass his little test, do you think?", "bytes": 35557, "sha256": "aaf54385e1838a47d88a06095a2c89627e40f1ed7c220af5aae2bf869edd4cc1", "src": "audio/movies/movies-108-agent.mp3"}, "user": {"seconds": 1.2, "voice": "avocado_v2:MAI_01", "text": "He smiled at the duck. I'd call that passing.", "bytes": 9637, "sha256": "2d6b3c1d1fdc3c0d0843afe0cc344d861e9e493bc66c32be6f3f7d9df5bfac40", "src": "audio/movies/movies-108-user.mp3"}}, "movies-109": {"agent": {"seconds": 3.888, "voice": "avocado_v2:ronan", "text": "Captain Quackers saves the day again! He's a hero!", "bytes": 31141, "sha256": "b8ae5db2efc3190f04f5a54b0d645b200defbc5d788d63458070c023f725a13c", "src": "audio/movies/movies-109-agent.mp3"}, "user": {"seconds": 2.52, "voice": "avocado_v2:MAI_01", "text": "The duck helped. But our honesty won him over.", "bytes": 20197, "sha256": "5ef4efe4588dfaffa3ab02061412b4bfc5387bd2e253decbc2a64e873ab9728a", "src": "audio/movies/movies-109-user.mp3"}}, "movies-110": {"agent": {"seconds": 5.088, "voice": "avocado_v2:myrtle", "text": "He's coming back. Everyone look calm and confident.", "bytes": 40741, "sha256": "807b4bdaa937ca26863000792ba26bd287534508812afa750931646d397c7fa7", "src": "audio/movies/movies-110-agent.mp3"}, "user": {"seconds": 3.312, "voice": "avocado_v2:MAI_01", "text": "Calm and confident. I can do calm and confident.", "bytes": 26533, "sha256": "ee9e22848a9dc85709fc8aca6aa9a5b2bb163dcca9c144b3367a1f364356a8c6", "src": "audio/movies/movies-110-user.mp3"}}, "movies-111": {"agent": {"seconds": 2.928, "voice": "avocado_v2:ronan", "text": "He's shaking your hand! That's a good sign!", "bytes": 23461, "sha256": "abd167b0926b3c97d3e871fe2eda642ac050784efbab5efc21072f5f9fefda54", "src": "audio/movies/movies-111-agent.mp3"}, "user": {"seconds": 2.16, "voice": "avocado_v2:MAI_01", "text": "He's offering us the investment, team!", "bytes": 17317, "sha256": "fd38fbd11a8c774c7b34f0ddd3b3b6e9b7eccc2760b9b8b50629db13ca94e431", "src": "audio/movies/movies-111-user.mp3"}}, "movies-112": {"agent": {"seconds": 4.56, "voice": "avocado_v2:myrtle", "text": "I knew it! Did he mention the terms?", "bytes": 36517, "sha256": "7215b492e65ecc17a723f9f1ed010c70f678d5a4fe01fcfeb51a89ba4ab27052", "src": "audio/movies/movies-112-agent.mp3"}, "user": {"seconds": 2.808, "voice": "avocado_v2:MAI_01", "text": "One condition: a kids' version within a year.", "bytes": 22501, "sha256": "fa6d12c2a17d444ebb48183f375c03062d532110272c227c201f2594489632d7", "src": "audio/movies/movies-112-user.mp3"}}, "movies-113": {"agent": {"seconds": 3.12, "voice": "avocado_v2:ronan", "text": "A kids' version? We can totally do that!", "bytes": 24997, "sha256": "dccfe9e56b8b95c3ce43fa185e1022f1b90a7a24e33d8d70dfa97332ba763413", "src": "audio/movies/movies-113-agent.mp3"}, "user": {"seconds": 3.552, "voice": "avocado_v2:MAI_01", "text": "Totally. BrightBox Junior. I love it already.", "bytes": 28453, "sha256": "5b28f6bdc1ed56c79391894499852135fa95421e8647e75a794c355fa88d9ef0", "src": "audio/movies/movies-113-user.mp3"}}, "movies-114": {"agent": {"seconds": 4.752, "voice": "avocado_v2:myrtle", "text": "Did you agree? Tell me you didn't agree too fast.", "bytes": 38053, "sha256": "17f414eafc9cfd51de9e896590dde9a12fd52768e5c64d418f8646186b6c1ca9", "src": "audio/movies/movies-114-agent.mp3"}, "user": {"seconds": 2.112, "voice": "avocado_v2:MAI_01", "text": "I said we'd love to discuss it properly.", "bytes": 16933, "sha256": "b4195831185bc0b0fc47342033980231626d1e112114fbcf9d33cc744e718152", "src": "audio/movies/movies-114-user.mp3"}}, "movies-115": {"agent": {"seconds": 4.392, "voice": "avocado_v2:ronan", "text": "Properly? Mia, he offered us money! Say yes!", "bytes": 35173, "sha256": "4e5d88b24c2245f28b6709236a7ef7ca3fa9d45e99b499ea47242f458d692f48", "src": "audio/movies/movies-115-agent.mp3"}, "user": {"seconds": 2.688, "voice": "avocado_v2:MAI_01", "text": "Smart founders read the terms first, Jake.", "bytes": 21541, "sha256": "d86d31660c4e4f4acfaabe8c00f4938241c3f4e01cbf26abf2096201fd549f67", "src": "audio/movies/movies-115-user.mp3"}}, "movies-116": {"agent": {"seconds": 6.432, "voice": "avocado_v2:myrtle", "text": "She's right. Excitement now, lawyers tomorrow.", "bytes": 51493, "sha256": "afd90dee38ab71c7dae1959139e6a39efafe480541a2d94f1b9767baa15c6f15", "src": "audio/movies/movies-116-agent.mp3"}, "user": {"seconds": 3.312, "voice": "avocado_v2:MAI_01", "text": "Exactly. But between us... I'm thrilled.", "bytes": 26533, "sha256": "add189db4dfca2d3ce0ddc856f244cbb674202f1b234fac0b2b1067cc6a50322", "src": "audio/movies/movies-116-user.mp3"}}, "movies-117": {"agent": {"seconds": 2.76, "voice": "avocado_v2:ronan", "text": "Can we celebrate now? Please? Just a little?", "bytes": 22117, "sha256": "8ff09acd005a8c93ed1e3d3f27e4c8903518c70c2149ea589a63e3e8852b41f6", "src": "audio/movies/movies-117-agent.mp3"}, "user": {"seconds": 2.88, "voice": "avocado_v2:MAI_01", "text": "A little. But no robot dance yet.", "bytes": 23077, "sha256": "d4cd70648b6871bafebb3fb3417e86df74dcc040e252c239f743fb04f7223032", "src": "audio/movies/movies-117-user.mp3"}}, "movies-118": {"agent": {"seconds": 6.24, "voice": "avocado_v2:myrtle", "text": "Mr. Chen is leaving. Let's walk him out properly.", "bytes": 49957, "sha256": "77dd4c3ba39146643aa50cbe352ebb330ec66a3a79312f4178a9b853d3f2ccf8", "src": "audio/movies/movies-118-agent.mp3"}, "user": {"seconds": 2.112, "voice": "avocado_v2:MAI_01", "text": "Thank you for believing in us, Mr. Chen.", "bytes": 16933, "sha256": "c80fef3b752510c5a4fc509032e51314792c6a9eecb81cbeed545148540eff7b", "src": "audio/movies/movies-118-user.mp3"}}, "movies-119": {"agent": {"seconds": 3.192, "voice": "avocado_v2:ronan", "text": "He waved at the duck! The duck gets a wave!", "bytes": 25573, "sha256": "b4f28f78885b5cf312c816651719f6b0be145319d6d3f9a995d8f98297247cdf", "src": "audio/movies/movies-119-agent.mp3"}, "user": {"seconds": 3.648, "voice": "avocado_v2:MAI_01", "text": "Everyone loves Captain Quackers. It's science.", "bytes": 29221, "sha256": "f23d03cb4e6e92be35e8e00780fa66ee14cfb1242f84332b70f251801713d335", "src": "audio/movies/movies-119-user.mp3"}}, "movies-120": {"agent": {"seconds": 5.52, "voice": "avocado_v2:myrtle", "text": "Term sheet tomorrow, he said. Then we celebrate.", "bytes": 44197, "sha256": "0047d3aa4053f1deca12d80f925fbe1919392d9028b9d35158ee06d916adfe3b", "src": "audio/movies/movies-120-agent.mp3"}, "user": {"seconds": 3.432, "voice": "avocado_v2:MAI_01", "text": "Tomorrow. Today, we breathe and clean up.", "bytes": 27493, "sha256": "963432c1165af868457d39bc10f859caafaa1e9be71f60b7c4117755604a833e", "src": "audio/movies/movies-120-user.mp3"}}, "movies-121": {"agent": {"seconds": 3.12, "voice": "avocado_v2:ronan", "text": "I can't believe we survived! We actually did it!", "bytes": 24997, "sha256": "58be5b772ae737be8f13b126c6168f3add67ba46746238d526f01d3c3dd245ce", "src": "audio/movies/movies-121-agent.mp3"}, "user": {"seconds": 2.328, "voice": "avocado_v2:MAI_01", "text": "We did. Paper screenshots and all.", "bytes": 18661, "sha256": "311b9d2a774486fa7921ff0d1c75a42048aa45e3e5ed1e4f1f12123a143d5b98", "src": "audio/movies/movies-121-user.mp3"}}, "movies-122": {"agent": {"seconds": 4.992, "voice": "avocado_v2:myrtle", "text": "Never underestimate old school methods, my dears.", "bytes": 39973, "sha256": "c179b599a418d77ba25869d7eae5afc9d0f8820d5c82b7b14ba470479a6d9ddd", "src": "audio/movies/movies-122-agent.mp3"}, "user": {"seconds": 3.552, "voice": "avocado_v2:MAI_01", "text": "Lesson learned, Lucy. I'll never doubt the printouts.", "bytes": 28453, "sha256": "cb8daab64781d327fc54dc9a8c241bf640623df50bd37dba6269d3d743d745ed", "src": "audio/movies/movies-122-user.mp3"}}, "movies-123": {"agent": {"seconds": 2.88, "voice": "avocado_v2:ronan", "text": "So... can I do the robot dance now?", "bytes": 23077, "sha256": "7be02c7e0977106440358c5835f38fe54ecc8a6915e552866b41d25add325209", "src": "audio/movies/movies-123-agent.mp3"}, "user": {"seconds": 3.36, "voice": "avocado_v2:MAI_01", "text": "Fine. One robot dance. You've earned it.", "bytes": 26917, "sha256": "64976f9d031d1559f9bfc7c2e4bc1216c152893001949d4399e8ee1c37bea10e", "src": "audio/movies/movies-123-user.mp3"}}, "movies-124": {"agent": {"seconds": 6.0, "voice": "avocado_v2:myrtle", "text": "I'll allow it. Just don't break anything else.", "bytes": 48037, "sha256": "9d339680fadc17a49d5dde79ddeed44fdfeb4858033ba342f3ba4fabc330442f", "src": "audio/movies/movies-124-agent.mp3"}, "user": {"seconds": 3.12, "voice": "avocado_v2:MAI_01", "text": "The coffee machine is already broken. Go wild.", "bytes": 24997, "sha256": "fd497de346cd06fc62a9671e5218951a2d049194080df7c39eb1e3214ca2f593", "src": "audio/movies/movies-124-user.mp3"}}, "movies-125": {"agent": {"seconds": 3.408, "voice": "avocado_v2:ronan", "text": "Best day ever! Ship it! Ship it! Ship it!", "bytes": 27301, "sha256": "a77a628f248baed200d67b172b5629e483a7ace20f29e36786e4005d0a19822b", "src": "audio/movies/movies-125-agent.mp3"}, "user": {"seconds": 3.528, "voice": "avocado_v2:MAI_01", "text": "Ship it! Okay, team, let's clean this office.", "bytes": 28261, "sha256": "e0a8cf16e4220d79a90ac37c3b429d2fdc56c7b8a0af2a1234455ed08d8e402e", "src": "audio/movies/movies-125-user.mp3"}}, "movies-126": {"agent": {"seconds": 4.992, "voice": "avocado_v2:myrtle", "text": "I'll start with Jake's desk. It scares me.", "bytes": 39973, "sha256": "23bf1595dd5d683454253aa4373c37a146b0d9967f9ec72f1c845e7e93103e71", "src": "audio/movies/movies-126-agent.mp3"}, "user": {"seconds": 2.592, "voice": "avocado_v2:MAI_01", "text": "Good luck. You'll need a map and snacks.", "bytes": 20773, "sha256": "7e446a429a1715e4248e4fbfcc0302492da24385f5fd652cb033b89287d6ed36", "src": "audio/movies/movies-126-user.mp3"}}, "movies-127": {"agent": {"seconds": 6.432, "voice": "avocado_v2:myrtle", "text": "Mia, hand me that paperclip. Watch a master.", "bytes": 51493, "sha256": "3ae4e76c4b5867dfb13fbec234dcb8cf348df64be5a1d16d7c671fa855809afa", "src": "audio/movies/movies-127-agent.mp3"}, "user": {"seconds": 3.24, "voice": "avocado_v2:MAI_01", "text": "A paperclip? You're fixing it with a paperclip?", "bytes": 25957, "sha256": "6efa70d000420c1e06a23384324c5bcae6c98a8a16cbe6a3e8d1dbbb6a38b5ab", "src": "audio/movies/movies-127-user.mp3"}}, "movies-128": {"agent": {"seconds": 4.8, "voice": "avocado_v2:ronan", "text": "No way. That machine is dead forever.", "bytes": 38437, "sha256": "862a40cbc38b98912142301601ace33d028b783c1dc47219d291f4e203f28234", "src": "audio/movies/movies-128-agent.mp3"}, "user": {"seconds": 2.688, "voice": "avocado_v2:MAI_01", "text": "Lucy fixed the printer with a hairpin once.", "bytes": 21541, "sha256": "06baa488c29550d6dda0d8a4a0fe4587c5b11d11dea33397ebdab52b7ef85aad", "src": "audio/movies/movies-128-user.mp3"}}, "movies-129": {"agent": {"seconds": 6.552, "voice": "avocado_v2:myrtle", "text": "And... there! Listen to that beautiful sound!", "bytes": 52453, "sha256": "3416dfc7b04186dad0bd05d71ec20a114cb0c28e25546dedf8c6b91c3f0e00fa", "src": "audio/movies/movies-129-agent.mp3"}, "user": {"seconds": 3.24, "voice": "avocado_v2:MAI_01", "text": "It's working! Lucy, you're a miracle worker!", "bytes": 25957, "sha256": "beb126ca5738989bd43224a40129611e3db9c125ff327609b0ce3007415af3eb", "src": "audio/movies/movies-129-user.mp3"}}, "movies-130": {"agent": {"seconds": 3.552, "voice": "avocado_v2:ronan", "text": "I take back everything. You're a genius, Lucy!", "bytes": 28453, "sha256": "88a8156fbcda251a61bf6832090e79de602c289e4a245d2395d33478fb9434c3", "src": "audio/movies/movies-130-agent.mp3"}, "user": {"seconds": 3.672, "voice": "avocado_v2:MAI_01", "text": "To Lucy: keeper of screenshots, fixer of machines.", "bytes": 29413, "sha256": "feaf1900fcb497c3aabe58d98ff63262a1cac8e13484c592f1e038a00a7e39f8", "src": "audio/movies/movies-130-user.mp3"}}, "movies-131": {"agent": {"seconds": 4.848, "voice": "avocado_v2:myrtle", "text": "To the team: the bravest startup in town.", "bytes": 38821, "sha256": "53765ebc97828b956c2c6dded666712b561405cd04c12c2ff63dd2a4962c1c7a", "src": "audio/movies/movies-131-agent.mp3"}, "user": {"seconds": 2.88, "voice": "avocado_v2:MAI_01", "text": "To BrightBox! And to Captain Quackers!", "bytes": 23077, "sha256": "55672cc7b21c34bb40f64d10cd3ad7ec101619b524b4e45671de3f4b6c5a4b32", "src": "audio/movies/movies-131-user.mp3"}}, "movies-132": {"agent": {"seconds": 3.24, "voice": "avocado_v2:ronan", "text": "Best team ever! Now, about my password...", "bytes": 25957, "sha256": "aa8cef2265359cf905281c0a14d5d07a5b0b79f902bcf2ff19b25077401e4dd1", "src": "audio/movies/movies-132-agent.mp3"}, "user": {"seconds": 3.408, "voice": "avocado_v2:MAI_01", "text": "Change it tonight. Password one two three four is weak.", "bytes": 27301, "sha256": "8378e82d875efaed76027b8f27af915063c4f2fc294a76f57342a5cdd9ac719e", "src": "audio/movies/movies-132-user.mp3"}}, "movies-133": {"agent": {"seconds": 5.4, "voice": "avocado_v2:myrtle", "text": "Speaking of tonight, check your email, Mia.", "bytes": 43237, "sha256": "0c13d90707cdd7df453799daf1473efdd72a154edcf07bc00659cdc46c8692ce", "src": "audio/movies/movies-133-agent.mp3"}, "user": {"seconds": 3.6, "voice": "avocado_v2:MAI_01", "text": "Email? At six? Can't it wait till morning?", "bytes": 28837, "sha256": "8a6b81a3200bb673be4524a498fecc657dd09c98104bb0d60495fb90fba1fef0", "src": "audio/movies/movies-133-user.mp3"}}, "movies-134": {"agent": {"seconds": 3.072, "voice": "avocado_v2:ronan", "text": "Is it the term sheet? Already? That was fast!", "bytes": 24613, "sha256": "3bbe0907fe26db1b8b76e71466ff3fcac18208631121a7aa7593916f5d42f39a", "src": "audio/movies/movies-134-agent.mp3"}, "user": {"seconds": 3.0, "voice": "avocado_v2:MAI_01", "text": "Not the term sheet. It's... oh no.", "bytes": 24037, "sha256": "01a4f510ec735e1ccf66d30b558da5d5f4a3b97c6603e070a966164ca82efa9d", "src": "audio/movies/movies-134-user.mp3"}}, "movies-135": {"agent": {"seconds": 9.432, "voice": "avocado_v2:myrtle", "text": "Oh no what? Mia, what does oh no mean?", "bytes": 75493, "sha256": "d0adbbe323f4cec697555e52f9ecbebf3666c69a12adb2043530d829b5729252", "src": "audio/movies/movies-135-agent.mp3"}, "user": {"seconds": 2.52, "voice": "avocado_v2:MAI_01", "text": "It's from LunchTech. Our biggest competitor.", "bytes": 20197, "sha256": "23212fcf86f152414edfd76d7ef205ec5d4b8df4f037a6e84a2d625aa2a4c4d8", "src": "audio/movies/movies-135-user.mp3"}}, "movies-136": {"agent": {"seconds": 2.4, "voice": "avocado_v2:ronan", "text": "LunchTech? What do they want from us?", "bytes": 19237, "sha256": "5d33a388cc37b138da3729a166d81996cf25a441b6fa259c57b9bfbc8eeea391", "src": "audio/movies/movies-136-agent.mp3"}, "user": {"seconds": 3.192, "voice": "avocado_v2:MAI_01", "text": "They want to meet. Tomorrow. About a partnership.", "bytes": 25573, "sha256": "d0e9f69743e03f4e9bff4d8e09c684701ddec3a2602461065b463d666ce41333", "src": "audio/movies/movies-136-user.mp3"}}, "movies-137": {"agent": {"seconds": 4.56, "voice": "avocado_v2:myrtle", "text": "A partnership? Or are they scared of us?", "bytes": 36517, "sha256": "311d08f34e9e78b0ecaf17947344dad353ab0290b6f92570a2f3d8085debfc56", "src": "audio/movies/movies-137-agent.mp3"}, "user": {"seconds": 3.0, "voice": "avocado_v2:MAI_01", "text": "Probably scared. We just got funded, after all.", "bytes": 24037, "sha256": "faa3c0e8e8d5f154d73753f69f22ca829bf27482ef9d044b6b418ed1457979b5", "src": "audio/movies/movies-137-user.mp3"}}, "movies-138": {"agent": {"seconds": 3.528, "voice": "avocado_v2:ronan", "text": "Tomorrow? I need sleep! Real sleep this time!", "bytes": 28261, "sha256": "7211ecd02c14bcffb95c8b1a08053c84662003f66a9db0826005a11d4c679cf0", "src": "audio/movies/movies-138-agent.mp3"}, "user": {"seconds": 3.048, "voice": "avocado_v2:MAI_01", "text": "Sleep fast, Jake. Tomorrow we meet the competition.", "bytes": 24421, "sha256": "60c858ca5742f9ea44db44e5a5dd4b9e3066cb7c0d0609495f4c12a4c6707d74", "src": "audio/movies/movies-138-user.mp3"}}, "movies-139": {"agent": {"seconds": 4.968, "voice": "avocado_v2:myrtle", "text": "Same time tomorrow, team. Bring your A-game.", "bytes": 39781, "sha256": "1725954753dbe10fc1e95f513ab79c48b1308ebad4d78f4095c6947e7237ad0f", "src": "audio/movies/movies-139-agent.mp3"}, "user": {"seconds": 2.76, "voice": "avocado_v2:MAI_01", "text": "And Jake? No more midnight coding tonight.", "bytes": 22117, "sha256": "b1b3e7a3cbaeea8ecc7dee0cc88b868e6e1309cfca758e385985649e78ccb78e", "src": "audio/movies/movies-139-user.mp3"}}, "movies-140": {"agent": {"seconds": 2.928, "voice": "avocado_v2:ronan", "text": "No promises! But first... SHIP IT!", "bytes": 23461, "sha256": "5df21370ad046c7b6580a0bdb8725725072fbd668865a72aac06c86139bb1c48", "src": "audio/movies/movies-140-agent.mp3"}, "user": {"seconds": 2.16, "voice": "avocado_v2:MAI_01", "text": "Ship it! See you tomorrow, team.", "bytes": 17317, "sha256": "403b818d4c271eec6d12a3f5068f2c4aa9d30a24933deba3db39dee06121d5bb", "src": "audio/movies/movies-140-user.mp3"}}}, "restaurant": {"restaurant-001": {"agent": {"seconds": 4.032, "voice": "am_michael", "text": "Good evening. Thank you for calling Bella Roma. How can I help?", "bytes": 48960, "sha256": "6adada875922effc0570c65032ba936b70af85756573e3438e157815189ef4d8", "src": "audio/restaurant/restaurant-001-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "I'd like to book a table for two.", "bytes": 21600, "sha256": "40420ddf9002cb4c629e1816c3d5711686bed31314df88813d8c1884d783c984", "src": "audio/restaurant/restaurant-001-user.mp3"}}, "restaurant-002": {"agent": {"seconds": 2.752, "voice": "am_michael", "text": "Of course. Which day would you like to come?", "bytes": 33696, "sha256": "f4614cbe11086bf5ea2358811b8ec3abb2e2bea12ee008ae1d8248275a5e85ac", "src": "audio/restaurant/restaurant-002-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_bella", "text": "Friday evening, around seven o'clock.", "bytes": 28800, "sha256": "94cb33c5ed75ee59472d22e382d78b2d3c44f20e62fda0f435814417b49f38e3", "src": "audio/restaurant/restaurant-002-user.mp3"}}, "restaurant-003": {"agent": {"seconds": 3.157, "voice": "am_michael", "text": "Friday at seven. How many people is that for?", "bytes": 38592, "sha256": "dc0732dce319a5b251b5baada3545cc1269922410d07ac97605f0ab540bb9236", "src": "audio/restaurant/restaurant-003-agent.mp3"}, "user": {"seconds": 1.344, "voice": "af_bella", "text": "Just two of us, please.", "bytes": 16704, "sha256": "183684d0da778aa6ffe5080fa28391818890f73015d0d847340694a994cf7d45", "src": "audio/restaurant/restaurant-003-user.mp3"}}, "restaurant-004": {"agent": {"seconds": 3.093, "voice": "am_michael", "text": "Do you have a preference — inside or on the terrace?", "bytes": 37728, "sha256": "7a2208c113591fe79ce854b2d8d3921af2fcbd4aeab1539fd5063b898b23c964", "src": "audio/restaurant/restaurant-004-agent.mp3"}, "user": {"seconds": 2.432, "voice": "af_bella", "text": "Inside, near the window if possible.", "bytes": 29952, "sha256": "a478bbf530dacb4202226eddb54d79482ad44c6ad1d9c901b51e68738c61f055", "src": "audio/restaurant/restaurant-004-user.mp3"}}, "restaurant-005": {"agent": {"seconds": 3.221, "voice": "am_michael", "text": "I'll note that down. A name for the reservation?", "bytes": 39456, "sha256": "1f14f08057c158315e374976ad1d44eba354ef3f45943ef6805b4bf5c39ec908", "src": "audio/restaurant/restaurant-005-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "It's under Li, L-I.", "bytes": 19584, "sha256": "a0d298d1dbbec6cb6c9f48fc1ccc10ea82c40bfa4e62cda3e2b7da399f254bf4", "src": "audio/restaurant/restaurant-005-user.mp3"}}, "restaurant-006": {"agent": {"seconds": 2.112, "voice": "am_michael", "text": "Thank you. And a phone number, please?", "bytes": 25920, "sha256": "ea464b6ba91914c544167106758ad4b61aa2c9e658946aa72a06f814f8452ac2", "src": "audio/restaurant/restaurant-006-agent.mp3"}, "user": {"seconds": 2.411, "voice": "af_bella", "text": "Sure, it's one three eight, eight eight eight eight.", "bytes": 29664, "sha256": "4fca304f935ed38aa04a7fae11a933a642777fea8d8f63574d334654301334a4", "src": "audio/restaurant/restaurant-006-user.mp3"}}, "restaurant-007": {"agent": {"seconds": 2.709, "voice": "am_michael", "text": "Any special occasion we should know about?", "bytes": 33120, "sha256": "db966c1859220fc60ca90d23841af6e35b30e2bf2e8b6fb500064978557eca24", "src": "audio/restaurant/restaurant-007-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_bella", "text": "It's our anniversary, actually.", "bytes": 25344, "sha256": "4ce649a7a446f19de31ff69594f337243d5d5644e671dd24be548ee494b06060", "src": "audio/restaurant/restaurant-007-user.mp3"}}, "restaurant-008": {"agent": {"seconds": 2.752, "voice": "am_michael", "text": "Wonderful! Would you like a quiet corner table?", "bytes": 33696, "sha256": "972877b0ca3a040b9202664f97f24f4343c8bf0d9c918eeb43bd77971bc1b995", "src": "audio/restaurant/restaurant-008-agent.mp3"}, "user": {"seconds": 1.685, "voice": "af_bella", "text": "That would be lovely, thanks.", "bytes": 21024, "sha256": "984b7c870875bbd597f10ba020d80ab1935e531bcc6d19b5a761a88ccb74c77a", "src": "audio/restaurant/restaurant-008-user.mp3"}}, "restaurant-009": {"agent": {"seconds": 3.456, "voice": "am_michael", "text": "We hold tables for fifteen minutes. Is that okay?", "bytes": 42048, "sha256": "e3aa2023e488b871c5d9df4115b8d358d127af34be2be04c1a95a3689b0bed66", "src": "audio/restaurant/restaurant-009-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Yes, we'll be on time.", "bytes": 20448, "sha256": "e0e48a2b7e75f3bbd5635a4cafa49b06aaf0609f6a0c114a4ecf1c18f7fa7d92", "src": "audio/restaurant/restaurant-009-user.mp3"}}, "restaurant-010": {"agent": {"seconds": 3.029, "voice": "am_michael", "text": "One last thing — any allergies we should note?", "bytes": 37152, "sha256": "65bfb70804730816a0d99812f0efb205811444ea7b972d2eb1103b477a76a894", "src": "audio/restaurant/restaurant-010-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "No allergies, thank you.", "bytes": 19584, "sha256": "c64791b623cc18f77760dfae52d7b148b7a0b6663629f62dfb861e8d0e2c9753", "src": "audio/restaurant/restaurant-010-user.mp3"}}, "restaurant-011": {"agent": {"seconds": 2.539, "voice": "am_michael", "text": "Perfect. Anything else I can do for you?", "bytes": 31104, "sha256": "c54b4bdb51bb1fb9348606d630f00f57dc643049c26a1b0040a67322816c260f", "src": "audio/restaurant/restaurant-011-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "No, that's everything. Thanks!", "bytes": 21312, "sha256": "2a759d5f1a684be9ec66ff9341ec31c0cd9cf195fdf8bf8f8ce91c39a913fe69", "src": "audio/restaurant/restaurant-011-user.mp3"}}, "restaurant-012": {"agent": {"seconds": 3.285, "voice": "am_michael", "text": "See you Friday at seven, Mr. Li. Goodbye.", "bytes": 40032, "sha256": "6a22b31a9ed35f434ba80c3409c056ccf1c152c134ed9f18902d53b0a69ddce7", "src": "audio/restaurant/restaurant-012-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Great, see you then. Bye!", "bytes": 20160, "sha256": "9584b9c4851a4e4335d66db9b66e7eed631db2916109a3a491f207451030e51f", "src": "audio/restaurant/restaurant-012-user.mp3"}}, "restaurant-013": {"agent": {"seconds": 4.117, "voice": "am_michael", "text": "Good evening! Welcome to Bella Roma. Do you have a reservation?", "bytes": 50112, "sha256": "14953a4a43b6cae98224f35a33f9cca2f4acbc78353b8d35a1b31872b078a3a2", "src": "audio/restaurant/restaurant-013-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_bella", "text": "Yes, a table for two under Li.", "bytes": 28224, "sha256": "9c296406e50a87cf1345701fd1122f51e5024313842021445f0a5ec6b05d2d79", "src": "audio/restaurant/restaurant-013-user.mp3"}}, "restaurant-014": {"agent": {"seconds": 3.968, "voice": "am_michael", "text": "Mr. Li, right this way. How was your evening so far?", "bytes": 48384, "sha256": "2016f10b20a9cf2c008cd2fd02ade44810a44aa6deca4ca45a77e260d824ea3f", "src": "audio/restaurant/restaurant-014-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Pretty good, thank you. And yours?", "bytes": 23904, "sha256": "f9e5345272ba4d806af6fb3e2bc60bd182f276946c39b474e531b392b7815ea0", "src": "audio/restaurant/restaurant-014-user.mp3"}}, "restaurant-015": {"agent": {"seconds": 3.136, "voice": "am_michael", "text": "Busy but fun. Here's your table by the window.", "bytes": 38304, "sha256": "caa7735eb6c872bfdd25eb2fd6bbd63b2947cb571ea76ae6539e9a6d1d06fcc7", "src": "audio/restaurant/restaurant-015-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "This is perfect. Thank you.", "bytes": 22464, "sha256": "18f257b3dffc1e977fd8a5eb3aa841303e9ae5267ac62d14bcf3b49480526178", "src": "audio/restaurant/restaurant-015-user.mp3"}}, "restaurant-016": {"agent": {"seconds": 1.941, "voice": "am_michael", "text": "Can I take your coats for you?", "bytes": 23904, "sha256": "dea27df5a06903f1f4ac255882a25d017f3e423dfaa28056992100ec8795f62c", "src": "audio/restaurant/restaurant-016-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_bella", "text": "Yes, please. Take our coats.", "bytes": 22176, "sha256": "c22166d6f60520e1a5e55c970273d828f0cdd29feb059bcb9aa6ee73d2b7a5d0", "src": "audio/restaurant/restaurant-016-user.mp3"}}, "restaurant-017": {"agent": {"seconds": 2.347, "voice": "am_michael", "text": "Your waiter will be with you in a moment.", "bytes": 28800, "sha256": "fd1b348984d9c3933828d82fb58f717be9b7d7a5e4ec6c2a6e96c7c8d9484227", "src": "audio/restaurant/restaurant-017-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "No rush. We're in no hurry.", "bytes": 22464, "sha256": "ddcfb6ffb17890ae332f4dd2f7984fb9175a5f286e7399f9eb711929716e995a", "src": "audio/restaurant/restaurant-017-user.mp3"}}, "restaurant-018": {"agent": {"seconds": 3.456, "voice": "am_michael", "text": "Here are the menus. The specials are on the back page.", "bytes": 42048, "sha256": "24730ab817c088a9cdccbf5373524baf0ae25ec2d63d1f4c3abd41d0786f9936", "src": "audio/restaurant/restaurant-018-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "Thanks. We'll study the menus.", "bytes": 24192, "sha256": "c71e976a2c42fb55f5fb8678fdb82edc33cdf0ecbe4cb726b4e1e11a39191672", "src": "audio/restaurant/restaurant-018-user.mp3"}}, "restaurant-019": {"agent": {"seconds": 3.029, "voice": "am_michael", "text": "Would you like still or sparkling water to start?", "bytes": 37152, "sha256": "3bad075970491b2a70e5f5d13b291ca43d8eb0eeb3d9f71290da594a69ec51bf", "src": "audio/restaurant/restaurant-019-agent.mp3"}, "user": {"seconds": 1.408, "voice": "af_bella", "text": "Still water would be great.", "bytes": 17568, "sha256": "71fbb086314dfb3df56ee2bc841c8a97e875a36c2e9a6252e4f864336f46d4f6", "src": "audio/restaurant/restaurant-019-user.mp3"}}, "restaurant-020": {"agent": {"seconds": 2.496, "voice": "am_michael", "text": "Of course. I'll bring that right away.", "bytes": 30528, "sha256": "1d0d618b19fe6f992a436d4b06a8222fd3b3e14417216e5a03a51881201074f7", "src": "audio/restaurant/restaurant-020-agent.mp3"}, "user": {"seconds": 1.109, "voice": "af_bella", "text": "Thank you very much.", "bytes": 14112, "sha256": "cfe6fceb2b8481d88bcc69b2a4f059e50ac60fae0a1b3ecc4e895aef5ddab978", "src": "audio/restaurant/restaurant-020-user.mp3"}}, "restaurant-021": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "Is this your first time dining with us?", "bytes": 28512, "sha256": "5026f677de51c21dc6e31f51087f16235c5fc4e4146ebca1936dbd40e00c284d", "src": "audio/restaurant/restaurant-021-agent.mp3"}, "user": {"seconds": 2.496, "voice": "af_bella", "text": "Yes, our friends recommended this place.", "bytes": 30528, "sha256": "64cf7981289cc2b97d8845bf82d9d666ca187c28c789dbbc93aacdb308422d83", "src": "audio/restaurant/restaurant-021-user.mp3"}}, "restaurant-022": {"agent": {"seconds": 3.157, "voice": "am_michael", "text": "Lovely! I hope you enjoy your anniversary dinner.", "bytes": 38592, "sha256": "059ca6f6fa92a09bb4488343ae5bcde660d1b957d0582d5198f342b3c001779a", "src": "audio/restaurant/restaurant-022-agent.mp3"}, "user": {"seconds": 2.325, "voice": "af_bella", "text": "Thank you. We're really looking forward to it.", "bytes": 28512, "sha256": "505288d07feabd6b769757250de5e150edead7f8c9fe7957df534de83e302841", "src": "audio/restaurant/restaurant-022-user.mp3"}}, "restaurant-023": {"agent": {"seconds": 3.776, "voice": "am_michael", "text": "Enjoy your evening, and just wave if you need anything.", "bytes": 46080, "sha256": "bde5e32e575030d03c536ceaf89d698a1120f61fa06d4a3f14fb97cd8263c16b", "src": "audio/restaurant/restaurant-023-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "Will do. I'll wave you down.", "bytes": 21312, "sha256": "568eba1f5aaab722d46138117dea42bb9232257490c405515cfe1a2c78697874", "src": "audio/restaurant/restaurant-023-user.mp3"}}, "restaurant-024": {"agent": {"seconds": 2.453, "voice": "am_michael", "text": "Here's your water. Enjoy your evening!", "bytes": 30240, "sha256": "06ee80f91b30d158d83cf69039c44b4aaffb8d68af9a775ca983e63026da385e", "src": "audio/restaurant/restaurant-024-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Perfect timing, thanks. Cheers!", "bytes": 25632, "sha256": "7ea9a92d3c5f49b90ffe8a34b73b5b6c65a8877cabdf4ffc1e44bebbc72be36f", "src": "audio/restaurant/restaurant-024-user.mp3"}}, "restaurant-025": {"agent": {"seconds": 3.349, "voice": "am_michael", "text": "Good evening, I'm Marco. Can I start you with drinks?", "bytes": 40896, "sha256": "d53d06cfccafd285efea00a708f4afb1b931389c6f15c221c8c2129efb79b642", "src": "audio/restaurant/restaurant-025-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_bella", "text": "Yes, I'd like a glass of red wine.", "bytes": 28800, "sha256": "4c55d5ad2e6f760f01bbd371338be59298485860f3c24124869a8d26623e06bf", "src": "audio/restaurant/restaurant-025-user.mp3"}}, "restaurant-026": {"agent": {"seconds": 3.136, "voice": "am_michael", "text": "Any preference? We have a lovely house Chianti.", "bytes": 38304, "sha256": "ac0bfeccdb7a75924fd73afbf3704ab4cfe95ade5607cd5ea069c7ed30ab81ef", "src": "audio/restaurant/restaurant-026-agent.mp3"}, "user": {"seconds": 1.493, "voice": "af_bella", "text": "The house red sounds good.", "bytes": 18720, "sha256": "c0a8ea5d6efdf43943fbf7a151519071703723262d1359db02bcfb33e4e191c9", "src": "audio/restaurant/restaurant-026-user.mp3"}}, "restaurant-027": {"agent": {"seconds": 2.496, "voice": "am_michael", "text": "And for you, madam? What would you like?", "bytes": 30528, "sha256": "f394cf78bc3aafce68233b81b4ca5c33f4c2f787368514d44cf91d231be74ad8", "src": "audio/restaurant/restaurant-027-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "I'll have a sparkling water with lime.", "bytes": 24192, "sha256": "02b6e0f358a73d340a70600f92049c8ce35d09cbc0dec39eae6d32cf70499b33", "src": "audio/restaurant/restaurant-027-user.mp3"}}, "restaurant-028": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "Would you like to see the cocktail menu?", "bytes": 28512, "sha256": "465c369b02025c36c256ee3913b3c1c27ace1c21e1b6ec03520f5f28cf17f535", "src": "audio/restaurant/restaurant-028-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_bella", "text": "Not tonight, thanks. Just the wine.", "bytes": 27072, "sha256": "3a7dcd1a6eb0c91af13f971ef0df045bbb46cda6dd74eec618c0f5bc417bf5a2", "src": "audio/restaurant/restaurant-028-user.mp3"}}, "restaurant-029": {"agent": {"seconds": 3.691, "voice": "am_michael", "text": "Red wine and sparkling water with lime. Anything else?", "bytes": 44928, "sha256": "20bef3fc0a43c94d18fd54d76959b481fb1a6b61b5fe247c8f628bc5f4d99fa3", "src": "audio/restaurant/restaurant-029-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "That's all for now, thanks.", "bytes": 19008, "sha256": "33dadd4f8cb0a5aebd5198fdca8c4248766885f02bbea1beeccfe55ac5d18ac4", "src": "audio/restaurant/restaurant-029-user.mp3"}}, "restaurant-030": {"agent": {"seconds": 1.856, "voice": "am_michael", "text": "Your drinks will be right out.", "bytes": 23040, "sha256": "ab2f968248e0ba034a8b9d7b519c8e1b61481c58e08883981b9195f1048adc81", "src": "audio/restaurant/restaurant-030-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Great. Could we have some bread too?", "bytes": 25632, "sha256": "b735fe75c2897f372fed7158cc2375507191c94b46a3c3fab63731aaa30e59da", "src": "audio/restaurant/restaurant-030-user.mp3"}}, "restaurant-031": {"agent": {"seconds": 2.731, "voice": "am_michael", "text": "Of course — our bread is baked fresh daily.", "bytes": 33408, "sha256": "8e1986d02dc246cdcac63ce48704edcc6c71bcf2089f173bc132a249c3b3d9ed", "src": "audio/restaurant/restaurant-031-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Wonderful. We love fresh bread.", "bytes": 23904, "sha256": "daa4d943bc806826985c2b5c96e1b081bb338da8842330c9576a5289502e5156", "src": "audio/restaurant/restaurant-031-user.mp3"}}, "restaurant-032": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "Here are your drinks. Enjoy them!", "bytes": 27072, "sha256": "32121001a1ea6f788af913677c0f586938064e392d3209366bfbb7b64570f8f2", "src": "audio/restaurant/restaurant-032-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_bella", "text": "Thank you. The drinks look great.", "bytes": 25056, "sha256": "af3b827f238c756e452b064007dd23b5e83409e122af39abbaf513c1d9cb63ae", "src": "audio/restaurant/restaurant-032-user.mp3"}}, "restaurant-033": {"agent": {"seconds": 2.944, "voice": "am_michael", "text": "Can I get you anything else while you decide?", "bytes": 36000, "sha256": "060e56f527ded1d24c9fb3cd069b70b5b68488a977b623824773e5dc20e0f0ad", "src": "audio/restaurant/restaurant-033-agent.mp3"}, "user": {"seconds": 1.493, "voice": "af_bella", "text": "We're still looking at the menu.", "bytes": 18720, "sha256": "b2a857b12290a439b4390115e4d162754348a5db1a4d8a15d53bef724c11d36f", "src": "audio/restaurant/restaurant-033-user.mp3"}}, "restaurant-034": {"agent": {"seconds": 3.093, "voice": "am_michael", "text": "Take your time. I'll check back in a few minutes.", "bytes": 37728, "sha256": "82af45b5aeaca80a402653dc7d1111ff4b0502be8baab693d14e9890c4f7ced4", "src": "audio/restaurant/restaurant-034-agent.mp3"}, "user": {"seconds": 1.6, "voice": "af_bella", "text": "Sounds good. Thank you.", "bytes": 19872, "sha256": "db2d73ef6c28f51374c200d65186b3695cdd9549a354870af5bedabfe8c7aa4b", "src": "audio/restaurant/restaurant-034-user.mp3"}}, "restaurant-035": {"agent": {"seconds": 2.645, "voice": "am_michael", "text": "How's the wine? Is it to your liking?", "bytes": 32544, "sha256": "a22e6437fa6edf5180d8461670454202404545191587da1905d4b75ffa8ad326", "src": "audio/restaurant/restaurant-035-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "It's excellent, really smooth.", "bytes": 21312, "sha256": "6a1b7c053f653bb048a3896f8e6069a6464999dbba239d5eb012f9053fdc607e", "src": "audio/restaurant/restaurant-035-user.mp3"}}, "restaurant-036": {"agent": {"seconds": 3.669, "voice": "am_michael", "text": "Glad to hear it. Ready to order, or a few more minutes?", "bytes": 44640, "sha256": "9e9969c8a3006c88093a14789f2582b1e40012813cd6b89a817601d3884c5f45", "src": "audio/restaurant/restaurant-036-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "Give us five more minutes, please.", "bytes": 21600, "sha256": "74ac5c418873709323f4f3ad4cc908593bbd833110c1c15e372ad28baaa279fb", "src": "audio/restaurant/restaurant-036-user.mp3"}}, "restaurant-037": {"agent": {"seconds": 2.517, "voice": "am_michael", "text": "Have you had a chance to look at the starters?", "bytes": 30816, "sha256": "46afa3d8ca88c0e3d37510301d3ab4924a6caad80712202d18eec3e4f4b52767", "src": "audio/restaurant/restaurant-037-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Yes, we'll start with the bruschetta.", "bytes": 25632, "sha256": "8ea576e3229348d6843c4e9c49516219b2ac496c4b6f4e32b1e60a9715ca48f9", "src": "audio/restaurant/restaurant-037-user.mp3"}}, "restaurant-038": {"agent": {"seconds": 3.627, "voice": "am_michael", "text": "Excellent choice. Would you like anything else to begin?", "bytes": 44352, "sha256": "e3c79cebbf076ce053e7ac1bd8681bf109a40e3c220010029741fc61ce4b34b8", "src": "audio/restaurant/restaurant-038-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_bella", "text": "The garlic mushrooms as well, please.", "bytes": 27072, "sha256": "18e26248a6546c053239863be2a55724e747ccfad143ca3dc76f4ea0d646f77e", "src": "audio/restaurant/restaurant-038-user.mp3"}}, "restaurant-039": {"agent": {"seconds": 2.709, "voice": "am_michael", "text": "Would you like those to share, or one each?", "bytes": 33120, "sha256": "856179880245b31c5d3f1d8cb9d6c1ab9a39ffe1966abe4985e60bea4b3b149b", "src": "audio/restaurant/restaurant-039-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "We'll share both, thanks.", "bytes": 18144, "sha256": "347a228ce2a9f2effdc1938da9186710d53bd018d04d56dadbd1952e3af74719", "src": "audio/restaurant/restaurant-039-user.mp3"}}, "restaurant-040": {"agent": {"seconds": 3.072, "voice": "am_michael", "text": "Lovely. And how about something to drink with those?", "bytes": 37440, "sha256": "9ac9f561dc7207a1c9b9b0e1209b605af91d60e1c5bf0f7c86b0e6bdd8057356", "src": "audio/restaurant/restaurant-040-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "We're fine with our drinks, thanks.", "bytes": 22464, "sha256": "490459b449c9ff6d3b8867fe60569150835dcde5f390b58fced88d8b3634c963", "src": "audio/restaurant/restaurant-040-user.mp3"}}, "restaurant-041": {"agent": {"seconds": 2.411, "voice": "am_michael", "text": "Would you like to hear today's soup special?", "bytes": 29664, "sha256": "ef2feb161571523f1cd606fddd8704fc88000360744b2b099f7f3223530c58f6", "src": "audio/restaurant/restaurant-041-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "Sure, what's the soup today?", "bytes": 19008, "sha256": "66f9303946bab1d94829c6aef78c5f17f2ce279d9c17e350f499d34c8d62d132", "src": "audio/restaurant/restaurant-041-user.mp3"}}, "restaurant-042": {"agent": {"seconds": 3.285, "voice": "am_michael", "text": "Creamy tomato basil, served with warm bread.", "bytes": 40032, "sha256": "d6249596df993a52d85bdc6d935c1d9a70d52feafbd5c9b1c2fa3c69940a6735", "src": "audio/restaurant/restaurant-042-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "Sounds nice, but we'll skip the soup.", "bytes": 26784, "sha256": "d1d75b4884dc33230c7b7183e8f9ad0c39f407dd96d39cfaaa97329c288df434", "src": "audio/restaurant/restaurant-042-user.mp3"}}, "restaurant-043": {"agent": {"seconds": 3.115, "voice": "am_michael", "text": "No problem. Should I bring the starters together?", "bytes": 38016, "sha256": "0e1b24fbb646053156fb7e8ee27aebeb080e55968520cc1b5ce7641e412daf75", "src": "audio/restaurant/restaurant-043-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_bella", "text": "Yes, together is perfect.", "bytes": 22176, "sha256": "1ea38568b983e60f7a9cbf5710f72da26d6928551f8ca84ecd5428b5a9bbbe68", "src": "audio/restaurant/restaurant-043-user.mp3"}}, "restaurant-044": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "I'll get those starters fired up right away.", "bytes": 31968, "sha256": "9002ee5f42c9541a3c2ae01071304858dafbf04f7be86fba76c887e86d3f2a5c", "src": "audio/restaurant/restaurant-044-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "Great, thank you very much.", "bytes": 21600, "sha256": "babcfc272d300230528cbabf04bf4b304e3a0975f7f608856c9e10c6393b4489", "src": "audio/restaurant/restaurant-044-user.mp3"}}, "restaurant-045": {"agent": {"seconds": 3.648, "voice": "am_michael", "text": "Here are your starters — bruschetta and garlic mushrooms.", "bytes": 44352, "sha256": "8b0d9ceb4c0f9e8c018b5011876a6eacea76f1ad531c2a98e43fda12dad7b795", "src": "audio/restaurant/restaurant-045-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "They look delicious. Thank you!", "bytes": 23904, "sha256": "ed8da2ad40ed600ee0aefb54526fc53b600dd2f6feac99d49a2bae57b53cff96", "src": "audio/restaurant/restaurant-045-user.mp3"}}, "restaurant-046": {"agent": {"seconds": 2.901, "voice": "am_michael", "text": "Enjoy! I'll be back to take your main orders.", "bytes": 35424, "sha256": "f745ee35803eb53f348a3b159a48293a8bb7e6e0d5ce75d74329371fef04abe2", "src": "audio/restaurant/restaurant-046-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_bella", "text": "Perfect. We'll keep looking at the menu.", "bytes": 28224, "sha256": "cb7f335df6226a9c3bdaeb2ea882eeac09b056cd62d8db4e88515f0bf6efd1b5", "src": "audio/restaurant/restaurant-046-user.mp3"}}, "restaurant-047": {"agent": {"seconds": 2.709, "voice": "am_michael", "text": "How are the starters? Everything good?", "bytes": 33120, "sha256": "2d1ba93bf73b1adc534abda46a301910be339ba0ef0c06a8625fd9182dd3cd84", "src": "audio/restaurant/restaurant-047-agent.mp3"}, "user": {"seconds": 2.688, "voice": "af_bella", "text": "Really tasty. The bruschetta is amazing.", "bytes": 32832, "sha256": "8fe71fe30637958d8c3b5e3da1a9716d18760ef369a6239c5041952460cf6f60", "src": "audio/restaurant/restaurant-047-user.mp3"}}, "restaurant-048": {"agent": {"seconds": 3.413, "voice": "am_michael", "text": "Wonderful. Ready for mains, or shall I give you time?", "bytes": 41760, "sha256": "01c01f4c794dc8ac64a7c803e499583fc810c1310312577191122b6a0dd765d6", "src": "audio/restaurant/restaurant-048-agent.mp3"}, "user": {"seconds": 1.131, "voice": "af_bella", "text": "We're ready when you are.", "bytes": 14400, "sha256": "22224162c811cb74aa3fc8306c375df0dbf0c67fa5bf4d2ae25edbd80f35b9d3", "src": "audio/restaurant/restaurant-048-user.mp3"}}, "restaurant-049": {"agent": {"seconds": 2.453, "voice": "am_michael", "text": "What can I get you for your main courses?", "bytes": 30240, "sha256": "6b910f0239024830d788db88ce44ed382e6640fb09a9d65b965063f8a9bf5582", "src": "audio/restaurant/restaurant-049-agent.mp3"}, "user": {"seconds": 2.24, "voice": "af_bella", "text": "I'll have the mushroom risotto, please.", "bytes": 27648, "sha256": "c2d61dd59abc601b7a25fe8c9225836e660d725815469a5dede3fee5bf3163a0", "src": "audio/restaurant/restaurant-049-user.mp3"}}, "restaurant-050": {"agent": {"seconds": 2.219, "voice": "am_michael", "text": "And for you, sir? What's your choice?", "bytes": 27360, "sha256": "418844becc936c192570ab400d18226603166e044b9fe535caf16ca5dc3dd16f", "src": "audio/restaurant/restaurant-050-agent.mp3"}, "user": {"seconds": 1.408, "voice": "af_bella", "text": "The grilled salmon for me.", "bytes": 17568, "sha256": "d9d2e0fdebc250f595c31b5fd1fa1672f6d07ac92be1f97a36264f4f987125e5", "src": "audio/restaurant/restaurant-050-user.mp3"}}, "restaurant-051": {"agent": {"seconds": 2.091, "voice": "am_michael", "text": "How would you like your salmon cooked?", "bytes": 25920, "sha256": "1e4420a83fa155e594d386b8685ecd1a8a1e16a8aeea422df917cad2a5ae51ad", "src": "audio/restaurant/restaurant-051-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "Medium, please. Not too dry.", "bytes": 24480, "sha256": "62e13604f1e986424c86611e9c21c2ae695da6e74df5768be08254e71fd7a088", "src": "audio/restaurant/restaurant-051-user.mp3"}}, "restaurant-052": {"agent": {"seconds": 2.133, "voice": "am_michael", "text": "Would you like any sides with that?", "bytes": 26208, "sha256": "541877fd3d28c7a86e1e00aca0d4d0a2d39bf0dcb3f613d229384fbe7bdbc935", "src": "audio/restaurant/restaurant-052-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "The roasted vegetables, please.", "bytes": 23904, "sha256": "119280f89ba5cbd5317fa5853824fc837094c674d760f07643aa55dd59fb693c", "src": "audio/restaurant/restaurant-052-user.mp3"}}, "restaurant-053": {"agent": {"seconds": 3.115, "voice": "am_michael", "text": "Anything for the lady — a side salad, perhaps?", "bytes": 38016, "sha256": "9af7c8a6d81d912caa07398d162caffb5c97caae6b0c2870902d10346842c974", "src": "audio/restaurant/restaurant-053-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "A small green salad, please.", "bytes": 22752, "sha256": "e0f4368b4f1fa141feb89d4ada78dc919d2ba7cafda9a86da78df746086837bc", "src": "audio/restaurant/restaurant-053-user.mp3"}}, "restaurant-054": {"agent": {"seconds": 3.029, "voice": "am_michael", "text": "Dressing on the salad — oil and vinegar okay?", "bytes": 37152, "sha256": "e5f1af58ace05122c045ccf4e54939de889584f775b76f150dc664c970edb96e", "src": "audio/restaurant/restaurant-054-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_bella", "text": "Just olive oil, please.", "bytes": 20736, "sha256": "1e2424cf71b0aee23ea1ec9e218fb08edaf70da048b24aee4cb9cdefeff89231", "src": "audio/restaurant/restaurant-054-user.mp3"}}, "restaurant-055": {"agent": {"seconds": 3.84, "voice": "am_michael", "text": "So: risotto, salmon, vegetables, and a green salad.", "bytes": 46656, "sha256": "526e8fa4681e86d3ee8eaf5c3fdf48470dcb779df28ac11cabb4b6a7776a4321", "src": "audio/restaurant/restaurant-055-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "That's exactly right. Thanks!", "bytes": 23616, "sha256": "37f445a6e2296ac15ff1f418a7edd4b5a20dbe20e10ef6a640a4bb0b0e7efb77", "src": "audio/restaurant/restaurant-055-user.mp3"}}, "restaurant-056": {"agent": {"seconds": 2.261, "voice": "am_michael", "text": "I'll fire those mains right away.", "bytes": 27936, "sha256": "0e316d1d04d25064fdaaef4e2244991e60c6720a9effb9d9c1c8fc9dca1f17fb", "src": "audio/restaurant/restaurant-056-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_bella", "text": "Wonderful. We're looking forward to it.", "bytes": 26496, "sha256": "1b651f72ee0035351b7a336b78cfbeb38e1acb0aa8e204b7cee7f3b8c84901b0", "src": "audio/restaurant/restaurant-056-user.mp3"}}, "restaurant-057": {"agent": {"seconds": 3.221, "voice": "am_michael", "text": "Your mains are on the way — about fifteen minutes.", "bytes": 39456, "sha256": "9dba7d8233661039fb1be2e055627182ae4780e0784bf7a97a3d4d2b644cb136", "src": "audio/restaurant/restaurant-057-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "No rush at all. Thank you.", "bytes": 21600, "sha256": "56ec87d5682cc4754a108e1917e37f1229af866873e913deb974dba74d8ea651", "src": "audio/restaurant/restaurant-057-user.mp3"}}, "restaurant-058": {"agent": {"seconds": 2.304, "voice": "am_michael", "text": "Can I top up your water while you wait?", "bytes": 28224, "sha256": "c6b61dc3c72455453c1153a66ca24eacf2382c2229b4434323309b9f5e99de43", "src": "audio/restaurant/restaurant-058-agent.mp3"}, "user": {"seconds": 2.389, "voice": "af_bella", "text": "Yes, please. More water would be lovely.", "bytes": 29376, "sha256": "e82dbbab61d5be959c5ab83b6a2fd6ebc4edcd88f5b7030b51c30d29f1d779e8", "src": "audio/restaurant/restaurant-058-user.mp3"}}, "restaurant-059": {"agent": {"seconds": 2.837, "voice": "am_michael", "text": "Here are your main courses. Enjoy your meal!", "bytes": 34848, "sha256": "cf4153f45cae7d589e0d6c690b6bd41a9f5960ee3e4f07c2e5c79a35377821d9", "src": "audio/restaurant/restaurant-059-agent.mp3"}, "user": {"seconds": 2.155, "voice": "af_bella", "text": "Thank you. Everything looks wonderful.", "bytes": 26496, "sha256": "11576d7a35157ff9dc9f8c405943613cc91963585b381c475d681fe99c48fbc9", "src": "audio/restaurant/restaurant-059-user.mp3"}}, "restaurant-060": {"agent": {"seconds": 1.941, "voice": "am_michael", "text": "I'll check back in a few minutes.", "bytes": 23904, "sha256": "ac7f68299f3ab055d1464df34f68b77fac721fe973645f3ecb3a08722b7c92f1", "src": "audio/restaurant/restaurant-060-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_bella", "text": "Great, thanks so much, Marco.", "bytes": 25344, "sha256": "750b85d688bb4c19ce8403ae56a486c9f76c89d30a765adabf829ab1026048cc", "src": "audio/restaurant/restaurant-060-user.mp3"}}, "restaurant-061": {"agent": {"seconds": 3.669, "voice": "am_michael", "text": "Before I go — any dietary requirements I should note?", "bytes": 44640, "sha256": "3b0183e5ce432efd84255411f89acc8975a79408fa0b5f8ab6c980429292cbde", "src": "audio/restaurant/restaurant-061-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_bella", "text": "Actually, I'm a vegetarian.", "bytes": 24768, "sha256": "9a9d4a4d3728e2819890c5635d1a02925c1022ac17fd00597418eb521a6106a4", "src": "audio/restaurant/restaurant-061-user.mp3"}}, "restaurant-062": {"agent": {"seconds": 3.797, "voice": "am_michael", "text": "No problem. Several dishes can be made vegetarian.", "bytes": 46368, "sha256": "c7f942e30e17c9da38f654fb252d22e343dd34062bc88f07b20b82556649314a", "src": "audio/restaurant/restaurant-062-agent.mp3"}, "user": {"seconds": 2.112, "voice": "af_bella", "text": "Is the risotto made with chicken stock?", "bytes": 25920, "sha256": "265ab7161467d79d8b71c04758976ccf59441da7d3f634866bcf7e322f1d2534", "src": "audio/restaurant/restaurant-062-user.mp3"}}, "restaurant-063": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "Good question — let me check with the kitchen.", "bytes": 31968, "sha256": "770ead884e86713a448bcabae48a588923a92211064add6db26998fd390f2fb6", "src": "audio/restaurant/restaurant-063-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "Thanks. I'd really appreciate that.", "bytes": 26784, "sha256": "bcfd0c1f6ee0942c238bb27921ca8bf151cee89a4264769fab98434fee7f585e", "src": "audio/restaurant/restaurant-063-user.mp3"}}, "restaurant-064": {"agent": {"seconds": 3.371, "voice": "am_michael", "text": "Good news — our risotto uses vegetable stock.", "bytes": 41184, "sha256": "9b529829a6df8d055ed743109cfecf95d02cfd1cacddc4ddd41e6a8c754cdf1a", "src": "audio/restaurant/restaurant-064-agent.mp3"}, "user": {"seconds": 1.6, "voice": "af_bella", "text": "Perfect. That's a relief!", "bytes": 19872, "sha256": "e1dd2343ffe66dfd477338c7693d7a2cd5b7487ed64376b12e6f2b567951a1a5", "src": "audio/restaurant/restaurant-064-user.mp3"}}, "restaurant-065": {"agent": {"seconds": 3.093, "voice": "am_michael", "text": "And you, sir — any allergies I should know about?", "bytes": 37728, "sha256": "38759964ebab3256a85422a15d5b7855b6c3180ebedb8defe21dae70d79bcd5b", "src": "audio/restaurant/restaurant-065-agent.mp3"}, "user": {"seconds": 1.408, "voice": "af_bella", "text": "I'm allergic to peanuts.", "bytes": 17568, "sha256": "99202dff4c5f13d68fc9b5cd6f73ad672ba11263391a6f1ed7b00c5ce2ca150f", "src": "audio/restaurant/restaurant-065-user.mp3"}}, "restaurant-066": {"agent": {"seconds": 2.944, "voice": "am_michael", "text": "Thank you for telling me. I'll alert the kitchen.", "bytes": 36000, "sha256": "9d0fab04565865b3c93560fbfcc6358c4877d9e00d999e454e826e8efaef985e", "src": "audio/restaurant/restaurant-066-agent.mp3"}, "user": {"seconds": 2.496, "voice": "af_bella", "text": "It's quite serious, so please be careful.", "bytes": 30528, "sha256": "c9a1edba5fceb678b78f2e2a25832c94f804749e51e61109c4ef08f4e2df41ee", "src": "audio/restaurant/restaurant-066-user.mp3"}}, "restaurant-067": {"agent": {"seconds": 3.605, "voice": "am_michael", "text": "Absolutely. We'll take every precaution in the kitchen.", "bytes": 44064, "sha256": "2a25a8efe0f872c03ced4801b1404e068a5eb02a3e3fd27dbe549a31acfe41f8", "src": "audio/restaurant/restaurant-067-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_bella", "text": "Thank you. That means a lot.", "bytes": 22176, "sha256": "2ed2c6d2be209504b2b535bc18bc7a2390a179e992af79c970fb4a8754e1b4d7", "src": "audio/restaurant/restaurant-067-user.mp3"}}, "restaurant-068": {"agent": {"seconds": 3.264, "voice": "am_michael", "text": "The salmon is cooked separately — no nuts involved.", "bytes": 39744, "sha256": "5caeca7bb5f7fedc631d01e315089a34844cb687be2289cd406ca861a08dc78f", "src": "audio/restaurant/restaurant-068-agent.mp3"}, "user": {"seconds": 1.515, "voice": "af_bella", "text": "Good to know. Thank you.", "bytes": 19008, "sha256": "31b4b1fc55d10a83959f8616746b5409bbb8e3a338c931dfa0f9d900f6136e8e", "src": "audio/restaurant/restaurant-068-user.mp3"}}, "restaurant-069": {"agent": {"seconds": 2.923, "voice": "am_michael", "text": "Would you like the allergen menu to double-check?", "bytes": 35712, "sha256": "7085d96c549ed3233086bc7399afbc30c1c288a59dfe1c5d79215198696bad30", "src": "audio/restaurant/restaurant-069-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_bella", "text": "Yes, please. Better safe than sorry.", "bytes": 28224, "sha256": "b596d361994ed1f337abfb4d33682c5a336380776225eb92ac4eb180a16b7263", "src": "audio/restaurant/restaurant-069-user.mp3"}}, "restaurant-070": {"agent": {"seconds": 2.347, "voice": "am_michael", "text": "Here you go. Take your time reading it.", "bytes": 28800, "sha256": "070130b67d5bbfdf8b58dbe1af81a8f74253154f157118d70d3814dee001d0b1", "src": "audio/restaurant/restaurant-070-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "Thanks. This is very helpful.", "bytes": 24192, "sha256": "5e1db6ec72c1a2b1ba6204f47d8cadf48ada9d15c47469864e07d5e197e8a675", "src": "audio/restaurant/restaurant-070-user.mp3"}}, "restaurant-071": {"agent": {"seconds": 2.795, "voice": "am_michael", "text": "All set? Can I confirm your order as is?", "bytes": 34272, "sha256": "c53716215e74ae2ed8c5c3bdcbd7956225d3df635d5148bd65758dfcb43e05bc", "src": "audio/restaurant/restaurant-071-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "Yes, everything looks good.", "bytes": 21312, "sha256": "5ac187df41705775eea50e09f944315c36df358c8b773198b9e9464f012b056c", "src": "audio/restaurant/restaurant-071-user.mp3"}}, "restaurant-072": {"agent": {"seconds": 2.624, "voice": "am_michael", "text": "Wonderful. The kitchen has all the notes.", "bytes": 32256, "sha256": "5794b8063ca7d835286c418194e31148a39ff682073b81fd0202afe959810b42", "src": "audio/restaurant/restaurant-072-agent.mp3"}, "user": {"seconds": 1.749, "voice": "af_bella", "text": "Great. Thanks for checking.", "bytes": 21600, "sha256": "5741ba8ac904eb447fd8143bc5a1bb4938f9feb3320d2e93be56981903fe8b07", "src": "audio/restaurant/restaurant-072-user.mp3"}}, "restaurant-073": {"agent": {"seconds": 2.88, "voice": "am_michael", "text": "Is everything alright with your meal so far?", "bytes": 35136, "sha256": "13721bc39014efc64402187d938e47e096940e51b165603d82da7f60114814c2", "src": "audio/restaurant/restaurant-073-agent.mp3"}, "user": {"seconds": 2.261, "voice": "af_bella", "text": "Yes, lovely. Could I ask something?", "bytes": 27936, "sha256": "e99f9510d007cf52cc096c91db5db55b469bfa75c7a8f358cc439abdf7738f7f", "src": "audio/restaurant/restaurant-073-user.mp3"}}, "restaurant-074": {"agent": {"seconds": 2.261, "voice": "am_michael", "text": "Of course! What would you like to know?", "bytes": 27936, "sha256": "48f6a1a26d53c221e8c95ed4cf97e9321b95797ec8a6178f6ab36c6ce5e5ec22", "src": "audio/restaurant/restaurant-074-agent.mp3"}, "user": {"seconds": 1.707, "voice": "af_bella", "text": "What wine goes well with salmon?", "bytes": 21312, "sha256": "f00c1f89ec5527a3a585f5b0a60f0220a90f69f0b7a02857786ea832c1141b3a", "src": "audio/restaurant/restaurant-074-user.mp3"}}, "restaurant-075": {"agent": {"seconds": 3.179, "voice": "am_michael", "text": "A crisp white — our Pinot Grigio is perfect.", "bytes": 38880, "sha256": "a1f338cf6081c1a369c9802733e50a94ddcbde7977744f13db83602df2add2ea", "src": "audio/restaurant/restaurant-075-agent.mp3"}, "user": {"seconds": 1.515, "voice": "af_bella", "text": "Could we try a glass each?", "bytes": 19008, "sha256": "1ba8aa7a414eed197fd98aa3196eee13fee32e5d3f302d141d1882c77d0bb7fb", "src": "audio/restaurant/restaurant-075-user.mp3"}}, "restaurant-076": {"agent": {"seconds": 2.389, "voice": "am_michael", "text": "Certainly. I'll bring those right over.", "bytes": 29376, "sha256": "67122dbb5e4a4a6a1d7e0c18f0b838cd7f6665758590ebdd297369a973837599", "src": "audio/restaurant/restaurant-076-agent.mp3"}, "user": {"seconds": 1.792, "voice": "af_bella", "text": "Thank you. You're very helpful.", "bytes": 22176, "sha256": "e214136d7e9aaf0e4a838e1228b540f8c30fb9c39c71afc65237ba75cadac100", "src": "audio/restaurant/restaurant-076-user.mp3"}}, "restaurant-077": {"agent": {"seconds": 2.923, "voice": "am_michael", "text": "How is everything tasting so far tonight?", "bytes": 35712, "sha256": "1e085034f4135b84b8318806b3e9a4dae28f2fadc9e9c1702d72f89c05245eba", "src": "audio/restaurant/restaurant-077-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "Delicious. What's in this sauce?", "bytes": 23616, "sha256": "3f2a0c03a6e14245df07809bae985e4f770c252b4cc2e3d35594996b1b27f138", "src": "audio/restaurant/restaurant-077-user.mp3"}}, "restaurant-078": {"agent": {"seconds": 2.688, "voice": "am_michael", "text": "It's a lemon butter sauce with fresh herbs.", "bytes": 32832, "sha256": "e227a35930c528ee51af9185590494b0300bb1415da4f14e8274f72ccc306c48", "src": "audio/restaurant/restaurant-078-agent.mp3"}, "user": {"seconds": 2.56, "voice": "af_bella", "text": "It's fantastic. I'll have to try making it.", "bytes": 31392, "sha256": "ad68caacaf5a799e623a2d2c04eb12f7982be7cc2e146ce243e767fd0bc268c3", "src": "audio/restaurant/restaurant-078-user.mp3"}}, "restaurant-079": {"agent": {"seconds": 2.56, "voice": "am_michael", "text": "Can I get you anything else at the moment?", "bytes": 31392, "sha256": "83d5e0e125b38bd462f9f5a535cbddd3e52649062356840cb7eb37f21ae0df88", "src": "audio/restaurant/restaurant-079-agent.mp3"}, "user": {"seconds": 1.899, "voice": "af_bella", "text": "Could we have some more bread, please?", "bytes": 23616, "sha256": "0c9da34a786fbaeaaec28e12246cd457ac7be295df2d03de9e1a71d43a4e734d", "src": "audio/restaurant/restaurant-079-user.mp3"}}, "restaurant-080": {"agent": {"seconds": 2.347, "voice": "am_michael", "text": "Right away. White or whole wheat?", "bytes": 28800, "sha256": "c4239075935ecb11d7c244e0739ac03d9d8814121188e2127a6d8389f672b8a0", "src": "audio/restaurant/restaurant-080-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "White, please. The warm kind.", "bytes": 23616, "sha256": "007d562d5864e733ec10acaea0de6dbf4bdcc42fa09929b12c84759bff7e2489", "src": "audio/restaurant/restaurant-080-user.mp3"}}, "restaurant-081": {"agent": {"seconds": 2.901, "voice": "am_michael", "text": "Just so you know, the kitchen closes at ten.", "bytes": 35424, "sha256": "f89b5da389776f68b9c9db6bc09da3bf6edae988a42dc6c974d36eb364d47f34", "src": "audio/restaurant/restaurant-081-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "Good to know. We're in no rush.", "bytes": 22464, "sha256": "e9dd7cf32b0d52877b2f3e892b9da00589c564f7c4a1beb48805315f39377872", "src": "audio/restaurant/restaurant-081-user.mp3"}}, "restaurant-082": {"agent": {"seconds": 2.581, "voice": "am_michael", "text": "Would you like a peek at the dessert menu?", "bytes": 31680, "sha256": "a256a5c028dd7068f1b69f294aa6dc6f27204fdec2d6e3c46d573f9b01ae919d", "src": "audio/restaurant/restaurant-082-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "Yes, please. We love dessert.", "bytes": 24192, "sha256": "258018e61ef731fe189b2aaeba0d1cc079fabfc0dcf3b282ce6d569140cfda49", "src": "audio/restaurant/restaurant-082-user.mp3"}}, "restaurant-083": {"agent": {"seconds": 2.773, "voice": "am_michael", "text": "Here it is. The tiramisu is famous here.", "bytes": 33984, "sha256": "e7c09981208413ca6f9693341a3312238d9455e1cb9ca2c9bd40466adf88d1ba", "src": "audio/restaurant/restaurant-083-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "We'll decide after the mains.", "bytes": 20448, "sha256": "4d628d969d1e8985fb5565355496bb836af249e5ff0d67d21ca9359a00917ff8", "src": "audio/restaurant/restaurant-083-user.mp3"}}, "restaurant-084": {"agent": {"seconds": 2.731, "voice": "am_michael", "text": "Take your time. I'm here if you need me.", "bytes": 33408, "sha256": "9d4f09bb7076fa3fefce5e92caa50959f71e3a9b7826fcca9c1ac5a4bc89f106", "src": "audio/restaurant/restaurant-084-agent.mp3"}, "user": {"seconds": 1.664, "voice": "af_bella", "text": "Thanks. You've been wonderful.", "bytes": 20736, "sha256": "0fa06a5f0d954e3075b7b75c4258bbc6163781db5832a5640a6830346482cc13", "src": "audio/restaurant/restaurant-084-user.mp3"}}, "restaurant-085": {"agent": {"seconds": 2.731, "voice": "am_michael", "text": "How is everything? Enjoying your mains?", "bytes": 33408, "sha256": "e23cd1e4b32472b676b50ccf3a57a2f08045305df21c2e4293066fd2ac00fcc2", "src": "audio/restaurant/restaurant-085-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_bella", "text": "Mostly, but my salmon is quite dry.", "bytes": 28224, "sha256": "69e0f0ff2d9944f500c9e5bdb2b6b0a7a8dd8c8390a8db8d06dba16f246daef9", "src": "audio/restaurant/restaurant-085-user.mp3"}}, "restaurant-086": {"agent": {"seconds": 2.496, "voice": "am_michael", "text": "Oh no, I'm so sorry to hear that.", "bytes": 30528, "sha256": "38710d9eeb7bfda1e9ea0862edd453f8085f0d892250030e42ad9cbf3e044c85", "src": "audio/restaurant/restaurant-086-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "It's okay. These things happen.", "bytes": 24192, "sha256": "cf5ea9e9cb22f9b476c9009179352993c5157360cc1e670a3b5be087214b052f", "src": "audio/restaurant/restaurant-086-user.mp3"}}, "restaurant-087": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "Would you like me to have it remade?", "bytes": 25344, "sha256": "20c0edb63183410cce1978347c5b623bcdb49843f196b53d1cfe77392edd22ea", "src": "audio/restaurant/restaurant-087-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "Could you have it remade, please?", "bytes": 21312, "sha256": "7e433dffb925d58ed773cebe161438ea660592cccc4cff1baba884674c6a723d", "src": "audio/restaurant/restaurant-087-user.mp3"}}, "restaurant-088": {"agent": {"seconds": 3.413, "voice": "am_michael", "text": "Of course. Medium, and nice and moist this time.", "bytes": 41760, "sha256": "7ab04946f2e58e67362f2a2e91fc39e6c85512b3c7177c6b7b7f0ddfea52ce78", "src": "audio/restaurant/restaurant-088-agent.mp3"}, "user": {"seconds": 2.389, "voice": "af_bella", "text": "Exactly. Thank you for understanding.", "bytes": 29376, "sha256": "e9cb0027151c7855c069318396cb8a08aa51a882e951a2dd8d14d219c7fb34ff", "src": "audio/restaurant/restaurant-088-user.mp3"}}, "restaurant-089": {"agent": {"seconds": 2.453, "voice": "am_michael", "text": "I'll take this back and rush a fresh one.", "bytes": 30240, "sha256": "e890e7d11afc8740b5aae6db1ca2cd644cd10740aee7c5349e9f514a31b0b711", "src": "audio/restaurant/restaurant-089-agent.mp3"}, "user": {"seconds": 1.6, "voice": "af_bella", "text": "No hurry. I'll wait.", "bytes": 19872, "sha256": "36c3657473bc5ec3671e49983022ed1d488d24b312e11d97eee9266fb5f53012", "src": "audio/restaurant/restaurant-089-user.mp3"}}, "restaurant-090": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "Can I bring you something while you wait?", "bytes": 27648, "sha256": "15a9895cb6cb57098c7dd71292d97b981a5d7c24f2992f74e5f0d8fc71fb67de", "src": "audio/restaurant/restaurant-090-agent.mp3"}, "user": {"seconds": 1.536, "voice": "af_bella", "text": "Maybe a small side salad.", "bytes": 19008, "sha256": "7d3b6d7754a94b83d1fdb9a59d099c5c65b80fca31014c3f33dee3416d8f517c", "src": "audio/restaurant/restaurant-090-user.mp3"}}, "restaurant-091": {"agent": {"seconds": 3.413, "voice": "am_michael", "text": "On the house, of course. My apologies again.", "bytes": 41760, "sha256": "9ffc592fbc6da3559d9f157a3febe628527be2769b554f8418b887b463e8343d", "src": "audio/restaurant/restaurant-091-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "That's very kind. Thank you.", "bytes": 23328, "sha256": "e2709e3c2d2eccd9acf2280a2832af422b22064a105556e7de81d5463cce1ece", "src": "audio/restaurant/restaurant-091-user.mp3"}}, "restaurant-092": {"agent": {"seconds": 2.795, "voice": "am_michael", "text": "Here's your fresh salmon. I hope it's better.", "bytes": 34272, "sha256": "1b865f7ec6d3e8cb77522be17095cc017c2712c7ab429434abc6fcf505bf647a", "src": "audio/restaurant/restaurant-092-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "Much better. Thank you, Marco.", "bytes": 24480, "sha256": "f229bf36f204823ffb3f2fc8653959b8c3b6d54c627df8cc2491830d845bc40a", "src": "audio/restaurant/restaurant-092-user.mp3"}}, "restaurant-093": {"agent": {"seconds": 3.712, "voice": "am_michael", "text": "I'm glad. Please let me know if anything else comes up.", "bytes": 45216, "sha256": "256a46dce430565b87613bbd003381b465d7cabc47c9b0d458301037773429fc", "src": "audio/restaurant/restaurant-093-agent.mp3"}, "user": {"seconds": 1.515, "voice": "af_bella", "text": "Will do. Thanks again.", "bytes": 19008, "sha256": "9695cd861f4925c8418d472df1905989fa1597980e850674f2c55e7e0c9d73bc", "src": "audio/restaurant/restaurant-093-user.mp3"}}, "restaurant-094": {"agent": {"seconds": 2.859, "voice": "am_michael", "text": "Is there anything else I can fix for you?", "bytes": 35136, "sha256": "d4fd762b6e6e27fb0fae015796d9ef37650db1a74e605974ef8ae719832c46f8", "src": "audio/restaurant/restaurant-094-agent.mp3"}, "user": {"seconds": 1.92, "voice": "af_bella", "text": "No, everything's perfect now.", "bytes": 23616, "sha256": "dda1bafe644dfc3293346b992842cbfeb55e5fa5f98f4c1f090ff6b27d827e50", "src": "audio/restaurant/restaurant-094-user.mp3"}}, "restaurant-095": {"agent": {"seconds": 2.539, "voice": "am_michael", "text": "Wonderful. Enjoy the rest of your meal.", "bytes": 31104, "sha256": "0c65cfaa3e22b4e91aac830605b9ca5d0fb9a7c4dddf71779a3c09a1d31ef7f9", "src": "audio/restaurant/restaurant-095-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_bella", "text": "We will. Thanks for sorting it out.", "bytes": 27072, "sha256": "5d305c5de34b8612ea16e32954058ca68dc76363d417eec2f43bfebc3fe43863", "src": "audio/restaurant/restaurant-095-user.mp3"}}, "restaurant-096": {"agent": {"seconds": 2.752, "voice": "am_michael", "text": "It's my pleasure. That's what I'm here for.", "bytes": 33696, "sha256": "f9a020492d13a909c0b5ebae8bb7f1ffe725f7d9b0c9527777b0323f7456799a", "src": "audio/restaurant/restaurant-096-agent.mp3"}, "user": {"seconds": 1.557, "voice": "af_bella", "text": "You handled that really well.", "bytes": 19296, "sha256": "e02aef328ef365e7851e39a48082eec78e7373773a48c14a4f17bbd7ba89872d", "src": "audio/restaurant/restaurant-096-user.mp3"}}, "restaurant-097": {"agent": {"seconds": 2.539, "voice": "am_michael", "text": "Would you like to see the dessert menu now?", "bytes": 31104, "sha256": "e8f40d1184af173cd0d2fb7331ba442d34dbe7d68e963ac8faa890b4fc44b6b9", "src": "audio/restaurant/restaurant-097-agent.mp3"}, "user": {"seconds": 2.432, "voice": "af_bella", "text": "Yes, please. What's the best dessert here?", "bytes": 29952, "sha256": "99cfd50849a7487b0a4983d02fd2605480836bed9152678243a9488a7f7a3cc4", "src": "audio/restaurant/restaurant-097-user.mp3"}}, "restaurant-098": {"agent": {"seconds": 3.285, "voice": "am_michael", "text": "The tiramisu is our signature — very popular.", "bytes": 40032, "sha256": "55fbbcefa23aa4da057f983b2e373c64fe5c9892ac0af16abf4f1559c8af5007", "src": "audio/restaurant/restaurant-098-agent.mp3"}, "user": {"seconds": 2.133, "voice": "af_bella", "text": "One tiramisu, please. To share.", "bytes": 26208, "sha256": "bc04012777f534aaa1233f5c9a224ca5db5b330e14e9587fed089d4802bf97d1", "src": "audio/restaurant/restaurant-098-user.mp3"}}, "restaurant-099": {"agent": {"seconds": 2.347, "voice": "am_michael", "text": "And for you, madam? Something sweet?", "bytes": 28800, "sha256": "d9198a0442a9797da1bf14011b0ebfb51698755f576d76ee363f650faee56c97", "src": "audio/restaurant/restaurant-099-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "The chocolate cake sounds tempting.", "bytes": 23904, "sha256": "88940ce9906eb13bdb0f8d4851a2a9de2365f36507e5d3301d5a2ac42f904f66", "src": "audio/restaurant/restaurant-099-user.mp3"}}, "restaurant-100": {"agent": {"seconds": 2.837, "voice": "am_michael", "text": "Two desserts. Any coffee to go with those?", "bytes": 34848, "sha256": "d2caf3588ef93b7c0323d6ff9abbd66609d383504b9ebc809613bc88e549b1df", "src": "audio/restaurant/restaurant-100-agent.mp3"}, "user": {"seconds": 1.451, "voice": "af_bella", "text": "I'd love a cappuccino.", "bytes": 18144, "sha256": "2b4b53b715b5e5bffb83a4bf857ad58c1072ef1f96dac042af7202e6e63cf70a", "src": "audio/restaurant/restaurant-100-user.mp3"}}, "restaurant-101": {"agent": {"seconds": 2.667, "voice": "am_michael", "text": "Would you like regular or decaf coffee?", "bytes": 32832, "sha256": "807956ad9c11737662e961611f8a71a9bb5e11c69483c664673c813897079e0a", "src": "audio/restaurant/restaurant-101-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_bella", "text": "Decaf, please. It's quite late.", "bytes": 25056, "sha256": "947922aba73fae40100539bc4fc24306c5d28396451885d31e73d47ce236799b", "src": "audio/restaurant/restaurant-101-user.mp3"}}, "restaurant-102": {"agent": {"seconds": 2.475, "voice": "am_michael", "text": "And for you, sir? Anything to drink?", "bytes": 30528, "sha256": "13378425d41f474f37e69ad871a1129ccb6d40639f0cb39ab0f277e8821d37a1", "src": "audio/restaurant/restaurant-102-agent.mp3"}, "user": {"seconds": 1.493, "voice": "af_bella", "text": "Just an espresso for me.", "bytes": 18720, "sha256": "8c27e12793068390025d7189496646123539ae50756b3fb7b2c88d2d1a8ee3ac", "src": "audio/restaurant/restaurant-102-user.mp3"}}, "restaurant-103": {"agent": {"seconds": 3.925, "voice": "am_michael", "text": "Tiramisu, chocolate cake, cappuccino, espresso. Correct?", "bytes": 47808, "sha256": "32d8a6220080c7239b9fffefcc5e0cda2663e323511889229ce93cdc346475ed", "src": "audio/restaurant/restaurant-103-agent.mp3"}, "user": {"seconds": 1.472, "voice": "af_bella", "text": "Spot on. Thank you.", "bytes": 18432, "sha256": "811ca7310a8ad8cd02b816153ec568e3ca7848327ff3a62884d41c6a772d32a6", "src": "audio/restaurant/restaurant-103-user.mp3"}}, "restaurant-104": {"agent": {"seconds": 2.581, "voice": "am_michael", "text": "I'll bring those desserts right out for you.", "bytes": 31680, "sha256": "f7b5372b26dd8487002590bcf5acbd0e28c6029bfad9a243255ecb49a1af3e3b", "src": "audio/restaurant/restaurant-104-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Lovely. We can't wait.", "bytes": 20160, "sha256": "8f52bd678f7615eb16060fffcaad694b1a95c9cc7ae394965de7790024175f36", "src": "audio/restaurant/restaurant-104-user.mp3"}}, "restaurant-105": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "Here are your desserts. Please enjoy them!", "bytes": 31968, "sha256": "96f700836c692b468950cb3d319f402e4db443951dcfbf2f579278b2a5ec3eff", "src": "audio/restaurant/restaurant-105-agent.mp3"}, "user": {"seconds": 1.856, "voice": "af_bella", "text": "They look incredible. Thank you!", "bytes": 23040, "sha256": "ce5cbb20814f0a6900b6df25d6a13a8cb93c9b24cae40caa3b5364560f13a46a", "src": "audio/restaurant/restaurant-105-user.mp3"}}, "restaurant-106": {"agent": {"seconds": 2.56, "voice": "am_michael", "text": "How's the tiramisu? Worth the hype?", "bytes": 31392, "sha256": "65a160d6ce1dbb400bee93b16edae471828fc2c104a1d2037f6505e800abc3e7", "src": "audio/restaurant/restaurant-106-agent.mp3"}, "user": {"seconds": 2.347, "voice": "af_bella", "text": "Absolutely divine. Best I've had.", "bytes": 28800, "sha256": "7ef8f970625143c51854d89d2037deea3b0859c66eb7e22c32b938f4de85259c", "src": "audio/restaurant/restaurant-106-user.mp3"}}, "restaurant-107": {"agent": {"seconds": 2.709, "voice": "am_michael", "text": "I'll tell the pastry chef — she'll be thrilled.", "bytes": 33120, "sha256": "45cfe145ecdbc3d83f64df4b05f6a2665306b5a4ad7144cd5a0964f69b35522d", "src": "audio/restaurant/restaurant-107-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "Please do. It's outstanding.", "bytes": 23328, "sha256": "a53aab82bd5c9a67593d65c69167313b4f9f88653838068564d2e1e592fe0487", "src": "audio/restaurant/restaurant-107-user.mp3"}}, "restaurant-108": {"agent": {"seconds": 1.963, "voice": "am_michael", "text": "Can I get you anything else?", "bytes": 24192, "sha256": "96088237c0630ec52111f95110c558b9115628976ad6bd43a94ef1745b00dda5", "src": "audio/restaurant/restaurant-108-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "No, we're completely satisfied.", "bytes": 24480, "sha256": "7994a0cb3856338164724378205e1055b944bf62c1570a0c6ae8d9690045dbcc", "src": "audio/restaurant/restaurant-108-user.mp3"}}, "restaurant-109": {"agent": {"seconds": 2.517, "voice": "am_michael", "text": "Was everything to your liking this evening?", "bytes": 30816, "sha256": "b232fd8bc6299d902eddaa4074e0414d24a0ec32fad1c12bdc2cf12cec5a2c11", "src": "audio/restaurant/restaurant-109-agent.mp3"}, "user": {"seconds": 1.984, "voice": "af_bella", "text": "Everything was wonderful. Thank you.", "bytes": 24480, "sha256": "76cbc756f35c57a863549c21281237e15553da19aa8d8ac0247c8e8d312121ca", "src": "audio/restaurant/restaurant-109-user.mp3"}}, "restaurant-110": {"agent": {"seconds": 1.536, "voice": "am_michael", "text": "Can I get you the bill?", "bytes": 19008, "sha256": "8957694145e569869c8c64cca58b0cb5ef831310e51de8a45ca40c17c7994978", "src": "audio/restaurant/restaurant-110-agent.mp3"}, "user": {"seconds": 2.304, "voice": "af_bella", "text": "Yes, please. The bill, when you're ready.", "bytes": 28224, "sha256": "ea666fed8a79718ee2e37542f5dafd4a742a1b40e4fb0d8f7551cd30bb06e9e2", "src": "audio/restaurant/restaurant-110-user.mp3"}}, "restaurant-111": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "Here you go. No rush at all.", "bytes": 25344, "sha256": "8dcc39ca3f0dee7423f7fc413604b2014b26b4ebdb59b742e541989a8048b308", "src": "audio/restaurant/restaurant-111-agent.mp3"}, "user": {"seconds": 1.557, "voice": "af_bella", "text": "Could we split the bill, please?", "bytes": 19296, "sha256": "4b40c7ab7f80a77e016e8920a792c83835813db8576789c1b80f610e3b38eb46", "src": "audio/restaurant/restaurant-111-user.mp3"}}, "restaurant-112": {"agent": {"seconds": 2.197, "voice": "am_michael", "text": "Of course. Shall we do half and half?", "bytes": 27072, "sha256": "2d9d890fff877554607668aa70da491d4b84bbac969962917abcd8c4020ee0b4", "src": "audio/restaurant/restaurant-112-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Yes, fifty-fifty is perfect.", "bytes": 25632, "sha256": "dbec5b6ef7ab21e357978ab739f04658118e5923f353344421907a4d863dcb91", "src": "audio/restaurant/restaurant-112-user.mp3"}}, "restaurant-113": {"agent": {"seconds": 2.901, "voice": "am_michael", "text": "How would you like to pay — together or separately?", "bytes": 35424, "sha256": "6850f354b409d517a1476ad5445c69d4810c21aa6c36c041413077a11f95c6f3", "src": "audio/restaurant/restaurant-113-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_bella", "text": "Separately, please. Two cards.", "bytes": 25056, "sha256": "8a4763bd4eb848e4ce7bb80e6717e03be172e7abf60eb19eb9ddf1c4d486cacb", "src": "audio/restaurant/restaurant-113-user.mp3"}}, "restaurant-114": {"agent": {"seconds": 2.176, "voice": "am_michael", "text": "Card or cash for the first half?", "bytes": 26784, "sha256": "95c577b749dafdf673f903b7d7f561bf4d574a11c217b034b5c469d8475138de", "src": "audio/restaurant/restaurant-114-agent.mp3"}, "user": {"seconds": 1.877, "voice": "af_bella", "text": "Card, please. Here you go.", "bytes": 23328, "sha256": "06de95a6da9a766b28430a9e1f63bf896a3f4dcdbb428baee5724d52e26a3856", "src": "audio/restaurant/restaurant-114-user.mp3"}}, "restaurant-115": {"agent": {"seconds": 1.792, "voice": "am_michael", "text": "Would you like to add a tip?", "bytes": 22176, "sha256": "b4b6f927cf067d28d222c899c988fb8c12ab6f9a84478625694e711ed550bf7f", "src": "audio/restaurant/restaurant-115-agent.mp3"}, "user": {"seconds": 2.176, "voice": "af_bella", "text": "Yes, please add a ten percent tip.", "bytes": 26784, "sha256": "b1442d5f99970a8cf56335464ae9a8d34d2f25c602e41374eb6db4c4b7e6ab03", "src": "audio/restaurant/restaurant-115-user.mp3"}}, "restaurant-116": {"agent": {"seconds": 2.795, "voice": "am_michael", "text": "Very generous of you. Thank you so much.", "bytes": 34272, "sha256": "d916f984c632d54803da0447c1e413a238132186703120dcbb772d0bb7a1eb8e", "src": "audio/restaurant/restaurant-116-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "You've earned it. Great service.", "bytes": 21312, "sha256": "d0cc4f7f1d4d72366cb78f92400239d5c444dc1d8c82c8d2a8f5a7c14b427c9a", "src": "audio/restaurant/restaurant-116-user.mp3"}}, "restaurant-117": {"agent": {"seconds": 2.219, "voice": "am_michael", "text": "Here's your receipt. All paid up.", "bytes": 27360, "sha256": "e90bd17fcb495cef8b73343f2074bd1e247bf2f4f9b2a0a75ae1a3ade5aca831", "src": "audio/restaurant/restaurant-117-agent.mp3"}, "user": {"seconds": 1.941, "voice": "af_bella", "text": "Perfect. Thanks for the receipt.", "bytes": 23904, "sha256": "c38c774695e51879d95526b991254d5ea8f4b759ccaf7d72c91dfcb89a361c92", "src": "audio/restaurant/restaurant-117-user.mp3"}}, "restaurant-118": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "Would you like a copy emailed to you?", "bytes": 28512, "sha256": "396ae7374683bae408115567c643e69e53592e0e5545c2b98c6bdb119424e347", "src": "audio/restaurant/restaurant-118-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_bella", "text": "No need. The paper one's fine.", "bytes": 27360, "sha256": "907834cfbe3a266bb52bd750093ca5c592571485b7c9f5e7f3e78e71a6a0fce6", "src": "audio/restaurant/restaurant-118-user.mp3"}}, "restaurant-119": {"agent": {"seconds": 2.133, "voice": "am_michael", "text": "Thank you for dining with us tonight.", "bytes": 26208, "sha256": "800531e4a19b0949d92c8f8ee249d1bbb6210a395344e1798da9412d6f658d97", "src": "audio/restaurant/restaurant-119-agent.mp3"}, "user": {"seconds": 2.069, "voice": "af_bella", "text": "Thank you. We had a lovely evening.", "bytes": 25632, "sha256": "145caf690010eb7213a3f390d28aa3f4b361a951a1cef29962466955ddf9d541", "src": "audio/restaurant/restaurant-119-user.mp3"}}, "restaurant-120": {"agent": {"seconds": 1.835, "voice": "am_michael", "text": "We hope to see you again soon!", "bytes": 22752, "sha256": "07b49f9d9988ee317541b47ef937b1993b5f29ef768005e29684fc91706540ad", "src": "audio/restaurant/restaurant-120-agent.mp3"}, "user": {"seconds": 1.707, "voice": "af_bella", "text": "Definitely. We'll be back.", "bytes": 21312, "sha256": "6140c90536e0ef59cf95c71443a8c6918ff5aa8622b176e7a11daa64582ed550", "src": "audio/restaurant/restaurant-120-user.mp3"}}, "restaurant-121": {"agent": {"seconds": 2.517, "voice": "am_michael", "text": "Would you like a box for the leftover cake?", "bytes": 30816, "sha256": "7fd5fe7dc2e9680044f2086f1149220fae0b16d936f3a42c81b56ee15dd3732a", "src": "audio/restaurant/restaurant-121-agent.mp3"}, "user": {"seconds": 2.261, "voice": "af_bella", "text": "Yes, please. A box would be great.", "bytes": 27936, "sha256": "2133fdd495482e6adda1041a89c6bcb771a4122afbca10b58f4690e05aada9e9", "src": "audio/restaurant/restaurant-121-user.mp3"}}, "restaurant-122": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "I'll pack that up for you right away.", "bytes": 27648, "sha256": "0e0824e7184de5098c0cdab29fe12edf7a46b8199cf844827858e2664a9aaebb", "src": "audio/restaurant/restaurant-122-agent.mp3"}, "user": {"seconds": 2.027, "voice": "af_bella", "text": "Thank you. We hate to waste it.", "bytes": 25056, "sha256": "626fa1c02377a4f10803475c8af62db02070a217aa98c6a2b9e514775c4912a9", "src": "audio/restaurant/restaurant-122-user.mp3"}}, "restaurant-123": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "Would you like anything else to take home?", "bytes": 31968, "sha256": "9bf882e4c0d5c0aa6272d50d88dbc77dc6c07e70211625d07d33bd73305128c2", "src": "audio/restaurant/restaurant-123-agent.mp3"}, "user": {"seconds": 1.472, "voice": "af_bella", "text": "Could we get the bread to go?", "bytes": 18432, "sha256": "21043522a6631eb7cd7842805e151a0a8eed7f2a499a506e9094db9db3b35a2d", "src": "audio/restaurant/restaurant-123-user.mp3"}}, "restaurant-124": {"agent": {"seconds": 2.709, "voice": "am_michael", "text": "Of course. I'll wrap up some fresh bread.", "bytes": 33120, "sha256": "4cff0b2e49fb21baa1e61a03c9961b8e6ea60cd88fd3dbc14a139c973ae28eb1", "src": "audio/restaurant/restaurant-124-agent.mp3"}, "user": {"seconds": 1.685, "voice": "af_bella", "text": "Lovely. Thank you so much.", "bytes": 21024, "sha256": "93f00fc9152ec988839b3948ca8365eb6a5e9fafe6ef33e7c271b0d14efc53a3", "src": "audio/restaurant/restaurant-124-user.mp3"}}, "restaurant-125": {"agent": {"seconds": 2.24, "voice": "am_michael", "text": "Do you need a bag for all of this?", "bytes": 27648, "sha256": "e20fdb577e590e2e3c563e8e05ada20ac370917a8353ee695680a0efe0247a50", "src": "audio/restaurant/restaurant-125-agent.mp3"}, "user": {"seconds": 1.621, "voice": "af_bella", "text": "Yes, one bag is enough.", "bytes": 20160, "sha256": "ffaeb682ccce31c4d0b36d3c2ca343e94157413fe88f8c40d01a8f178db411db", "src": "audio/restaurant/restaurant-125-user.mp3"}}, "restaurant-126": {"agent": {"seconds": 2.859, "voice": "am_michael", "text": "Here are your takeaway boxes, all packed.", "bytes": 35136, "sha256": "6b753d1026ea790898bf43e6c294443837968a4ccd26851adbd3cf2a67a43c40", "src": "audio/restaurant/restaurant-126-agent.mp3"}, "user": {"seconds": 2.496, "voice": "af_bella", "text": "Perfect. Everything is packed up nicely.", "bytes": 30528, "sha256": "7f1db0c3f8078ac042d8900993fe2377de1e2df39c6ce6db31ef06ec11d93334", "src": "audio/restaurant/restaurant-126-user.mp3"}}, "restaurant-127": {"agent": {"seconds": 3.499, "voice": "am_michael", "text": "The tiramisu keeps well until tomorrow, by the way.", "bytes": 42624, "sha256": "b37aee81b44c62cd52b9e7fdd07246c6bdae49e7f9a819df6377f0a33a18cb81", "src": "audio/restaurant/restaurant-127-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_bella", "text": "Good to know. It won't last that long!", "bytes": 28224, "sha256": "809f2fd4b43a75eb85db4e19d816d906a716fdadce7129a57d19a6a44447106a", "src": "audio/restaurant/restaurant-127-user.mp3"}}, "restaurant-128": {"agent": {"seconds": 2.453, "voice": "am_michael", "text": "Ha! I completely believe you on that.", "bytes": 30240, "sha256": "18aa0ec229244f3f9265e0a2e113db4866f18f7fa2a589cc61103a6e839636ea", "src": "audio/restaurant/restaurant-128-agent.mp3"}, "user": {"seconds": 1.344, "voice": "af_bella", "text": "It's just too delicious.", "bytes": 16704, "sha256": "27507332c037fdcb31b77a16ab7348f4187001dd4dd6da8145febe3cdfd93606", "src": "audio/restaurant/restaurant-128-user.mp3"}}, "restaurant-129": {"agent": {"seconds": 2.731, "voice": "am_michael", "text": "Is there anything else before you head out?", "bytes": 33408, "sha256": "3cedc97fe609a9961d25adbdee34c0fe013afbc9043c7e3aa891e52c6ff75d36", "src": "audio/restaurant/restaurant-129-agent.mp3"}, "user": {"seconds": 1.579, "voice": "af_bella", "text": "No, I think we're all set.", "bytes": 19584, "sha256": "2f222a8932eb9895f381953a9b9f50b79e7059ca8b553533bd0e644b5bec529c", "src": "audio/restaurant/restaurant-129-user.mp3"}}, "restaurant-130": {"agent": {"seconds": 1.749, "voice": "am_michael", "text": "Let me walk you to the door.", "bytes": 21600, "sha256": "46e46523be506d00d0d5557307a1c8f2ccd57a7386a8cb312887149d85a39a98", "src": "audio/restaurant/restaurant-130-agent.mp3"}, "user": {"seconds": 1.728, "voice": "af_bella", "text": "That's kind, but no need.", "bytes": 21312, "sha256": "f5070c1d1af13b46bc3f79b5ee4b1c04e0157a362a51a0397fb3cc6c6c873c65", "src": "audio/restaurant/restaurant-130-user.mp3"}}, "restaurant-131": {"agent": {"seconds": 1.536, "voice": "am_michael", "text": "Your coats — here you are.", "bytes": 19008, "sha256": "d4fefa5a91723fa43693cf96240af65759effa43f6025d113d6c8ae94ae86998", "src": "audio/restaurant/restaurant-131-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "Thank you. Have a good night!", "bytes": 21888, "sha256": "7c1f3b68cc40181147cf8bba29f43313501d6ae73d0221f1d2ca9dbc0740acce", "src": "audio/restaurant/restaurant-131-user.mp3"}}, "restaurant-132": {"agent": {"seconds": 2.688, "voice": "am_michael", "text": "Goodnight! Thanks for coming to Bella Roma.", "bytes": 32832, "sha256": "7d7b6d80b155deadff5deffb83a2849b4b31bc9275d84265a5777100246634ec", "src": "audio/restaurant/restaurant-132-agent.mp3"}, "user": {"seconds": 2.219, "voice": "af_bella", "text": "Goodnight! We'll definitely return.", "bytes": 27360, "sha256": "6da48bc44dd4dc0120fe64ff001cfb8cbb4c8ca575b1dadfee6df3b57dc776bd", "src": "audio/restaurant/restaurant-132-user.mp3"}}, "restaurant-133": {"agent": {"seconds": 2.688, "voice": "am_michael", "text": "Before you go — how was everything tonight?", "bytes": 32832, "sha256": "cdf9450eb08f656b5aaf41d895ff194132fc0f86793f554ca85c3ac0f1f23c50", "src": "audio/restaurant/restaurant-133-agent.mp3"}, "user": {"seconds": 2.261, "voice": "af_bella", "text": "Honestly, one of our best meals out.", "bytes": 27936, "sha256": "92aeb9b192fa79bdc75665c9bd058b98b13650794847cf84d3d10db107c1dde7", "src": "audio/restaurant/restaurant-133-user.mp3"}}, "restaurant-134": {"agent": {"seconds": 2.091, "voice": "am_michael", "text": "That means so much. Thank you!", "bytes": 25920, "sha256": "70204f07b49bf0b35cd724940785c3487b18115b98eb59f1c0afe35a878dd94b", "src": "audio/restaurant/restaurant-134-agent.mp3"}, "user": {"seconds": 1.771, "voice": "af_bella", "text": "The salmon was cooked perfectly.", "bytes": 21888, "sha256": "135b8114375004f2a7e8200b734f250c0efd4557a084826c09a70931825420ff", "src": "audio/restaurant/restaurant-134-user.mp3"}}, "restaurant-135": {"agent": {"seconds": 1.941, "voice": "am_michael", "text": "I'll pass that on to the chef.", "bytes": 23904, "sha256": "9547e5b2d07ae8446369eeafa0f420e8599189b50551188473449b4767c8368e", "src": "audio/restaurant/restaurant-135-agent.mp3"}, "user": {"seconds": 1.963, "voice": "af_bella", "text": "And the tiramisu was unforgettable.", "bytes": 24192, "sha256": "321cb525c92c489bc06a5ed89ab91e52b92a8026e82523d49ac26c8776621f76", "src": "audio/restaurant/restaurant-135-user.mp3"}}, "restaurant-136": {"agent": {"seconds": 2.411, "voice": "am_michael", "text": "Our pastry chef will be over the moon.", "bytes": 29664, "sha256": "8f59332a1f93c5c6da498f742c5916c419e5365510934316470b85e4ccee2e4d", "src": "audio/restaurant/restaurant-136-agent.mp3"}, "user": {"seconds": 1.643, "voice": "af_bella", "text": "Please tell her we said thanks.", "bytes": 20448, "sha256": "21de4eb4da703d98a7b475f83ccfde34651c6e8222b7eb81b22726b271e6acf2", "src": "audio/restaurant/restaurant-136-user.mp3"}}, "restaurant-137": {"agent": {"seconds": 3.093, "voice": "am_michael", "text": "Would you mind leaving us a quick review online?", "bytes": 37728, "sha256": "a9c4c620b3786095bd207e0650237723dac2a0b9ffe12242ecc4bacd2c889800", "src": "audio/restaurant/restaurant-137-agent.mp3"}, "user": {"seconds": 2.197, "voice": "af_bella", "text": "Of course. We'll leave a review tonight.", "bytes": 27072, "sha256": "28ef4e05fdba66339c183693b1afb1d13f5c9328e8007a673d4459fbf612d09d", "src": "audio/restaurant/restaurant-137-user.mp3"}}, "restaurant-138": {"agent": {"seconds": 2.603, "voice": "am_michael", "text": "It really helps a small place like ours.", "bytes": 31968, "sha256": "1440813ef104438b16a9f43a81abf1a34cfe42c40d3b6c0e7483d106b54dea38", "src": "audio/restaurant/restaurant-138-agent.mp3"}, "user": {"seconds": 2.539, "voice": "af_bella", "text": "We understand. Five stars for sure.", "bytes": 31104, "sha256": "abebc2e7f393d3cce01fbcdf1259b904fe63a21473ac93ea217da57dd301643a", "src": "audio/restaurant/restaurant-138-user.mp3"}}, "restaurant-139": {"agent": {"seconds": 2.325, "voice": "am_michael", "text": "You're too kind. Thank you so much!", "bytes": 28512, "sha256": "792ad1e997a56b0332472800f4500ee2b5023e3f3513479deaea3f50b9a36757", "src": "audio/restaurant/restaurant-139-agent.mp3"}, "user": {"seconds": 2.005, "voice": "af_bella", "text": "It's well deserved. Trust me.", "bytes": 24768, "sha256": "65732ec5670f10ffc01ef3b912e17bcf779412c4832462bc370a41756168b0bb", "src": "audio/restaurant/restaurant-139-user.mp3"}}, "restaurant-140": {"agent": {"seconds": 2.283, "voice": "am_michael", "text": "Will you be celebrating with us again?", "bytes": 28224, "sha256": "2f9e4ebe6e8250e3b1c1dff74ddb7c2be07fde2aa0ee8e7efc600b2c5e943dfe", "src": "audio/restaurant/restaurant-140-agent.mp3"}, "user": {"seconds": 1.216, "voice": "af_bella", "text": "We'll be back for sure.", "bytes": 15264, "sha256": "3f84a1e27ded3d8b7d6d2c379d6d78c9c55015afd408a5a76b81e4ee19ed4c7a", "src": "audio/restaurant/restaurant-140-user.mp3"}}, "restaurant-141": {"agent": {"seconds": 2.539, "voice": "am_michael", "text": "Ask for me next time — I'm Marco.", "bytes": 31104, "sha256": "ece5f3178fe6181601b3903cfd85842b71f57c3f5dc7a51e92cbd5fab753cd34", "src": "audio/restaurant/restaurant-141-agent.mp3"}, "user": {"seconds": 2.283, "voice": "af_bella", "text": "We will, Marco. Thanks for everything.", "bytes": 28224, "sha256": "fa817f658692f1fb6bfa6b4884e8f77233fc438f17ee1f31a068f7703767c537", "src": "audio/restaurant/restaurant-141-user.mp3"}}, "restaurant-142": {"agent": {"seconds": 2.048, "voice": "am_michael", "text": "The pleasure was all mine tonight.", "bytes": 25344, "sha256": "31b1676ed5fefe262849c23d8646cece78ba19af8da807bf646354ea1c0a2413", "src": "audio/restaurant/restaurant-142-agent.mp3"}, "user": {"seconds": 1.813, "voice": "af_bella", "text": "What a lovely evening this was.", "bytes": 22464, "sha256": "f2796d98813d39efb5b3c97e09b6588abf94336c1e72ac1f0778964384ca1c8b", "src": "audio/restaurant/restaurant-142-user.mp3"}}, "restaurant-143": {"agent": {"seconds": 2.56, "voice": "am_michael", "text": "Happy anniversary once more, you two!", "bytes": 31392, "sha256": "5edd3db70b9ef9e45a83bbb3dc908031ef8f36aa9ec64be68e262031b208db88", "src": "audio/restaurant/restaurant-143-agent.mp3"}, "user": {"seconds": 1.835, "voice": "af_bella", "text": "Thank you. You made it special.", "bytes": 22752, "sha256": "e8bd02f22672f64265f7638b735636ef4756bb307d8fa2ddad3a7eee3875f929", "src": "audio/restaurant/restaurant-143-user.mp3"}}, "restaurant-144": {"agent": {"seconds": 2.539, "voice": "am_michael", "text": "Goodnight, and safe travels home tonight!", "bytes": 31104, "sha256": "848472d386241087cbf47fd423c0b6e25e0521a92789024971814321664d4028", "src": "audio/restaurant/restaurant-144-agent.mp3"}, "user": {"seconds": 2.048, "voice": "af_bella", "text": "Goodnight! Thanks again, Marco.", "bytes": 25344, "sha256": "9993ca8b289969a3622d2d410177746ea84574b1a4a445598de5d431fc1a82dc", "src": "audio/restaurant/restaurant-144-user.mp3"}}}}, "complete": true};